#!/usr/bin/env bash
# ASB host tests: WebUI, log kit, asbdiag and capture comparison.
#
# Each test is a function t_<name> whose body runs in its own subshell, exactly as the
# standalone script it used to be; the C fixtures it builds are the functions _c_<name>.
#   bash tests/asb_ui.sh                 run every test in this file
#   bash tests/asb_ui.sh NAME [NAME...]  run the named tests
#   bash tests/asb_ui.sh --list          list the tests
#   bash tests/asb_ui.sh --source NAME   print an embedded C fixture
# tools/asb_full_regression.sh runs every test of every tests/asb_*.sh in parallel.

t_asbdiag_report_host_runtime() (
# Runtime (fix151): asbdiag says which janky frames are its own output scrolling.
#
# A CPH2691 report run from Termux: "com.termux 663 of 676 frames (20.72/s)" and "steady:
# com.termux missed 663 of the 676 frames ... while you only waited for this report". An
# outside audit read that as "over 90% UI lag in Termux, up to 20 a second" and proposed CPU
# boosts and big-core whitelists for it. Termux was drawing the report. The REAL functions
# run on a fake /proc and cpuset: the app in front at the start is found from the top-app
# group (uid >= 10000, oom_score_adj 0), and its line says it is the report's own window.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
D="$ROOT/tools/asb_diag.sh"
fail() { echo "FAIL asbdiag report host: $*" >&2; exit 1; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
sed -n '/^# asb_gfx_pkg_begin$/,/^# asb_gfx_pkg_end$/p' "$D" > "$T/f.sh"
grep -q '^asb_report_host() {' "$T/f.sh" || fail "no host lookup in the testable block"
mkdir -p "$T/cpuset/top-app"
mk() {   # pid uid oom cmdline
  mkdir -p "$T/proc/$1"
  printf 'Name:\tx\nUid:\t%s\t%s\t%s\t%s\n' "$2" "$2" "$2" "$2" > "$T/proc/$1/status"
  echo "$3" > "$T/proc/$1/oom_score_adj"
  printf '%s\000' "$4" > "$T/proc/$1/cmdline"
}
mk 100 1000 0 system_server
mk 200 10123 200 com.google.android.inputmethod.latin
mk 300 10234 0 /data/data/com.termux/files/usr/bin/bash
mk 400 10234 0 com.termux
printf '100\n200\n300\n400\n' > "$T/cpuset/top-app/cgroup.procs"
h="$(ASB_PROC_ROOT="$T/proc" ASB_CPUSET_ROOT="$T/cpuset" sh -c '. "$1"; asb_report_host' x "$T/f.sh")"
[ "$h" = com.termux ] || fail "host: '$h', want com.termux"
printf 'com.termux 1000 10\ncom.android.systemui 2000 20\n' > "$T/a"
printf 'com.termux 1676 673\ncom.android.systemui 3144 44\n' > "$T/b"
d="$(sh -c '. "$1"; asb_gfx_run_delta "$(cat "$2")" "$(cat "$3")" 32 com.termux' x "$T/f.sh" "$T/a" "$T/b")"
printf '%s\n' "$d" | grep 'com.termux 663 of 676 frames (20.72/s, the window this report is printed in)' >/dev/null || fail "per-app line: $d"
printf '%s\n' "$d" | grep '^host: com.termux missed 663 of the 676 frames it drew - the report scrolling in it, not a lag$' >/dev/null || fail "host line: $d"
printf '%s\n' "$d" | grep '^steady:' >/dev/null && fail "the report's own window called a steady redraw: $d"
d="$(sh -c '. "$1"; asb_gfx_run_delta "$(cat "$2")" "$(cat "$3")" 32 com.rifsxd.ksunext' x "$T/f.sh" "$T/a" "$T/b")"
printf '%s\n' "$d" | grep '^steady: com.termux missed 663' >/dev/null || fail "another app in front still gets the steady verdict: $d"
# fix178: no host found at all (a CPH2691 run from Termux) - a terminal at the top is the host.
d="$(sh -c '. "$1"; asb_gfx_run_delta "$(cat "$2")" "$(cat "$3")" 32 ""' x "$T/f.sh" "$T/a" "$T/b")"
printf '%s\n' "$d" | grep '^host: com.termux missed 663' >/dev/null || fail "a terminal at the top without a host lookup: $d"
printf '%s\n' "$d" | grep 'the window this report is printed in' >/dev/null || fail "no host label on the terminal's line: $d"
printf 'com.example.feed 1000 10\ncom.android.systemui 2000 20\n' > "$T/a2"
printf 'com.example.feed 1676 673\ncom.android.systemui 3144 44\n' > "$T/b2"
d="$(sh -c '. "$1"; asb_gfx_run_delta "$(cat "$2")" "$(cat "$3")" 32 ""' x "$T/f.sh" "$T/a2" "$T/b2")"
printf '%s\n' "$d" | grep '^steady: com.example.feed missed 663' >/dev/null || fail "an ordinary app at the top lost its steady verdict: $d"
grep -q 'asb_gfx_run_delta "$_gfx_run0" "$_gfx_run1" "$(( $(date +%s) - ${_gfx_run0_t:-0} ))" "$_gfx_host"' "$D" || fail "7c does not pass the host"
cmp -s "$D" "$ROOT/system/bin/asbdiag" || fail "asbdiag copies differ"
echo "PASS asbdiag report host: the window the report prints into is named, not read as lag"
)

t_asbdiag_wake_paths_runtime() (
# Runtime (fix178): two asbdiag lines that misread a CPH2691.
#
# "WARN: 4 of 4 screen wakes were found only by the idle tick" on a phone whose governor had
# caught 32 wakes on the display-state path (screen_on_detect=uevent:0,recheck:0,tick:4,display:32)
# - the total left that path out. And the status-bar settings list printed the whole of
# oplus.radio.smart5g_apk_cfg, matched on "Internetspeed" inside its value. The REAL lines run.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
D="$ROOT/tools/asb_diag.sh"
fail() { echo "FAIL asbdiag wake paths: $*" >&2; exit 1; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
{ echo '_sod="uevent:0,recheck:0,tick:4,display:32"; _sot=4'
  sed -n '/_sou="$(printf .%s. "$_sod" | sed -n .s\/.\*uevent/,/^    _sall=/p' "$D"
  echo 'echo "$_sall"'; } > "$T/w.sh"
grep -q '_sodp=' "$T/w.sh" || fail "the display path is not read"
[ "$(sh "$T/w.sh")" = 36 ] || fail "wake total: $(sh "$T/w.sh"), want 36"
prog="$(grep -m1 "awk -F= 'tolower(\$1) ~ /net(work)?_?speed" "$D" | sed "s/.*awk -F= '//; s/' *\\\\\$//")"
[ -n "$prog" ] || fail "status-bar matcher not found"
out="$(printf '%s\n' 'system:oplus.radio.smart5g_apk_cfg=ver_num=9;filetrans=com.Wifi.lte5g.speedtest.Internetspeed' \
                     'system:show_network_speed=1' 'secure:clock_seconds=0' 'global:wifi_on=1' | awk -F= "$prog")"
printf '%s\n' "$out" | grep 'smart5g' >/dev/null && fail "a key matched on its value: $out"
printf '%s\n' "$out" | grep -x 'system:show_network_speed=1' >/dev/null || fail "network speed key missed: $out"
printf '%s\n' "$out" | grep -x 'secure:clock_seconds=0' >/dev/null || fail "clock seconds key missed: $out"
# fix178: the codec of the ACTIVE A2DP device (an inactive one listed first is not it), and the
# multipoint hint only for a high-bitrate codec. The REAL block runs against a stub dumpsys.
mkdir -p "$T/bin"
cat > "$T/bin/dumpsys" <<'B'
#!/bin/sh
cat "$DUMP"
B
chmod +x "$T/bin/dumpsys"
{ echo 'NOTE() { echo "NOTE $*"; }'
  sed -n '/^_btc="\$(dumpsys bluetooth_manager/,/^fi$/p' "$D"; } > "$T/c.sh"
grep -q 'mCodecConfig' "$T/c.sh" || fail "codec block not found"
cat > "$T/dump1" <<'B'
  === A2dpStateMachine for XX:XX:XX:XX:9D:9F ===
    mCodecConfig: {codecName:SBC,mCodecType:0,mCodecPriority:1001,mSampleRate:0x1(44100),mBitsPerSample:0x1(16),mChannelMode:0x2(STEREO)}
  === A2dpStateMachine for XX:XX:XX:XX:B8:86 (Active) ===
    mConnectionState: STATE_CONNECTED, mLastConnectionState: STATE_CONNECTING
    mCodecConfig: {codecName:LHDC,mCodecType:19,mCodecPriority:9002,mSampleRate:0x2(48000),mBitsPerSample:0x2(24),mChannelMode:0x2(STEREO)}
B
out="$(PATH="$T/bin:$PATH" DUMP="$T/dump1" sh "$T/c.sh")"
printf '%s\n' "$out" | grep -x 'NOTE active A2DP codec: LHDC 48000 Hz / 24-bit' >/dev/null || fail "active codec line: $out"
printf '%s\n' "$out" | grep 'multipoint' >/dev/null || fail "no multipoint hint on LHDC: $out"
sed 's/codecName:LHDC/codecName:AAC/' "$T/dump1" > "$T/dump2"
out="$(PATH="$T/bin:$PATH" DUMP="$T/dump2" sh "$T/c.sh")"
printf '%s\n' "$out" | grep -x 'NOTE active A2DP codec: AAC 48000 Hz / 24-bit' >/dev/null || fail "AAC codec line: $out"
printf '%s\n' "$out" | grep 'multipoint' >/dev/null && fail "multipoint hint on AAC: $out"
out="$(PATH="$T/bin:$PATH" DUMP=/dev/null sh "$T/c.sh")"
[ -z "$out" ] || fail "no A2DP device still printed: $out"
# fix178: the Wi-Fi link line names the band, not the network, and skips state-machine rows.
cat > "$T/bin/cmd" <<'B'
#!/bin/sh
[ "$1 $2" = "wifi status" ] && cat "$CMDOUT"
B
chmod +x "$T/bin/cmd"
{ echo 'P() { echo "$*"; }; NOTE() { echo "NOTE $*"; }'
  sed -n '/^_wfl="\$({ cmd wifi status/,/^case "\$_wfl" in/p' "$D"; } > "$T/wf.sh"
grep -q 'Frequency' "$T/wf.sh" || fail "wifi link block not found"
printf '%s\n' '       rec[5]: time=10-18 18:10:22.130 processed=DefaultState org=EnabledState SSID x' \
  'mWifiInfo SSID: "home", BSSID: 11:22:33:44:55:66, Wi-Fi standard: 11ax, RSSI: -61, Link speed: 573Mbps, Tx Link speed: 573Mbps, Rx Link speed: 432Mbps, Frequency: 2437MHz' > "$T/wd"
out="$(PATH="$T/bin:$PATH" DUMP="$T/wd" CMDOUT=/dev/null sh "$T/wf.sh")"
printf '%s\n' "$out" | grep -x '  live wifi link: 2437 MHz (2.4 GHz), RSSI -61 dBm, 573 Mbps, 11ax' >/dev/null || fail "wifi link: $out"
printf '%s\n' "$out" | grep 'home\|11:22' >/dev/null && fail "the network name or BSSID reached the report: $out"
printf '%s\n' "$out" | grep '^NOTE Wi-Fi on 2.4 GHz' >/dev/null || fail "no 2.4 GHz note: $out"
printf '%s\n' 'Wifi is connected to "home"' 'WifiInfo: SSID: "home", RSSI: -50, Link speed: 1200Mbps, Frequency: 5745MHz' > "$T/wc"
out="$(PATH="$T/bin:$PATH" DUMP=/dev/null CMDOUT="$T/wc" sh "$T/wf.sh")"
[ "$out" = '  live wifi link: 5745 MHz (5 GHz), RSSI -50 dBm, 1200 Mbps' ] || fail "cmd wifi status link: $out"
printf 'mWifiInfo SSID: <unknown ssid>, RSSI: -127, Link speed: -1Mbps, Frequency: -1MHz\n' > "$T/wd"
out="$(PATH="$T/bin:$PATH" DUMP="$T/wd" CMDOUT=/dev/null sh "$T/wf.sh")"
[ "$out" = '  live wifi link: not connected, or the ROM printed no link line' ] || fail "disconnected link: $out"
# fix179: who held Wi-Fi multicast since the unplug, from batterystats' per-uid blocks.
cat > "$T/bin/dumpsys" <<'B'
#!/bin/sh
printf '  Total WiFi Multicast wakelock time: 3h 49m\n  1000:\n    WiFi Multicast Wakelock count = 12 time = 41m2s3ms\n  u0a345:\n    WiFi Multicast Wakelock count = 3 time = 11m56s541ms\n'
B
cat > "$T/bin/pm" <<'B'
#!/bin/sh
printf 'package:com.instagram.android uid:10345\npackage:com.other uid:103450\n'
B
chmod +x "$T/bin/dumpsys" "$T/bin/pm"
{ echo 'P() { echo "$*"; }; _mct=13752'
  sed -n '/^  if \[ "\$_mct" -ge 600 \]; then$/,/^  fi$/p' "$D"; } > "$T/mc.sh"
grep -q 'held since the unplug' "$T/mc.sh" || fail "multicast holder block not found"
out="$(PATH="$T/bin:$PATH" sh "$T/mc.sh")"
printf '%s\n' "$out" | grep -x '    held since the unplug: system  ·  WiFi Multicast Wakelock count = 12 time = 41m2s3ms' >/dev/null || fail "system holder: $out"
printf '%s\n' "$out" | grep -x '    held since the unplug: com.instagram.android  ·  WiFi Multicast Wakelock count = 3 time = 11m56s541ms' >/dev/null || fail "app holder: $out"
printf '%s\n' "$out" | grep 'com.other' >/dev/null && fail "a uid prefix matched another app: $out"
cmp -s "$D" "$ROOT/system/bin/asbdiag" || fail "asbdiag copies differ"
echo "PASS asbdiag wake paths: the display path counts in the wake total, status-bar keys are matched by name, the active codec, the Wi-Fi band and the multicast holders are named"
)

t_asbdiag_throttle_point_runtime() (
# Runtime: the throttle-point check of tools/asb_diag.sh. An OP15 asbdiag read FAIL=1 for
# "throttle point below live CPU sensor" because a core reached 71 C under the load of the
# report itself while the automatic point was 65 C - the clamp working as asked, not a setting
# ASB got wrong. With the screen on it is a note; with the screen off (a hot phone at rest)
# it stays a FAIL; a manual point stays a WARN. The REAL block runs over fake thermal zones.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
D="$ROOT/tools/asb_diag.sh"
fail() { echo "FAIL asbdiag throttle point: $*" >&2; exit 1; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
awk '/^  _tp_set="\$\(cfg sustained_temp_enter\)"$/ { f = 1 } f { print } f && /^esac$/ { exit }' "$D" \
  | sed "s#/sys/class/thermal/thermal_zone\*#$T/tz/thermal_zone*#" > "$T/b.sh"
grep -q 'headroom ok' "$T/b.sh" && grep -q "$T/tz" "$T/b.sh" || fail "throttle block not found"
mkdir -p "$T/tz/thermal_zone0" "$T/tz/thermal_zone1"
echo cpu-1-1-0 > "$T/tz/thermal_zone0/type"; echo 71000 > "$T/tz/thermal_zone0/temp"
echo cpu-hw-trip-0 > "$T/tz/thermal_zone1/type"; echo 95000 > "$T/tz/thermal_zone1/temp"
run() {  # $1 mode, $2 point, $3 screen
  printf 'sustained_temp_mode=%s\nsustained_temp_enter=%s\n' "$1" "$2" > "$T/conf"
  { echo 'P() { echo "$*"; }; NOTE() { echo "(i) $1"; }'
    echo 'V() { if [ "$3" = "$2" ]; then echo "[PASS] $1"; else echo "[FAIL] $1 want=$2 live=$3"; fi; }'
    echo "cfg() { grep -E \"^\$1=\" '$T/conf' | head -1 | sed 's/^[^=]*=//'; }"
    echo "_pl_scr='$3'"; cat "$T/b.sh"; } > "$T/r.sh"
  sh "$T/r.sh"
}
out="$(run smart 65 1)"
printf '%s\n' "$out" | grep '\[FAIL\]' >/dev/null && fail "load with the screen on still fails the install: $out"
printf '%s\n' "$out" | grep 'hottest live CPU sensor 71C with the screen on.*intended behaviour' >/dev/null || fail "screen-on note: $out"
out="$(run smart 65 0)"
printf '%s\n' "$out" | grep '\[FAIL\] *throttle point below live CPU sensor with the screen off want=point >= 71C live=65C' >/dev/null || fail "a hot phone at rest is no longer a FAIL: $out"
out="$(run manual 65 1)"
printf '%s\n' "$out" | grep '\[WARN\] throttle point below live CPU sensor (manual 65C, live 71C)' >/dev/null || fail "manual point: $out"
out="$(run smart 75 1)"
printf '%s\n' "$out" | grep 'headroom ok' >/dev/null || fail "headroom: $out"
printf '%s\n' "$out" | grep '95C' >/dev/null && fail "a hardware trip point was read as a sensor: $out"
cmp -s "$D" "$ROOT/system/bin/asbdiag" || fail "asbdiag copies differ"
echo "PASS asbdiag throttle point: load with the screen on is a note, a hot phone at rest a FAIL, a manual point a WARN, trip zones ignored"
)

t_asbdiag_hires_owner_runtime() (
# Runtime (V66): a release asbdiag on a OnePlus 15 read 92% with one FAIL, "Hi-res 384000 present
# in audio policy: want 1, live 0", on an install whose audio tweaks were off: ASB never delivered
# that file, so the stock policy is not ASB's verdict. The check is a verdict only when ASB
# delivers the policy (an odm bind queued for it, or the /vendor overlay carrying it). The REAL
# block of tools/asb_diag.sh runs over fake paths.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
D="$ROOT/tools/asb_diag.sh"
fail() { echo "FAIL asbdiag hi-res owner: $*" >&2; exit 1; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
awk '/^# hi-res$/ { f = 1 } f && /^# runtime audio props$/ { exit } f { print }' "$D" \
  | sed -e "s#'/vendor/etc/#'$T/vendor/etc/#g" -e "s#'/odm/etc/#'$T/odm/etc/#g" -e "s#/data/adb/asb/odm_bind_manifest.txt#$T/man#" > "$T/b.sh"
grep -q '_hr_t' "$T/b.sh" && grep -q "$T/man" "$T/b.sh" && grep -q "$T/vendor/etc" "$T/b.sh" || fail "hi-res block not found"
mkdir -p "$T/vendor/etc" "$T/odm/etc/audio" "$T/mod"
printf '<mixPort samplingRates="44100,48000"/>\n' > "$T/vendor/etc/audio_policy_configuration.xml"
run() {
  { echo 'P() { echo "$*"; }; NOTE() { echo "(i) $1"; }'
    echo 'V() { if [ "$3" -ge "$2" ]; then echo "[PASS] $1"; else echo "[FAIL] $1 want=$2 live=$3"; fi; }'
    echo 'firstf() { for _g in $@; do for _f in $_g; do [ -f "$_f" ] && { printf "%s" "$_f"; return 0; }; done; done; return 1; }'
    echo "MODDIR='$T/mod'"; cat "$T/b.sh"; } > "$T/r.sh"
  sh "$T/r.sh"
}
out="$(run)"
printf '%s\n' "$out" | grep '\[FAIL\]' >/dev/null && fail "a stock policy ASB never delivered failed the install: $out"
printf '%s\n' "$out" | grep '(i) Hi-res 384000 in audio policy: 0 line(s) in stock .*not checked' >/dev/null || fail "stock note: $out"
printf 'VENDOR_OVERLAY=0\n' > "$T/mod/features.conf"; mkdir -p "$T/mod/system$T/vendor/etc"; : > "$T/mod/system$T/vendor/etc/audio_policy_configuration.xml"
printf '%s\n' "$(run)" | grep '\[FAIL\]' >/dev/null && fail "a disabled overlay counted as delivery"
printf 'VENDOR_OVERLAY=1\n' > "$T/mod/features.conf"
printf '%s\n' "$(run)" | grep '\[FAIL\] Hi-res 384000 present in audio policy want=1 live=0' >/dev/null || fail "an overlay that carries the policy but is stock live is no longer a FAIL: $(run)"
printf '<mixPort samplingRates="44100,48000,384000"/>\n' > "$T/vendor/etc/audio_policy_configuration.xml"
printf '%s\n' "$(run)" | grep '\[PASS\] Hi-res 384000 present in audio policy' >/dev/null || fail "overlay pass: $(run)"
printf 'VENDOR_OVERLAY=0\n' > "$T/mod/features.conf"; printf '<mixPort samplingRates="44100,48000"/>\n' > "$T/vendor/etc/audio_policy_configuration.xml"
printf '<mixPort samplingRates="48000,384000"/>\n' > "$T/odm/etc/audio/audio_policy_configuration.xml"
printf '%s|/data/adb/asb/odm_patched/x\n' "$T/odm/etc/audio/audio_policy_configuration.xml" > "$T/man"
printf '%s\n' "$(run)" | grep '\[PASS\] Hi-res 384000 present in audio policy' >/dev/null || fail "the odm-bound policy is not the one checked: $(run)"
printf '<mixPort samplingRates="48000"/>\n' > "$T/odm/etc/audio/audio_policy_configuration.xml"
printf '%s\n' "$(run)" | grep '\[FAIL\] Hi-res 384000 present in audio policy want=1 live=0' >/dev/null || fail "a queued odm bind that is stock live no longer fails: $(run)"
printf '/odm/etc/camera/media_profiles.xml|/x\n' > "$T/man"
printf '%s\n' "$(run)" | grep '\[FAIL\]' >/dev/null && fail "a camera bind counted as audio policy delivery"
rm -f "$T/vendor/etc/audio_policy_configuration.xml"
printf '%s\n' "$(run)" | grep '(i) audio_policy_configuration not found' >/dev/null || fail "missing policy: $(run)"
cmp -s "$D" "$ROOT/system/bin/asbdiag" || fail "asbdiag copies differ"
echo "PASS asbdiag hi-res owner: the 384000 policy check is a verdict only where ASB delivers the policy (odm bind or overlay); a stock file is a note"
)

t_asbdiag_dsp_guard_held_runtime() (
# Runtime: a tripped effects safety guard is reported as HELD, not as two install FAILs.
# A OnePlus 13R (test24/26/27) sent FAIL=2 four times: "library mapped into the audio HAL"
# and "effect registered with audioflinger" both absent, under a guard that had unbound the
# effect itself after three audio-service PID changes. While the guard holds, an unattached
# effect is what ASB intends. The REAL helpers, DSP attach block and verdict block of
# tools/asb_diag.sh run over stubbed Android tools: guard held -> HELD (FAIL=0, named in the
# verdict, excluded from pass_ratio); no guard -> the same absence is still FAIL; guard file
# but effect attached -> PASS. Reports without a held guard keep their exact totals line.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
D="$ROOT/tools/asb_diag.sh"
fail() { echo "FAIL asbdiag DSP guard held: $*" >&2; exit 1; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
awk '/^P\(\)  \{/ { f = 1 } /^firstf\(\) \{/ { exit } f { print }' "$D" > "$T/h.sh"
awk '/^_dsp_pid=""$/ { f = 1 } f && /^SEC "2\. BLUETOOTH"$/ { exit } f { print }' "$D" \
  | sed -e "s#/data/adb/#$T/data/adb/#g" -e "s#/vendor/lib#$T/vendor/lib#g" > "$T/b.sh"
awk '/^P "  C\. VERDICT"$/ { f = 1 } f { print } f && /HELD = checks kept off on purpose/ { exit }' "$D" > "$T/v.sh"
grep -q '^HELD()' "$T/h.sh" && grep -q '^V() {' "$T/h.sh" || fail "helper block not found"
grep -q '_dsp_held' "$T/b.sh" && grep -q 'dsp_effects_blocked' "$T/b.sh" || fail "DSP block not found"
grep -q 'HELD=' "$T/v.sh" || fail "verdict block not found"
mkdir -p "$T/data/adb/asb" "$T/data/adb/modules/AutoSystemBoost" "$T/vendor/lib64/soundfx"
printf 'legacy\n' > "$T/data/adb/modules/AutoSystemBoost/dsp_abi_installed"
: > "$T/vendor/lib64/soundfx/libasbdsp.so"
run() {  # $1 = effect line audioflinger prints ('' = not registered)
  { echo 'OUT1=""; OUT2=""'
    echo 'getprop() { case "$1" in persist.asb.dsp.enable) echo 1 ;; persist.asb.dsp.outputs) echo all ;; *) : ;; esac; }'
    echo 'cfg() { [ "$1" = dsp_loudness ] && echo 1; }'
    echo 'pidof() { [ "$1" = android.hardware.audio.service_64 ] && echo 4799; }'
    printf 'dumpsys() { [ "$1" = media.audio_flinger ] && printf "%%s\\n" "%s"; }\n' "$1"
    echo 'logcat() { :; }'
    echo "MODDIR='$T/mod'"
    cat "$T/h.sh" "$T/b.sh"
    echo '_ux_refused=0'
    cat "$T/v.sh"; echo 'exit 0'; } > "$T/r.sh"
  sh "$T/r.sh"
}
printf 'ts=1795456411 restarts=3\n' > "$T/data/adb/asb/dsp_effects_blocked"
out="$(run '')"
printf '%s\n' "$out" | grep -F '[FAIL]' >/dev/null && fail "the guard's own unbind is still an install FAIL: $out"
[ "$(printf '%s\n' "$out" | grep -c '^  \[HELD\]   ')" = 2 ] || fail "map and registration must both be HELD: $out"
printf '%s\n' "$out" | grep -F 'held by: effects safety guard (ts=1795456411 restarts=3)' >/dev/null || fail "guard record not named: $out"
printf '%s\n' "$out" | grep -F 'FAIL=0 · HELD=2 - no install failure, but DSP effect is kept off on purpose' >/dev/null || fail "verdict: $out"
printf '%s\n' "$out" | grep -F 'everything this report can check for your settings is in effect' >/dev/null && fail "held DSP called fully in effect: $out"
printf '%s\n' "$out" | grep -E '^  PASS=0   FAIL=0   N/A=0   OFF=0   info=[0-9]+   HELD=2$' >/dev/null || fail "totals: $out"
printf '%s\n' "$out" | grep -F 'HELD = checks kept off on purpose by an ASB safety guard: DSP effect (excluded from pass_ratio)' >/dev/null || fail "held list: $out"
printf '%s\n' "$out" | python3 -c 'import re,sys; m=re.search(r"PASS=(\d+)\s+FAIL=(\d+)", sys.stdin.read()); sys.exit(0 if m and m.group(2)=="0" else 1)' || fail "log intake regex no longer reads FAIL=0"
printf '%s\n' "$out" | grep -F 'guard is active; do not retry registration' >/dev/null || fail "guard guidance lost: $out"
rm -f "$T/data/adb/asb/dsp_effects_blocked"
out="$(run '')"
[ "$(printf '%s\n' "$out" | grep -c '^  \[FAIL\] ')" = 2 ] || fail "without a guard an absent attach must stay FAIL: $out"
printf '%s\n' "$out" | grep -F 'HELD' >/dev/null && fail "HELD shown without a guard: $out"
printf '%s\n' "$out" | grep -E '^  PASS=0   FAIL=2   N/A=0   OFF=0   info=[0-9]+$' >/dev/null || fail "totals line changed without a guard: $out"
printf 'ts=1 restarts=3\n' > "$T/data/adb/asb/dsp_effects_blocked"
mkdir -p "$T/proc"; out="$(run 'ASB Loudness')"
printf '%s\n' "$out" | grep -E '\[PASS\] +effect registered with audioflinger' >/dev/null || fail "attached effect under a stale guard file: $out"
printf '%s\n' "$out" | grep -F '[HELD]' >/dev/null && fail "an attached effect was reported HELD: $out"
cmp -s "$D" "$ROOT/system/bin/asbdiag" || fail "asbdiag copies differ"
echo "PASS asbdiag DSP guard held: a tripped effects guard reads HELD (FAIL=0, named, out of pass_ratio); without the guard the absence stays FAIL; totals unchanged otherwise"
)

t_asbdiag_write_ratio_runtime() (
# Runtime (fix179): "writes per transition" is judged against the phone's own cpufreq slots,
# and chatter by how often the state changes. A CPH2691 read "13 (8+ ... suggests the ladder
# is chattering)" with three slots, 65 unlock lifts, 63 prime bursts, 296 re-sends through a
# vendor hold and 35 state changes an hour. The REAL block of tools/asb_diag.sh runs.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
D="$ROOT/tools/asb_diag.sh"
fail() { echo "FAIL asbdiag write ratio: $*" >&2; exit 1; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
awk '/^  if \[ "\$_ov_t" -gt 0 \] 2>\/dev\/null; then$/ { f = 1 } f { print } f && /^  fi$/ { exit }' "$D" > "$T/b.sh"
grep -q '_ov_nd' "$T/b.sh" || fail "ratio block not found"
run() {  # $1 transitions, $2 writes, $3 slots, $4 uptime
  printf 'governor_transitions=%s\ngovernor_writes=%s\nslot_policy_ids=%s\nunlock_lifts=65\nprime_escape_count=63\nwriter_hold_bypass=296\ngovernor_uptime_s=%s\ncap_vendor_passive=0\ngovernor_vendor_overrides=0\n' "$1" "$2" "$3" "$4" > "$T/st"
  { echo 'P() { echo "$*"; }; _rget() { grep -E "^$1=" "$2" 2>/dev/null | tail -1 | sed "s/^[^=]*=//"; }'
    echo "_state=$T/st; _ov_t=$1; _ov_w=$2"; cat "$T/b.sh"; } > "$T/r.sh"
  sh "$T/r.sh"
}
out="$(run 224 2940 0,2,5 22800)"
printf '%s\n' "$out" | grep 'chattering$' >/dev/null && fail "the CPH2691 still reads as chattering: $out"
printf '%s\n' "$out" | grep 'above the 9 nodes one transition writes on 3 cpufreq slot(s).*65 unlock lift(s), 63 prime burst(s) and 296 re-send(s)' >/dev/null || fail "OP12 breakdown: $out"
printf '%s\n' "$out" | grep '35 an hour, one every 101 s on average - not a chattering ladder' >/dev/null || fail "OP12 rate: $out"
out="$(run 628 5544 0,6,-1 86186)"
printf '%s\n' "$out" | grep 'writes per transition: 8 - above the 7 nodes one transition writes on 2 cpufreq slot(s)' >/dev/null || fail "OP15 ratio: $out"
out="$(run 900 3600 0,6,-1 3600)"
printf '%s\n' "$out" | grep 'normal - one transition writes up to 7 nodes' >/dev/null || fail "normal ratio: $out"
printf '%s\n' "$out" | grep '900 an hour, one every 4 s - the ladder is chattering' >/dev/null || fail "real chatter not named: $out"
out="$(run 5 40 0,6,-1 3600)"
printf '%s\n' "$out" | grep 'too few to judge' >/dev/null || fail "few transitions: $out"
cmp -s "$D" "$ROOT/system/bin/asbdiag" || fail "asbdiag copies differ"
echo "PASS asbdiag write ratio: writes per transition against the phone's own slots, chatter by how often the state changes"
)

t_asbdiag_settings_summary_runtime() (
# Runtime (fix159): asbdiag ends with "your settings vs what is live" - what the user changed
# in the WebUI (name, default -> value), what the device really has (one line per live check,
# the system settings Android refused, what waits for a reboot) and a verdict that reads FAIL,
# not PASS.
#
# Field reports compared "30 PASS" on one phone with "11 PASS" on another and read the second
# as a broken install; the difference was how many tweaks were switched on. The section is cut
# out of the REAL tools/asb_diag.sh (and the REAL V()) and run against the REAL WebUI, shipped
# config and key ownership registry, with a config, a boot-time copy and an apply ledger made
# up here.
set -u
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
D="$ROOT/tools/asb_diag.sh"
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
fail=0; f() { echo "FAIL asbdiag settings summary: $*" >&2; fail=1; }
cmp -s "$D" "$ROOT/system/bin/asbdiag" || f "system/bin/asbdiag is not a copy of tools/asb_diag.sh"
awk '/^SEC "11. YOUR SETTINGS/ { on = 1 } /^P "  PASS=\$PASS/ { exit } on' "$D" > "$T/sec.sh"
grep -q 'WHAT YOU CHOSE' "$T/sec.sh" || { echo "FAIL asbdiag settings summary: section 11 not found" >&2; exit 1; }
awk '/^V\(\) \{/ { on = 1 } on { print } on && /^\}/ { exit }' "$D" > "$T/v.sh"
grep -q 'CHK_LIST=' "$T/v.sh" || f "V() does not record its checks"

mkdir -p "$T/mod/config" "$T/mod/webroot" "$T/state"
cp "$ROOT/config/governor.conf.shipped" "$ROOT/config/key_ownership.tsv" "$T/mod/config/"
cp "$ROOT/webroot/index.html" "$T/mod/webroot/"
S="$T/mod/config/governor.conf.shipped"
sed -e 's/^dsp_loudness=.*/dsp_loudness=25/' -e 's/^CAMERA_LEVEL=.*/CAMERA_LEVEL=10/' \
    -e 's/^media_vol_steps=.*/media_vol_steps=30/' -e 's/^heavy_gpu_enter=.*/heavy_gpu_enter=99/' "$S" > "$T/conf"
grep -q '^dsp_loudness=25$' "$T/conf" && grep -q '^media_vol_steps=30$' "$T/conf" && grep -q '^heavy_gpu_enter=99$' "$T/conf" \
  || { echo "FAIL asbdiag settings summary: shipped config lacks the keys this test edits" >&2; exit 1; }
cp "$T/conf" "$T/boot_same"
cp "$S" "$T/boot_old"
cat > "$T/state/apply_ledger" <<'L'
1|settings|ntp_server|time.example|time.example|time.example|already_set||
2|settings|network_recommendations_enabled|0|1|1|not_writable|write rejected|
3|settings|ram_expand_switch_state|0|1|0|applied||
4|reconcile|uclamp.max|100|0|100|applied||
5|settings|cloud_dns_happy_eyeballs_priority_enabled|off|||unsupported|key absent on this ROM|
6|sysfs|some_node|1|||unsupported|node absent on this device|
L
run() {
  cat > "$T/run.sh" <<EOF
P() { printf '%s\n' "\$1"; }
SEC() { P "== \$1"; }
NOTE() { P "  (i) \$1"; }
MODDIR="$T/mod"; CONF="$1"; ASB_CONFIG_STATE="$T/state"; ASB_DIAG_BOOT_CONF="$2"
PASS=0; FAIL=0; NA=0; OFFN=0; OFF_LIST=""; CHK_LIST=""
. "$T/v.sh"
V "DSP gain applied (persist.asb.dsp.gain_mb)" 2500 2500 eq
V "camera grade live" 10 "$3" eq
. "$T/sec.sh"
EOF
  sh "$T/run.sh" 2>&1
}

o="$(run "$T/conf" "$T/boot_old" 3)"
printf '%s\n' "$o" | grep '^  A. WHAT YOU CHOSE' >/dev/null || f "part A missing"
printf '%s\n' "$o" | awk '/^     Audio$/ { a = 1; next } /^     [A-Z]/ { a = 0 } a && /DSP Loudness/ && /0 -> 25/ && /\[dsp_loudness\]/ { ok = 1 } END { exit !ok }' \
  || f "DSP Loudness not listed under Audio as 0 -> 25 with its key: $o"
printf '%s\n' "$o" | grep 'Camera Grade .*0 -> 10 .*\[CAMERA_LEVEL\]' >/dev/null || f "camera grade change not listed"
printf '%s\n' "$o" | grep 'heavy_gpu_enter' >/dev/null && f "an internal engine key listed as a user choice"
printf '%s\n' "$o" | grep -E '^     3 of [0-9]+ WebUI settings changed' >/dev/null || f "changed-count line wrong: $o"
printf '%s\n' "$o" | grep 'Media Volume Steps .*stock -> 30  (waits for a reboot)' >/dev/null || f "reboot-scoped change not flagged"
printf '%s\n' "$o" | grep '^     waiting for a reboot (changed after this boot, read only at boot):$' >/dev/null || f "waiting-for-reboot heading missing"
printf '%s\n' "$o" | grep '^       Media Volume Steps: stock -> 30   \[media_vol_steps\]$' >/dev/null || f "waiting key not named"
printf '%s\n' "$o" | grep '^       Camera Grade: 0 -> 10   \[CAMERA_LEVEL\]$' >/dev/null || f "reboot-scoped camera grade not listed as waiting"
printf '%s\n' "$o" | grep 'DSP Loudness:' >/dev/null && f "a setting applied live listed as waiting for a reboot"
printf '%s\n' "$o" | grep '^     \[PASS\] DSP gain applied (persist.asb.dsp.gain_mb)  ->  2500$' >/dev/null || f "PASS check not echoed in part B"
printf '%s\n' "$o" | grep '^     \[FAIL\] camera grade live  ->  3$' >/dev/null || f "FAIL check not echoed in part B"
printf '%s\n' "$o" | grep 'applied 1 · already set 1 · refused by Android 1' >/dev/null || f "ledger totals wrong (reconcile rows must not count): $o"
printf '%s\n' "$o" | grep 'refused, not in effect: settings/network_recommendations_enabled (wanted 0, device keeps 1)' >/dev/null || f "refused key not named"
# fix221: an absent-on-this-ROM settings key is counted and listed apart from refusals;
# an unsupported SYSFS node is neither counted nor listed here.
printf '%s\n' "$o" | grep 'refused by Android 1 · not on this ROM 1' >/dev/null || f "absent-on-ROM count missing: $o"
printf '%s\n' "$o" | grep '^       not on this ROM: settings/cloud_dns_happy_eyeballs_priority_enabled (wanted off) - this ROM has no such setting; nothing is wrong$' >/dev/null || f "absent-on-ROM key not listed: $o"
printf '%s\n' "$o" | grep 'some_node' >/dev/null && f "an unsupported sysfs node leaked into the settings list: $o"
printf '%s\n' "$o" | grep '^     FAIL=1 - these did not take effect' >/dev/null || f "verdict does not name the failure count"
printf '%s\n' "$o" | grep '^       camera grade live: want 10, live 3$' >/dev/null || f "failing check not listed in the verdict"
printf '%s\n' "$o" | grep 'Read FAIL, not PASS' >/dev/null || f "PASS-count explanation missing"

o="$(run "$T/conf" "$T/boot_same" 10)"
printf '%s\n' "$o" | grep '^     waiting for a reboot: nothing' >/dev/null || f "nothing pending not said when the boot copy matches"
printf '%s\n' "$o" | grep '(waits for a reboot)' >/dev/null && f "a change already booted with flagged as waiting"
printf '%s\n' "$o" | grep '^     FAIL=0 · REFUSED=1 - every live check passed, but 1 Android system setting(s) are not in effect (listed above).$' >/dev/null || f "refused setting disappeared from the FAIL=0 verdict"
printf '%s\n' "$o" | grep 'FAIL=0 - everything this report can check' >/dev/null && f "refused setting still allows the unconditional clean verdict"

mv "$T/state/apply_ledger" "$T/state/apply_ledger.off"
o="$(run "$T/conf" "$T/boot_same" 10)"
printf '%s\n' "$o" | grep '^     FAIL=0 - everything this report can check for your settings is in effect.$' >/dev/null || f "genuinely clean verdict missing"
mv "$T/state/apply_ledger.off" "$T/state/apply_ledger"

o="$(run "$S" "$T/missing" 10)"
printf '%s\n' "$o" | grep '^     nothing - every setting is at its shipped default$' >/dev/null || f "all-default config not described: $o"
printf '%s\n' "$o" | grep '^     waiting for a reboot: unknown' >/dev/null || f "missing boot copy not reported as unknown"
printf '%s\n' "$o" | grep 'not an install error' >/dev/null || f "default-is-not-an-error line missing"

grep -q 'cp -f "$MODDIR/config/governor.conf" /dev/.asb_profile_state/governor.boot.conf' "$ROOT/post-fs-data.sh" \
  || f "post-fs-data does not keep the config this boot used"
[ "$fail" = 0 ] && echo "PASS asbdiag settings summary: your choices, what is live, refused writes, pending reboots and REFUSED-aware verdicts"
exit "$fail"
)

t_profile_trial_audit() (
set -eu
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
python3 - "$ROOT/tools" <<'PYTEST'
import hashlib, pathlib, subprocess, sys, tempfile
sys.path.insert(0, sys.argv[1])
from asb_profile_trial import evaluate, template, verify_artifacts
trial = template()
for field in ("model", "rom_fingerprint", "kernel", "device_alias", "workload", "A", "B"):
    trial[field] = field
for rule in trial["metrics"].values():
    rule["tolerance"] = 0.5
for i, order in enumerate(("AA", "AB", "BA", "AB")):
    for j, variant in enumerate(order):
        trial["runs"].append({"id": f"{i}-{j}", "pair": str(i), "variant": variant,
                              "duration_s": 30, "conditions": "fixed",
                              "values": {key: 10 if variant == "A" else 8 for key in trial["metrics"]}})
assert evaluate(trial)["status"] == "incomplete_provenance"
trial["provenance"] = {"asb_commit": "a" * 40, "asb_zip_sha256": "b" * 64,
                       "kernel_buildinfo_sha256": "c" * 64, "config_sha256": "d" * 64}
assert evaluate(trial)["status"] == "unverified_provenance"
assert evaluate(trial)["observed_status"] == "repeatable_gain_in_this_cohort"
with tempfile.TemporaryDirectory() as d:
    p = pathlib.Path(d); repo = p/'repo'; repo.mkdir()
    subprocess.run(['git', 'init', '-q', str(repo)], check=True)
    subprocess.run(['git', '-C', str(repo), '-c', 'commit.gpgsign=false', '-c', 'user.email=test@example.invalid', '-c', 'user.name=Test', 'commit', '--allow-empty', '-qm', 'fixture'], check=True)
    files = [p/name for name in ('asb.zip', 'kernel.json', 'config')]
    for i, f in enumerate(files): f.write_text(f'fixture {i}')
    trial['provenance'] = dict(asb_commit=subprocess.check_output(['git','-C',str(repo),'rev-parse','HEAD'], text=True).strip(),
                               **dict(zip(('asb_zip_sha256','kernel_buildinfo_sha256','config_sha256'), (hashlib.sha256(f.read_bytes()).hexdigest() for f in files))))
    assert verify_artifacts(trial['provenance'], *files, repo)
    assert evaluate(trial, artifacts_match=True)['status'] == 'repeatable_gain_in_this_cohort'
    files[0].write_text('modified')
    try: verify_artifacts(trial['provenance'], *files, repo)
    except ValueError: pass
    else: raise AssertionError('tampered archive was accepted')
    files[0].write_text('fixture 0')
    (repo/'uncommitted').write_text('dirty')
    try: verify_artifacts(trial['provenance'], *files, repo)
    except ValueError: pass
    else: raise AssertionError('dirty repository was accepted')
trial["runs"][-1]["values"]["surface_peak_c"] = 11
assert evaluate(trial)["status"] == "regression"
trial['provenance'] = {}
assert evaluate(trial)["status"] == "regression", 'missing provenance must not hide an observed regression'
trial["runs"][-1]["excluded_reason"] = "charging"
result = evaluate(trial)
assert result["status"] == "insufficient_data" and result["excluded_pairs"] == {"3": "charging"}
PYTEST
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
cd "$T"
mkdir -p sys/devices/system/cpu/cpufreq/policy7 proc/pressure
echo 3200000 > sys/devices/system/cpu/cpufreq/policy7/scaling_max_freq
echo 'some avg10=0.00 total=100' > proc/pressure/memory
echo 'governor_writes=23' > state
ASB_TRIAL_SYS="$PWD/sys" ASB_TRIAL_PROC="$PWD/proc" ASB_TRIAL_STATE="$PWD/state" sh "$ROOT/tools/asb_trial_snapshot.sh" > snapshot
awk '$1=="policy7/scaling_max_freq" && $2==3200000 {cpu=1} $1=="governor_writes" && $2==23 {gov=1} $1=="psi/memory/some" {psi=1} END {exit !(cpu && gov && psi)}' snapshot
git init -q
git config user.name Test
git config user.email fixture@example.invalid
echo base > base; git add base; git commit -qm base
base=$(git rev-parse HEAD)
echo fixed > fix; git add fix; git commit -qm fix
fix=$(git rev-parse HEAD)
tool="$ROOT/tools/asb_fix_history.sh"
[ "$("$tool" "$fix" "$fix")" = fix_in_history ]
[ "$("$tool" "$fix" "$base")" = patch_not_found ]
git checkout -q --detach "$base"
echo other > other; git add other; git commit -qm other
git cherry-pick "$fix" >/dev/null
[ "$("$tool" "$fix" "$(git rev-parse HEAD)")" = equivalent_patch_in_history ]
)
t_capture_compare_runtime() (
# Runtime (fix152): the host comparison of field logs, build against build.
#
# Asked for: "after the tests I will send a new archive of logs from different users - compare
# how much better it got". The REAL tool reads full-day captures and asbdiag reports from
# folders and zips (a zip inside a zip too), counts a capture sent twice once, saves the
# figures (--json) and compares a new set with them per phone model (--baseline): lower drain
# and fewer janky frames read "better", a figure the report marks '~' is not compared.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
TOOL="$ROOT/tools/asb_capture_compare.py"
fail() { echo "FAIL capture compare: $*" >&2; exit 1; }
command -v python3 >/dev/null 2>&1 || { echo "SKIP capture compare: no python3"; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
cap() {   # dir model start night_pct night_awake idle_pct janky_s li_s cpu_ms wifi_med
  mkdir -p "$1"
  printf 'model:           %s\nfingerprint: fixture/android/build\nkernel_release: fixture-kernel\nmodule_version:  V65-debug%s\noem_build:       X\n' "$2" "$3" > "$1/env.txt"
  printf '# phase timeline\n%s|2026-10-20 08:00:00|active|capture_start\n' "$3" > "$1/phase_timeline.txt"
  printf 'governor_cpu_ms=%s\ngovernor_uptime_s=36000\n' "$9" > "$1/snapshot_1.txt"
  cat > "$1/_full_day_report.txt" <<R
 capture: 24h target, 1200 min elapsed
===== UI SMOOTHNESS (screen-on, HWUI frames of every app) =====
all screen-on intervals: 400  frames 900000  janky 4.0%  deadline missed 4.0%  slow UI thread 2.0%
janky frames per second on screen: $7
ASB state        intervals    frames    janky  janky/s
MODERATE               278    756613     3.0%     1.70
LIGHT_IDLE              65     44071    28.1%     $8

steady floor: 1.11 janky frames a second while almost nothing was drawn (under 5 frames/s),
1.73 a second in the busy intervals (20 frames/s and more). Something misses a deadline about
screen-on samples 472: prime cores working in 14%, main cores in 81%
===== WI-FI LEAVE (the leave-bad-Wi-Fi watcher, this capture) =====
releases: 3 (out of range 2, no internet 1) - Wi-Fi given back after the window: 3, could not disable: 0
first failing reading to the release: median ${10} s, longest 12 s (3 release(s))
===== PER-PHASE SUMMARY =====

phase            dur_min   d_pct    pct/h     mA  rmnetMiB     cpuT    surfT     p6MHz    gpu%  throttle   awake%
active             142.2      26   10.97     297    1420.4       39       35       917       7        39     98.1
idle               126.3       4    $6     182     106.1       34       36       806       5         0     23.5
sleep              553.9       6    0.65     155     113.2       36       38       768       4         0      5.1
night(longest)     538.2       5     $4    154         -       37       39       768       -         -      $5

Legend: x
R
}
cap "$T/old/a" CPH2745 1000 0.56 4.0 1.90 2.08 3.92 18000 20
cap "$T/old/b" CPH2691 2000 0.90 9.0 5.50 1.94 2.50 18000 20
cap "$T/new/a" CPH2745 3000 0.44 3.0 1.95 1.80 2.00 14400 6
cap "$T/new/b" CPH2691 4000 0.95 9.5 3.36~ 1.94 2.50 18000 6
( cd "$T/new" && mkdir -p z && cp -r a z/dup && cd z && python3 -c "
import zipfile,os
with zipfile.ZipFile('inner.zip','w') as z:
    for r,_,fs in os.walk('dup'):
        for f in fs: z.write(os.path.join(r,f))
with zipfile.ZipFile('../outer.zip','w') as z: z.write('inner.zip')
" && cd .. && rm -rf z )
cat > "$T/new/diag.txt" <<'D'
################################################################
#         AutoSystemBoost — GLOBAL SYSTEM DIAGNOSTIC            #
################################################################
 date    : Mon Oct 20 10:00:00 CEST 2026
 device  : OnePlus CPH2745  (OP611FL1)
 version : V65-debug9  (650)
  ASB overhead          : event_wakeups=1 timer_wakeups=2 cpu_ms=14201 over 8 h 36 min = 1.6 s of CPU per hour
    mSafeMediaVolumeState=SAFE_MEDIA_VOLUME_INACTIVE
  (i) net_txqueue=short - live: rmnet_data0=1000 wlan0=256
  (i) doze_trim_whitelist = 1 · trimmed by ASB: 7 · kept (WebUI list): 3 · made exempt by ASB: 1
    audio_remove_volume_limit=1
D
python3 "$TOOL" "$T/old" --json "$T/base.json" --label base > "$T/o1" || fail "baseline run failed"
grep -q '^FULL-DAY CAPTURES (2)$' "$T/o1" || fail "baseline captures: $(head -3 "$T/o1")"
python3 "$TOOL" "$T/new" "$T/new/outer.zip" --baseline "$T/base.json" > "$T/o2" || fail "compare run failed"
grep -q '^FULL-DAY CAPTURES (2)$' "$T/o2" || fail "a capture sent twice (a zip inside a zip) counted twice: $(grep -c CPH2745 "$T/o2")"
grep -q '^night %/h *0.56 *0.44 .*lower' "$T/o2" || fail "night not better: $(grep 'night %/h' "$T/o2")"
grep -q '^LIGHT_IDLE janky/s *3.92 *2.00 .*lower' "$T/o2" || fail "LIGHT_IDLE jank: $(grep LIGHT "$T/o2")"
grep -q '^Wi-Fi leave median s *20 *6 .*lower' "$T/o2" || fail "Wi-Fi leave: $(grep 'Wi-Fi leave' "$T/o2")"
grep -q '^ASB CPU s/h *1.80 *1.44 .*lower' "$T/o2" || fail "ASB CPU: $(grep 'ASB CPU s/h' "$T/o2")"
grep -q '^night %/h *0.90 *0.95 .*higher' "$T/o2" || fail "a 5% change called a verdict: $(grep 'night %/h' "$T/o2")"
grep -q '^idle %/h *5.50 *- ' "$T/o2" || fail "a '~' figure was compared: $(grep 'idle %/h' "$T/o2")"
grep -q 'wlan0=256' "$T/o2" || fail "the Wi-Fi queue from asbdiag is not shown"
grep -q 'doze trim 7/kept 3/granted 1' "$T/o2" || fail "the doze trim figures from asbdiag are not shown"
python3 -c "import json,sys; d=json.load(open(sys.argv[1])); assert d['label']=='base' and len(d['captures'])==2" "$T/base.json" || fail "saved figures unreadable"
python3 "$TOOL" "$ROOT/docs/field_baseline" --baseline "$ROOT/docs/field_baseline/fix150.json" >/dev/null || fail "the stored fix150 baseline does not load"
sed -i 's/fixture-kernel/other-kernel/' "$T/new/a/env.txt"
python3 "$TOOL" "$T/new/a" --baseline "$T/base.json" > "$T/other"
grep -q 'only in the new logs' "$T/other" || fail "kernel cohorts mixed"
if grep -q '^night %/h ' "$T/other"; then fail "cross-kernel battery delta"; fi
echo "PASS capture compare: field logs read from folders and nested zips, one capture once, build against build per model"
)

t_capture_compare_warm_runtime() (
# Runtime (fix156): the comparison reads how the clusters were used while the phone was warm.
#
# fix156 keeps the main cores level with the prime under Smart's comfort trim and in HEAVY and
# SUSTAINED. What should change in the next round of logs: fewer warm screen-on samples with the
# main ceiling under the prime's, the prime working less, a lower sampled current. The REAL
# tool computes those from the raw traces of a capture (so captures made before the report
# printed them compare too): screen-on samples only, surface 40 C and above, capacities from the
# governor state, hardware maxima from the throttle trace; and the --baseline table names them.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
TOOL="$ROOT/tools/asb_capture_compare.py"
fail() { echo "FAIL capture compare warm: $*" >&2; exit 1; }
command -v python3 >/dev/null 2>&1 || { echo "SKIP capture compare warm: no python3"; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
cap() {
  d="$T/$1"; mkdir -p "$d"
  printf 'model:           CPH2745\nfingerprint: fixture/android/build\nkernel_release: fixture-kernel\nmodule_version:  V65-debug%s\n' "$2" > "$d/env.txt"
  printf '%s|2026-10-20 08:00:00|active|capture_start\n' "$3" > "$d/phase_timeline.txt"
  printf ' capture: 24h target, 600 min elapsed\n' > "$d/_full_day_report.txt"
  printf 'main_parity_capacity="762,1024"\n' > "$d/snapshot_1.txt"
  printf '# throttle trace\n%s|active|p0_max=1555200/3628800|p6_max=1862400/4608000|cpu_temp=50\n' "$3" > "$d/throttle_trace.txt"
  echo "epoch|datetime|phase|screen|bl_raw|bl_max|bl_pct|refresh_hz|bat_mA|wake|disp_state" > "$d/display_trace.txt"
  echo "epoch|datetime|x|x|x|x|x|x|x|x|x|x|p0_cur|p0_max|p6_cur|p6_max|x|x|x|x|x|bat_mA|x|x|x|x|x|x|x|x|x|x|x|x|x|surface_c" > "$d/perf_trace.txt"
}
row() {   # dir epoch screen p0_max p6_cur p6_max mA surface
  echo "$2|d|active|$3|1|1|1|90|1||" >> "$T/$1/display_trace.txt"
  echo "$2|d|||||||||||1|$4|$5|$6||||||$7||||||||||||||$8" >> "$T/$1/perf_trace.txt"
}
cap old 8 1000
e=1000
for i in 1 2 3 4; do row old $e 1 1555200 1862400 1862400 480 44; e=$((e + 20)); done
for i in 1 2; do row old $e 1 1996800 768000 1862400 340 43; e=$((e + 20)); done
row old $e 1 1555200 1862400 1862400 900 33; e=$((e + 20))
row old $e 0 1555200 1862400 1862400 900 45; e=$((e + 20))
cap new 10 5000
e=5000
for i in 1 2 3 4 5; do row new $e 1 1996800 768000 1862400 330 44; e=$((e + 20)); done
row new $e 1 1996800 1862400 1862400 410 42
python3 "$TOOL" "$T/old" --json "$T/base.json" --label old > "$T/o1" 2>&1 || { cat "$T/o1" >&2; fail "tool failed"; }
python3 - "$T/base.json" <<'P' || fail "warm figures of the old capture"
import json, sys
c = json.load(open(sys.argv[1]))["captures"][0]
want = {"warm_on_n": 6, "warm_below_pct": 66.7, "warm_prime_pct": 66.7, "warm_on_ma": 433}
bad = {k: (c.get(k), v) for k, v in want.items() if c.get(k) != v}
if bad:
    print(bad); sys.exit(1)
P
python3 "$TOOL" "$T/new" --baseline "$T/base.json" > "$T/o2" 2>&1 || { cat "$T/o2" >&2; fail "comparison failed"; }
grep -qE '^warm: main under prime % +66\.70 +0\.00 +-66\.70 \(-100%\) +lower' "$T/o2" || fail "main-under-prime row: $(cat "$T/o2")"
grep -qE '^warm: prime working % +66\.70 +16\.70 .* lower' "$T/o2" || fail "prime row: $(cat "$T/o2")"
grep -qE '^warm screen-on mA +433 +343 .* lower' "$T/o2" || fail "current row: $(cat "$T/o2")"
cap cool 9 9000
e=9000
for i in 1 2 3 4 5 6; do row cool $e 1 1555200 1862400 1862400 480 35; e=$((e + 20)); done
python3 "$TOOL" "$T/cool" --json "$T/cool.json" > "$T/o3" 2>&1 || fail "cool capture"
python3 -c "import json,sys; c=json.load(open(sys.argv[1]))['captures'][0]; sys.exit(0 if c['warm_on_n'] is None and c['warm_on_ma'] is None else 1)" "$T/cool.json" || fail "a capture that never got warm produced warm figures"
echo "PASS capture compare warm: warm screen-on samples, main under the prime, prime work and current, from the raw traces"
)

t_cluster_roles_runtime() (
# Runtime (fix146): the capture judges the cores the governor calls main, and says which.
#
# 1. The jank trace took the lowest and the highest policy for "main" and "prime". On a
#    1+3+2+1 part (CPH2691, SM8650: policies 0/2/5/7) "main" was the A520 pair, which runs
#    no UI - every "main cores at the ASB ceiling" line of those captures described the
#    wrong cores. Main and prime now come from the governor's slot_policy_ids.
# 2. The report names them where it is not the obvious pair, and the throttle split calls
#    slot 0 "little" there instead of "main".
# 3. The per-app table went to the app with the most frames only; on PLQ110 capture 28616
#    that was the app store while "LIGHT_IDLE 25.6% janky" was YouTube playing untouched.
#    The app in front with the most janky frames gets its own table.
# 4. asbdiag called policy0 of a 6+2 part "little".
# The REAL functions run here.
set -u
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
C="$ROOT/tools/logkit/_asb_logkit_common.sh"
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
fail=0; f() { echo "FAIL cluster roles: $*" >&2; fail=1; }

# --- 1. roles from the governor's map --------------------------------------------------------
roles() { printf 'slot_policy_ids=%s\n' "$1" > "$T/st"; ASB_LK_STATE_FILE="$T/st" sh -c '. "$0" >/dev/null 2>&1; lk_cluster_roles' "$C"; }
[ "$(roles 0,2,7)" = "2 7 0" ] || f "1+3+2+1 map: '$(roles 0,2,7)' (want main 2, prime 7, little 0)"
[ "$(roles 0,6,-1)" = "0 6 -" ] || f "6+2 map: '$(roles 0,6,-1)' (want main 0, prime 6)"
: > "$T/st"
[ -z "$(ASB_LK_STATE_FILE="$T/st" sh -c '. "$0" >/dev/null 2>&1; lk_cluster_roles' "$C")" ] || f "roles invented with no map"

# --- 2. the recorder measures policy2, not policy0, on a 4-cluster part ----------------------
for p in 0 2 5 7; do mkdir -p "$T/cpufreq/policy$p/stats"; done
# policy0 (little) idles far below its ceiling; policy2 (main) sits at it the whole interval.
echo 1017600 > "$T/cpufreq/policy0/scaling_max_freq"; echo 364800 > "$T/cpufreq/policy0/scaling_cur_freq"
echo 1497600 > "$T/cpufreq/policy2/scaling_max_freq"; echo 1497600 > "$T/cpufreq/policy2/scaling_cur_freq"
echo 1497600 > "$T/cpufreq/policy5/scaling_max_freq"; echo 1497600 > "$T/cpufreq/policy5/scaling_cur_freq"
echo 1593600 > "$T/cpufreq/policy7/scaling_max_freq"; echo 480000  > "$T/cpufreq/policy7/scaling_cur_freq"
printf '364800 1000\n1017600 0\n' > "$T/cpufreq/policy0/stats/time_in_state"
printf '499200 0\n1497600 1000\n' > "$T/cpufreq/policy2/stats/time_in_state"
printf '480000 1000\n1593600 0\n' > "$T/cpufreq/policy7/stats/time_in_state"
printf 'state=MODERATE\ntouch_starts=1\nslot_policy_ids=0,2,7\n' > "$T/st4"
gfx() { printf 'Package: com.x\nStats since: 1000ns\nTotal frames rendered: %s\nJanky frames: %s (1.00%%)\nNumber Frame deadline missed: %s\nNumber Slow UI thread: 0\nNumber High input latency: 0\n' "$2" "$3" "$3" > "$1"; }
gfx "$T/g1" 1000 10; gfx "$T/g2" 3000 50
mkdir -p "$T/c"
rec="$(LK_OUT_DIR="$T/c" ASB_LK_CPUFREQ_ROOT="$T/cpufreq" ASB_LK_STATE_FILE="$T/st4" T="$T" sh -c '
  . "$0" >/dev/null 2>&1
  lk_jank_trace_header
  ASB_LK_GFXSTATS_DUMP="$T/g1" lk_capture_jank_row active 1
  printf "499200 0\n1497600 2000\n" > "$T/cpufreq/policy2/stats/time_in_state"
  printf "364800 2000\n1017600 0\n" > "$T/cpufreq/policy0/stats/time_in_state"
  printf "480000 2000\n1593600 0\n" > "$T/cpufreq/policy7/stats/time_in_state"
  ASB_LK_GFXSTATS_DUMP="$T/g2" lk_capture_jank_row active 1
  grep -v "^#" "$LK_OUT_DIR/jank_trace.tsv"
' "$C" 2>&1)"
r="$(printf '%s\n' "$rec" | grep '|active|' | head -1)"
[ "$(printf '%s' "$r" | cut -d'|' -f6)" = 1 ] || f "main_at_cap not from policy2 (at its ceiling): $r"
[ "$(printf '%s' "$r" | cut -d'|' -f14)" = 100 ] || f "main_cap_pct not from policy2 (100% at the ceiling): $r"
[ "$(printf '%s' "$r" | cut -d'|' -f7)" = 0 ] || f "prime_at_cap not from policy7: $r"
L="$T/c/cluster_layout.txt"
[ -s "$L" ] || f "no cluster_layout.txt"
grep -qx 'policies=0 2 5 7' "$L" || f "layout policies: $(cat "$L" 2>/dev/null)"
grep -qx 'main=policy2' "$L" && grep -qx 'prime=policy7' "$L" && grep -qx 'little=policy0' "$L" || f "layout roles: $(cat "$L" 2>/dev/null)"
# A 6+2 part: no little line, policy0 is main.
mkdir -p "$T/c2" "$T/cf2/policy0" "$T/cf2/policy6"
printf 'slot_policy_ids=0,6,-1\n' > "$T/st2"
LK_OUT_DIR="$T/c2" ASB_LK_CPUFREQ_ROOT="$T/cf2" ASB_LK_STATE_FILE="$T/st2" sh -c '. "$0" >/dev/null 2>&1; lk_jank_trace_header' "$C"
grep -qx 'main=policy0' "$T/c2/cluster_layout.txt" && ! grep -q '^little=' "$T/c2/cluster_layout.txt" || f "6+2 layout: $(cat "$T/c2/cluster_layout.txt" 2>/dev/null)"

# --- 3. report: names the clusters on a 4-cluster part only --------------------------------
J="$T/c/jank_trace.tsv"
i=0
row() {   # state touches frames janky front pkgs
  i=$((i + 1))
  printf '%s|t|active|%s|48|1|0|%s|%s|%s|%s|5|1|70|0|%s|%s\n' "$i" "$1" "$2" "$3" "$4" "$4" "$5" "$6" >> "$J"
}
for k in 1 2 3 4 5 6; do row MODERATE 2 9000 30 com.heytap.market "com.heytap.market:28:8800"; done
for k in 1 2; do row MODERATE 0 3000 0 com.heytap.market "-"; done
for k in 1 2 3; do row MODERATE 0 600 130 com.google.android.youtube "com.google.android.youtube:128:590"; done
for k in 1 2 3 4; do row LIGHT_IDLE 0 500 135 com.google.android.youtube "com.google.android.youtube:134:495"; done
out="$(sh -c '. "$0" >/dev/null 2>&1; LK_OUT_DIR="$1"; lk_emit_jank_summary' "$C" "$T/c" 2>&1)"
printf '%s\n' "$out" | grep '^main cores below = policy2 and policy5 (the middle clusters, under one ceiling), prime = policy7; the little cluster (policy0) runs no UI and is not in these lines.$' >/dev/null \
  || f "4-cluster layout line: $out"
printf '%s\n' "$out" | grep '^within com.heytap.market (most frames), by ASB state and touch:$' >/dev/null || f "most-frames table: $out"
printf '%s\n' "$out" | grep '^within com.google.android.youtube (most janky frames), by ASB state and touch:$' >/dev/null || f "no table for the app with the most janky frames: $out"
printf '%s\n' "$out" | awk '/^within com.google.android.youtube/ { f = 1; next } /^within |^  Compare/ { f = 0 } f' > "$T/yt"
grep -qE '^  MODERATE +no +3 +1800 +21\.7% +2\.71$' "$T/yt" || f "YouTube MODERATE row: $(cat "$T/yt")"
grep -qE '^  LIGHT_IDLE +no +4 +2000 +27\.0% +2\.81$' "$T/yt" || f "YouTube LIGHT_IDLE row: $(cat "$T/yt")"
[ "$(printf '%s\n' "$out" | grep -c '^  Compare states inside one app')" = 1 ] || f "the caveat is printed once: $out"
printf '%s\n' "$out" | grep -q '^  touch = a touch began after 3 s without one; steady typing or scrolling can read no.$' || f "touch column not explained: $out"
# Same app most frames and most janky: one table. 6+2 layout: no cluster line.
mkdir -p "$T/d"; J="$T/d/jank_trace.tsv"; i=0; echo "# h" > "$J"
cp "$T/c2/cluster_layout.txt" "$T/d/"
for k in 1 2 3; do row MODERATE 1 4000 40 com.a "com.a:40:4000"; done
for k in 1 2; do row LIGHT_IDLE 0 300 20 com.a "com.a:20:300"; done
for k in 1 2; do row MODERATE 1 200 5 com.b "com.b:5:200"; done
out="$(sh -c '. "$0" >/dev/null 2>&1; LK_OUT_DIR="$1"; lk_emit_jank_summary' "$C" "$T/d" 2>&1)"
[ "$(printf '%s\n' "$out" | grep -c '^within ')" = 1 ] || f "two tables for one app: $out"
printf '%s\n' "$out" | grep '^main cores below' >/dev/null && f "cluster line on a 6+2 part: $out"

# --- 4. throttle split: slot 0 is the little pair there --------------------------------------
printf '1|active|p0_max=1/2|p6_max=1/2|cpu_temp=40|surface=33|cap_owner=asb|main_by=asb_trim|prime_by=vendor\n' > "$T/thr"
out="$(LK_OUT_DIR="$T/c" sh -c '. "$0" >/dev/null 2>&1; lk_emit_cap_cause_split "$1"' "$C" "$T/thr")"
printf '%s\n' "$out" | grep -E '^  little: asb_trim 1$' >/dev/null || f "4-cluster split still says main: $out"
printf '%s\n' "$out" | grep 'little = policy0, the efficiency cores' >/dev/null || f "little note: $out"
out="$(LK_OUT_DIR="$T/d" sh -c '. "$0" >/dev/null 2>&1; lk_emit_cap_cause_split "$1"' "$C" "$T/thr")"
printf '%s\n' "$out" | grep -E '^  main: +asb_trim 1$' >/dev/null || f "6+2 split: $out"
grep -q 'the LPM feature or the cellular power policy (radio_policy_enable, off by default) is off' "$ROOT/tools/logkit/asb_log_full_day.sh" \
  || f "an empty modem LPM line still prints nothing"

# --- 5. asbdiag: policy0 of a 6+2 part is "main" ---------------------------------------------
D="$ROOT/tools/asb_diag.sh"
grep -q '_tier="little"; \[ "$_npol" -eq 2 \] && _tier="main"' "$D" || f "asbdiag policy list calls the six main cores little"
grep -q '\[ "$_ncl" -eq 2 \] && _role=main' "$D" || f "asbdiag slot map calls the six main cores little"
cmp -s "$D" "$ROOT/system/bin/asbdiag" || f "asbdiag copies differ"

[ "$fail" = 0 ] && echo "PASS cluster roles: main/prime from the governor's map, named in the report, a table for the jankiest app, asbdiag labels"
exit "$fail"
)

t_page_export_runtime() (
set -euo pipefail
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
E="$ROOT/runtime/asb_page_export.sh"
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
fail() { echo "FAIL page export: $*" >&2; exit 1; }
sh -n "$E"
mkdir -p "$T/logs"
export ASB_PAGE_EXPORT_OUTDIR="$T/logs"
STAMP=20261118_144905
OUT="$T/logs/asb_report_${STAMP}.txt"
python3 - "$T" <<'PY'
import base64, pathlib, sys
root=pathlib.Path(sys.argv[1])
raw=('Привет, OnePlus 15 — диагностика\nASCII and 汉字\n' * 1800).encode('utf-8')
(root/'expected').write_bytes(raw)
b64=base64.b64encode(raw).decode('ascii')
for n,pos in enumerate(range(0,len(b64),48000)):
    (root/f'chunk.{n:03d}').write_text(b64[pos:pos+48000],encoding='ascii')
PY
[ "$(find "$T" -maxdepth 1 -name 'chunk.*' | wc -l)" -ge 2 ] || fail "fixture did not produce multiple chunks"
r="$(sh "$E" begin report "$STAMP" '')"
[ "$r" = status=started ] || fail "begin: $r"
[ -f "$T/logs/.asb_report_${STAMP}.b64" ] || fail "begin created no bounded temporary file"
for c in "$T"/chunk.*; do
  part="$(cat "$c")"
  r="$(sh "$E" append report "$STAMP" "$part")"
  [ "$r" = status=appending ] || fail "append: $r"
done
r="$(sh "$E" finish report "$STAMP")"
printf '%s\n' "$r" | grep -Fx 'status=saved' >/dev/null || fail "finish status: $r"
printf '%s\n' "$r" | grep -Fx "path=$OUT" >/dev/null || fail "finish path: $r"
cmp -s "$T/expected" "$OUT" || fail "UTF-8/multichunk round trip changed the page"
find "$T/logs" -maxdepth 1 -type f \( -name '.*.b64' -o -name '.*.decoded.*' \) | grep . && fail "temporary export file survived finish"

STAMP2=20261118_145000
sh "$E" begin zygisk "$STAMP2" '' >/dev/null
sh "$E" append zygisk "$STAMP2" 'QUJD' >/dev/null
[ "$(sh "$E" abort zygisk "$STAMP2")" = status=cancelled ] || fail "abort acknowledgement"
[ ! -e "$T/logs/asb_zygisk_${STAMP2}.txt" ] || fail "abort published a partial file"
[ ! -e "$T/logs/.asb_zygisk_${STAMP2}.b64" ] || fail "abort left its temporary file"
if r="$(sh "$E" append device 20261118_145001 'QUJD' 2>&1)"; then rc=0; else rc=$?; fi
[ "$rc" -eq 4 ] && [ "$r" = error=export_not_started ] || fail "append without begin: rc=$rc $r"
if r="$(sh "$E" begin '../../bad' "$STAMP" '' 2>&1)"; then rc=0; else rc=$?; fi
[ "$rc" -eq 2 ] && [ "$r" = error=bad_kind ] || fail "unsafe kind: rc=$rc $r"
if r="$(sh "$E" begin report '../../bad' '' 2>&1)"; then rc=0; else rc=$?; fi
[ "$rc" -eq 2 ] && [ "$r" = error=bad_stamp ] || fail "unsafe stamp: rc=$rc $r"
[ ! -e "$T/bad" ] && [ ! -e "$T/logs/../../bad" ] || fail "unsafe input created a path"
STAMP3=20261118_145002
sh "$E" begin device "$STAMP3" '' >/dev/null
if r="$(sh "$E" append device "$STAMP3" '***' 2>&1)"; then rc=0; else rc=$?; fi
[ "$rc" -eq 2 ] && [ "$r" = error=bad_base64 ] || fail "base64 alphabet: rc=$rc $r"
if r="$(sh "$E" append device "$STAMP3" 'A' 2>&1)"; then rc=0; else rc=$?; fi
[ "$rc" -eq 0 ] || fail "bounded malformed payload was not passed to atomic decode: $r"
if r="$(sh "$E" finish device "$STAMP3" 2>&1)"; then rc=0; else rc=$?; fi
[ "$rc" -eq 5 ] && [ "$r" = error=export_decode_failed ] || fail "malformed base64 finish: rc=$rc $r"
[ ! -e "$T/logs/asb_device_${STAMP3}.txt" ] && [ ! -e "$T/logs/.asb_device_${STAMP3}.b64" ] || fail "decode failure left output/temp files"
printf 'not a directory\n' > "$T/notdir"
if r="$(ASB_PAGE_EXPORT_OUTDIR="$T/notdir" sh "$E" begin report "$STAMP" '' 2>&1)"; then rc=0; else rc=$?; fi
[ "$rc" -eq 5 ] && [ "$r" = error=export_outdir_failed ] || fail "invalid output directory: rc=$rc $r"
! grep -Fq '/sdcard/Download' "$E" || fail "Download fallback remains"
echo 'PASS page export: fixed ASB/logs destination, UTF-8 multichunk round trip, atomic finish, abort/decode cleanup and unsafe-input rejection'
)

t_debug_support_contract() (
# Contract: debug WebUI support actions stay debug-gated, bounded and non-overlapping.
set -euo pipefail
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
HELPER="$ROOT/runtime/asb_debug_support.sh"
TIMELINE="$ROOT/runtime/asb_boot_timeline.sh"
DIAG="$ROOT/tools/asb_diag.sh"
INSTALLED_DIAG="$ROOT/system/bin/asbdiag"
UI="$ROOT/webroot/index.html"
TMP="$(mktemp -d)"
trap 'if [ -n "${REC_PID:-}" ]; then kill "$REC_PID" 2>/dev/null || true; fi; rm -rf "$TMP"' EXIT

need() { grep -Fq -- "$2" "$1" || { echo "FAIL debug support: missing [$2]" >&2; exit 1; }; }
count_exact() {
  _actual="$(grep -Foc -- "$2" "$1" 2>/dev/null || true)"
  [ "$_actual" -eq "$3" ] || { echo "FAIL debug support: expected $3 [$2], found $_actual" >&2; exit 1; }
}
[ -f "$HELPER" ] || { echo "FAIL debug support: helper missing" >&2; exit 1; }
[ -f "$TIMELINE" ] || { echo "FAIL debug support: boot timeline helper missing" >&2; exit 1; }
[ -f "$DIAG" ] && [ -f "$INSTALLED_DIAG" ] || { echo "FAIL debug support: asbdiag copy missing" >&2; exit 1; }
sh -n "$HELPER"
sh -n "$TIMELINE"
cmp -s "$DIAG" "$INSTALLED_DIAG" || { echo "FAIL debug support: asbdiag copies diverged" >&2; exit 1; }
sed -n '/^P()  {/p' "$DIAG" > "$TMP/p.sh"
[ -s "$TMP/p.sh" ] || { echo 'FAIL debug support: P function missing' >&2; exit 1; }
OUT1="$TMP/direct-copy" OUT2='' sh -c '. "$1"; P terminal; [ "$?" -eq 0 ]' x "$TMP/p.sh" || { echo 'FAIL debug support: empty optional OUT2 became terminal failure' >&2; exit 1; }
[ "$(cat "$TMP/direct-copy")" = terminal ] || { echo 'FAIL debug support: direct ASB/logs copy missing' >&2; exit 1; }
need "$DIAG" 'OUT1="/sdcard/ASB/logs/asb_diag_report.txt"; OUT2=""'
need "$HELPER" 'ASB_DIAG_NO_SIDE_COPIES=1 "$MODDIR/system/bin/asbdiag"'
! grep -Eq '/sdcard/asb_diag_report\.txt|/data/local/tmp/asb_diag_report\.txt' "$DIAG" || { echo 'FAIL debug support: legacy direct side-copy path remains' >&2; exit 1; }
[ "$(tail -n 1 "$DIAG")" = 'exit 0' ] || { echo 'FAIL debug support: completed collection has no explicit success status' >&2; exit 1; }
need "$DIAG" 'BOOT TIMELINE'
need "$DIAG" 'boot_timeline.tsv'

# Release and testN expose the same passive boot timeline; no version gate remains.
for _version in V65 V65-test1 V65-test10; do
  _mod="$TMP/timeline-${_version}"; mkdir -p "$_mod"
  printf 'id=AutoSystemBoost\nversion=%s\n' "$_version" > "$_mod/module.prop"
  _state="$TMP/timeline-state-${_version}"
  ASB_BOOT_TIMELINE_MODDIR="$_mod" ASB_BOOT_TIMELINE_STATE_DIR="$_state" sh "$TIMELINE" begin postfs_begin >/dev/null
  ASB_BOOT_TIMELINE_MODDIR="$_mod" ASB_BOOT_TIMELINE_STATE_DIR="$_state" sh "$TIMELINE" mark service_enter >/dev/null
  grep -Fq $'\tpostfs_begin\t' "$_state/boot_timeline.tsv" || { echo 'FAIL debug support: unified postfs marker missing' >&2; exit 1; }
  grep -Fq $'\tservice_enter\t' "$_state/boot_timeline.tsv" || { echo 'FAIL debug support: unified service marker missing' >&2; exit 1; }
done
! grep -Fq 'debug_only' "$HELPER" || { echo 'FAIL debug support: version-only support gate remains' >&2; exit 1; }
! grep -Fq 'debug_only' "$TIMELINE" || { echo 'FAIL debug support: version-only timeline gate remains' >&2; exit 1; }

# A public release gets the same mocked diagnostic and unlimited recorder. The recorder reproduces the real
# ownership protocol: it claims the tokenized directory with ITS OWN PID and only removes
# a guard that still names that PID. This catches launcher-PID and cleanup races on host.
DBG="$TMP/debug"; mkdir -p "$DBG/system/bin" "$DBG/tools/logkit" "$TMP/out"
printf 'id=AutoSystemBoost\nversion=V65\n' > "$DBG/module.prop"
TL_STATE="$TMP/timeline-debug"
ASB_BOOT_TIMELINE_MODDIR="$DBG" ASB_BOOT_TIMELINE_STATE_DIR="$TL_STATE" sh "$TIMELINE" begin postfs_begin >/dev/null
ASB_BOOT_TIMELINE_MODDIR="$DBG" ASB_BOOT_TIMELINE_STATE_DIR="$TL_STATE" sh "$TIMELINE" mark service_enter >/dev/null
grep -Fq $'\tpostfs_begin\t' "$TL_STATE/boot_timeline.tsv" || { echo 'FAIL debug support: postfs boot marker missing' >&2; exit 1; }
grep -Fq $'\tservice_enter\t' "$TL_STATE/boot_timeline.tsv" || { echo 'FAIL debug support: service boot marker missing' >&2; exit 1; }
printf '#!/bin/sh\n[ "${ASB_DEBUG_SUPPORT_TEST_DIAG_DELAY:-0}" = 1 ] && sleep 1\nif [ "${ASB_DEBUG_SUPPORT_TEST_DIAG_FAIL:-0}" = 1 ]; then echo diagnostic-failed; exit 9; fi\necho diagnostic-ok\n' > "$DBG/system/bin/asbdiag"; chmod 0755 "$DBG/system/bin/asbdiag"
cat > "$DBG/tools/logkit/asb_log_full_day.sh" <<'EOF_RECORDER'
#!/bin/sh
set -u
_lock="${ASB_DEBUG_SUPPORT_LOCKDIR:-}"
_token="${ASB_DEBUG_SUPPORT_LOCK_TOKEN:-}"
[ -n "$_lock" ] && [ -d "$_lock" ] || exit 91
[ "$(cat "$_lock/token" 2>/dev/null || true)" = "$_token" ] || exit 92
printf '%s\n' "$$" > "$_lock/pid.tmp.$$" || exit 93
mv -f "$_lock/pid.tmp.$$" "$_lock/pid" || exit 94
_out="$_lock/capture_output"; mkdir -p "$_out" || exit 95
printf '%s\n' "$_out" > "$_lock/output_dir" || exit 96
cleanup() {
  _pid="$(tr -dc '0-9' < "$_lock/pid" 2>/dev/null || true)"
  [ "$_pid" = "$$" ] && rm -rf "$_lock" 2>/dev/null || true
}
trap 'cleanup; exit 0' TERM INT HUP
sleep 30
cleanup
EOF_RECORDER
chmod 0755 "$DBG/tools/logkit/asb_log_full_day.sh"
ENV=(ASB_DEBUG_SUPPORT_MODDIR="$DBG" ASB_DEBUG_SUPPORT_STATE_DIR="$TMP/state" ASB_DEBUG_SUPPORT_RUNLOG="$TMP/full_day.out" ASB_DEBUG_SUPPORT_DIAG_OUTDIR="$TMP/out")
# Capture the output AND the status separately.
#
# Under `set -e` a non-zero exit from the helper aborts the test at this line, before any
# assertion runs - so the whole regression reported "exit code 8" with no failing check
# named, and the real problem was invisible. The helper legitimately returns non-zero for
# conditions this test is meant to observe, so its status is data here, not an error.
DIAG_OUT="$(env "${ENV[@]}" sh "$HELPER" diag || true)"
grep -Fq 'status=saved' <<<"$DIAG_OUT"
DIAG_PATH="$(printf '%s\n' "$DIAG_OUT" | sed -n 's/^path=//p')"
[ -f "$DIAG_PATH" ] && grep -Fq 'diagnostic-ok' "$DIAG_PATH" || { echo 'FAIL debug support: diag export' >&2; exit 1; }
[ "$(find "$TMP/out" -maxdepth 1 -type f -name 'asbdiag_*.txt' | wc -l)" -eq 1 ] || {
  echo 'FAIL debug support: one diag action did not publish exactly one report' >&2; exit 1;
}
need "$HELPER" 'DIAG_OUTDIR="${ASB_DEBUG_SUPPORT_DIAG_OUTDIR:-/sdcard/ASB/logs}"'
! grep -Fq '_outdir="/sdcard"' "$HELPER" || { echo 'FAIL debug support: /sdcard fallback remains' >&2; exit 1; }
! grep -Fq '_outdir="/sdcard/Download"' "$HELPER" || { echo 'FAIL debug support: Download fallback remains' >&2; exit 1; }
printf 'not a directory\n' > "$TMP/diag-outdir-file"
BAD_OUTDIR="$(env -u ASB_DEBUG_SUPPORT_DIAG_OUTDIR ASB_DEBUG_SUPPORT_MODDIR="$DBG" \
  ASB_DEBUG_SUPPORT_STATE_DIR="$TMP/state" ASB_DEBUG_SUPPORT_RUNLOG="$TMP/full_day.out" \
  ASB_DEBUG_SUPPORT_DIAG_OUTDIR="$TMP/diag-outdir-file" sh "$HELPER" diag 2>&1 || true)"
grep -Fqx 'error=diag_outdir_failed' <<<"$BAD_OUTDIR" || { echo "FAIL debug support: output-dir failure not surfaced: $BAD_OUTDIR" >&2; exit 1; }
! grep -Fq 'status=saved' <<<"$BAD_OUTDIR" || { echo 'FAIL debug support: failed export claimed saved' >&2; exit 1; }
! grep -Fq 'path=/sdcard' <<<"$BAD_OUTDIR" || { echo 'FAIL debug support: failed export fell back to shared storage' >&2; exit 1; }

# WebUI cannot paint while a KSU bridge waits for a synchronous diagnostic export.
# The async action must acknowledge a delayed worker immediately, remain observable via
# fixed status command, and publish a complete saved record after the worker exits.
ASYNC_DIAG="$(ASB_DEBUG_SUPPORT_TEST_DIAG_DELAY=1 env "${ENV[@]}" sh "$HELPER" diag-start || true)"
grep -Fqx 'status=started' <<<"$ASYNC_DIAG" || { echo 'FAIL debug support: async diag did not return started' >&2; exit 1; }
ASYNC_PID="$(printf '%s\n' "$ASYNC_DIAG" | sed -n 's/^pid=//p')"
[ -n "$ASYNC_PID" ] && kill -0 "$ASYNC_PID" 2>/dev/null || { echo 'FAIL debug support: async diag worker missing' >&2; exit 1; }
ASYNC_STATUS="$(env "${ENV[@]}" sh "$HELPER" diag-status || true)"
grep -Eq '^status=(starting|running)$' <<<"$ASYNC_STATUS" || { echo 'FAIL debug support: async diag status not live' >&2; exit 1; }
for _diag_try in $(seq 1 100); do
  sleep 0.1
  ASYNC_STATUS="$(env "${ENV[@]}" sh "$HELPER" diag-status || true)"
  grep -Fqx 'status=saved' <<<"$ASYNC_STATUS" && break
done
grep -Fqx 'status=saved' <<<"$ASYNC_STATUS" || { echo 'FAIL debug support: async diag never reached saved' >&2; exit 1; }
ASYNC_PATH="$(printf '%s\n' "$ASYNC_STATUS" | sed -n 's/^path=//p')"
[ -f "$ASYNC_PATH" ] && grep -Fq 'diagnostic-ok' "$ASYNC_PATH" || { echo 'FAIL debug support: async diag saved output missing' >&2; exit 1; }
REPEAT_DIAG="$(env "${ENV[@]}" sh "$HELPER" diag-start || true)"
grep -Fqx 'status=started' <<<"$REPEAT_DIAG" || { echo "FAIL debug support: repeat after saved was refused: $REPEAT_DIAG" >&2; exit 1; }
for _diag_try in $(seq 1 100); do
  sleep 0.1
  REPEAT_STATUS="$(env "${ENV[@]}" sh "$HELPER" diag-status || true)"
  grep -Fqx 'status=saved' <<<"$REPEAT_STATUS" && break
done
grep -Fqx 'status=saved' <<<"$REPEAT_STATUS" || { echo "FAIL debug support: repeat diag did not reach saved: $REPEAT_STATUS" >&2; exit 1; }
REPEAT_PATH="$(printf '%s
' "$REPEAT_STATUS" | sed -n 's/^path=//p')"
[ -f "$REPEAT_PATH" ] && grep -Fq 'diagnostic-ok' "$REPEAT_PATH" || { echo 'FAIL debug support: repeat report missing' >&2; exit 1; }

# A dead diagnostic worker must not leave a permanent `already_running` lock, and a nonzero
# asbdiag exit must become an explicit failed status rather than a misleading saved toast.
mkdir -p "$TMP/state/asbdiag_webui.lock"
printf '999999\n' > "$TMP/state/asbdiag_webui.lock/pid"
STALE_DIAG="$(env "${ENV[@]}" sh "$HELPER" diag-start || true)"
grep -Fqx 'status=started' <<<"$STALE_DIAG" || { echo 'FAIL debug support: known-dead diag lock not reclaimed' >&2; exit 1; }
for _diag_try in $(seq 1 100); do sleep 0.1; env "${ENV[@]}" sh "$HELPER" diag-status | grep -Fx 'status=saved' >/dev/null && break; done
FAIL_DIAG="$(ASB_DEBUG_SUPPORT_TEST_DIAG_FAIL=1 env "${ENV[@]}" sh "$HELPER" diag-start || true)"
grep -Fqx 'status=started' <<<"$FAIL_DIAG" || { echo 'FAIL debug support: failing diag did not launch' >&2; exit 1; }
for _diag_try in $(seq 1 100); do
  sleep 0.1
  FAIL_DIAG_STATUS="$(env "${ENV[@]}" sh "$HELPER" diag-status || true)"
  grep -Fqx 'status=failed' <<<"$FAIL_DIAG_STATUS" && break
done
grep -Fqx 'status=failed' <<<"$FAIL_DIAG_STATUS" || { echo 'FAIL debug support: nonzero diag did not reach failed state' >&2; exit 1; }
grep -Fqx 'error=asbdiag_exit_9' <<<"$FAIL_DIAG_STATUS" || { echo 'FAIL debug support: nonzero diag exit was not surfaced' >&2; exit 1; }
START1="$(env "${ENV[@]}" sh "$HELPER" full-day || true)"
grep -Fq 'status=started' <<<"$START1"
grep -Fq 'hours=0' <<<"$START1"
grep -Fq 'limit=until_stopped' <<<"$START1"
REC_PID="$(printf '%s\n' "$START1" | sed -n 's/^pid=//p')"
[ -n "$REC_PID" ] && kill -0 "$REC_PID" 2>/dev/null || { echo 'FAIL debug support: recorder did not stay alive' >&2; exit 1; }
START2="$(env "${ENV[@]}" sh "$HELPER" full-day || true)"
grep -Fq 'status=already_running' <<<"$START2"
grep -Fq "pid=$REC_PID" <<<"$START2"

# Deleting the exact directory published by the live recorder is an explicit cancellation.
# The helper may stop ONLY that recorder, clear its lock and launch a new single capture.
# Simulate a common Android toybox limitation: both ps formats expose only a shortened command
# line. The recovery still needs the script basename, but remains gated by a live lock PID and
# an explicitly removed recorder-owned output directory.
mkdir -p "$TMP/ps-truncated"
cat > "$TMP/ps-truncated/ps" <<'EOF_PS'
#!/bin/sh
printf '%s\n' 'sh asb_log_full_day.sh 0'
EOF_PS
chmod 0755 "$TMP/ps-truncated/ps"
ORPHAN_OUT="$(cat "$TMP/state/full_day_webui.lock/output_dir")"
[ -d "$ORPHAN_OUT" ] || { echo 'FAIL debug support: recorder did not publish output dir' >&2; exit 1; }
rm -rf "$ORPHAN_OUT"
RECOVERED="$(PATH="$TMP/ps-truncated:$PATH" env "${ENV[@]}" sh "$HELPER" full-day || true)"
# fix220: the same storm fix219 proved in the sibling test fired here once in a full
# regression: the helper had cancelled the orphan (cancel=output_removed in the log, the
# recorder gone) but a loaded /proc misread kept the still-live check from clearing the
# lock inside the wait, and the answer was already_running over a corpse. The recovery is
# idempotent, so one retry tells a flake from a regression: the retry reclaims the now
# dead lock and starts; a helper that genuinely lost orphan recovery answers
# already_running to BOTH attempts and still fails below.
case "$RECOVERED" in
  *status=started*) : ;;
  *status=already_running*)
    sleep 0.5
    RECOVERED="$RECOVERED
$(PATH="$TMP/ps-truncated:$PATH" env "${ENV[@]}" sh "$HELPER" full-day || true)" ;;
esac
grep -Fq 'status=started' <<<"$RECOVERED" || {
  echo 'FAIL debug support: removed output dir did not recover capture slot' >&2
  # What the helper answered and why (fix146: a CI run failed here with nothing to read).
  printf '  helper: %s\n' "$RECOVERED" >&2
  sed 's/^/  recovery log: /' "$TMP/state/full_day_webui.recovery.log" >&2 2>/dev/null || true
  _rp="$(printf '%s\n' "$START1" | sed -n 's/^pid=//p')"
  [ -n "$_rp" ] && { printf '  recorder %s: ' "$_rp"; cat "/proc/$_rp/stat" 2>/dev/null || echo gone; } >&2
  exit 1
}
# The evidence of the recovery path is the cancel note itself - the recovered= note can be
# lost when the retry takes the dead-lock reclaim instead (the cancel already proved the
# missing-output path was taken).
grep -Fq 'output_removed' "$TMP/state/full_day_webui.recovery.log" || { echo 'FAIL debug support: orphan recovery evidence missing' >&2; exit 1; }
# With the retry the combined answer can name two PIDs - the cancelled orphan's and the new
# recorder's. The new recorder is the last.
REC_PID="$(printf '%s\n' "$RECOVERED" | sed -n 's/^pid=//p' | tail -n 1)"
[ -n "$REC_PID" ] && kill -0 "$REC_PID" 2>/dev/null || { echo 'FAIL debug support: recovered recorder missing' >&2; exit 1; }

# Repeat simultaneous starts from a clean state. One and only one recorder may be created in
# every round; the losing request must publish the winner PID rather than relying on a
# short-lived helper process or a removable empty PID file. Inspect the answer files directly:
# under pipefail, `printf ... | grep -q` can report SIGPIPE after grep has already found its
# match, turning two correct answers into a random false failure on a loaded runner.
for round in $(seq 1 12); do
  kill -KILL "$REC_PID" 2>/dev/null || true
  wait "$REC_PID" 2>/dev/null || true
  REC_PID=""
  rm -rf "$TMP/state/full_day_webui.lock"
  rm -f "$TMP/state/full_day_webui.pid"
  env "${ENV[@]}" sh "$HELPER" full-day > "$TMP/concurrent_${round}_a.out" & C1=$!
  env "${ENV[@]}" sh "$HELPER" full-day > "$TMP/concurrent_${round}_b.out" & C2=$!
  # wait propagates the child status, and under set -e that aborts the test before the
  # assertion that is meant to inspect it. The helper legitimately returns non-zero for
  # the losing side of this race - that is the behaviour being measured.
  wait "$C1" || true; wait "$C2" || true
  CONCURRENT="$(cat "$TMP/concurrent_${round}_a.out" "$TMP/concurrent_${round}_b.out")"
  if [ "$(printf '%s\n' "$CONCURRENT" | grep -c '^status=started$')" -ne 1 ]; then
    echo "FAIL debug support: concurrent start count round=$round" >&2
    printf '  concurrent answers:\n%s\n' "$CONCURRENT" >&2
    printf '  recorder log:\n' >&2; tail -n 12 "$TMP/full_day.out" >&2 2>/dev/null || true
    exit 1
  fi
  if ! grep -Fq 'status=already_running' "$TMP/concurrent_${round}_a.out" "$TMP/concurrent_${round}_b.out"; then
    echo "FAIL debug support: concurrent guard did not report running round=$round" >&2
    printf '  concurrent answers:\n%s\n' "$CONCURRENT" >&2
    printf '  recorder log:\n' >&2; tail -n 12 "$TMP/full_day.out" >&2 2>/dev/null || true
    printf '  lock files:\n' >&2; find "$TMP/state/full_day_webui.lock" -maxdepth 1 -type f -print -exec cat {} \; >&2 2>/dev/null || true
    exit 1
  fi
  REC_PID="$(awk -F= '/^pid=[0-9]+$/ { print $2; exit }' "$TMP/concurrent_${round}_a.out" "$TMP/concurrent_${round}_b.out")"
  [ -n "$REC_PID" ] && kill -0 "$REC_PID" 2>/dev/null || { echo "FAIL debug support: concurrent recorder missing round=$round" >&2; exit 1; }
  grep -Fq "pid=$REC_PID" "$TMP/concurrent_${round}_a.out" "$TMP/concurrent_${round}_b.out" || { echo "FAIL debug support: loser did not observe winner PID round=$round" >&2; exit 1; }
done

# A killed recorder leaves a known-dead PID. The next action may reclaim only that stale lock.
kill -KILL "$REC_PID" 2>/dev/null || true
wait "$REC_PID" 2>/dev/null || true
# The recorder is not this shell's child, so `wait` returns at once; SIGKILL lands
# asynchronously. The lock records BOTH recorder and launcher, and lock_known_dead rightly
# refuses reclamation while either identity is live. Wait for both to be gone or zombies,
# rather than timing out on the recorder alone while the launcher is still exiting on a
# loaded host. The 15 s bound is used only by this abnormal-death fixture.
_dead_launcher="$(tr -dc '0-9' < "$TMP/state/full_day_webui.lock/launcher" 2>/dev/null || true)"
_dk=0
while [ "$_dk" -lt 150 ]; do
  _dk_live=0
  for _dead_pid in "$REC_PID" "$_dead_launcher"; do
    [ -n "$_dead_pid" ] || continue
    kill -0 "$_dead_pid" 2>/dev/null || continue
    case "$(cat "/proc/$_dead_pid/stat" 2>/dev/null)" in *') Z '*|*') X '*|*') x '*) ;; *) _dk_live=1 ;; esac
  done
  [ "$_dk_live" = 0 ] && break
  sleep 0.1; _dk=$((_dk + 1))
done
STALE="$(env "${ENV[@]}" sh "$HELPER" full-day || true)"
grep -Fq 'status=started' <<<"$STALE" || {
  printf 'FAIL debug support: known-dead lock not reclaimed after %s waits; recorder=%s launcher=%s\n%s\n' \
    "$_dk" "$REC_PID" "${_dead_launcher:-missing}" "$STALE" >&2
  exit 1
}
REC_PID="$(printf '%s\n' "$STALE" | sed -n 's/^pid=//p')"

# The helper accepts a fixed enum only; it has no eval/source/untrusted command interpolation.
need "$HELPER" "case \"\${1:-status}\" in"
need "$HELPER" 'mkdir "$LOCKDIR"'
need "$HELPER" 'lock_known_dead()'
need "$HELPER" 'full_day_output_missing()'
need "$HELPER" 'full_day_cancel_orphan()'
need "$HELPER" 'full_day_pid_matches_recorder()'
need "$HELPER" 'asb_log_full_day.sh*) return 0'
need "$HELPER" 'full_day_recovery_note()'
need "$HELPER" 'RECOVERY_LOG='
need "$HELPER" 'PROC_ROOT='
need "$HELPER" 'diag_lock_known_dead()'
need "$HELPER" 'asbdiag_exit_${_rc}'
need "$HELPER" 'lock_wait_live_pid()'
need "$HELPER" 'ASB_DEBUG_SUPPORT_LOCKDIR="$LOCKDIR"'
need "$HELPER" 'diag-start) diag_start'
need "$HELPER" 'diag-status) diag_status'
need "$HELPER" 'full-day-start) start_full_day 1'
need "$HELPER" 'DIAG_LOCKDIR="$STATE_DIR/asbdiag_webui.lock"'
need "$ROOT/tools/logkit/asb_log_full_day.sh" 'LK_WEBUI_LOCKDIR="${ASB_DEBUG_SUPPORT_LOCKDIR:-}"'
need "$ROOT/tools/logkit/asb_log_full_day.sh" 'lk_webui_guard_claim()'
need "$ROOT/tools/logkit/asb_log_full_day.sh" 'lk_webui_guard_claim || { echo '\''[debug-webui] guard claim failed'\''; exit 2; }'
need "$ROOT/tools/logkit/asb_log_full_day.sh" "trap 'lk_on_signal' TERM INT HUP"
need "$ROOT/tools/logkit/asb_log_full_day.sh" 'lk_webui_guard_release'
need "$ROOT/tools/logkit/asb_log_full_day.sh" 'lk_webui_guard_publish_output()'
need "$ROOT/tools/logkit/asb_log_full_day.sh" 'LK_WEBUI_OUTPUTFILE'
need "$ROOT/tools/logkit/asb_log_full_day.sh" 'FULL-DAY capture complete. Output: $LK_OUT_DIR'
need "$ROOT/tools/logkit/asb_log_full_day.sh" 'LK_HOURS="${1:-0}"'
need "$ROOT/tools/logkit/asb_log_full_day.sh" '[ "$LK_MAX_SEC" -gt 0 ] && [ "$_elapsed" -ge "$LK_MAX_SEC" ] && break'
need "$ROOT/tools/logkit/asb_log_full_day.sh" 'INFINITE LOG running until it is stopped from the WebUI, across reboots.'
need "$HELPER" 'asb_log_full_day.sh" 0 >'
need "$HELPER" "echo 'limit=until_stopped'"
# Debug capture must expose a resolvable AudioMix owner and the evidence that made
# a media-like workload game-like, without putting any package-manager polling in
# the native governor. The logkit helpers are passive and use one capture-start map.
COMMON="$ROOT/tools/logkit/_asb_logkit_common.sh"
need "$COMMON" 'lk_audio_wakelock_attribution_init()'
need "$COMMON" 'audio_wakelock_attribution.tsv'
need "$COMMON" 'lk_fsm_media_trace_header()'
need "$COMMON" 'fsm_media_trace.tsv'
# Android 16 emits a chained WorkSource for AudioMix. Test both that real form and
# the compact legacy form; raw UID attribution is useless if the recorder prints '-'.
sed -n '/^lk_audio_wakelock_live_row() {/,/^}/p' "$COMMON" > "$TMP/audio_wakelock_fn.sh"
[ -s "$TMP/audio_wakelock_fn.sh" ] || { echo 'FAIL debug support: cannot extract AudioMix attribution helper' >&2; exit 1; }
lk_audio_wakelock_package_for_uid() { printf 'pkg.uid.%s\n' "$1"; }
LK_OUT_DIR="$TMP/audio_attr"; mkdir -p "$LK_OUT_DIR"
. "$TMP/audio_wakelock_fn.sh"
lk_audio_wakelock_live_row "PARTIAL_WAKE_LOCK 'AudioMix' (uid=1041 ws=WorkSource{ chains=WorkChain{(10658), (1041)}})" 123
lk_audio_wakelock_live_row "PARTIAL_WAKE_LOCK 'AudioMix' WorkSource{10652}" 124
grep -Fq '123|' "${LK_OUT_DIR}/audio_wakelock_attribution.tsv" || { echo 'FAIL debug support: chained AudioMix row absent' >&2; exit 1; }
grep -Fq '|10658|pkg.uid.10658|' "${LK_OUT_DIR}/audio_wakelock_attribution.tsv" || { echo 'FAIL debug support: chained WorkSource UID unresolved' >&2; exit 1; }
grep -Fq '|10652|pkg.uid.10652|' "${LK_OUT_DIR}/audio_wakelock_attribution.tsv" || { echo 'FAIL debug support: compact WorkSource UID unresolved' >&2; exit 1; }
# fix179: a job lock held beside AudioMix is not AudioMix (capture 30423: ru.vk.store, 95 rows).
lk_audio_wakelock_live_row "PARTIAL_WAKE_LOCK '*job*r/@androidx.work.systemjobscheduler@ru.vk.store/x' ACQ=-1s (uid=1000 ws=WorkSource{ chains=WorkChain{(10436), (1000, JobScheduler)}});PARTIAL_WAKE_LOCK 'AudioMix' ACQ=-5s (uid=1041 ws=WorkSource{10345});" 125
grep -Fq '125|' "${LK_OUT_DIR}/audio_wakelock_attribution.tsv" || { echo 'FAIL debug support: AudioMix beside a job lock not recorded' >&2; exit 1; }
grep -Fq '|10436|' "${LK_OUT_DIR}/audio_wakelock_attribution.tsv" && { echo 'FAIL debug support: a job lock held beside AudioMix was credited to AudioMix' >&2; exit 1; }
grep -F '125|' "${LK_OUT_DIR}/audio_wakelock_attribution.tsv" | grep 'ru.vk.store' >/dev/null && { echo 'FAIL debug support: the job lock text was kept as AudioMix evidence' >&2; exit 1; }
grep -Fq '125|' "${LK_OUT_DIR}/audio_wakelock_attribution.tsv" && grep -F '125|' "${LK_OUT_DIR}/audio_wakelock_attribution.tsv" | grep -F '|10345|pkg.uid.10345|' >/dev/null || { echo 'FAIL debug support: the AudioMix owner beside a job lock was lost' >&2; exit 1; }
need "$ROOT/tools/logkit/asb_log_full_day.sh" 'lk_audio_wakelock_attribution_init'
need "$ROOT/tools/logkit/asb_log_full_day.sh" 'lk_capture_fsm_media_trace_row "$_phase"'
need "$ROOT/tools/logkit/asb_log_full_day.sh" 'rmnetMiB'
need "$ROOT/src/asb_governor.c" 'asb_smart_media_guard_observe'
need "$ROOT/src/asb_governor.c" 'no_fresh_known_media_pkg'
need "$ROOT/src/asb_governor.c" 'ASB_SMART_MEDIA_GUARD_GPU_MAX_PCT = 70'
need "$ROOT/src/asb_smart.h" 'asb_smart_pkg_is_media_candidate'
if grep -nE '\beval\b|\bsource\b|/system/bin/sh -c|sh -c' "$HELPER" >/dev/null; then
  echo 'FAIL debug support: helper accepts unsafe shell execution' >&2; exit 1
fi
# Every one of Profile, Monitor and Settings gets one support wrapper. A debug build
# swaps its single release Telegram link for exactly one no-wrap, three-control rail.
count_exact "$UI" '<div class="footer-support-row" data-debug-support-row hidden>' 3
count_exact "$UI" '<a class="tg-link" data-release-telegram' 3
count_exact "$UI" '<a class="tg-link" data-debug-telegram' 3
count_exact "$UI" "asbDebugAction('diag')" 3
count_exact "$UI" "asbDebugAction('full-day')" 3
count_exact "$UI" '<span class="tg-link-ico" data-tech-icon="telegram"></span>' 6
need "$UI" '.tg-link-ico .tech-icon { width: 18px; height: 18px; }'
need "$UI" '.footer-support-row .tg-link-ico { width: 16px; height: 16px; flex-basis: 16px; }'
need "$UI" 'background: linear-gradient(135deg, rgba(0,240,180,0.08), rgba(0,212,255,0.05));'
need "$UI" 'height: 40px;'
need "$UI" 'flex-wrap: nowrap;'
need "$UI" '[data-release-telegram][hidden] { display: none !important; }'
need "$UI" 'runtime/asb_debug_support.sh'
need "$UI" 'loadDebugSupport()'
need "$UI" 'row.hidden = false;'
! grep -Fq '/-debug[1-9][0-9]*$/i' "$UI" || { echo 'FAIL debug support: WebUI version gate remains' >&2; exit 1; }
# asbdiag can spend seconds writing its export. A persistent modal must open before
# the root bridge await, stay while the pulse is active, and close only in finally.
need "$UI" 'id="debugActionWait"'
need "$UI" 'debug-action-wait-sheet'
need "$UI" 'background:#000;'
need "$UI" 'stockRestoreToastOpen();'
need "$UI" 'stockRestoreToastClose();'
need "$UI" 'toast.stock-restoring'
need "$UI" 'stockRestoreToastPulse'
need "$UI" 'debugDiagPulse .38s'
need "$UI" 'debugActionWaitOpen(action);'
need "$UI" 'debugActionWaitClose();'
need "$UI" 'await debugFrame();'
need "$UI" "'diag-start' : 'full-day-start'"
need "$UI" 'runtime/asb_debug_support.sh diag-status'
need "$UI" 'async function debugDiagPoll()'
need "$UI" 'async function debugFullDayPoll()'
need "$UI" 'runtime/asb_debug_support.sh status'
awk '
  /async function asbDebugAction\(action\)/ { in_fn=1 }
  in_fn && /debugActionWaitOpen\(action\)/ { opened=NR }
  in_fn && /await run\(/ && !awaited { awaited=NR }
  in_fn && /finally \{/ { in_final=1 }
  in_final && /debugActionWaitClose\(\)/ { closed=1 }
  in_fn && /^}/ { if (opened && awaited && opened < awaited && closed) ok=1; in_fn=0 }
  END { if (!ok) { print "FAIL debug support: wait modal lifecycle is not open-before-await / close-in-finally" > "/dev/stderr"; exit 1 } }
' "$UI"
awk '
  /<div class="footer-support-row" data-debug-support-row hidden>/ { inrow=1; seq=""; next }
  inrow && /asbDebugAction\('\''diag'\''\)/ { seq=seq "D" }
  inrow && /data-debug-telegram/ { seq=seq "T" }
  inrow && /asbDebugAction\('\''full-day'\''\)/ { seq=seq "L" }
  inrow && /<\/div>/ { if (seq != "DTL") { printf "FAIL debug support: expected DTL rail order, got %s\\n", seq > "/dev/stderr"; exit 1 }; rails++; inrow=0 }
  END { if (rails != 3) { printf "FAIL debug support: checked %d central rails\\n", rails > "/dev/stderr"; exit 1 } }
' "$UI"
for locale in "$ROOT"/webroot/i18n/*.json; do
  # Check the VALUE, not the byte sequence.
  #
  # These matched '"key": "value"' with the space that json.dump's indent mode happens to
  # emit. Compacting the locale files to save 43 KB changed no data at all and broke both
  # lines, because a grep for punctuation is not a test of content.
  #
  # Matching the key and value with optional whitespace between them holds for either
  # formatting, and still fails if the string is actually missing or renamed - which is
  # what the contract is about.
  grep -Eq '"dbg_diag_btn"[[:space:]]*:[[:space:]]*"asbdiag"' "$locale" \
    || fail "missing dbg_diag_btn=asbdiag in $locale"
  grep -Eq '"dbg_log_btn"[[:space:]]*:[[:space:]]*"' "$locale" \
    || fail "missing dbg_log_btn in $locale"
  grep -Fq '"dbg_log_btn": "24h log"' "$locale" && fail "obsolete 24h label in $locale"
  need "$locale" '"dbg_log_failed"'
  need "$locale" '"lr_running_open"'
  need "$locale" '"dbg_log_started_hint"'
  need "$locale" '"page_saved"'
  need "$locale" '"page_save_error"'
  need "$locale" '"dbg_log_stop_sent"'
  need "$locale" '"dbg_log_stop_busy"'
done

echo 'PASS debug support WebUI/helper contract'
)

t_debug_support_stale_lock() (
# Regression: the WebUI must be able to start a daily log again after a previous one ended or
# its folder was deleted. Three cases:
#   1. stale lock whose PID now belongs to an UNRELATED live process (PID reuse within a boot)
#      -> the lock is not ours: start must succeed, the unrelated process must be left alive;
#   2. our recorder alive, folder present -> still "already running" (no second recorder);
#   3. our recorder alive, folder deleted -> recorder AND its sampler child stopped, new start.
set -u
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
HELPER="$ROOT/runtime/asb_debug_support.sh"
TMP="$(mktemp -d)"; trap 'kill $(jobs -p) 2>/dev/null; pkill -f "$TMP" 2>/dev/null; rm -rf "$TMP"' EXIT
fail() { echo "FAIL debug stale-lock: $*" >&2; exit 1; }
# Alive and not a zombie: a killed process stays visible to kill -0 until it is reaped.
alive() { [ -r "/proc/$1/stat" ] || return 1; case "$(sed 's/^.*) //' "/proc/$1/stat" | cut -c1)" in Z|X) return 1 ;; esac; return 0; }
DBG="$TMP/mod"; mkdir -p "$DBG/tools/logkit" "$DBG/runtime"
printf 'id=AutoSystemBoost\nversion=V65-test10\nversionCode=650\n' > "$DBG/module.prop"
cat > "$DBG/tools/logkit/asb_log_full_day.sh" << 'EOF_REC'
set -u
_lock="${ASB_DEBUG_SUPPORT_LOCKDIR:-}"; _token="${ASB_DEBUG_SUPPORT_LOCK_TOKEN:-}"
[ -d "$_lock" ] && [ "$(cat "$_lock/token")" = "$_token" ] || exit 91
printf '%s\n' "$$" > "$_lock/pid"
_out="$_lock/../capture_$$"; mkdir -p "$_out"; printf '%s\n' "$_out" > "$_lock/output_dir"
( while :; do sleep 1; done ) &          # a sampler child, as the real recorder has
echo $! > "$_lock/../child_$$"
sleep 60
EOF_REC
ENV=(ASB_DEBUG_SUPPORT_MODDIR="$DBG" ASB_DEBUG_SUPPORT_STATE_DIR="$TMP/state" ASB_DEBUG_SUPPORT_RUNLOG="$TMP/run.out")
H() { env "${ENV[@]}" sh "$HELPER" "$@" 2>/dev/null || true; }
LOCK="$TMP/state/full_day_webui.lock"
boot="$(cat /proc/sys/kernel/random/boot_id 2>/dev/null || echo boot)"

# ---- case 1: stale lock, PID reused by an unrelated live process
mkdir -p "$LOCK"; sleep 300 & OTHER=$!
printf '%s\n' "$boot" > "$LOCK/boot_id"; printf 'tok\n' > "$LOCK/token"
printf '%s\n' "$OTHER" > "$LOCK/pid"; printf '%s\n' "$OTHER" > "$LOCK/launcher"
printf '%s\n' "$TMP/deleted_capture" > "$LOCK/output_dir"
OUT="$(H full-day-start)"
echo "$OUT" | grep 'status=started' >/dev/null || fail "case 1: stale lock blocked the start: $OUT"
kill -0 "$OTHER" 2>/dev/null || fail "case 1: an unrelated process was killed"
sleep 0.6
P1="$(tr -dc 0-9 < "$LOCK/pid" 2>/dev/null)"; [ -n "$P1" ] && kill -0 "$P1" || fail "case 1: recorder not running"

# ---- case 2: our recorder alive, folder present -> already running
OUT="$(H full-day-start)"
echo "$OUT" | grep 'status=already_running' >/dev/null || fail "case 2: a second recorder was allowed: $OUT"

# ---- case 3: folder deleted -> recorder and child stopped, new recorder started
CHILD="$(cat "$TMP/state/child_$P1" 2>/dev/null)"
CAPDIR="$(cat "$LOCK/output_dir")"
[ -n "$CAPDIR" ] || fail "case 3: the published output_dir read empty under load"
rm -rf "$CAPDIR"
[ ! -d "$CAPDIR" ] || fail "case 3: could not remove the capture dir"
OUT="$(H full-day-start)"
# A host under the full suite's fork pressure can transiently read a tiny lock file as
# empty (a failed fork inside a command substitution), which the helper - correctly -
# fails closed on: "cannot prove the output is gone, so the live recorder stays". On a
# device that answer is right; here it is the storm, not the logic. The recovery is
# idempotent, so one retry tells a flake from a regression: a helper that genuinely lost
# orphan recovery answers already_running to BOTH attempts and still fails below.
case "$OUT" in
  *orphan_recovered=output_dir_removed*) : ;;
  *status=already_running*)
    sleep 0.5
    OUT="$OUT
$(H full-day-start)" ;;
esac
if ! printf '%s\n' "$OUT" | grep 'orphan_recovered=output_dir_removed' >/dev/null; then
  # The first attempt may have recovered the slot but tripped on the final still-live
  # check; the retry then started over the dead lock without the note line. The contract
  # is "a new start succeeds and the old recorder is gone" - checked either way below.
  printf '%s\n' "$OUT" | grep 'status=started' >/dev/null || fail "case 3: orphan not recovered: $OUT"
fi
printf '%s\n' "$OUT" | grep 'status=started' >/dev/null || fail "case 3: no new start: $OUT"
sleep 0.4
alive "$P1" && fail "case 3: old recorder still alive"
[ -n "$CHILD" ] && alive "$CHILD" && fail "case 3: old sampler child still alive"
kill "$OTHER" 2>/dev/null
echo "PASS debug support stale-lock and deleted-folder recovery"
)

t_debug_support_stop_runtime() (
# Runtime (fix242): an open-ended session log can be stopped from the WebUI menu.
#
# Since fix235 the capture runs until shutdown, and the only way to end it was to delete its
# folder (which discards it) or to reboot. full-day-stop sends the recorder the TERM it already
# traps - finalise the report, release the lock - wakes its foreground sleep so the trap runs
# now, returns at once with status=stopping, and a detached waiter forces the end only if the
# recorder ignores TERM. The REAL helper runs against a stub recorder with the same trap shape.
set -u
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
HELPER="$ROOT/runtime/asb_debug_support.sh"
TMP="$(mktemp -d)"; trap 'kill $(jobs -p) 2>/dev/null; pkill -f "$TMP" 2>/dev/null; rm -rf "$TMP"' EXIT
fail() { echo "FAIL debug stop: $*" >&2; exit 1; }
alive() { [ -r "/proc/$1/stat" ] || return 1; case "$(sed 's/^.*) //' "/proc/$1/stat" | cut -c1)" in Z|X) return 1 ;; esac; return 0; }
DBG="$TMP/mod"; mkdir -p "$DBG/tools/logkit" "$DBG/runtime"
printf 'id=AutoSystemBoost\nversion=V65-test15\nversionCode=650\n' > "$DBG/module.prop"
cat > "$DBG/tools/logkit/asb_log_full_day.sh" << 'EOF_REC'
set -u
_lock="${ASB_DEBUG_SUPPORT_LOCKDIR:-}"; _token="${ASB_DEBUG_SUPPORT_LOCK_TOKEN:-}"
[ -d "$_lock" ] && [ "$(cat "$_lock/token")" = "$_token" ] || exit 91
printf '%s\n' "$$" > "$_lock/pid"
_out="$(dirname "$_lock")/capture_$$"; mkdir -p "$_out"; printf '%s\n' "$_out" > "$_lock/output_dir"
if [ "${STUB_IGNORE_TERM:-0}" = 1 ]; then
  trap '' TERM
else
  trap 'echo finalized > "$_out/_full_day_report.txt"; rm -rf "$_lock"; exit 0' TERM
fi
while :; do sleep 60; done
EOF_REC
ENV=(ASB_DEBUG_SUPPORT_MODDIR="$DBG" ASB_DEBUG_SUPPORT_STATE_DIR="$TMP/state" ASB_DEBUG_SUPPORT_RUNLOG="$TMP/run.out" ASB_DEBUG_SUPPORT_STOP_WAIT_S=3)
H() { env "${ENV[@]}" sh "$HELPER" "$@" 2>/dev/null || true; }
LOCK="$TMP/state/full_day_webui.lock"
OUT="$(H full-day-stop)"
printf '%s\n' "$OUT" | grep -x 'status=idle' >/dev/null || fail "stop with nothing running did not say idle: $OUT"
OUT="$(H full-day-start)"; printf '%s\n' "$OUT" | grep 'status=started' >/dev/null || fail "start: $OUT"
n=0; while [ ! -s "$LOCK/output_dir" ] && [ "$n" -lt 50 ]; do sleep 0.1; n=$((n + 1)); done
P1="$(tr -dc 0-9 < "$LOCK/pid" 2>/dev/null)"; [ -n "$P1" ] && alive "$P1" || fail "recorder not running"
CAP="$(cat "$LOCK/output_dir")"
t0="$(date +%s)"
OUT="$(H full-day-stop)"
t1="$(date +%s)"
printf '%s\n' "$OUT" | grep -x 'status=stopping' >/dev/null || fail "stop did not answer stopping: $OUT"
printf '%s\n' "$OUT" | grep -x "pid=$P1" >/dev/null || fail "stop named another pid: $OUT"
printf '%s\n' "$OUT" | grep -x "output=$CAP" >/dev/null || fail "stop did not name the capture folder: $OUT"
[ $(( t1 - t0 )) -le 2 ] || fail "the helper held the WebView bridge for $(( t1 - t0 )) s"
n=0; while alive "$P1" && [ "$n" -lt 40 ]; do sleep 0.1; n=$((n + 1)); done
alive "$P1" && fail "the recorder did not end on TERM within 4 s (its sleep was not woken)"
grep -qx finalized "$CAP/_full_day_report.txt" 2>/dev/null || fail "the recorder was killed instead of finalising its report"
[ -d "$CAP" ] || fail "stopping removed the capture folder"
OUT="$(H status)"; printf '%s\n' "$OUT" | grep -x 'status=idle' >/dev/null || fail "status after stop: $OUT"
ENV+=(STUB_IGNORE_TERM=1)
OUT="$(H full-day-start)"; printf '%s\n' "$OUT" | grep 'status=started' >/dev/null || fail "second start: $OUT"
n=0; while [ ! -s "$LOCK/output_dir" ] && [ "$n" -lt 50 ]; do sleep 0.1; n=$((n + 1)); done
P2="$(tr -dc 0-9 < "$LOCK/pid" 2>/dev/null)"
OUT="$(H full-day-stop)"; printf '%s\n' "$OUT" | grep -x 'status=stopping' >/dev/null || fail "stop of a stubborn recorder: $OUT"
n=0; while alive "$P2" && [ "$n" -lt 80 ]; do sleep 0.1; n=$((n + 1)); done
alive "$P2" && fail "a recorder that ignores TERM was never ended"
n=0; while [ -d "$LOCK" ] && [ "$n" -lt 30 ]; do sleep 0.1; n=$((n + 1)); done
[ -d "$LOCK" ] && fail "the lock of a force-ended recorder stayed"
OUT="$(H status)"; printf '%s\n' "$OUT" | grep -x 'status=idle' >/dev/null || fail "status after a forced stop: $OUT"
H="$ROOT/webroot/index.html"
grep -Fq "asb_debug_support.sh full-day-stop 2>/dev/null" "$H" || fail "the WebUI does not call full-day-stop"
grep -Fq "if (action === 'full-day' && _asbLogRunning) {" "$H" || fail "the menu item does not turn into Stop while recording"
grep -Fq "Date.now() - _asbLogStopArmed >= 4000" "$H" || fail "stopping has no second-tap confirmation"
echo "PASS debug support stop: TERM ends the capture at once with its report finalised, the bridge returns immediately, a recorder that ignores TERM is ended, the menu asks twice"
)

t_debug_support_stop_finalize_runtime() (
# Runtime (fix287): the owner tapped Stop, saw "stopping · the report is being finalised", and
# on the next visit the menu offered Stop again - the status said "running" while the recorder
# finished its report, and the second stop cut it short. The helper now reports "stopping" for
# that interval, a repeated stop sends no second signal, and the recorder ignores further
# signals while it finalises. The REAL helper runs against a stub with a slow finaliser.
set -u
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
HELPER="$ROOT/runtime/asb_debug_support.sh"
TMP="$(mktemp -d)"; trap 'kill $(jobs -p) 2>/dev/null; pkill -f "$TMP" 2>/dev/null; rm -rf "$TMP"' EXIT
fail() { echo "FAIL debug stop finalize: $*" >&2; exit 1; }
alive() { [ -r "/proc/$1/stat" ] || return 1; case "$(sed 's/^.*) //' "/proc/$1/stat" | cut -c1)" in Z|X) return 1 ;; esac; return 0; }
DBG="$TMP/mod"; mkdir -p "$DBG/tools/logkit" "$DBG/runtime"
printf 'id=AutoSystemBoost\nversion=V65-test16\nversionCode=650\n' > "$DBG/module.prop"
cat > "$DBG/tools/logkit/asb_log_full_day.sh" << 'EOF_REC'
set -u
_lock="${ASB_DEBUG_SUPPORT_LOCKDIR:-}"; _token="${ASB_DEBUG_SUPPORT_LOCK_TOKEN:-}"
[ -d "$_lock" ] && [ "$(cat "$_lock/token")" = "$_token" ] || exit 91
printf '%s\n' "$$" > "$_lock/pid"
_out="$(dirname "$_lock")/capture_$$"; mkdir -p "$_out"; printf '%s\n' "$_out" > "$_lock/output_dir"
fin() {
  echo term >> "$_out/terms"
  [ -f "$_out/finalizing" ] && return 0
  : > "$_out/finalizing"
  n=0; while [ "$n" -lt 25 ] && [ ! -f "$_out/release" ]; do sleep 0.1; n=$((n + 1)); done
  echo finalized > "$_out/_full_day_report.txt"; rm -rf "$_lock"; exit 0
}
trap fin TERM
while :; do sleep 60; done
EOF_REC
ENV=(ASB_DEBUG_SUPPORT_MODDIR="$DBG" ASB_DEBUG_SUPPORT_STATE_DIR="$TMP/state" ASB_DEBUG_SUPPORT_RUNLOG="$TMP/run.out" ASB_DEBUG_SUPPORT_STOP_WAIT_S=20)
H() { env "${ENV[@]}" sh "$HELPER" "$@" 2>/dev/null || true; }
LOCK="$TMP/state/full_day_webui.lock"
OUT="$(H full-day-start)"; printf '%s\n' "$OUT" | grep 'status=started' >/dev/null || fail "start: $OUT"
n=0; while [ ! -s "$LOCK/output_dir" ] && [ "$n" -lt 50 ]; do sleep 0.1; n=$((n + 1)); done
P="$(tr -dc 0-9 < "$LOCK/pid" 2>/dev/null)"; CAP="$(cat "$LOCK/output_dir")"
OUT="$(H full-day-stop)"; printf '%s\n' "$OUT" | grep -x 'status=stopping' >/dev/null || fail "stop: $OUT"
n=0; while [ ! -f "$CAP/finalizing" ] && [ "$n" -lt 40 ]; do sleep 0.1; n=$((n + 1)); done
[ -f "$CAP/finalizing" ] || fail 'the recorder never started finalising'
OUT="$(H status)"
printf '%s\n' "$OUT" | grep -x 'status=stopping' >/dev/null || fail "status while the report is finalised still says: $OUT"
printf '%s\n' "$OUT" | grep '^since=[0-9][0-9]*$' >/dev/null || fail "stopping has no start time: $OUT"
OUT="$(H full-day-stop)"
printf '%s\n' "$OUT" | grep -x 'status=stopping' >/dev/null && printf '%s\n' "$OUT" | grep -x "output=$CAP" >/dev/null || fail "a repeated stop: $OUT"
sleep 0.5
[ "$(grep -c term "$CAP/terms" 2>/dev/null)" = 1 ] || fail "a repeated stop signalled the finalising recorder again ($(grep -c term "$CAP/terms") signals)"
: > "$CAP/release"
n=0; while alive "$P" && [ "$n" -lt 50 ]; do sleep 0.1; n=$((n + 1)); done
alive "$P" && fail 'the recorder did not finish'
grep -qx finalized "$CAP/_full_day_report.txt" || fail 'the report was not finalised'
OUT="$(H status)"; printf '%s\n' "$OUT" | grep -x 'status=idle' >/dev/null || fail "status after the report: $OUT"
[ -e "$TMP/state/full_day_stopping" ] && fail 'the stopping marker outlived the recorder'
OUT="$(H full-day-start)"; printf '%s\n' "$OUT" | grep 'status=started' >/dev/null || fail "a new start after the stop: $OUT"
n=0; while [ ! -s "$LOCK/output_dir" ] && [ "$n" -lt 50 ]; do sleep 0.1; n=$((n + 1)); done
OUT="$(H status)"; printf '%s\n' "$OUT" | grep -x 'status=running' >/dev/null || fail "a new capture reads as stopping: $OUT"
H full-day-stop >/dev/null; : > "$(cat "$LOCK/output_dir" 2>/dev/null)/release" 2>/dev/null
F="$ROOT/tools/logkit/asb_log_full_day.sh"
awk '/^lk_on_signal\(\) \{/ { f = 1 } f && /trap .. TERM INT HUP/ { t = NR } f && /^  lk_finalize$/ { l = NR } f && /^}/ { exit } END { exit !(t && l && t < l) }' "$F" \
  || fail 'the recorder can still be interrupted while it finalises its report'
W="$ROOT/webroot/index.html"
grep -Fq "_asbLogStopping = !!(r && r.errno === 0 && info.status === 'stopping');" "$W" || fail 'the menu does not read the stopping state'
grep -Fq "if (action === 'full-day' && _asbLogStopping) {" "$W" || fail 'the menu still offers Stop while the report is finalised'
echo "PASS debug support stop finalize: 'stopping' until the report is written, no second signal, uninterruptible finalisation, a menu that waits"
)

t_debug_support_stop_fast_runtime() (
# Runtime (fix246): stopping the infinite log answers at once on a loaded phone.
#
# Owner, after a reboot mid-capture: "I tap Stop, tap again - nothing happens, the phone starts
# to stutter, and the log keeps recording." The stop helper walked /proc once per generation
# with a cat and a cut for every process - thousands of forks on a phone with ~1000 processes,
# from the manager app's cgroup, before it sent the recorder anything. The page sat silent, the
# user left it, the app's group was frozen and the TERM was never sent. The descendants are now
# one cat and one awk, the helper leaves the app's cgroup first, and the recorder sleeps in the
# background and waits, so a TERM interrupts it at once whatever the helper does.
set -u
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
HELPER="$ROOT/runtime/asb_debug_support.sh"
FD="$ROOT/tools/logkit/asb_log_full_day.sh"
T="$(mktemp -d)"; trap 'kill $(jobs -p) 2>/dev/null; rm -rf "$T"' EXIT
fail() { echo "FAIL debug stop fast: $*" >&2; exit 1; }
sed -n '/^pid_descendants() {$/,/^}$/p' "$HELPER" > "$T/pd.sh"
grep -q 'awk' "$T/pd.sh" || fail "pid_descendants is not a single pass"
grep -q 'for _pd_stat in' "$T/pd.sh" && fail "pid_descendants still forks per process"
sh -c 'sleep 40 & (sleep 41 & (sleep 42 & wait) & wait) & wait' & ROOTP=$!
sleep 0.5
kids="$(PROC_ROOT=/proc sh -c '. "$1"; pid_descendants "$2"' x "$T/pd.sh" "$ROOTP")"
want="$(ps -eo pid=,ppid= | awk -v r="$ROOTP" '{ pp[$1] = $2 } END { q[1] = r; n = 1; h = 1; while (h <= n) { c = q[h++]; for (p in pp) if (pp[p] == c) { q[++n] = p; print p } } }' | sort -n | tr '\n' ' ')"
got="$(printf '%s\n' $kids | sort -n | tr '\n' ' ')"
[ -n "$got" ] && [ "$got" = "$want" ] || fail "descendants: got [$got] want [$want]"
[ "$(printf '%s\n' $kids | wc -l)" -ge 5 ] || fail "three generations not all found: $kids"
pkill -P "$ROOTP" 2>/dev/null; kill "$ROOTP" 2>/dev/null
awk '/^stop_full_day\(\) \{/ { f = 1 } f && /asb_cgroup_detach \$\$/ && !d { d = NR } f && /_sk="\$\(pid_descendants "\$_sp"\)"/ { k = NR } f && /^}/ { exit } END { exit !(d && k && d < k) }' "$HELPER" \
  || fail "the stop helper scans /proc before leaving the app's cgroup"
grep -q 'ASB_DEBUG_SUPPORT_STOP_WAIT_S:-240' "$HELPER" || fail "a reniced finalise gets the old 120 s before it is killed"
grep -q '^  sleep "\$LK_POLL_S" &$' "$FD" && grep -q '^  wait "\$LK_SLEEP_PID" 2>/dev/null$' "$FD" || fail "the recorder still sleeps in the foreground"
grep -q '^  \[ -n "\${LK_SLEEP_PID:-}" \] && kill "\$LK_SLEEP_PID" 2>/dev/null$' "$FD" || fail "the signal handler leaves the sleep behind"
grep -q '^renice -n 10 -p \$\$' "$FD" || fail "the recorder competes with the UI at normal priority"
{ echo 'LK_POLL_S=60; trap "echo term > \"$1\"; exit 0" TERM'
  echo 'while :; do'
  sed -n '/^  sleep "\$LK_POLL_S" &$/,/^  LK_SLEEP_PID=""$/p' "$FD"
  echo 'done'; } > "$T/loop.sh"
sh "$T/loop.sh" "$T/termed" & LP=$!
sleep 0.5
t0="$(date +%s%N)"; kill -TERM "$LP"
n=0; while [ ! -s "$T/termed" ] && [ "$n" -lt 30 ]; do sleep 0.1; n=$((n + 1)); done
[ -s "$T/termed" ] || fail "a TERM does not interrupt the recorder's sleep"
[ $(( ($(date +%s%N) - t0) / 1000000 )) -lt 2000 ] || fail "the recorder took over 2 s to see a TERM"
H="$ROOT/webroot/index.html"
grep -Fq "toast(T('dbg_log_stop_sent', 'Stopping the infinite log…'), 'warn');" "$H" || fail "the second tap gives no immediate answer"
grep -Fq "if (_asbDebugActionBusy) { toast(T('dbg_log_stop_busy'" "$H" || fail "a busy stop returns in silence"
echo "PASS debug stop fast: one-pass descendants (three generations), the helper leaves the app's cgroup first, the recorder wakes on TERM at once, the page answers the second tap immediately"
)

t_debug_support_capture_freshness_runtime() (
# fix339: process liveness keeps Stop available, but only a same-PID, same-boot monotonic
# heartbeat may make the capture green. Exercise the REAL full_day_status CLI in all three
# progress states, including the already-running response used by a repeated Start tap.
set -u
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
HELPER="$ROOT/runtime/asb_debug_support.sh"
TMP="$(mktemp -d)"; trap 'kill $(jobs -p) 2>/dev/null; pkill -f "$TMP" 2>/dev/null; rm -rf "$TMP"' EXIT HUP INT TERM
fail() { echo "FAIL debug capture freshness: $*" >&2; exit 1; }
DBG="$TMP/mod"; mkdir -p "$DBG/tools/logkit"
printf 'id=AutoSystemBoost\nversion=V65\nversionCode=65339\n' > "$DBG/module.prop"
cat > "$DBG/tools/logkit/asb_log_full_day.sh" <<'EOF_REC'
set -u
_lock="${ASB_DEBUG_SUPPORT_LOCKDIR:-}"; _token="${ASB_DEBUG_SUPPORT_LOCK_TOKEN:-}"
[ -d "$_lock" ] && [ "$(cat "$_lock/token")" = "$_token" ] || exit 91
printf '%s\n' "$$" > "$_lock/pid"
_out="$(dirname "$_lock")/asb_log_full_day_$$"; mkdir -p "$_out"
printf '%s\n' "$_out" > "$_lock/output_dir"
trap 'rm -rf "$_lock"; exit 0' TERM
while :; do sleep 60; done
EOF_REC
ENV=(ASB_DEBUG_SUPPORT_MODDIR="$DBG" ASB_DEBUG_SUPPORT_STATE_DIR="$TMP/state"
     ASB_DEBUG_SUPPORT_RUNLOG="$TMP/run.out" ASB_DEBUG_SUPPORT_STOP_WAIT_S=2)
H() { env "${ENV[@]}" sh "$HELPER" "$@" 2>/dev/null || true; }
OUT="$(H full-day-start)"; printf '%s\n' "$OUT" | grep 'status=started' >/dev/null || fail "start: $OUT"
LOCK="$TMP/state/full_day_webui.lock"
n=0; while [ ! -s "$LOCK/output_dir" ] && [ "$n" -lt 50 ]; do sleep 0.1; n=$((n + 1)); done
[ -s "$LOCK/output_dir" ] && [ -s "$LOCK/pid" ] || fail 'recorder did not publish its lock/output'
CAP="$(cat "$LOCK/output_dir")"; PID="$(tr -dc 0-9 < "$LOCK/pid")"; BOOT="$(cat "$LOCK/boot_id")"
OUT="$(H status)"
printf '%s\n' "$OUT" | grep -x 'status=running' >/dev/null || fail "live process lost Stop-capable status: $OUT"
printf '%s\n' "$OUT" | grep -x 'capture_state=unknown' >/dev/null || fail "missing heartbeat was not unknown: $OUT"
printf '%s\n' "$OUT" | grep -x 'heartbeat_age_s=-1' >/dev/null || fail "missing heartbeat invented an age: $OUT"
UP="$(awk '{printf "%d", $1}' /proc/uptime)"
cat > "$CAP/recorder_heartbeat.env" <<EOF_HB
schema=1
pid=$PID
epoch=$(date +%s)
mono=$UP
tick=3
poll_s=45
stage=sampling
boot_id=$BOOT
EOF_HB
OUT="$(H status)"
printf '%s\n' "$OUT" | grep -x 'capture_state=running' >/dev/null || fail "fresh heartbeat was not running: $OUT"
printf '%s\n' "$OUT" | grep -x 'stage=sampling' >/dev/null || fail "fresh stage missing: $OUT"
printf '1600.00 3200.00\n' > "$TMP/uptime"
sed -i 's/^mono=.*/mono=1000/;s/^stage=.*/stage=dumpsys:batterystats/' "$CAP/recorder_heartbeat.env"
HS() { env "${ENV[@]}" ASB_DEBUG_SUPPORT_UPTIME_FILE="$TMP/uptime" sh "$HELPER" "$@" 2>/dev/null || true; }
OUT="$(HS status)"
printf '%s\n' "$OUT" | grep -x 'status=running' >/dev/null || fail "stale process must retain Stop: $OUT"
printf '%s\n' "$OUT" | grep -x 'capture_state=stale' >/dev/null || fail "old heartbeat was not stale: $OUT"
printf '%s\n' "$OUT" | grep -x 'heartbeat_age_s=600' >/dev/null || fail "wrong stale age: $OUT"
printf '%s\n' "$OUT" | grep -x 'stage=dumpsys:batterystats' >/dev/null || fail "stale stage missing: $OUT"
OUT="$(HS full-day)"
printf '%s\n' "$OUT" | grep -x 'status=already_running' >/dev/null || fail "repeated start did not preserve the single recorder: $OUT"
printf '%s\n' "$OUT" | grep -x 'capture_state=stale' >/dev/null || fail "already_running hid stale progress: $OUT"
sed -i 's/^mono=.*/mono=10x00/' "$CAP/recorder_heartbeat.env"
OUT="$(HS status)"; printf '%s\n' "$OUT" | grep -x 'capture_state=unknown' >/dev/null || fail "malformed monotonic evidence was repaired into a timestamp: $OUT"
rm -f "$CAP/recorder_heartbeat.env"
OUT="$(HS status)"; printf '%s\n' "$OUT" | grep -x 'capture_state=unknown' >/dev/null || fail "deleted heartbeat did not return to unknown: $OUT"
OUT="$(H full-day-stop)"; printf '%s\n' "$OUT" | grep -x 'status=stopping' >/dev/null || fail "stale/unknown capture could not be stopped: $OUT"
echo 'PASS debug capture freshness: real status CLI separates fresh/stale/unknown progress from live-process Stop and repeated Start'
)

t_debug_support_resume_runtime() (
# Runtime (fix244): a session log started from the WebUI survives a reboot.
#
# Owner: "the log collector should survive a reboot and keep recording until I stop it in the
# WebUI". The recorder leaves a resume marker (its folder and boot); only the WebUI stop or a
# deleted folder clears it. At boot the helper waits for boot completion and the unlocked
# storage, then starts the recorder on the SAME folder. The REAL helper runs against a stub
# recorder that publishes the marker as the real one does; a reboot is a SIGKILL plus a boot
# id that no longer matches.
set -u
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
HELPER="$ROOT/runtime/asb_debug_support.sh"
TMP="$(mktemp -d)"; trap 'kill $(jobs -p) 2>/dev/null; pkill -f "$TMP" 2>/dev/null; rm -rf "$TMP"' EXIT
fail() { echo "FAIL debug resume: $*" >&2; exit 1; }
alive() { [ -r "/proc/$1/stat" ] || return 1; case "$(sed 's/^.*) //' "/proc/$1/stat" | cut -c1)" in Z|X) return 1 ;; esac; return 0; }
DBG="$TMP/mod"; mkdir -p "$DBG/tools/logkit" "$DBG/runtime"
printf 'id=AutoSystemBoost\nversion=V65-test16\nversionCode=650\n' > "$DBG/module.prop"
cat > "$DBG/tools/logkit/asb_log_full_day.sh" << 'EOF_REC'
set -u
_lock="${ASB_DEBUG_SUPPORT_LOCKDIR:-}"; _token="${ASB_DEBUG_SUPPORT_LOCK_TOKEN:-}"
[ -d "$_lock" ] && [ "$(cat "$_lock/token")" = "$_token" ] || exit 91
printf '%s\n' "$$" > "$_lock/pid"
if [ -n "${ASB_LK_RESUME_DIR:-}" ] && [ -d "$ASB_LK_RESUME_DIR" ]; then
  _out="$ASB_LK_RESUME_DIR"; echo "$$" >> "$_out/resumed_by"
else
  _out="$(dirname "$_lock")/asb_log_full_day_$$"; mkdir -p "$_out"
fi
printf '%s\n' "$_out" > "$_lock/output_dir"
{ echo "dir=$_out"; echo "boot=${ASB_DEBUG_SUPPORT_BOOT_ID:-}"; } > "$ASB_DEBUG_SUPPORT_RESUMEFILE"
trap 'echo finalized > "$_out/_full_day_report.txt"; rm -rf "$_lock"; exit 0' TERM
while :; do sleep 60; done
EOF_REC
printf 'sys.boot_completed=1\nsys.user.0.ce_available=true\n' > "$TMP/props"
ENV=(ASB_DEBUG_SUPPORT_MODDIR="$DBG" ASB_DEBUG_SUPPORT_STATE_DIR="$TMP/state" ASB_DEBUG_SUPPORT_RUNLOG="$TMP/run.out"
     ASB_DEBUG_SUPPORT_STOP_WAIT_S=3 ASB_DEBUG_SUPPORT_PROPS="$TMP/props" ASB_DEBUG_SUPPORT_RESUME_POLL_S=1
     ASB_DEBUG_SUPPORT_RESUME_SETTLE_S=0 ASB_DEBUG_SUPPORT_RESUME_GRACE_S=2)
H() { env "${ENV[@]}" sh "$HELPER" "$@" 2>/dev/null || true; }
LOCK="$TMP/state/full_day_webui.lock"; MARK="$TMP/state/full_day_resume"
reboot_now() {
  _p="$(tr -dc 0-9 < "$LOCK/pid" 2>/dev/null)"
  [ -n "$_p" ] && kill -KILL "$_p" 2>/dev/null
  n=0; while [ -n "$_p" ] && alive "$_p" && [ "$n" -lt 30 ]; do sleep 0.1; n=$((n + 1)); done
  printf 'old-boot\n' > "$LOCK/boot_id" 2>/dev/null
  sed -i 's/^boot=.*/boot=old-boot/' "$MARK"
}
OUT="$(H full-day-start)"; printf '%s\n' "$OUT" | grep 'status=started' >/dev/null || fail "start: $OUT"
printf '%s\n' "$OUT" | grep -x 'limit=until_stopped' >/dev/null || fail "the start does not say it runs until stopped: $OUT"
n=0; while [ ! -s "$MARK" ] && [ "$n" -lt 50 ]; do sleep 0.1; n=$((n + 1)); done
CAP="$(sed -n 's/^dir=//p' "$MARK")"
[ -d "$CAP" ] || fail "no resume marker naming the capture folder"
OUT="$(H full-day-resume)"; printf '%s\n' "$OUT" | grep -x 'status=idle' >/dev/null || fail "a resume in the same boot must do nothing: $OUT"
reboot_now
OUT="$(H status)"
printf '%s\n' "$OUT" | grep -x 'status=resuming' >/dev/null || fail "after a reboot the status must say resuming: $OUT"
printf '%s\n' "$OUT" | grep -x "output=$CAP" >/dev/null || fail "the resuming status must name the folder: $OUT"
OUT="$(H full-day-resume)"; printf '%s\n' "$OUT" | grep -x 'status=resuming' >/dev/null || fail "boot resume: $OUT"
n=0; while [ ! -s "$CAP/resumed_by" ] && [ "$n" -lt 80 ]; do sleep 0.1; n=$((n + 1)); done
[ -s "$CAP/resumed_by" ] || fail "the recorder was not restarted on the same folder"
P2="$(tr -dc 0-9 < "$LOCK/pid" 2>/dev/null)"; [ -n "$P2" ] && alive "$P2" || fail "the resumed recorder is not running"
OUT="$(H status)"; printf '%s\n' "$OUT" | grep -x 'status=running' >/dev/null || fail "status after the resume: $OUT"
[ "$(sed -n 's/^dir=//p' "$MARK")" = "$CAP" ] || fail "the resumed recorder lost the marker"
reboot_now
printf 'sys.boot_completed=1\nsys.user.0.ce_available=false\n' > "$TMP/props"
mv "$CAP" "$CAP.locked"
OUT="$(H full-day-resume)"; printf '%s\n' "$OUT" | grep -x 'status=resuming' >/dev/null || fail "second boot resume: $OUT"
sleep 3
[ -s "$MARK" ] || fail "a locked storage must not drop the resume"
mv "$CAP.locked" "$CAP"
printf 'sys.boot_completed=1\nsys.user.0.ce_available=true\n' > "$TMP/props"
n=0; while [ "$(wc -l < "$CAP/resumed_by")" -lt 2 ] && [ "$n" -lt 80 ]; do sleep 0.1; n=$((n + 1)); done
[ "$(wc -l < "$CAP/resumed_by")" -ge 2 ] || fail "the capture did not resume once the storage unlocked"
P3="$(tr -dc 0-9 < "$LOCK/pid" 2>/dev/null)"
OUT="$(H full-day-stop)"; printf '%s\n' "$OUT" | grep -x 'status=stopping' >/dev/null || fail "stop of the resumed capture: $OUT"
[ -e "$MARK" ] && fail "stopping must clear the resume marker"
n=0; while alive "$P3" && [ "$n" -lt 40 ]; do sleep 0.1; n=$((n + 1)); done
grep -qx finalized "$CAP/_full_day_report.txt" 2>/dev/null || fail "the stopped capture did not finalise"
OUT="$(H status)"; printf '%s\n' "$OUT" | grep -x 'status=idle' >/dev/null || fail "status after the stop: $OUT"
OUT="$(H full-day-start)"; printf '%s\n' "$OUT" | grep 'status=started' >/dev/null || fail "third start: $OUT"
n=0; while [ ! -s "$MARK" ] && [ "$n" -lt 50 ]; do sleep 0.1; n=$((n + 1)); done
reboot_now
OUT="$(H full-day-stop)"
printf '%s\n' "$OUT" | grep -x 'status=stopped' >/dev/null || fail "stopping a pending resume: $OUT"
[ -e "$MARK" ] && fail "a pending resume survived the stop"
OUT="$(H status)"; printf '%s\n' "$OUT" | grep -x 'status=idle' >/dev/null || fail "status after cancelling the resume: $OUT"
OUT="$(H full-day-start)"; printf '%s\n' "$OUT" | grep 'status=started' >/dev/null || fail "fourth start: $OUT"
n=0; while [ ! -s "$MARK" ] && [ "$n" -lt 50 ]; do sleep 0.1; n=$((n + 1)); done
CAP4="$(sed -n 's/^dir=//p' "$MARK")"
reboot_now
rm -rf "$CAP4"
OUT="$(H full-day-resume)"
n=0; while [ -e "$MARK" ] && [ "$n" -lt 80 ]; do sleep 0.1; n=$((n + 1)); done
[ -e "$MARK" ] && fail "a deleted folder must cancel the resume"
grep -q 'resume=dir_missing' "$TMP/state/full_day_webui.recovery.log" || fail "the cancelled resume left no note"
[ -d "$CAP4" ] && fail "a resume recreated a deleted folder"
grep -Fq 'asb_debug_support.sh" full-day-resume' "$ROOT/service.sh" || fail "service.sh does not resume the capture at boot"
grep -Fq "info.status === 'resuming'" "$ROOT/webroot/index.html" || fail "the WebUI does not treat a pending resume as recording"
grep -Fq "if (info.status === 'stopped') {" "$ROOT/webroot/index.html" || fail "the WebUI has no answer for a cancelled resume"
echo "PASS debug support resume: the capture resumes on its own folder after a reboot (also after a late unlock), the status says resuming meanwhile, the WebUI stop cancels it, a deleted folder ends it"
)

t_debug_support_revive_runtime() (
# Runtime (fix279): an OP15 capture stopped at 15:37:57 when the Android framework restarted
# (SystemUI, the launcher and Bluetooth all came back within two seconds, no reboot): the
# recorder shared the root manager's session and died with it without finalising, and the
# boot-only resume never ran because the boot id had not changed. The recorder now starts in
# its own session, and a recorder lost within the same boot is continued on its own folder by
# full-day-revive (service tick and WebUI). The REAL helper runs against a stub recorder.
set -u
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
HELPER="$ROOT/runtime/asb_debug_support.sh"
TMP="$(mktemp -d)"; trap 'kill $(jobs -p) 2>/dev/null; pkill -f "$TMP" 2>/dev/null; rm -rf "$TMP"' EXIT
fail() { echo "FAIL debug revive: $*" >&2; exit 1; }
alive() { [ -r "/proc/$1/stat" ] || return 1; case "$(sed 's/^.*) //' "/proc/$1/stat" | cut -c1)" in Z|X) return 1 ;; esac; return 0; }
DBG="$TMP/mod"; mkdir -p "$DBG/tools/logkit" "$DBG/runtime"
printf 'id=AutoSystemBoost\nversion=V65-test16\nversionCode=650\n' > "$DBG/module.prop"
cat > "$DBG/tools/logkit/asb_log_full_day.sh" << 'EOF_REC'
set -u
_lock="${ASB_DEBUG_SUPPORT_LOCKDIR:-}"; _token="${ASB_DEBUG_SUPPORT_LOCK_TOKEN:-}"
[ -d "$_lock" ] && [ "$(cat "$_lock/token")" = "$_token" ] || exit 91
printf '%s\n' "$$" > "$_lock/pid"
if [ -n "${ASB_LK_RESUME_DIR:-}" ] && [ -d "$ASB_LK_RESUME_DIR" ]; then
  _out="$ASB_LK_RESUME_DIR"; echo "$$ ${ASB_LK_RESUME_KIND:-none}" >> "$_out/resumed_by"
else
  _out="$(dirname "$_lock")/asb_log_full_day_$$"; mkdir -p "$_out"
fi
sed 's/^.*) //' "/proc/$$/stat" | awk -v p="$$" '{ print ($4 == p) ? "own" : "shared" }' > "$_out/session.$$"
printf '%s\n' "$_out" > "$_lock/output_dir"
{ echo "dir=$_out"; echo "boot=${ASB_DEBUG_SUPPORT_BOOT_ID:-}"; } > "$ASB_DEBUG_SUPPORT_RESUMEFILE"
trap 'echo finalized > "$_out/_full_day_report.txt"; rm -f "$ASB_DEBUG_SUPPORT_RESUMEFILE"; rm -rf "$_lock"; exit 0' TERM
while :; do sleep 60; done
EOF_REC
printf 'sys.boot_completed=1\nsys.user.0.ce_available=true\n' > "$TMP/props"
ENV=(ASB_DEBUG_SUPPORT_MODDIR="$DBG" ASB_DEBUG_SUPPORT_STATE_DIR="$TMP/state" ASB_DEBUG_SUPPORT_RUNLOG="$TMP/run.out"
     ASB_DEBUG_SUPPORT_STOP_WAIT_S=3 ASB_DEBUG_SUPPORT_PROPS="$TMP/props")
H() { env "${ENV[@]}" sh "$HELPER" "$@" 2>/dev/null || true; }
LOCK="$TMP/state/full_day_webui.lock"; MARK="$TMP/state/full_day_resume"
OUT="$(H full-day-start)"; printf '%s\n' "$OUT" | grep 'status=started' >/dev/null || fail "start: $OUT"
n=0; while [ ! -s "$MARK" ] && [ "$n" -lt 50 ]; do sleep 0.1; n=$((n + 1)); done
CAP="$(sed -n 's/^dir=//p' "$MARK")"; [ -d "$CAP" ] || fail "no resume marker"
P1="$(tr -dc 0-9 < "$LOCK/pid")"
if command -v setsid >/dev/null 2>&1; then
  [ "$(cat "$CAP/session.$P1" 2>/dev/null)" = own ] || fail "the recorder still shares the launcher's session: $(cat "$CAP/session.$P1" 2>/dev/null)"
fi
OUT="$(H full-day-revive)"; printf '%s\n' "$OUT" | grep -x 'status=running' >/dev/null || fail "revive of a live recorder: $OUT"
kill -KILL "$P1"; n=0; while alive "$P1" && [ "$n" -lt 30 ]; do sleep 0.1; n=$((n + 1)); done
OUT="$(H status)"
printf '%s\n' "$OUT" | grep -x 'status=resuming' >/dev/null || fail "a recorder lost in this boot must read resuming: $OUT"
printf '%s\n' "$OUT" | grep -x 'reason=restart' >/dev/null || fail "the same-boot loss is not named: $OUT"
printf '%s\n' "$OUT" | grep -x "output=$CAP" >/dev/null || fail "the folder is not named: $OUT"
OUT="$(H full-day-resume)"; printf '%s\n' "$OUT" | grep -x 'status=idle' >/dev/null || fail "the boot resume must stay boot-only: $OUT"
printf 'sys.boot_completed=0\nsys.user.0.ce_available=true\n' > "$TMP/props"
OUT="$(H full-day-revive)"; printf '%s\n' "$OUT" | grep -x 'status=resuming' >/dev/null || fail "revive before boot completion: $OUT"
[ -e "$CAP/resumed_by" ] && fail "revived before the framework finished starting"
printf 'sys.boot_completed=1\nsys.user.0.ce_available=true\n' > "$TMP/props"
OUT="$(H full-day-revive)"; printf '%s\n' "$OUT" | grep -x 'status=started' >/dev/null || fail "revive: $OUT"
n=0; while [ ! -s "$CAP/resumed_by" ] && [ "$n" -lt 50 ]; do sleep 0.1; n=$((n + 1)); done
grep -q ' restart$' "$CAP/resumed_by" || fail "the revived recorder was not told it is a same-boot restart: $(cat "$CAP/resumed_by" 2>/dev/null)"
P2="$(tr -dc 0-9 < "$LOCK/pid")"; [ -n "$P2" ] && [ "$P2" != "$P1" ] && alive "$P2" || fail "no revived recorder"
grep -q 'revive=start' "$TMP/state/full_day_webui.recovery.log" || fail "the revive left no note"
OUT="$(H full-day-revive)"; printf '%s\n' "$OUT" | grep -x 'status=running' >/dev/null || fail "second revive: $OUT"
[ "$(wc -l < "$CAP/resumed_by")" = 1 ] || fail "a second recorder was started"
OUT="$(H full-day-stop)"; printf '%s\n' "$OUT" | grep -x 'status=stopping' >/dev/null || fail "stop: $OUT"
n=0; while alive "$P2" && [ "$n" -lt 40 ]; do sleep 0.1; n=$((n + 1)); done
[ -e "$MARK" ] && fail "stop kept the marker"
OUT="$(H full-day-revive)"; printf '%s\n' "$OUT" | grep -x 'status=idle' >/dev/null || fail "revive after a stop: $OUT"
OUT="$(H status)"; printf '%s\n' "$OUT" | grep -x 'status=idle' >/dev/null || fail "status after the stop: $OUT"
OUT="$(H full-day-start)"; n=0; while [ ! -s "$MARK" ] && [ "$n" -lt 50 ]; do sleep 0.1; n=$((n + 1)); done
P3="$(tr -dc 0-9 < "$LOCK/pid")"; CAP3="$(sed -n 's/^dir=//p' "$MARK")"
kill -KILL "$P3"; n=0; while alive "$P3" && [ "$n" -lt 30 ]; do sleep 0.1; n=$((n + 1)); done
OUT="$(H full-day-stop)"; printf '%s\n' "$OUT" | grep -x 'status=stopped' >/dev/null || fail "stopping a pending same-boot revive: $OUT"
OUT="$(H full-day-revive)"; printf '%s\n' "$OUT" | grep -x 'status=idle' >/dev/null || fail "a cancelled revive came back: $OUT"
[ -e "$CAP3/resumed_by" ] && fail "a cancelled capture was revived"
grep -Fq 'asb_debug_support.sh" full-day-revive' "$ROOT/service.sh" || fail "the service tick does not revive a lost recorder"
grep -Fq "asb_debug_support.sh full-day-revive" "$ROOT/webroot/index.html" || fail "the WebUI does not revive a lost recorder"
grep -Fq 'nohup $_fd_setsid sh' "$HELPER" || fail "the recorder is not started in its own session"
echo "PASS debug support revive: own session, a recorder lost in the same boot reads resuming/restart and continues on its folder once, a stop cancels it"
)

t_webui_fix279_drain_runtime() (
# buildfix21: the active card uses since-boot + global last night. Inactive cards use only
# their own latest completed screen-on session and own last night, never the active history.
set -eu
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
command -v node >/dev/null 2>&1 || { echo 'SKIP webui drain (no node)'; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
python3 - "$H" "$T/t.js" <<'PY'
import re,sys
h=open(sys.argv[1],encoding='utf-8').read()
def fn(n):
 m=re.search(r'^function '+re.escape(n)+r'\([^\n]*\) \{.*?^\}',h,re.M|re.S);assert m,n;return m.group(0)
def const(n):
 m=re.search(r'^const '+re.escape(n)+r' = .*?;$',h,re.M|re.S);assert m,n;return m.group(0)
body="""function T(k,d){return d} function techIcon(){return ''}
const els={}; function _el(id){return els[id]||null}
['bnDrain','bnDrainOff','bnDrainOnLabel','bnDrainOffLabel','liveEtaOn','liveEtaOff'].forEach(id=>els[id]={textContent:'',title:''});
function node(){return {textContent:'',className:'',innerHTML:'',title:'',hidden:false,children:[],appendChild(c){this.children.push(c);this.textContent+=c.textContent||''}}}
const boxes=['smart','battery'].map(profile=>Object.assign(node(),{getAttribute(){return profile}}));
const document={querySelectorAll(s){return s==='.pmeta[data-meter]'?boxes:[]},createElement(){return node()},createTextNode(t){return {textContent:t}}};
const asbUiFrame={request(){}};function asbFitPages(){}
function asbMetricPaint(){} function liveDrainIsOpen(){return false} function liveDrainPaint(){}
let _selectedProfile='smart';
"""
src='\n'.join([body,const('_lvMeter'),const('_lvGovOff'),const('_lvDrain'),const('_lvEta'),
 fn('lvBootParse'),fn('lvBootBasis'),fn('lvBootOnFigure'),fn('lvNightParse'),fn('lvMeterParse'),fn('lvDurDHM'),fn('lvPct'),fn('lvOffFigure'),
 fn('lvNightFresh'),fn('lvNightFigure'),fn('lvProfileNightFigure'),fn('lvProfileOnFigure'),fn('lvBootMature'),fn('lvOnFigure'),fn('lvOnKind'),fn('lvOnTip'),fn('lvPrimaryOffFigure'),fn('lvMeterHasOn'),fn('lvMeterPaint'),fn('lvEtaFmt'),fn('lvEtaPaint'),fn('homeOffFigure'),fn('homeMeterPaint'),r"""
let bad=0;function chk(c,m){if(!c){bad=1;console.log('FAIL '+m)}}
const testNowDate=new Date();testNowDate.setHours(12,0,0,0);const testNow=Math.floor(testNowDate.getTime()/1000);Date.now=()=>testNow*1000;
const parsed=lvMeterParse('smart 3600 500 14400 200 1 50 14400 1 500 3600 10 50 14400 10\ncurrent smart\n');
chk(parsed.p.smart.onLast===500&&parsed.p.smart.onLastS===3600&&parsed.p.smart.nightLastS===14400,'15-field parser');
_lvMeter.p=parsed.p;_lvMeter.cur='battery';_lvMeter.boot=lvBootParse('abc 7200 10000 1000 0 0 0');
const nightNow=testNow;_lvMeter.night=lvNightParse('25 14400 '+(nightNow-3600));
_lvMeter.p.battery={on:100,onMin:60,off:80,offN:2,offS:20000,offLast:0,offLastS:0,offLastAt:0,onLast:120,onLastS:3600,onLastAt:20,nightLast:40,nightLastS:18000,nightLastAt:nightNow-1800};
homeMeterPaint();
chk(boxes[0].textContent==='5.0%/h0.25%/h','active Home uses the mature latest profile sample and last night: '+boxes[0].textContent);
chk(boxes[1].textContent==='1.2%/h0.40%/h','inactive Home uses only its own latest session and night: '+boxes[1].textContent);
chk(boxes.every(b=>!b.children.some(c=>c.className==='pmeta-scope')),'Home cards do not create visible scope labels');
_lvEta.cap=60;lvMeterPaint('smart');
chk(els.bnDrain.textContent==='5.0%/h'&&els.bnDrainOnLabel.textContent==='Screen on','selected active prefers its mature profile sample: '+els.bnDrain.textContent);
chk(els.bnDrainOff.textContent==='0.25%/h'&&els.bnDrainOffLabel.textContent==='Screen off','active last night');
/* Field regression: a stale shared 2.83 %/h record must not hide the active profile's
 * newer 0.20 %/h night. An older-than-latest-morning record is not "last night" at all. */
_lvMeter.night=lvNightParse('283 21600 '+(nightNow-3600));
_lvMeter.p.smart.nightLast=20;_lvMeter.p.smart.nightLastS=18000;_lvMeter.p.smart.nightLastAt=nightNow-1800;
lvMeterPaint('smart');
chk(els.bnDrainOff.textContent==='0.20%/h','newer profile night replaces stale shared 2.83: '+els.bnDrainOff.textContent);
homeMeterPaint();
chk(boxes[0].textContent==='5.0%/h0.20%/h','Home also chooses the newer 0.20 profile night: '+boxes[0].textContent);
chk(lvNightFresh(nightNow-1800,nightNow*1000)&&!lvNightFresh(1,nightNow*1000),'calendar freshness rejects an old saved night');
_lvMeter.night=lvNightParse('25 14400 '+(nightNow-3600));_lvMeter.p.smart.nightLastAt=10;
lvMeterPaint('battery');
chk(els.bnDrain.textContent==='1.2%/h'&&els.bnDrainOnLabel.textContent==='Screen on','inactive own latest: '+els.bnDrain.textContent);
chk(els.bnDrainOff.textContent==='0.40%/h'&&els.bnDrainOffLabel.textContent==='Screen off','inactive own night');
chk(els.liveEtaOn.textContent==='12h 00m','ETA stays bound to the selected active profile while an inactive comparison is painted: '+els.liveEtaOn.textContent);
_selectedProfile='battery';lvMeterPaint('battery');
chk(els.bnDrain.textContent==='1.2%/h'&&els.liveEtaOn.textContent==='50h 00m','newly selected profile keeps its own mature sample: '+els.bnDrain.textContent+' '+els.liveEtaOn.textContent);
_selectedProfile='smart';_lvMeter.p.battery.nightLastS=0;lvMeterPaint('battery');
chk(els.bnDrainOff.textContent==='0.80%/h'&&els.bnDrainOffLabel.textContent==='Screen off','inactive aggregate fallback is labelled');
chk(els.bnDrainOff.textContent!=='0.25%/h','inactive borrowed active global night');
_lvMeter.cur='';_lvMeter.p.smart.on=0;_lvMeter.p.smart.onLastS=0;_lvMeter.boot=lvBootParse('abc 3600 10000 0 0 0 0');lvMeterPaint('smart');
chk(els.bnDrain.textContent==='measuring…','zero-step since-boot must wait instead of inventing a rate: '+els.bnDrain.textContent);
homeMeterPaint();
chk(boxes[0].textContent==='0.25%/h','active Home omits an unmeasured boot rate with empty meter current: '+boxes[0].textContent);
_lvMeter.p.battery.on=0;_lvMeter.p.battery.onLast=0;lvMeterPaint('battery');
chk(els.bnDrain.textContent==='measuring…','a zero-step session is no rate and no upper bound: '+els.bnDrain.textContent);
_lvMeter.p.battery.on=70;_lvMeter.p.battery.onMin=180;lvMeterPaint('battery');
chk(els.bnDrain.textContent==='7.0%/h','a zero-step session falls back to the profile average: '+els.bnDrain.textContent);
_lvMeter.p.battery.onLast=100;_lvMeter.p.battery.onLastS=600;lvMeterPaint('battery');
chk(els.bnDrain.textContent==='7.0%/h','one step in ten minutes is too coarse to replace the average: '+els.bnDrain.textContent);
_lvMeter.p.battery.onLast=200;lvMeterPaint('battery');
chk(els.bnDrain.textContent==='12.0%/h','two steps make a short session a measurement: '+els.bnDrain.textContent);
_lvMeter.p.battery.onLast=100;_lvMeter.p.battery.onLastS=1800;lvMeterPaint('battery');
