    if p.name == 'en.json':
        assert d['lr_sec_drain'] == '\U0001f50b Battery drain'
        assert d['dbg_log_btn'] == 'Infinite log' and d['lr_menu'] == 'Infinite log report'
        assert d['lr_running'] == 'recording \u00b7 {min} min of {h} h'
        assert d['lr_running_open'] == 'recording \u00b7 {min} min \u00b7 until you stop it'
        assert d['lr_tip_night'] == 'Overnight the phone lost ~{pct}%/h - check background apps.'
        assert d['lr_per_hour'] == '%/h' and d['lr_refresh'] == 'Refresh'
        assert d['lr_secs'] == '{n} sec'
        assert d['lr_sec_smooth'] == '\U0001f4f1 Smoothness'
        assert d['lr_saved'] == 'saved capture \u00b7 {when} \u00b7 {profile}'
        assert d['lr_jank_all'] == 'of {frames} frames' and d['lr_ms_h'] == '{n} ms/h'
        assert d['lr_tip_jank_ok'] == 'Smoothness is good: only {pct}% of frames were late.'
        assert 'proved' not in d['lr_tip_smart_help'].lower()
        assert 'mostly in {phase}' not in d['lr_tip_heat_warm']
        assert 'do not distinguish app updates' in d['lr_dx_fix_net_play']
        assert 'not proof that a lift was armed' in d['lr_zy_accept_note']
        assert 'not a hardware ceiling write' in d['lr_zy_gov_note']
        assert 'total control of other Zygisk modules' in d['lr_zy_note_actions'] and 'No A/B comparison' in d['lr_zy_note_actions']
    if p.name == 'ru.json':
        assert d['lr_sec_drain'] == '\U0001f50b Разряд батареи'
        assert d['lr_menu'] == 'Отчёт бесконечного лога' and d['lr_refresh'] == 'Обновить'
        assert d['dbg_log_btn'] == 'Бесконечный лог' and d['dbg_log_stop_btn'] == 'Остановить бесконечный лог'
        assert 'выключ' not in d['dbg_log_started']
        assert d['lr_secs'] == '{n} сек'
        assert d['lr_sec_smooth'] == '\U0001f4f1 Плавность'
        assert d['lr_saved'] == 'сохранённый лог \u00b7 {when} \u00b7 {profile}'
# Key-set parity: every locale must carry exactly the English key set. A missing key
# silently falls back to English mid-screen; an extra one is dead weight. (Real drift
# caught: t_cfg_video existed in 12 locales but not en.)
ref = set(json.loads((root / 'webroot' / 'i18n' / 'en.json').read_text(encoding='utf-8')))
for p in files:
    d = json.loads(p.read_text(encoding='utf-8'))
    assert set(d) == ref, '%s: key set differs from en (%s)' % (p.name, sorted(set(d) ^ ref)[:3])
h = (root / 'webroot' / 'index.html').read_text(encoding='utf-8')
assert h.count('data-i18n="lr_menu"') == 2, 'menu item and page section label carry lr_menu'
P
grep -Fq 'onclick="asbLogMenuPick('"'"'report'"'"')"' "$H" || fail "the menu item does not pick report"
grep -Fq "if (action === 'report') { openReportPage(); return; }" "$H" || fail "the report branch is gone from asbLogMenuPick"
grep -Fq "run('sh ' + MD + '/tools/logkit/asb_fullday_digest.sh 2>/dev/null')" "$H" || fail "the digest invocation changed"
grep -Fq 'iclassName' "$H" && fail "typo"
grep -Fq '#reportPage { z-index: 130;' "$H" || fail "the report page is not a page layer above Config"
grep -Fq 'id="reportPage"' "$H" || fail "report page markup missing"
grep -Fq 'function openReportPage()' "$H" || fail "openReportPage missing"
grep -Fq 'function closeReportPage()' "$H" || fail "closeReportPage missing"
grep -Fq "if (document.body.classList.contains('report-active')) return 'report';" "$H" || fail "asbNavCurrent does not know the report page"
grep -Fq '.lgr-heros { display: grid;' "$H" || fail "hero tiles styles missing"
grep -Fq "'Noto Color Emoji'" "$H" || fail "the sans stack lost its emoji fallback"
grep -Fq 'function logReportDurSec(sec)' "$H" || fail "seconds-level duration formatter missing"
grep -Fq 'logReportDurSec(w.sec)' "$H" || fail "wakelock rows must format sub-minute holds in seconds"
grep -Fq 'textContent = tip.ic' "$H" || fail "tips must render via textContent, not markup"
grep -Fq 'function logReportTable(heads, rows, numCols)' "$H" || fail "the fix200 table builder is missing"
grep -Fq '.lgr-table { width: 100%; border-collapse: collapse; table-layout: fixed;' "$H" || fail "the fix200 table styles are missing"
grep -Fq "logReportT('lr_saved', 'saved capture · {when} · {profile}'" "$H" || fail "a saved capture must be named with its start time and profile"
grep -Fq "lr_tip_wl_enable: '{app} held the phone awake for {min} min" "$H" || fail "the wakelock tip lost its English fallback"
grep -Fq "Tcfg('night_modem_idle', 'name', 'Quiet Radio at Night')" "$H" || fail "advice must name settings as the Settings screen names them"
grep -Fq '"tools/logkit/asb_fullday_digest.sh"' "$ROOT/.github/workflows/build-test.yml" || fail "debug workflow does not ship the digest"
grep -Fq '"tools/logkit/asb_fullday_digest.sh"' "$ROOT/.github/workflows/build-release.yml" || fail "release workflow does not ship the digest"
grep -Fq 'asb_fullday_digest.sh' "$ROOT/.github/workflows/build-release.yml" || fail "release staging loop lost the digest"
grep -Fq 'crash.ltime' "$H" || fail "fix204: the sheet must show WHEN the latest crash happened"
# fix213: device context, heat durations, night habits and the trend must all be wired
grep -Fq 'd.sections.meta2' "$H" || fail "the page never reads the device context"
grep -Fq "T('lr_sec_trend'," "$H" || fail "the trend section is not rendered"
grep -Fq "'lr_tip_heat_warm'" "$H" || fail "the heat advice is gone"
grep -Fq "Tcfg('sustained_temp_mode', 'name', 'Throttling Point')" "$H" || fail "the heat advice does not name the thermal switch"
grep -Fq "T('lr_mwake'," "$H" || fail "the night-habits row is gone"
grep -Fq "tag === 'hist'" "$H" || fail "the parser drops the history rows"
grep -Fq 'hist\tstarted=' "$ROOT/tools/logkit/asb_fullday_digest.sh" 2>/dev/null || grep -F 'hist\tstarted=%s' "$ROOT/tools/logkit/asb_fullday_digest.sh" >/dev/null || fail "the digest emits no history rows"
grep -Fq 'report_history.tsv' "$ROOT/tools/logkit/asb_fullday_digest.sh" || fail "the digest keeps no capture history"
echo "PASS webui log report: digest over a fixture capture (drain..cfg, live holders, per-profile drain, charging, LTPO, AOD, wake causes by occurrence fix210), fresh-capture crash window (fix204), plain-words parser/tips in node (ru+en), 13 locales, menu wiring"
)

t_fullday_digest_trace_truth_runtime() (
# fix246: an owner's Battery capture said "skin above 40 C for 41 min" and "night peak CPU
# 37" while the phone sat at 33 C overnight and once ran at 57 C with the screen off. The
# recorder averaged a zone that never moves (sys-therm-6 pinned at 40-41 C) into its idle
# phases, and the digest read phase averages as peaks. The sync loop that kept it awake
# printed as "com.whatsapp:android" and the report then hid it behind the package row.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
D="$ROOT/tools/logkit/asb_fullday_digest.sh"
C="$ROOT/tools/logkit/_asb_logkit_common.sh"
fail() { echo "FAIL digest trace truth: $*" >&2; exit 1; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
NOW=$(date +%s)
CAP="$T/asb_log_full_day_1"; mkdir -p "$CAP"
S0=$((NOW-20000))
printf '# phase\tstart\n' > "$CAP/phase_ledger.tsv"
printf 'active\t%s\t%s\t80\t78\t44\t41\t1800\t20\t0\t0\t100\t300\t0\t0\t0\n' $((S0)) $((S0+1800)) >> "$CAP/phase_ledger.tsv"
printf 'idle\t%s\t%s\t78\t78\t34\t40\t0\t0\t0\t0\t9\t50\t0\t0\t0\n' $((S0+1800)) $((S0+3600)) >> "$CAP/phase_ledger.tsv"
printf 'sleep\t%s\t%s\t78\t74\t36\t40\t0\t0\t0\t0\t30\t60\t0\t0\t0\n' $((S0+3600)) $((S0+14400)) >> "$CAP/phase_ledger.tsv"
{
  echo 'epoch|datetime|fsm_state|profile|screen|bat_pct|bat_mA|bat_uV|bat_dC|cpu_max_c|skin_c|surface_c|board_c'
  i=0; while [ $i -lt 30 ]; do
    e=$((S0 + i * 60)); c=46; s=41; [ $i -ge 20 ] && { c=40; s=38; }
    echo "$e|d|MODERATE|battery|1|80|300|0|0|$c|35|$s|$s"; i=$((i + 1))
  done
  i=0; while [ $i -lt 20 ]; do
    e=$((S0 + 3700 + i * 500)); c=33; s=33; [ $i -eq 7 ] && { c=57; s=42; }
    echo "$e|d|DEEP_IDLE|battery|0|77|40|0|0|$c|33|$s|$s"; i=$((i + 1))
  done
} > "$CAP/battery_trace.txt"
cat > "$CAP/_full_day_report.txt" <<'EOF'
----- LIVE WAKELOCK HOLDERS (power-manager samples, screen off) -----
screen-off samples: 44
  held in  68% of samples, longest hold    0 min  *job*r/@SyncManager@com.android.contacts/com.whatsapp:android  (com.whatsapp)
  held in  68% of samples, longest hold    0 min  *sync*/com.android.contacts/com.whatsapp  (com.whatsapp)
  held in  22% of samples, longest hold    0 min  *job*r/#MediaCountUploadWorker#@androidx.work.systemjobscheduler@com.facebook.katana/androidx.work.impl.background.systemjob.SystemJobService  (com.facebook.katana)
  held in  10% of samples, longest hold    2 min  *alarm*/com.example/.Tick  (com.example)

steady floor: 1.33 janky frames a second while almost nothing was drawn (under 5 frames/s),
2.52 a second in the busy intervals (20 frames/s and more). Something misses a deadline about
main cores at the ASB ceiling (end of interval): yes 5.8% of 26813 frames (2.25/s), no 5.7% of 50927 frames (2.06/s)
prime cores at the ASB ceiling (end of interval): yes - of 0 frames (-/s), no 5.7% of 77740 frames (2.12/s)
the floor: com.android.systemui drew 94.0% of the janky frames in the quiet intervals.
who held the lower ceiling, per cluster (26 samples):
  main:  at or above the rail
  prime: asb_trim 6, vendor 20
  asb_trim = ASB's own thermal-budget/comfort trim (live == what ASB wrote)
EOF
out="$(sh "$D" "$CAP" 2>/dev/null)"
printf '%s\n' "$out" | grep '^wlive	tag=contacts	pct=68	min=0	pkg=com.whatsapp	kind=sync$' >/dev/null || fail "sync holder: $(printf '%s\n' "$out" | grep '^wlive' | head -1)"
[ "$(printf '%s\n' "$out" | grep -c '^wlive	tag=contacts	')" = 1 ] || fail "the same sync counted twice"
printf '%s\n' "$out" | grep -q '^wlive	tag=MediaCountUploadWorker	pct=22	min=0	pkg=com.facebook.katana	kind=worker$' || fail "worker holder: $(printf '%s\n' "$out" | grep '^wlive' | sed -n 2p)"
printf '%s\n' "$out" | grep '^wlive	tag=Tick	pct=10	min=2	pkg=com.example	kind=alarm$' >/dev/null || fail "alarm holder: $(printf '%s\n' "$out" | grep '^wlive' | sed -n 3p)"
printf '%s\n' "$out" | grep '^thermal	cpu=57	surf=42$' >/dev/null || fail "trace peak: $(printf '%s\n' "$out" | grep '^thermal')"
printf '%s\n' "$out" | grep -q '^heat	peak_phase=active	peak_c=44	warm_min=20	skin_min=20	warm_episodes=1	warm_run_min=20$' || fail "trace durations: $(printf '%s\n' "$out" | grep '^heat')"
printf '%s\n' "$out" | grep '^nightd	.*	cpu_t=57	skin_t=42	' >/dev/null || fail "night peaks from the trace: $(printf '%s\n' "$out" | grep '^nightd')"
printf '%s\n' "$out" | grep -q '^nightw' && fail "the night window leaked into the digest"
# fix247: the facts the causes card reads - whether the ASB ceiling costs frames, the jank
# floor and who held the prime cores.
printf '%s\n' "$out" | grep -q '^jcap_main	yes=5.8	yes_f=26813	yes_jps=2.25	no=5.7	no_f=50927	no_jps=2.06$' || fail "main ceiling split: $(printf '%s\n' "$out" | grep '^jcap_main')"
printf '%s\n' "$out" | grep '^jcap_prime	yes=-	yes_f=0	yes_jps=-	no=5.7	no_f=77740	no_jps=2.12$' >/dev/null || fail "prime ceiling split: $(printf '%s\n' "$out" | grep '^jcap_prime')"
printf '%s\n' "$out" | grep -q '^jfloor	quiet=1.33	busy=2.52	app=com.android.systemui	share=94.0$' || fail "jank floor: $(printf '%s\n' "$out" | grep '^jfloor')"
printf '%s\n' "$out" | grep '^vcap	n=26	main_vendor=0	main_asb=0	prime_vendor=20	prime_asb=6$' >/dev/null || fail "ceiling holders: $(printf '%s\n' "$out" | grep '^vcap')"
head -n 32 "$CAP/battery_trace.txt" > "$T/bt" && mv "$T/bt" "$CAP/battery_trace.txt"
printf 'active\t%s\t%s\t80\t78\t44\t41\t1800\t20\t0\t0\t100\t300\t0\t0\t0\n' $((S0)) $((S0+1800)) > "$CAP/phase_ledger.tsv"
out2="$(sh "$D" "$CAP" 2>/dev/null)"
printf '%s\n' "$out2" | grep -q '^heat	peak_phase=active	peak_c=44	warm_min=20	skin_min=20	warm_episodes=1	warm_run_min=20$' || fail "screen-on trace: $(printf '%s\n' "$out2" | grep '^heat')"
printf 'epoch|x\n1|a\n' > "$CAP/battery_trace.txt"
out3="$(sh "$D" "$CAP" 2>/dev/null)"
printf '%s\n' "$out3" | grep '^heat	peak_phase=active	peak_c=44	warm_min=0	skin_min=30	warm_episodes=0	warm_run_min=0$' >/dev/null || fail "ledger fallback: $(printf '%s\n' "$out3" | grep '^heat')"
printf '%s\n' "$out3" | grep -q '^thermal	cpu=44	surf=41$' || fail "ledger peak fallback: $(printf '%s\n' "$out3" | grep '^thermal')"
# fix298: total hot minutes alone cannot distinguish one sustained run from separated spells.
# Two warm episodes (2 and 3 minutes) must retain their own count and longest continuous run.
{
  echo 'epoch|datetime|fsm_state|profile|screen|bat_pct|bat_mA|bat_uV|bat_dC|cpu_max_c|skin_c|surface_c|board_c'
  i=0
  for c in 40 46 46 40 40 46 46 46 40 40 40 40; do
    echo "$((S0 + i * 60))|d|MODERATE|battery|1|80|300|0|0|$c|35|35|35"
    i=$((i + 1))
  done
} > "$CAP/battery_trace.txt"
out4="$(sh "$D" "$CAP" 2>/dev/null)"
printf '%s\n' "$out4" | grep '^heat	peak_phase=active	peak_c=44	warm_min=5	skin_min=0	warm_episodes=2	warm_run_min=3$' >/dev/null || fail "warm episodes/longest run: $(printf '%s\n' "$out4" | grep '^heat')"

Z="$T/tz"; for z in 26 15 74 83 76; do mkdir -p "$Z/thermal_zone$z"; done
echo 34000 > "$Z/thermal_zone26/temp"; echo 33000 > "$Z/thermal_zone15/temp"
echo 40000 > "$Z/thermal_zone74/temp"; echo 33000 > "$Z/thermal_zone83/temp"; echo 32500 > "$Z/thermal_zone76/temp"
f="$(sed -n '/^lk_direct_temps() {/,/^}/p' "$C")"
[ -n "$f" ] || fail "lk_direct_temps is gone"
r="$(sh -c "$f
LK_THERMAL_BASE='$Z' TZ_CPU_PRIME=26 TZ_CPU_PERF=15 TZ_SYSTHERM6=74 TZ_BOARD=83
lk_direct_temps 76; lk_direct_temps ''; lk_direct_temps 99")"
[ "$r" = "34|32
34|40
34|40" ] || fail "direct temps must read the governor's surface zone first: $r"
grep -q 'lk_direct_temps "$(echo "$_j" | awk -F'"'"'"thermal_surface_zone":'"'"'' "$ROOT/tools/logkit/asb_log_full_day.sh" || fail "the phase ledger does not pass the governor's surface zone"
grep -q 'lk_direct_temps "$(echo "$_j" | awk -F'"'"'"thermal_surface_zone":'"'"'' "$C" || fail "the battery trace does not pass the governor's surface zone"
echo "PASS digest trace truth: sync/worker/alarm holders named and deduped, peaks and hot minutes from the trace, night peaks inside the chain, ledger fallback, surface zone first"
)

t_fullday_digest_network_runtime() (
# fix248: a day of 1.9 GiB over LTE + 5G NSA read as "Mobile traffic: 1963.6 MiB" and nothing
# more. The digest now carries the screen-on share of it, the apps from Android's per-UID
# history (mobile idents only, the capture window only, the UID section only), the radio's
# network at each check, the screen-on current with and without data moving, and whether the
# LTE switches actually ran between the first and last snapshot. The display table no longer
# stops at a "?" refresh row, and ASB's wakeups carry the screen split.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
D="$ROOT/tools/logkit/asb_fullday_digest.sh"
fail() { echo "FAIL digest network: $*" >&2; exit 1; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
NOW=$(date +%s); S0=$(( (NOW - 20000) / 7200 * 7200 + 600 ))
CAP="$T/asb_log_full_day_2"; mkdir -p "$CAP"
printf '# phase\tstart\n' > "$CAP/phase_ledger.tsv"
printf 'active\t%s\t%s\t80\t70\t40\t35\t1800\t20\t0\t0\t100\t300\t%s\t%s\t0\n' $S0 $((S0 + 7200)) 943718400 104857600 >> "$CAP/phase_ledger.tsv"
printf 'sleep\t%s\t%s\t70\t69\t33\t30\t0\t0\t0\t0\t10\t40\t%s\t%s\t0\n' $((S0 + 7200)) $((S0 + 10800)) 10485760 0 >> "$CAP/phase_ledger.tsv"
{
  echo 'epoch|datetime|fsm_state|profile|screen|bat_pct|bat_mA|bat_uV|bat_dC|cpu_max_c|skin_c|surface_c|board_c|env_iq|bat_deep_idle_s|bat_light_idle_s|reserved|bat_wake|headroom_pct|headroom_valid|headroom_reason|cpu_zone|fb_zone|wifi_rx|wifi_tx|rmnet_rx|rmnet_tx'
  b=0; i=0
  while [ $i -lt 60 ]; do
    e=$((S0 + i * 60))
    if [ $((i % 2)) = 0 ]; then b=$((b + 6291456)); ma=340; else b=$((b + 1024)); ma=250; fi
    echo "$e|d|MODERATE|battery|1|80|$ma|0|0|40|30|33|33|0|0|0||0|100|1|ok|z|z|0|0|$b|0"
    i=$((i + 1))
  done
} > "$CAP/battery_trace.txt"
cat > "$CAP/netstats_uid_latest.txt" <<EOF
# netstats uid capture: tag=latest epoch=$((S0 + 10800))
Active interfaces:
  iface=rmnet_data2 ident=[{type=0, ratType=13}]
Xt stats:
  ident=[{type=0, ratType=-2}] uid=-1 set=ALL tag=0x0
    NetworkStatsHistory: bucketDuration=7200
      st=$((S0 - 600)) rb=999999999 rp=1 tb=0 tp=0 op=0
UID stats:
  Pending bytes: 0
  ident=[{type=0, ratType=-2, metered=true}] uid=10617 set=DEFAULT tag=0x0
    NetworkStatsHistory: bucketDuration=7200
      st=$((S0 - 7800)) rb=500000000 rp=1 tb=0 tp=0 op=0
      st=$((S0 - 600)) rb=314572800 rp=1 tb=10485760 tp=1 op=0
      st=$((S0 + 6600)) rb=209715200 rp=1 tb=0 tp=0 op=0
  ident=[{type=1, ratType=-1, metered=false}] uid=10617 set=DEFAULT tag=0x0
    NetworkStatsHistory: bucketDuration=7200
      st=$((S0 - 600)) rb=888888888 rp=1 tb=0 tp=0 op=0
  ident=[{type=0, ratType=-2, metered=true}] uid=10443 set=FOREGROUND tag=0x0
    NetworkStatsHistory: bucketDuration=7200
      st=$((S0 - 600)) rb=104857600 rp=1 tb=0 tp=0 op=0
  ident=[{type=0, ratType=-2, metered=true}] uid=10999 set=DEFAULT tag=0x0
    NetworkStatsHistory: bucketDuration=7200
      st=$((S0 - 600)) rb=4194304 rp=1 tb=0 tp=0 op=0
InterfaceMapHelper:
  ident=[{type=0}] uid=10443 set=DEFAULT tag=0x0
      st=$((S0 - 600)) rb=777777777 rp=1 tb=0 tp=0 op=0
EOF
printf '10617 com.moonshot.kimichat\n10443 org.telegram.messenger\n' > "$CAP/uid_map.txt"
printf '  data_rat: network=LTE, overrideNetwork=NR_NSA \n  data_rat: network=LTE, overrideNetwork=NONE \n  data_rat: network=LTE, overrideNetwork=NR_NSA \n' > "$CAP/network_trace.txt"
snap() {
  printf '===== NET STATE =====\n  lte_screenoff status:\n    enabled=1\n    applied=0\n    reason=none\n    light=1\n    light_watch=%s\n    pending=0\n    unsupported=0\n    last=x\n    applies=%s\n    restores=%s\n    lte_minutes=%s\n    quiet_windows=%s\n  lte_screenoff log (last 8):\n    10-28 x\n' "$1" "$2" "$2" "$3" "$4" > "$5"
}
snap 0 19 685 35 "$CAP/before.txt"
snap 1 20 690 35 "$CAP/snapshot_$((S0 + 3600)).txt"
snap 0 21 700 36 "$CAP/snapshot_$((S0 + 9000)).txt"
printf 'battery_hold=1\nbattery_hold_kept=2\nbattery_hold_released=3\nbattery_hold_testing=1\n' >> "$CAP/snapshot_$((S0 + 3600)).txt"
printf 'battery_hold=0\nbattery_hold_kept=2\nbattery_hold_released=4\nbattery_hold_testing=0\nthermal_spike_holds=3\nthermal_spike_last_c=61\nthermal_spike_last_peer_hi=2\nthermal_spike_last_peer_n=5\n' >> "$CAP/snapshot_$((S0 + 9000)).txt"
cat > "$CAP/governor.log.session" <<'EOF'
11-03 10:00:00 battery_hold: com.example.feed - kept (12 windows; janky 10.0% without, 3.0% with): helps scrolling
11-03 10:05:00 battery_hold: com.example.chat - released after 12 windows (janky 5.0% without, 5.0% with): does not help
EOF
cat > "$CAP/_full_day_report.txt" <<'EOF'
 capture: 0h target (until stopped), 180 min elapsed
refresh_hz  samples  share   avg_brightness%  avg_mA
?                 4     1%               12     538
90              125    30%               16     271
60              228    55%               14     279
brightness%  samples  avg_mA
0-24             384     299
average brightness while on: 14%
  governor cpu             : 4977 ms/h (15157 ms total)
  writer attempts          : 620/h
  physical write calls     : 480/h
  already-set confirms     : 140/h (no physical write)
  writer reads             : 900/h precheck + 480/h confirmation
  timer wakeups            : 1628/h
    by screen state        : screen on 1271/h, screen off 356/h - no alarm clock: none of them wakes a sleeping phone
link drops (ACL disconnects): 5 - lost link (timeout): 3, ended by the headset: 1, ended by this phone: 1, other/unknown: 0
media-profile drops in the Bluetooth service history (phone clock; last 20 changes per profile, kept across snapshots):
  10-29 19:29:01  device A  reported by the Bluetooth stack (the headset ended it or the radio link went); call profile dropped with it; not back within the kept history
  10-29 20:01:10  device A  asked for on the phone; back within 2 min
media drops: 2 (stack-reported 1, asked for on the phone 1); whole device (call profile too): 1; media only (call profile kept): 1
EOF
printf '# x\n1\tz\t I A2dpStateMachine: Connected: stopped playing: XX\ndup\t I A2dpStateMachine: Connected: stopped playing: XX\n2\tz\t I A2dpStateMachine: Connected: started playing: XX\n' > "$CAP/bt_lifecycle_stack_evidence.tsv"
out="$(ASB_LK_STATE_DIR="$T/state" ASB_TOMBSTONE_DIR="$T/none" sh "$D" "$CAP")"
line() { printf '%s\n' "$out" | grep "^$1	" || true; }
[ "$(line radio)" = "$(printf 'radio\tmib=1010.0\ton=1000.0')" ] || fail "radio with the screen-on share: $(line radio)"
_since="$(date -d "@$S0" '+%H:%M' 2>/dev/null || date -r "$S0" '+%H:%M')"
[ "$(line rnet)" = "$(printf 'rnet\ttot=614.0\tsince=%s' "$_since")" ] || fail "per-app total over the capture window, mobile only: $(line rnet) (since $_since)"
[ "$(line rapp)" = "$(printf 'rapp\tpkg=com.moonshot.kimichat\tmib=510.0\nrapp\tpkg=org.telegram.messenger\tmib=100.0')" ] || fail "apps by mobile data, named, under 8 MiB left out: $(line rapp)"
[ "$(line rat)" = "$(printf 'rat\tnsa=2\tsa=0\tlte=1\tof=3')" ] || fail "radio network per check: $(line rat)"
[ "$(line lte)" = "$(printf 'lte\ten=1\tlight=1\tapplies=2\tlte_min=15\twatch=1\tsnaps=3\tunsup=0\tquiet=1')" ] || fail "LTE switch activity between the snapshots: $(line lte)"
[ "$(line bhold)" = "$(printf 'bhold\tkept=2\treleased=4\ttesting=0')" ] || fail "fix271: Battery hold verdicts from the last snapshot: $(line bhold)"
[ "$(line tspike)" = "$(printf 'tspike\tholds=3\tlast_c=61\tpeer_hi=2\tpeer_n=5')" ] || fail "thermal spike evidence: $(line tspike)"
[ "$(line bhv)" = "$(printf 'bhv\tapp=com.example.feed\tstate=kept\twithout=10.0\twith=3.0\nbhv\tapp=com.example.chat\tstate=released\twithout=5.0\twith=5.0')" ] || fail "recent hold verdicts: $(line bhv)"
[ "$(line netma)" = "$(printf 'netma\tlo=250\tlo_n=30\thi=340\thi_n=29')" ] || fail "screen-on current by traffic: $(line netma)"
[ "$(line hz | wc -l)" = 2 ] && line hz | grep 'mode=60' >/dev/null || fail "the refresh table stopped at the '?' row: $(line hz)"
[ "$(line bright)" = "$(printf 'bright\tavg=14')" ] || fail "average brightness: $(line bright)"
[ "$(line asbcost)" = "$(printf 'asbcost\tcpu_msh=4977\twrites_h=480\twakes_h=1628\twakes_on=1271\twakes_off=356\tnoalarm=1')" ] || fail "ASB wakes by screen: $(line asbcost)"
[ "$(line bt)" = "$(printf 'bt\tacl=5\tlost=3\tby_dev=1\tby_phone=1\tmedia=2\twhole=1\tstreams=2')" ] || fail "Bluetooth drops and stream pauses: $(line bt)"
[ "$(line btdrop)" = "$(printf 'btdrop\tat=10-29 19:29\twho=stack\twhole=1\tback=0\nbtdrop\tat=10-29 20:01\twho=phone\twhole=0\tback=1')" ] || fail "media drops by time: $(line btdrop)"
rm -f "$CAP/snapshot_"*.txt
out="$(ASB_LK_STATE_DIR="$T/state" ASB_TOMBSTONE_DIR="$T/none" sh "$D" "$CAP")"
[ -z "$(line lte)" ] || fail "one snapshot is no activity window: $(line lte)"
echo "PASS digest network: screen-on data share, apps over the window from the UID section, NSA per check, LTE switch activity, current by traffic, refresh '?' row, ASB wakes by screen, Bluetooth drops vs stream pauses"
)

t_webui_liquid_glass_runtime() (
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL webui liquid glass: $*" >&2; exit 1; }
command -v node >/dev/null 2>&1 || { echo "SKIP webui liquid glass: no node"; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
{
  cat <<'EOF'
const store = { asb_theme:'glass' };
const localStorage = { getItem:k => store[k] || null, setItem:(k,v) => { store[k]=v; } };
const attrs = {};
const root = { setAttribute:(k,v) => { attrs[k]=v; }, removeAttribute:k => { delete attrs[k]; } };
const meta = { setAttribute:(k,v) => { meta.content=v; } };
const buttons = [];
for (let page=0; page<5; page++) for (const choice of ['dark','light','glass']) {
  const classes = new Set();
  buttons.push({ choice, classes, attrs:{}, getAttribute(k) { return k==='data-theme-choice' ? choice : this.attrs[k]; }, setAttribute(k,v) { this.attrs[k]=v; }, classList:{ toggle(c,on) { on ? classes.add(c) : classes.delete(c); } } });
}
const document = { documentElement:root, querySelector:s => s==='meta[name="theme-color"]' ? meta : null, querySelectorAll:s => s==='[data-theme-choice]' ? buttons : [] };
function T(k,d) { return d; }
let sounds=0; function uiSound() { sounds++; }
EOF
  for fn in asbThemeValue asbGlassBase asbPaintThemeControls asbSetTheme; do sed -n "/^function $fn(/,/^}/p" "$H"; done
  cat <<'EOF'
function chk(c,m) { if (!c) throw new Error(m); }
asbPaintThemeControls();
chk(!('data-asb-theme' in attrs)&&attrs['data-asb-glass']==='1','legacy Glass cold start defaults to the black palette');
chk(meta.content==='#000000','black Glass theme-color');
chk(buttons.filter(b=>b.classes.has('active')).length===5,'not all five switches select glass');
chk(buttons.filter(b=>b.choice==='glass').every(b=>b.attrs['aria-pressed']==='true'&&b.attrs['aria-label']==='Liquid Glass theme'),'glass aria state/label');
asbSetTheme('light'); chk(attrs['data-asb-theme']==='light'&&!('data-asb-glass' in attrs)&&store.asb_theme==='light'&&store.asb_glass_base==='light','Glass -> light remembers the light base');
asbSetTheme('glass'); chk(attrs['data-asb-theme']==='light'&&attrs['data-asb-glass']==='1'&&store.asb_theme==='glass'&&store.asb_glass_base==='light','Light -> Glass produces light glass');
chk(meta.content==='#f2f4f6','light Glass theme-color matches the solid canvas');
asbSetTheme('dark'); chk(!('data-asb-theme' in attrs)&&!('data-asb-glass' in attrs)&&store.asb_theme==='dark'&&store.asb_glass_base==='dark','light Glass -> dark remembers the dark base');
asbSetTheme('glass'); chk(!('data-asb-theme' in attrs)&&attrs['data-asb-glass']==='1'&&store.asb_theme==='glass'&&store.asb_glass_base==='dark','Dark -> Glass produces black glass');
store.asb_glass_base='light'; asbPaintThemeControls();
chk(attrs['data-asb-theme']==='light'&&attrs['data-asb-glass']==='1','a saved light-Glass choice cold-starts on the light palette');
asbSetTheme('invalid'); chk(!('data-asb-theme' in attrs)&&!('data-asb-glass' in attrs)&&store.asb_theme==='dark','unknown theme is not accepted');
chk(buttons.every(b=>(b.classes.has('active'))===(b.choice==='dark')),'switches diverged after cycling');
console.log('ok');
EOF
} > "$T/t.js"
out="$(node "$T/t.js" 2>&1)" || fail "$out"
[ "$out" = ok ] || fail "$out"
python3 - "$H" <<'PY' || fail 'markup or material'
import sys
h=open(sys.argv[1],encoding='utf-8').read()
assert h.count('data-theme-choice="glass"') == 6
assert h.count('data-theme-toggle=') == 6
assert 'backdrop-filter:blur(8px)' in h
assert 'html[data-asb-glass="1"]' in h
assert 'html[data-asb-glass="1"][data-asb-theme="light"]' in h
assert '--accent:#00f0b4' in h and '--accent:#007c63' in h
assert '--surface:rgba(8,13,10,.90)' in h and '--border:rgba(108,151,133,.46)' in h
assert 'html[data-asb-glass="1"] .log-menu,\nhtml[data-asb-glass="1"] .cfg-fm-box,\nhtml[data-asb-glass="1"] .asb-tabbar,' in h
assert 'html[data-asb-glass="1"] .log-menu,\nhtml[data-asb-glass="1"] .cfg-fm-box,\nhtml[data-asb-glass="1"] .cfg-profile-sheet,\nhtml[data-asb-glass="1"] .cfg-reset-dialog {' in h
assert 'html[data-asb-glass="1"] .cfg-fm-btn:not(asb-spec-pad),\nhtml[data-asb-glass="1"] .cfg-fm-place:not(asb-spec-pad),\nhtml[data-asb-glass="1"] .cfg-fm-cancel:not(asb-spec-pad),' in h
assert '#00aaff' not in h and '0,170,255' not in h and '101,215,255' not in h
assert "localStorage.getItem('asb_glass_base')" in h
assert '@media (prefers-reduced-motion:reduce)' in h
# Semantic readings survive both neutral Glass material layers, for direct Smart classes
# and Stock load's descendant spans alike.
for selector in (
    'html[data-asb-glass="1"] .smart-banner-value:is(.cap-raised,.load-low)',
    'html[data-asb-glass="1"] .smart-banner-value:is(.basis-warn,.heat-warm,.load-mid)',
    'html[data-asb-glass="1"] .smart-banner-value:is(.cap-clamp,.basis-veto,.load-high)',
    'html[data-asb-glass="1"] .smart-banner-value .load-mid',
):
    assert selector in h, selector
assert "asbMetricPaint('bnApp', appView.metric)" in h
assert "lvAppView(appH, parseInt(kv.smart_app_hint_inferred || '0', 10), warm)" in h
assert '.smart-banner-value.load-mid,' in h and 'color: var(--bal);' in h
for cls in ('good', 'warm', 'bad', 'neutral'):
    assert '.smart-banner-value.metric-' + cls in h
    assert '.live-cell-value.metric-' + cls in h
    assert 'html[data-asb-glass="1"] .smart-banner-value.metric-' + cls in h
    assert 'html[data-asb-glass="1"] .live-cell-value.metric-' + cls in h
assert all('html[data-asb-glass="1"] ' + v + ':is(.metric-normal,.metric-info)' in h for v in ('.live-cell-value', '.smart-banner-value', '.smart-drain-val', '.live-info-val'))
assert 'html[data-asb-glass="1"] :is(.live-cell-value,.smart-banner-value,.live-info-val).metric-fsm-moderate' in h
# Category colour is a translucent material layer, not a flat replacement or a neutral wash.
assert 'html[data-asb-glass="1"] .cfg-tile[class*="cat-"] {' in h
assert 'html[data-asb-glass="1"][data-asb-theme="light"] .cfg-tile[class*="cat-"] {' in h
assert 'color-mix(in srgb,var(--cat) 28%,transparent)' in h
assert 'color-mix(in srgb,var(--cat) 17%,transparent)' in h
assert 'html[data-asb-glass="1"] .cfg-tile[class*="cat-"] .cfg-tile-ico {' in h
PY
echo "PASS webui liquid glass: cold start, five synchronized switches, dark/light compatibility and localized aria"
)

t_webui_stock_trend_retry_runtime() (
# A transient root/sysfs read failure must not erase the last good thermal trend.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL webui stock trend retry: $*" >&2; exit 1; }
command -v node >/dev/null 2>&1 || { echo "SKIP webui stock trend retry: no node"; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
{
  cat <<'EOF'
const nodes = {};
function _el(id) { if (!nodes[id]) nodes[id] = { classList:{remove(){}}, style:{display:''}, textContent:'' }; return nodes[id]; }
function T(k,d) { return d; }
let _selectedProfile = 'stock', _stockRomHistory = {};
let _stockTelemetryLastMs = 0, _stockSettingsAtMs = 0;
let _stockTelemetryKv = { tsms:'1000', 'thermal.cpu-1-1-0':'41000' };
const STOCK_TELEMETRY_MIN_INTERVAL_MS = 10000, MD = '/mod';
let painted = [];
function paintStockLive(kv) { painted.push(kv); _el('liveStockRomBanner').style.display = Object.keys(kv).length ? '' : 'none'; }
function lvTopSecSync() {} async function lvMeterPoll() {}
const _lvMonCache = { rom: null }; let saves = 0; function lvMonCacheSave() { saves++; } function lvStale() {}
let calls = 0;
async function run() { calls++; if (calls === 1) throw new Error('temporary root failure'); return { stdout:'thermal.cpu-1-1-0=42000\n' }; }
let clock = 10000; Date.now = () => clock;
EOF
  for fn in parseStockTelemetry pollStockTelemetry stockTelemetryCmd stockTelemetryApply lvMonCacheRom; do sed -n "/^\\(async \\)\\{0,1\\}function $fn(/,/^}/p" "$H"; done
  cat <<'EOF'
(async function () {
  await pollStockTelemetry(true, true);
  if (calls !== 1 || !_stockTelemetryKv.tsms || painted.length !== 1 || painted[0].tsms !== '1000') throw new Error('cached snapshot lost after a transient failure');
  if (_el('liveStockRomBanner').style.display === 'none') throw new Error('thermal card hidden despite a cached trend');
  clock = 30000;
  await pollStockTelemetry(true, true);
  if (calls !== 2 || _stockTelemetryKv['thermal.cpu-1-1-0'] !== '42000' || !painted[1].tsms) throw new Error('retry did not replace the cache with fresh telemetry');
  if (saves !== 1 || !_lvMonCache.rom || _lvMonCache.rom.tsms || _lvMonCache.rom['thermal.cpu-1-1-0'] !== '42000') throw new Error('fix287: the fresh sample was not kept for the next visit without its clock');
  console.log('ok');
})().catch(e => { console.error(e.message); process.exit(1); });
EOF
} > "$T/t.js"
out="$(node "$T/t.js" 2>&1)" || fail "$out"
[ "$out" = ok ] || fail "$out"
echo "PASS webui stock trend retry: a transient read keeps the last good trend and the next poll refreshes it"
)

t_webui_visual_hierarchy_contract() (
# Contract (fix230): DSP outputs precede loudness and the global icons have clean silhouettes.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL webui visual hierarchy: $*" >&2; exit 1; }
python3 - "$H" <<'PY' || fail 'DSP order or icons'
import re, sys
h = open(sys.argv[1], encoding='utf-8').read()
assert "keys:['dsp_outputs','dsp_loudness','dsp_bass','dsp_voice','dsp_width','dsp_clarity','dsp_rumble','dsp_compressor','dsp_headroom','dsp_true_peak','dsp_lookahead','dsp_dc_protect']" in h, 'DSP Outputs is not first'
for name in ('smart','performance','theme_glass'):
    if name == 'smart':
        m = re.search(r'^  smart: ([\s\S]*?),\n  /\* Performance:', h, re.M)
    else:
        m = re.search(r'^  %s: \'([^\']*)\'' % name, h, re.M)
    assert m, '%s missing from TECH_ICON_PATHS' % name
    if name in ('performance','theme_glass'):
        assert m.group(1).count('<path') == 1 and '<circle' not in m.group(1) and '<rect' not in m.group(1), '%s has an unwanted inner glyph' % name
    else:
        assert m.group(1).count('<path') == 6 and m.group(1).count('<rect') == 1 and m.group(1).count('<circle') == 4 and '<g stroke-width="1.35">' in m.group(1), 'Smart lost its top-down processor-brain geometry'
