  document.hidden = false; rafs = [];
  const p = realPaintYield(); chk(rafs.length === 1, 'the paint yield did not wait for a frame'); rafs[0](); await p;
  process.exit(bad ? 1 : 0);
})().catch(e => { console.log('FAIL ' + e.stack); process.exit(1); });
