chk(d2dump.includes('7.18 · 7.95 · 4.97 (1 / 5 / 15 min) · 3 of 11967 threads running') && !d2dump.includes('3/11967 8744'), 'raw /proc/loadavg line shown');
chk(d2dump.includes('Load average counts tasks'), 'load average explanation missing');
chk(d2dump.includes('15.0 GB') && d2dump.includes('4.7 GB free of 15.0 GB · zRAM 6.0 GB used'), 'memory not humanised');
chk(d2dump.includes('28.0 °C') && d2dump.includes('-412 mA') && d2dump.includes('4.12 V') && d2dump.includes('7300 mAh'), 'battery units not humanised');
chk(d2dump.includes('Silicon-carbon (Si/C)') && d2dump.includes('77% of design capacity') && d2dump.includes('214 cycles'), 'battery chemistry note, wear or cycles missing');
chk(d2dump.includes('CPU 0–5 · walt · now 1.13 GHz · limit 384 MHz–3.63 GHz · hardware 384 MHz–3.63 GHz'), 'cpu policy not formatted');
chk(d2dump.includes('msm-adreno-tz · now 160 MHz · range 160 MHz–1.20 GHz · busy 25%'), 'gpu not formatted');
chk(deviceDisplayValue('gpu', 'kgsl-3d0', 'governor=pwrlevel; current_hz=160000000; min_hz=160000000; max_hz=1200000000; busy=17; levels=18; model=Adreno840', d2).replace(/\u00a0/g, ' ') ===
    'Adreno 840 · power levels · now 160 MHz · range 160 MHz–1.20 GHz · busy 17%', 'a power-level GPU with its model: ' + deviceDisplayValue('gpu', 'kgsl-3d0', 'governor=pwrlevel; current_hz=160000000; min_hz=160000000; max_hz=1200000000; busy=17; levels=18; model=Adreno840', d2));
chk(d2dump.includes('1.02 GHz–4.61 GHz · 22 steps · floor control: yes') && d2dump.includes('power levels · 11 steps') && d2dump.includes('92 zones'), 'ASB capability rows not formatted');
chk(d2dump.includes('KernelSU') && d2dump.includes('camera: yes · audio: no') && d2dump.includes('camera · audio · wifi'), 'ASB capability names not formatted');
chk(deviceRootManagerDisplay('ksu', d2).includes('KernelSU-compatible family') && deviceRootManagerDisplay('ksu', d2).includes('a fork is possible'), 'old KSU-only snapshots keep the variant uncertain');
chk(deviceRootManagerDisplay('ksu', d2) !== 'KernelSU' && deviceRootManagerDisplay('magisk', d2) === 'Magisk' && deviceRootManagerDisplay('apatch', d2) === 'APatch', 'generic KSU is not original KernelSU; other root managers are unchanged');
const nextRoot = parseDeviceInfo(['D\tmeta\tschema\t3', 'D\tasb_caps\troot_manager\tksu', 'D\troot\tmanager\tksu',
  'D\troot\tvariant\tKernelSU Next', 'D\troot\tversion\t1.0.8', 'D\troot\tvariant_evidence\tksud --version',
  'D\troot\tversion_evidence\tKernelSU Next v1.0.8'].join('\n'));
chk(deviceRootManagerDisplay('ksu', nextRoot) === 'KernelSU Next 1.0.8', 'positive KernelSU Next evidence is exact');
const originalRoot = parseDeviceInfo('D\troot\tvariant\tKernelSU\nD\troot\tversion\t0.9.5');
chk(deviceRootManagerDisplay('ksu', originalRoot) === 'KernelSU 0.9.5', 'original KernelSU requires positive variant evidence');
const sukiRoot = parseDeviceInfo('D\troot\tvariant\tSukiSU Ultra\nD\troot\tversion\t1.2.3');
chk(deviceRootManagerDisplay('ksu', sukiRoot) === 'SukiSU Ultra 1.2.3', 'another named KSU fork is preserved');
const versionOnlyRoot = parseDeviceInfo('D\troot\tvariant\tnot exposed\nD\troot\tversion\t0.9.5');
chk(deviceRootManagerDisplay('ksu', versionOnlyRoot).includes('0.9.5') && deviceRootManagerDisplay('ksu', versionOnlyRoot).includes('a fork is possible'), 'ksud version alone still cannot identify the variant');
chk(deviceInfoInsights(d2).some(x => x.text.includes('KernelSU Next and other forks remain possible')) && deviceInfoInsights(nextRoot)[0].text.includes('KernelSU Next'), 'device insights explain uncertainty versus positive evidence');
deviceInfoRender(nextRoot);
chk(countDeviceClass(body, 'lgr-ref-btn') >= 1, 'root insight has a real evidence button');
const oldDeviceEl = _el; let rootScrolled = '';
const rootTarget = { scrollIntoView() { rootScrolled = 'dev-sec-root'; } };
_el = function(id) { return id === 'dev-sec-root' ? rootTarget : oldDeviceEl(id); };
const rootRefs = []; (function walk(n) { if (String(n.className || '').split(/\s+/).includes('lgr-ref-btn')) rootRefs.push(n); (n.children || []).forEach(walk); })(body);
chk(rootRefs.length >= 1 && rootRefs[0].onclick() === true && rootScrolled === 'dev-sec-root', 'root evidence button scrolls to the actual root card');
_el = oldDeviceEl;
deviceInfoRender(d2);
const wearRow = []; (function walk(n) { if (n.className && n.className.split(/\s+/).includes('lgr-v') && n.textContent === '77%') wearRow.push(n); (n.children || []).forEach(walk); })(body);
chk(wearRow.length === 1 && wearRow[0].className.includes('dev-warn'), 'worn battery is not amber');
const d3 = parseDeviceInfo([
  'D\tmeta\tschema\t2', 'D\tfirmware\tbrand\tOnePlus', 'D\tfirmware\tmodel\tCPH2745', 'D\tfirmware\tandroid\t16',
  'D\tfirmware\tfingerprint\tOnePlus/x:16/y', 'D\tfirmware\tmarket_name\tOnePlus 15', 'D\tfirmware\tfuture_key\tZ1',
  'D\tfirmware\toplus_rom\tV16.0.0', 'D\tsoc\tsoc_model\tSM8850', 'D\tkernel\trelease\t6.12', 'D\tsusfs\tinterface\tavailable',
  'D\tkernel_features\tunicode_bypass_evidence\tno indicator', 'D\tkernel_features\tlto\tThinLTO (Clang)',
  'D\tkernel_features\tunicode_bypass_fix\tnot runtime-discoverable', 'D\tkernel_features\tntsync\tbuilt-in',
  'D\tasb\tprofile\tbattery', 'D\tsystem\tuptime\t508.51 2724.42', 'D\tbattery\tcapacity\t74', 'D\tkernel_runtime\tswappiness\t100'
].join('\n'));
deviceInfoRender(d3);
const d3dump = (function walk(n) { return [n.textContent || ''].concat((n.children || []).flatMap(walk)); })(body).join('\n');
const deviceDocks = []; (function walk(n) { if (String(n.className || '').split(/\s+/).includes('dev-page-nav')) deviceDocks.push(n); (n.children || []).forEach(walk); })(body);
const deviceGlyphs = []; (function walk(n) { if (String(n.className || '').split(/\s+/).includes('asb-tab-ico')) deviceGlyphs.push(n.innerHTML); (n.children || []).forEach(walk); })(deviceDocks[0] || mk('div'));
chk(JSON.stringify(deviceGlyphs) === JSON.stringify(['svg:hardware','svg:panel','svg:kernel','svg:zygisk_guard','svg:switches']), 'Device dock glyph assignment: ' + JSON.stringify(deviceGlyphs));
chk(new Set(deviceGlyphs).size === 5, 'Device dock reuses an icon for different destinations');
chk(d3dump.includes('ASB runtime') && d3dump.includes('battery') && d3dump.includes('collection limits, not proof'), 'fix255: ASB snapshot and unknown-evidence caveat render');
chk(countDeviceClass(body, 'dev-unknown') === 1 && countDeviceClass(body, 'dev-group-guide') === 5, 'fix255: unknown values stay neutral and all five group guides render');
chk(deviceValueClass('kernel_external', 'status', 'not_observable').includes('dev-unknown') && deviceInfoEvidence(parseDeviceInfo('D\tkernel_external\tstatus\tnot_observable')).limited === 1, 'fix255: not observable never becomes proof of stock voltage or a healthy value');
const seq = body.children.filter(n => /(?:^| )dev-group(?: |$)|lgr-sec/.test(n.className)).map(n => /(?:^| )dev-group(?: |$)/.test(n.className) ? '# ' + n.textContent : n.children[0].textContent);
chk(JSON.stringify(seq) === JSON.stringify(['At a glance', '# Hardware', 'Device', 'Chip (SoC)', 'Battery', '# Firmware and system', 'Firmware and ROM', 'System',
  '# Kernel', 'Kernel build', 'Custom kernel features', 'Live kernel facilities', '# Root and modules', 'SuSFS interface', '# ASB module', 'ASB runtime',
  'Collection metadata']), 'device page groups and order: ' + JSON.stringify(seq));
function cardRows(title) { const c = body.children.find(n => n.children && n.children[0] && n.children[0].textContent === title); const out = [];
  (function walk(n) { if (n.className && n.className.split(/\s+/).includes('lgr-v')) out.push(n.textContent); (n.children || []).forEach(walk); })(c); return out; }
chk(JSON.stringify(cardRows('Device')) === JSON.stringify(['OnePlus 15', 'OnePlus', 'CPH2745']), 'identity card: ' + JSON.stringify(cardRows('Device')));
chk(JSON.stringify(cardRows('Firmware and ROM')) === JSON.stringify(['16', 'V16.0.0', 'OnePlus/x:16/y', 'Z1']), 'firmware card keeps every other firmware key, the unknown one last: ' + JSON.stringify(cardRows('Firmware and ROM')));
chk(JSON.stringify(cardRows('Custom kernel features')) === JSON.stringify(['ThinLTO (Clang)', 'not runtime-discoverable', 'no indicator', 'built-in']), 'the Unicode evidence sits under its feature: ' + JSON.stringify(cardRows('Custom kernel features')));
const groupHead = body.children.find(n => /dev-group/.test(n.className));
chk(groupHead && groupHead.tagName === 'div', 'group heading element');
const d4 = parseDeviceInfo([
  'D\tkernel_origin\tassessment\tstock-like', 'D\tkernel_origin\tconfidence\tindicative; not a provenance proof',
  'D\tkernel_btf\tsummary\tbuilt-in config; vmlinux exposed', 'D\tkernel_btf\tvmlinux\tvmlinux readable and non-empty',
  'D\tkernel_ebpf\tsummary\tconfigured; runtime interfaces exposed', 'D\tkernel_ebpf\tpinned_objects\t0 top-level entries exposed',
  'D\tkernel_fuse_bpf\tsummary\tunknown; not runtime-discoverable', 'D\tkernel_fuse_bpf\tevidence_note\tordinary FUSE or eBPF alone does not prove FUSE-BPF'
].join('\n'));
deviceInfoRender(d4);
const d4dump = (function walk(n) { return [n.textContent || ''].concat((n.children || []).flatMap(walk)); })(body).join('\n');
chk(d4dump.includes('BTF evidence') && d4dump.includes('vmlinux readable and non-empty') && d4dump.includes('FUSE-BPF needs its own positive evidence'), 'BTF/eBPF/FUSE-BPF cards and evidence guide missing');
chk(d4dump.includes('Kernel origin is stock-like') && d4dump.includes('not guaranteed provenance'), 'kernel origin became a guaranteed stock/custom verdict');
deviceInfoRender(d2);
(async function () {
  window._asbDeviceInfoData = d2;
  window._asbDeviceInfoRaw = 'D\tgpu\tkgsl-3d0\tRAWMARK';
  let exportCalls = 0, commands = [];
  const notices = [];
  globalThis.run = async function (cmd) {
    exportCalls++; commands.push(cmd);
    const fin = /asb_page_export\.sh' finish 'device' '(\d{8}_\d{6})'/.exec(cmd);
    return { errno: 0, stdout: fin ? 'status=saved\npath=/sdcard/ASB/logs/asb_device_' + fin[1] + '.txt\n' : '', stderr: '' };
  };
  globalThis.toast = function (text, kind) { notices.push({ text, kind }); };
  globalThis.MD = '/md';
  globalThis.runOk = r => !!r && r.errno === 0;
  globalThis.runText = r => r && r.stdout || '';
  const safeButtons = [];
  for (const mode of ['off', 'on']) {
    const ed = deviceZygiskEditor(parseDeviceInfo('D\tzygisk_observer\tsafe_mode\t' + mode + '\nD\tzygisk_observer\tenabled_package_list\tcom.example.app\n'), function () {});
    const actions = ed.children.find(x => String(x.className).includes('dev-zygisk-actions'));
    const safe = actions.children[1]; safeButtons.push(safe.textContent);
    await safe.onclick();
  }
  chk(safeButtons[0] === 'Enable safe mode' && safeButtons[1] === 'Clear safe mode', 'Safe mode labels describe the action, not the current state: ' + safeButtons.join(','));
  chk(commands.some(c => c.endsWith('/runtime/asb_zygisk.sh safe-mode on')) && commands.some(c => c.endsWith('/runtime/asb_zygisk.sh safe-mode off')), 'Safe mode action labels send the opposite state command');
  await asbSavePage('device');
  const writes = commands.filter(c => c.includes("asb_page_export.sh' append 'device' "));
  const b64 = writes.map(c => c.match(/ append 'device' '\d{8}_\d{6}' '([^']*)'/)[1]).join('');
  const saved = Buffer.from(b64, 'base64').toString('utf8');
  chk(/^AutoSystemBoost - Device diagnostics\n27 facts\n/.test(saved), 'Device save header: ' + saved.slice(0, 80));
  chk(saved.includes('== At a glance ==') && saved.includes('8 cores · 2 clusters · up to 4.61 GHz'), 'Device save lost the overview');
  chk(/\n# Hardware\n[\s\S]{0,500}== Chip \(SoC\) ==/.test(saved) && saved.includes('Physical components and their live readings') && saved.indexOf('# Hardware') < saved.indexOf('# ASB module'), 'Device save lost the group headings or their guides');
  chk(/\n  [^\n]*: 77%  \(!\)/.test(saved), 'Device save lost a warning mark on the worn battery');
  chk(saved.includes('Load average counts tasks'), 'Device save lost the explanatory notes');
  chk(saved.includes('== Raw data (for the developer) ==\nD\tgpu\tkgsl-3d0\tRAWMARK'), 'Device save lost the raw collector output');
  chk(commands.some(c => /asb_page_export\.sh' begin 'device' '\d{8}_\d{6}'/.test(c)) && commands.some(c => /asb_page_export\.sh' finish 'device' '\d{8}_\d{6}'/.test(c)), 'Device save did not use the fixed helper protocol');
  chk(!commands.some(c => c.includes('/sdcard/Download') || c.includes('asb_device_info.sh')), 'Device save ran a new collector or used a legacy path');
  chk(!jsonButton.disabled && notices.some(n => n.kind === 'ok' && n.text.includes('/sdcard/ASB/logs/asb_device_')), 'Device save did not confirm the acknowledged path or left the button disabled');
  window._asbDeviceInfoData = null;
  const before = exportCalls;
  await asbSavePage('device');
  chk(exportCalls === before && notices.some(n => n.kind === 'error'), 'a page without data was saved');
  if (bad) process.exit(1); console.log('ok');
})().catch(e => { console.error(e); process.exit(1); });
EOF
} > "$T/t.js"
out="$(node "$T/t.js" 2>&1)" || fail "$out"
[ "$out" = ok ] || fail "$out"
echo "PASS webui device page: five SoC buttons/theme groups, safe TSV parser/renderer, five section groups in reading order with the identity card first, metamodule metadata, independent NoMount evidence and read-only loader"
)

t_webui_boot_fly_runtime() (
# dev18: the boot preview hands off by flying the spinning sphere itself into the header, where
# the same sphere is the logo on every page. dev17 replaced the orbits' CSS rotation with WAAPI
# transforms, set the pod to animation:none, transitioned a full-screen background colour and
# cancelled the flight before the overlay was hidden - the saucer snapped back and showed twice.
# Static contract first, then the REAL flight functions over a DOM mock.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL webui boot fly: $*" >&2; exit 1; }
python3 - "$H" <<'PY' || fail 'static wiring'
import re, sys
h = open(sys.argv[1], encoding='utf-8').read()
# One sphere design: every header copy carries the boot sphere's layers, the old glow/ring are gone.
assert h.count('<div class="logo-sphere-a"></div><div class="logo-sphere-b"></div>') == 6, 'a header copy lacks the sphere'
assert h.count('<div class="logo-frame-a"></div><div class="logo-frame-b"></div>') == 6, 'a header copy lacks the frames'
assert 'logo-glow' not in h and 'logo-ring' not in h, 'the retired header layers are still present'
# Same geometry at a different scale: both are 172px x --k, so the landing is pixel-aligned.
assert re.search(r'\.logo-c \{[^}]*width: calc\(172px \* var\(--k\)\)', h), 'header sphere is not on the shared scale'
assert '.asb-boot-core { --k:1; position:relative; width:calc(172px * var(--k));' in h, 'boot core is not on the shared scale'
# The backdrop is its own layer, faded by opacity; the overlay itself paints nothing.
assert '<div class="asb-boot-bg" aria-hidden="true"></div>' in h
intro = re.search(r'\n\.asb-boot-intro \{([^}]*)\}', h).group(1)
assert 'background:transparent' in intro, 'overlay still paints the full-screen background'
assert '.asb-boot-bg { position:absolute; inset:0; z-index:-3; background:#000; pointer-events:none; }' in h
warp = h[h.index('.asb-boot-warp .asb-boot-grid'):]
warp = warp[:warp.index('}') + 1]
assert 'opacity:0 !important' in warp and 'transform' not in warp and 'animation' not in warp and 'background' not in warp, 'warp state does more than fade text'
assert 'body.asb-boot-flying .page:not(.live-page) .logo-c { opacity:0; }' in h
# The leaving path tries the flight and keeps the old fade as the fallback.
_s = h.index("if (status) status.textContent = T('boot_intro_ready'")
lv = h[_s:_s + 700]
assert 'flew = await asbBootFlyToHeader(overlay)' in lv and "overlay.classList.add('is-leaving')" in lv and 'if (!flew)' in lv
# Held end states are released only after the overlay is hidden.
_f = h.index('} finally {', _s)
fin = h[_f:_f + 600]
assert fin.index('overlay.hidden = true;') < fin.index('asbBootFlightRelease(overlay)'), 'held animations released before the overlay is hidden'
assert "overlay.classList.remove('asb-boot-warp')" in fin and "document.body.classList.remove('asb-boot-flying')" in fin
fn = h[h.index('async function asbBootFlyToHeader(overlay) {'):h.index('function asbBootFlightRelease(overlay) {')]
assert 'prefers-reduced-motion: reduce' in fn and 'if (reduced || !overlay' in fn, 'no reduced-motion guard'
assert fn.count('.cancel()') == 1 and 'fadeIn.cancel()' in fn, 'the flight cancels something before the overlay is hidden'
assert "'.asb-boot-orbit" not in fn and 'animation:none' not in fn and "animation = 'none'" not in fn, 'the flight touches the orbit rotation'
for bad in ('.style.top', '.style.left', "top:'", "left:'", 'width:', 'height:', 'background'):
    assert bad not in fn, 'non-compositor property in the flight: ' + bad
PY
command -v node >/dev/null 2>&1 || { echo "SKIP webui boot fly runtime: no node"; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
{
  cat <<'EOF'
let REDUCED = false;
global.window = { innerHeight: 900, matchMedia: function () { return { matches: REDUCED }; } };
global.requestAnimationFrame = function (fn) { return setTimeout(fn, 0); };
const calls = [];
function anim(t) { return { currentTime: t, cancelled: false, cancel: function () { this.cancelled = true; } }; }
function el(id, kids) {
  const e = { id: id, _cls: new Set(), style: {}, _rect: { left: 0, top: 0, width: 0, height: 0 }, _anims: [] };
  e.classList = { add: function (c) { e._cls.add(c); }, remove: function (c) { e._cls.delete(c); }, contains: function (c) { return e._cls.has(c); } };
  e.animate = function (kf, opts) {
    const a = { id: id, kf: kf, opts: opts, cancelled: false, finished: Promise.resolve() };
    a.cancel = function () { a.cancelled = true; };
    calls.push(a); return a;
  };
  e.getAnimations = function () { return e._anims; };
  e.getBoundingClientRect = function () { return e._rect; };
  e.querySelector = function (sel) { return (kids || {})[sel] || null; };
  return e;
}
const orbA = el('orbA'), orbB = el('orbB'), pod = el('pod'), saucer = el('saucer');
orbA._anims = [anim(4321)]; orbB._anims = [anim(987)]; pod._anims = [anim(1500)];
const core = el('core', { '.asb-boot-orbit.a': orbA, '.asb-boot-orbit.b': orbB, '.asb-boot-ufo': pod, '.asb-boot-ufo svg': saucer });
core._rect = { left: 120, top: 380, width: 172, height: 172 };
const sphA = el('sphA'), sphB = el('sphB'), inner = el('inner');
sphA._anims = [anim(0)]; sphB._anims = [anim(0)]; inner._anims = [anim(0)];
const target = el('target', { '.logo-sphere-a': sphA, '.logo-sphere-b': sphB, '.logo-inner': inner });
target._rect = { left: 160, top: 40, width: 92, height: 92 };
const bg = el('bg');
const overlay = el('overlay', { '.asb-boot-core': core, '.asb-boot-bg': bg });
const home = el('home', { '.logo-c': target });
const bodyEl = el('body');
global.document = { body: bodyEl, querySelector: function (sel) { return sel === '.page:not(.live-page)' ? home : null; } };
let revealed = 0;
function asbHomeReveal() { revealed++; }
EOF
  sed -n '/^function _asbAnimFinished(anim, ms) {/,/^async function asbBootIntroStart()/p' "$H" | sed '/^async function asbBootIntroStart()/d'
  cat <<'EOF'
let bad = 0; function chk(c, m) { if (!c) { console.log('FAIL ' + m); bad++; } }
const num = function (s) { return (s.match(/-?[0-9.]+/g) || []).map(Number); };
(async function () {
  REDUCED = true;
  chk(await asbBootFlyToHeader(overlay) === false, 'reduced motion should decline the flight');
  chk(!overlay._cls.has('asb-boot-warp') && !bodyEl._cls.has('asb-boot-flying') && calls.length === 0, 'reduced motion still touched something');
  REDUCED = false;
  target._rect = { left: 160, top: 1200, width: 92, height: 92 };
  chk(await asbBootFlyToHeader(overlay) === false && calls.length === 0 && !overlay._cls.has('asb-boot-warp'), 'flew to a header out of view');
  target._rect = { left: 160, top: 40, width: 92, height: 92 };
  const r1 = await asbBootFlyToHeader(overlay);
  chk(r1 === true && revealed >= 1, 'the flight did not run with motion allowed');
  chk(overlay._cls.has('asb-boot-warp') && !bodyEl._cls.has('asb-boot-flying'), 'warp/flying classes wrong after landing');
  const by = function (id) { return calls.filter(function (c) { return c.id === id; }); };
  chk(by('orbA').length === 0 && by('orbB').length === 0 && by('pod').length === 0, 'the orbit rotation or pod pulse was overridden');
  const coreA = by('core');
  chk(coreA.length === 2, 'core should animate exactly twice (flight, fade): ' + coreA.length);
  const kf = coreA[0].kf;
  chk(kf.length >= 20 && coreA[0].opts.fill === 'forwards', 'the flight is not a held, sampled path');
  chk(kf.every(function (f) { return Object.keys(f).every(function (k) { return k === 'transform' || k === 'offset'; }); }), 'the flight animates more than transform');
  const first = num(kf[0].transform), last = num(kf[kf.length - 1].transform);
  chk(first[0] === 0 && first[1] === 0 && first[2] === 1, 'the flight does not start in place: ' + kf[0].transform);
  const dx = (160 + 46) - (120 + 86), dy = (40 + 46) - (380 + 86), sc = 92 / 172;
  chk(Math.abs(last[0] - dx) < .01 && Math.abs(last[1] - dy) < .01 && Math.abs(last[2] - sc) < .0001, 'the flight does not land on the header sphere: ' + kf[kf.length - 1].transform);
  chk(kf.some(function (f) { return Math.abs(num(f.transform)[0]) > Math.abs(dx) + 5; }), 'the path is a straight line');
  chk(by('bg').length === 1 && by('bg')[0].kf[by('bg')[0].kf.length - 1].opacity === 0, 'the backdrop is not faded by its own layer');
  chk(by('saucer').length === 1, 'the saucer does not sway in flight');
  chk(by('target').length === 1, 'the header sphere should appear exactly once');
  chk(sphA._anims[0].currentTime === 4321 && sphB._anims[0].currentTime === 987 && inner._anims[0].currentTime === 1500, 'rotation phase not handed to the header');
  const held = overlay._asbFlight || [];
  chk(held.length === 4 && held.every(function (a) { return !a.cancelled; }), 'a held end state was released before the overlay was hidden');
  chk(by('target')[0].cancelled === true, 'the header fade-in should end on the plain CSS state');
  chk(core.style.willChange === 'transform, opacity', 'core not promoted for the flight');
  asbBootFlightRelease(overlay);
  chk(held.every(function (a) { return a.cancelled; }) && overlay._asbFlight === null && core.style.willChange === '', 'release did not clear the held animations');
  asbBootFlightRelease({ hidden: true });
  if (bad) process.exit(1);
  console.log('ok');
})().catch(function (e) { console.error(e); process.exit(1); });
EOF
} > "$T/t.js"
out="$(node "$T/t.js" 2>&1)" || fail "$out"
[ "$out" = ok ] || fail "$out"
echo "PASS webui boot fly: the boot sphere itself flies a curved transform-only path onto the header sphere (same 172px x --k geometry), orbits keep their CSS spin with phase handed over, backdrop fades on its own layer, one landing, held states released only after the overlay hides, reduced motion and off-screen header decline"
)

t_webui_infirmary_runtime() (
# dev17: the Infirmary is a screen of its own, opened by the pharmacy button beside Reset. It
# holds the Battery Fix card plus the two repairs moved out of System Services.
# dev18: users could not tell whether the recompile ran or whether the fix worked at all. The
# card is now a three-step checklist (condition, ART recompile with live progress, statistics
# reset with its verified outcome) under one status chip, and the button follows the state
# (run / stop / reboot to finish). The pharmacy button is a designed control in every theme.
# Static wiring first, then the REAL card code over a mini DOM and a scripted shell.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL webui infirmary: $*" >&2; exit 1; }
python3 - "$H" <<'PY' || fail 'static wiring'
import re, sys
h = open(sys.argv[1], encoding='utf-8').read()
row = h[h.index('id="cfgActionsRow"'):h.index('<div class="cfg-list"')]
assert 'cfgResetDialogOpen()' in row and 'id="cfgInfirmaryBtn"' in row and 'cfgOpenInfirmary()' in row, 'pharmacy button missing from the actions row'
assert row.index('cfgResetDialogOpen()') < row.index('cfgOpenInfirmary()'), 'pharmacy button is not to the right of Reset'
btn = row[row.index('id="cfgInfirmaryBtn"'):]
btn = btn[:btn.index('</button>')]
assert 'class="cfg-inf-emblem" aria-hidden="true"' in btn and 'fill="url(#asbInfBtnGrad)"' in btn, 'pharmacy emblem missing'
assert 'class="cfg-inf-label" data-i18n="inf_title"' in btn, 'button label not localized'
assert 'aria-label=' not in btn, 'a fixed aria-label would hide the localized label from screen readers'
assert 'grid-template-columns: repeat(3, minmax(0, 1fr)) minmax(0, 1.32fr)' in h, 'the Infirmary button has no wider column'
# The themes restyle every .cfg-backup with !important; the button keeps its own paint by id.
base = re.search(r'\n#cfgActionsRow \.cfg-infirmary-btn \{([^}]*)\}', h).group(1)
for prop in ('color:', 'background:', 'border:', 'box-shadow:'):
    decl = [d for d in base.split(';') if d.strip().startswith(prop)]
    assert decl and '!important' in decl[0], 'theme overrides would flatten the button: ' + prop
light = re.search(r'html\[data-asb-theme="light"\] #cfgActionsRow \.cfg-infirmary-btn \{([^}]*)\}', h).group(1)
assert light.count('!important') >= 4, 'light theme paint not enforced'
assert 'const CFG_EXTRA_GROUPS = {' in h and "infirmary: { id:'infirmary'" in h, 'CFG_EXTRA_GROUPS.infirmary missing'
assert 'function cfgGroupMeta(' in h and 'cfgGroupMeta(_cfgGroup)' in h and 'cfgGroupMeta(cfgGroupOf(it.key))' in h
groups = h[h.index('const CFG_GROUPS = ['):h.index('const CFG_EXTRA_GROUPS')]
assert "id:'infirmary'" not in groups, 'infirmary must not be a hub tile'
gof = h[h.index('const CFG_GROUP_OF = {'):h.index('function cfgGroupOf')]
assert "heytap_mcs:'infirmary'" in gof and "documentsui_fix:'infirmary'" in gof
svc = h[h.index("keys:['UX_MANAGE_OEM_TOGGLES'"):].split(']', 1)[0]
assert 'heytap_mcs' not in svc and 'documentsui_fix' not in svc
inf = h[h.index('  infirmary: ['):h.index('\n};', h.index('  infirmary: ['))]
assert "card:'batteryfix'" in inf and "keys:['heytap_mcs','documentsui_fix']" in inf
for fn in ('function cfgRenderBatteryFixCard(', 'function bfxPaintFrom(', 'async function batteryFixPaint(',
           'async function batteryFixRun(', 'async function batteryFixCancel(', 'function cfgRenderInfirmaryHero(',
           'function asbPharmacyCross(', 'function cfgOpenInfirmary('):
    assert fn in h, 'missing ' + fn
assert "cfgShowGroup('infirmary')" in h
assert '!sectionItems.length && !section.card' in h
import json
from pathlib import Path
keys = {
 'inf_advice_title':(), 'inf_advice_desc':(), 'inf_advice_note':(), 'inf_advice_apply':(),
 'inf_advice_applying':(), 'inf_advice_confirm':(), 'inf_advice_refresh':(),
 'inf_advice_count':('{n}',), 'inf_advice_loading':(), 'inf_advice_loading_chip':(),
 'inf_advice_none':(), 'inf_advice_no_data':(), 'inf_advice_no_changes':(),
 'inf_advice_no_changes_chip':(), 'inf_advice_read_failed':(),
 'inf_advice_finished':('{applied}','{failed}','{skipped}'),
 'inf_advice_result_applied':(), 'inf_advice_result_failed':(),
 'inf_advice_result_changed':(), 'inf_advice_result_pending':(),
 'bfx_art_partial':('{ok}','{fail}','{left}'), 'bfx_art_binder':('{err}',)
}
for p in sorted((Path(sys.argv[1]).parent/'i18n').glob('*.json')):
 d=json.loads(p.read_text(encoding='utf-8'))
 assert 'bfx_art_bulk' not in d, p.name + ': obsolete aggregate compile phase remains'
 for k, ph in keys.items():
  assert isinstance(d.get(k),str) and d[k], (p.name,k)
  for token in ph: assert token in d[k], (p.name,k,token)
assert "if (groupId === 'infirmary') cfgRenderInfirmaryHero(list);" in h
PY
command -v node >/dev/null 2>&1 || { echo "SKIP webui infirmary runtime: no node"; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
{
  cat <<'EOF'
let MD = '/m', ASB_LANG = 'en';
function shQuote(v) { return "'" + String(v) + "'"; }
function T(k, d) { return d; }
function cfgInfLater(k, fn) { fn(); }
function uiSound() {}
const toasts = [];
function toast(m, t) { toasts.push({ m: m, t: t }); }
const reg = {};
function mk(tag) {
  const e = { tag: tag, children: [], className: '', textContent: '', hidden: false, disabled: false, dataset: {}, style: {}, innerHTML: '' };
  Object.defineProperty(e, 'id', { get: function () { return e._id; }, set: function (v) { e._id = v; reg[v] = e; } });
  e.appendChild = function (c) { e.children.push(c); c.parent = e; return c; };
  e.querySelector = function (sel) {
    const cls = sel.replace(/^\./, '');
    const walk = function (n) { for (const c of n.children) { if ((' ' + c.className + ' ').indexOf(' ' + cls + ' ') >= 0) return c; const r = walk(c); if (r) return r; } return null; };
    return walk(e);
  };
  return e;
}
let onScreen = true;
let _cfgOpen = true, _cfgGroup = 'infirmary';
function kernelMoreBlock(card,id,nodes){const btn=mk('button');btn.className='kernel-more';card.appendChild(btn);const body=mk('div');body.className='kernel-more-body';body.hidden=true;nodes.forEach(n=>{if(n)body.appendChild(n);});card.appendChild(body);return body;}
global.document = { createElement: mk, body: { contains: function () { return onScreen; } } };
function _el(id) { return reg[id] || null; }
const timers = [];
global.setTimeout = function (fn, ms) { timers.push({ fn: fn, ms: ms, live: true }); return timers.length; };
global.clearTimeout = function (id) { if (timers[id - 1]) timers[id - 1].live = false; };
const cmds = [];
const scripted = { status: '', run: '', cancel: '', stop: '' };
async function run(cmd) {
  cmds.push(cmd);
  for (const k of ['status', 'run', 'cancel', 'stop']) if (new RegExp(' ' + k + '$').test(cmd)) return { errno: 0, stdout: scripted[k] };
  return { errno: 0, stdout: '' };
}
EOF
  sed -n '/^const BATTERY_FIX_SCRIPT = MD/,/^function cfgOpenInfirmary() {/p' "$H" | sed '/^function cfgOpenInfirmary() {/d'
  for fn in infAdviceValue infAdviceRecommendations infAdviceReadConfig infAdvicePaint infAdviceApply; do
    sed -n "/^async function $fn(/,/^}/p; /^function $fn(/,/^}/p" "$H"
  done
  cat <<'EOF'
const CFG_FILE = '/data/adb/asb/governor.conf';
const CFG_ITEMS = [
  { key:'night_modem_idle', def:'0' }, { key:'doze_level', def:'stock' },
  { key:'perf_ceiling_pct', def:'100' }
];
let _cfgVals = {}, _infAdviceData = null, _infAdviceLoading = false, _infAdviceBusy = false;
let _infAdviceArmed = 0, _infAdviceResults = [], _infAdviceError = '';
let _infAdviceAt = 0; const INF_ADVICE_MAX_AGE_MS = 300000;
let adviceRecs = [], adviceSaved = {}, adviceFinalErrno = 0, adviceWrites = [], adviceCfgLoads = 0;
let adviceRepaintOnWrite = false, adviceOptimisticOnly = false;
function Tcfg(k, f, d) { return k; }
function Topt(v) { return String(v); }
let adviceTips = [];
function logReportRecommendations() { return adviceRecs; }
function logReportTips() { return adviceTips; }
function logReportTipText(tip) { return tip && tip.key || ''; }
let staleAdviceRefreshes = 0;
async function infAdviceLoad() { staleAdviceRefreshes++; }
async function cfgLoad() { adviceCfgLoads++; return false; }
function adviceNodes() {
  ['infAdviceRows','infAdviceApply','infAdviceRefresh','infAdviceChip'].forEach(function (id) {
    const e = mk(id === 'infAdviceRows' ? 'div' : (id === 'infAdviceChip' ? 'span' : 'button')); e.id = id;
  });
}
async function cfgSet(key, value) {
  adviceWrites.push(key + '=' + value);
  if (adviceOptimisticOnly) _cfgVals[key] = value;
  else adviceSaved[key] = value;
  if (adviceRepaintOnWrite) { adviceNodes(); infAdvicePaint(); }
}
function adviceResult(key) { return _infAdviceResults.filter(function (r) { return r.key === key; })[0]; }
function adviceReset(recs, saved) {
  adviceRecs = recs; adviceSaved = Object.assign({}, saved || {}); adviceFinalErrno = 0;
  adviceWrites = []; adviceCfgLoads = 0; adviceRepaintOnWrite = false; adviceOptimisticOnly = false;
  _infAdviceData = { cfg:{} }; _infAdviceLoading = false; _infAdviceBusy = false;
  _infAdviceArmed = 0; _infAdviceResults = []; _infAdviceError = ''; _cfgVals = {};
  adviceNodes(); infAdvicePaint();
}
let bad = 0; function chk(c, m) { if (!c) { console.log('FAIL ' + m); bad++; } }
const B = 'eligible=1 reason=- level=100 charging=1 ';
const tail = ' now=2000 last_reset=- removed= missing= fresh=-';
const idle = 'reset=none compile=idle phase= total= done= ok= fail= cur= started= finished=';
const step = function (id) { return { cls: reg[id].className, text: reg[id + 'S'].textContent }; };
const lastTimer = function () { const l = timers.filter(function (t) { return t.live; }); return l.length ? l[l.length - 1].ms : 0; };
async function paint(st) { scripted.status = st; await batteryFixPaint(); }
(async function () {
  const list = mk('div');
  scripted.status = 'eligible=0 reason=not_charging level=57 charging=0 ' + idle + tail;
  cfgRenderBatteryFixCard(list);
  await new Promise(function (r) { setImmediate(r); });
  const card = list.children[0];
  chk(card && card.id === 'bfxCard', 'card not rendered');
  const ol = card.children.filter(function (c) { return c.tag === 'ol'; })[0];
  chk(ol && ol.children.map(function (c) { return c.id; }).join() === 'bfxStepCond,bfxStepArt,bfxStepReset', 'the three steps are missing or out of order');
  chk(reg.bfxRun.disabled && reg.bfxRun.dataset.mode === 'run', 'discharging did not disable the run button');
  chk(step('bfxStepCond').cls === 'bfx-step is-off' && step('bfxStepCond').text === '57% · not on charge', 'condition not shown: ' + step('bfxStepCond').text);
  chk(reg.bfxChip.className === 'bfx-chip is-off' && reg.bfxNote.textContent !== '', 'unavailable state not explained');
  chk(step('bfxStepArt').text === 'Not run yet' && reg.bfxBarWrap.hidden, 'idle compile state wrong');
  chk(reg.bfxCancel.hidden && lastTimer() === 15000, 'idle poll should be slow');

  await paint(B + idle + tail);
  chk(!reg.bfxRun.disabled && reg.bfxChip.className === 'bfx-chip is-ready' && step('bfxStepCond').cls === 'bfx-step is-ok', 'full on charge not ready');
  chk(reg.bfxNote.textContent === '', 'a stale reason stayed visible');

  const n0 = cmds.length;
  await batteryFixRun();
  chk(cmds.length === n0 && toasts[toasts.length - 1].t === 'perf', 'first tap should only arm a confirm');
  scripted.run = 'result=armed reset_on=reboot compile=started';
  await batteryFixRun();
  chk(cmds.some(function (c) { return / run$/.test(c); }) && toasts[toasts.length - 1].t === 'ok', 'second tap did not start the fix');

  await paint(B + 'reset=pending compile=running phase=compile total=300 done=150 ok=148 fail=2 cur=com.example.app started=1000 finished=-' + ' now=1300 last_reset=- removed= missing= fresh=-');
  chk(reg.bfxChip.className === 'bfx-chip is-run', 'running chip not shown');
  const art = step('bfxStepArt');
  chk(art.cls === 'bfx-step is-run' && art.text === '150 of 300 · failed: 2 · about 5 min left', 'progress text wrong: ' + art.text);
  chk(reg.bfxArtNow.textContent === 'Now: com.example.app', 'current app not shown');
  chk(!reg.bfxBarWrap.hidden && reg.bfxBar.style.transform === 'scaleX(0.5000)', 'progress bar wrong: ' + reg.bfxBar.style.transform);
  chk(reg.bfxRun.dataset.mode === 'stop' && !reg.bfxRun.disabled, 'running state does not offer stop');
  chk(!reg.bfxCancel.hidden && step('bfxStepReset').cls === 'bfx-step is-wait', 'scheduled reset not shown while compiling');
  chk(lastTimer() === 2000, 'running poll should be fast');
  scripted.stop = 'result=stopping';
  await batteryFixRun();
  chk(cmds.some(function (c) { return / stop$/.test(c); }) && /current app/.test(toasts[toasts.length - 1].m), 'stop did not reach the script');

  await paint(B + 'reset=pending compile=running phase=finishing total=300 done=300 ok=297 fail=3 cur=- started=1000 finished=-' + tail);
  chk(step('bfxStepArt').text === 'Final background optimisation…' && reg.bfxBar.style.transform === 'scaleX(1.0000)', 'finishing phase not shown');
  await paint(B + 'reset=pending compile=partial phase=partial total=560 done=4 ok=1 fail=3 cur=- started=1000 finished=1002' + tail + '\nerr_text=cmd: Failure calling service package: Failed transaction (2147483646)');
  chk(step('bfxStepArt').cls === 'bfx-step is-wait' && /1 succeeded, 3 failed, 556 not attempted/.test(step('bfxStepArt').text) && /no aggregate success is inferred/.test(step('bfxStepArt').text), 'partial Binder recovery hid failures or fabricated unprocessed apps: ' + step('bfxStepArt').text);

  await paint(B + 'reset=pending compile=done phase=done total=300 done=300 ok=297 fail=3 cur=- started=1000 finished=1600' + tail);
  chk(step('bfxStepArt').cls === 'bfx-step is-ok' && step('bfxStepArt').text === 'Done: 297 succeeded, failed: 3 · 10 min', 'compile result wrong: ' + step('bfxStepArt').text);
  chk(reg.bfxChip.className === 'bfx-chip is-wait' && reg.bfxRun.dataset.mode === 'reboot' && !reg.bfxCancel.hidden, 'pending state does not ask for a reboot');
  chk(reg.bfxArtNow.textContent === '' && lastTimer() === 15000, 'stale current app or fast poll after compile');
  const rb = cmds.length;
  await batteryFixRun();
  chk(cmds.slice(rb).some(function (c) { return /reboot/.test(c); }), 'reboot mode did not reboot');

  await paint('eligible=0 reason=not_full level=98 charging=1 reset=none compile=done phase=done total=300 done=300 ok=297 fail=3 cur=- started=1000 finished=1600 now=9000 last_reset=1700 removed=batterystats.bin,batterystats-checkin.bin,batterystats-daily.xml missing=- fresh=1');
  const rs = step('bfxStepReset');
  chk(rs.cls === 'bfx-step is-ok' && /statistics files removed: 3/.test(rs.text) && /started a new record/.test(rs.text) && !/not present|could not/.test(rs.text), 'verified reset not shown: ' + rs.text);
  chk(reg.bfxChip.className === 'bfx-chip is-ok' && reg.bfxCancel.hidden, 'done chip not shown');
  chk(reg.bfxRun.disabled && reg.bfxRun.dataset.mode === 'run', 'the run button should rest after a finished fix below 100%');
  await paint('eligible=0 reason=not_full level=98 charging=1 reset=none compile=done phase=done total=300 done=300 ok=297 fail=3 cur=- started=1000 finished=1600 now=9000 last_reset=1700 removed=- missing=batterystats.bin fresh=0');
  chk(step('bfxStepReset').cls === 'bfx-step is-fail' && /removed: 0/.test(step('bfxStepReset').text) && /could not be removed: 1/.test(step('bfxStepReset').text) && /write the new record/.test(step('bfxStepReset').text), 'an empty reset was shown as success: ' + step('bfxStepReset').text);
  // dev49: a user saw "1 of 3 files removed" and a date months in the past. Files Android
  // never created are named as absent, not as a partial failure, and a reset whose
  // post-fs-data clock was not trusted reads "at the last reboot" instead of a wrong date.
  await paint('eligible=0 reason=not_full level=98 charging=1 reset=none compile=done phase=done total=300 done=300 ok=297 fail=3 cur=- started=1000 finished=1600 now=9000 last_reset=boot removed=batterystats.bin missing=- fresh=- absent=batterystats-checkin.bin,batterystats-daily.xml');
  const ra = step('bfxStepReset');
  chk(ra.cls === 'bfx-step is-ok' && /^Done at the last reboot: statistics files removed: 1 · not present on this Android: 2 · /.test(ra.text) && !/could not/.test(ra.text), 'absent files or unsettled time not shown: ' + ra.text);
  // dev49: every recompile refused - the worker stops early and the first answer is shown.
  await paint('eligible=1 reason=- level=100 charging=1 reset=pending compile=refused phase=refused total=560 done=12 ok=0 fail=12 cur=- started=1000 finished=1010' + tail + '\nerr_text=Error: Failed to compile <x> package');
  chk(step('bfxStepArt').cls === 'bfx-step is-fail' && step('bfxStepArt').text === 'Android refused every recompile (12 of 12 apps), so it was stopped early. Android said: Error: Failed to compile x package', 'refused recompile not explained: ' + step('bfxStepArt').text);
  await paint('eligible=1 reason=- level=100 charging=1 reset=none compile=refused phase=refused total=560 done=12 ok=0 fail=12 cur=- started=1000 finished=1010' + tail);
  chk(/Android said: no reason given$/.test(step('bfxStepArt').text), 'a refusal without output has no fallback');
  await paint(B + 'reset=pending compile=refused phase=refused total=560 done=1 ok=0 fail=1 cur=- started=1000 finished=1002' + tail + '\nerr_text=cmd: Failure calling service package: Failed transaction (2147483646)');
  chk(/rejected both package-scoped compile calls/.test(step('bfxStepArt').text) && /no all-package fallback or ART\/Dalvik cleanup was used/.test(step('bfxStepArt').text) && /Android said: cmd: Failure calling service package: Failed transaction \(2147483646\)/.test(step('bfxStepArt').text) && !/\{err\}/.test(step('bfxStepArt').text), 'Binder refusal hides Android response, leaves a placeholder or fabricates completion: ' + step('bfxStepArt').text);

  await paint(B + 'reset=none compile=refused phase=refused total=560 done=3 ok=0 fail=3 cur=- started=1000 finished=1002' + tail + '\nerr_text=cmd: Failed transaction');
  chk(!/reset.*scheduled/i.test(step('bfxStepArt').text) && /Not scheduled/.test(step('bfxStepReset').text), 'old compilation error fabricated a pending reset');
  await paint(B + 'reset=pending compile=scheduled phase=scheduled total=560 done=1 ok=0 fail=0 cur=- started=1000 finished=1002' + tail);
  chk(step('bfxStepArt').cls === 'bfx-step is-wait' && /background optimisation job was started/.test(step('bfxStepArt').text) && /does not confirm speed-profile/.test(step('bfxStepArt').text), 'background scheduling was presented as verified compilation: ' + step('bfxStepArt').text);
  await paint(B + 'reset=none compile=interrupted phase=compile total=300 done=40 ok=40 fail=0 cur=x started=1000 finished=-' + tail);
  chk(step('bfxStepArt').cls === 'bfx-step is-wait' && step('bfxStepArt').text === 'Interrupted at 40 of 300' && reg.bfxArtNow.textContent === '', 'interrupted run not shown');
  await paint(B + 'reset=none compile=stopped phase=stopped total=300 done=70 ok=70 fail=0 cur=- started=1000 finished=1200' + tail);
  chk(step('bfxStepArt').text === 'Stopped at 70 of 300', 'stopped run not shown');
  await paint(B + 'reset=none compile=failed phase=no_packages total=0 done=0 ok=0 fail=0 cur=- started=1000 finished=1000' + tail);
