cp "$T/config" "$T/config.notset"
sed -i -e 's/^CONFIG_BPF=y$/# CONFIG_BPF is not set/' -e 's/^CONFIG_BPF_SYSCALL=y$/# CONFIG_BPF_SYSCALL is not set/' "$T/config.notset"
gzip -c "$T/config.notset" > "$T/proc/config.gz"
