for _jit in bpf_jit_enable bpf_jit_harden bpf_jit_kallsyms; do mv "$T/proc/sys/net/core/$_jit" "$T/$_jit.saved"; done
out="$(run)"
want kernel_ebpf summary 'not enabled in exposed config; runtime not verified'
want kernel_ebpf config 'not set'; want kernel_ebpf syscall_config 'not set'; want kernel_ebpf bpfs 'not exposed at standard path'
mv "$T/bpf.saved" "$T/sys/fs/bpf"
for _jit in bpf_jit_enable bpf_jit_harden bpf_jit_kallsyms; do mv "$T/$_jit.saved" "$T/proc/sys/net/core/$_jit"; done
rm -f "$T/config.notset"
# LKM NoMount/NTSync: loaded state and a version that the driver does not expose.
sed -i -e 's/^CONFIG_NOMOUNT=y$/CONFIG_NOMOUNT=m/' -e 's/^CONFIG_NTSYNC=y$/CONFIG_NTSYNC=m/' "$T/config"
gzip -c "$T/config" > "$T/proc/config.gz"; rm -f "$T/sys/module/nomount/version"
out="$(run)"
want kernel_features nomount 'module loaded'; want kernel_features nomount_version 'not exposed'; want kernel_features ntsync 'module loaded'
want metamodule nomount_driver 'module loaded'; want metamodule nomount_driver_version 'not exposed'
# An executable with no read response is not advertised as a working SuSFS interface.
cat > "$T/susfs" <<'EOF'
#!/bin/sh
exit 0
EOF
chmod +x "$T/susfs"
out="$(run)"; want susfs interface present_no_read_response; want kernel_features susfs 'built-in config; runtime not independently confirmed'; want kernel_features susfs_version 'not exposed'
# Explicit specialized config is the only positive Unicode Bypass evidence in this fixture.
printf '\nCONFIG_UNICODE_BYPASS_FIX=y\n' >> "$T/config"; gzip -c "$T/config" > "$T/proc/config.gz"
out="$(run)"; want kernel_features unicode_bypass_fix 'built-in config; runtime not independently confirmed'
! grep -Eq 'set_uname|add_sus_path|add_sus_map|add_sus_kstat|add_sus_' "$D" || fail "a SuSFS writer entered the collector"
# Locked/green/user without positive patch markers is stock-like, never proven stock.
# Remove the still-running NoMount driver too: runtime custom evidence is intentionally
# stronger than the boot/build indicators and must not be hidden to preserve an old verdict.
printf 'Linux version 6.12.30-oplus (builder@host) #1 SMP PREEMPT\n' > "$T/proc/version"
sed -i -e '/^CONFIG_LOCALVERSION=/d' -e '/^CONFIG_KSU/d' -e '/^CONFIG_NOMOUNT/d' -e '/^CONFIG_SECURITY_BASEBAND_GUARD/d' -e '/^CONFIG_UNICODE_BYPASS/d' -e '/^CONFIG_SCHED_BORE/d' "$T/config"
rm -f "$T/proc/sys/kernel/sched_bore"
rmdir "$T/sys/module/nomount"
gzip -c "$T/config" > "$T/proc/config.gz"; out="$(run)"
want kernel_origin assessment stock-like; want kernel_origin basis 'boot/build indicators only; provenance not proven'
grep -Ev '^\[ro\.boot\.|^\[ro\.build\.type\]' "$T/props" > "$T/props.new"; mv "$T/props.new" "$T/props"
out="$(run)"; want kernel_origin assessment unknown; want kernel_origin basis 'not exposed'
# fix257: generic KSU and exact implementation evidence are different facts.
KSUD_MODE=next out="$(run)"; want root variant 'KernelSU Next'; want root version 1.0.8
want root variant_evidence 'ksud --version'; want root version_evidence 'KernelSU Next v1.0.8'
KSUD_MODE=original out="$(run)"; want root variant KernelSU; want root version 0.9.5
KSUD_MODE=suki out="$(run)"; want root variant 'SukiSU Ultra'; want root version 1.2.3
KSUD_MODE=generic out="$(run)"; want root variant 'not exposed'; want root version 0.9.5; want root version_evidence 'ksud 0.9.5'
KSUD_MODE=malformed out="$(run)"; want root variant 'not exposed'; want root version 'not exposed'; want root version_evidence 'not-a-version'
KSUD_MODE=empty out="$(run)"; want root variant 'not exposed'; want root version 'not exposed'; want root variant_evidence 'not exposed'
KSUD_MODE=sanitize out="$(run)"; want root variant 'KernelSU Next'; want root version 1.0.8; want root version_evidence 'KernelSU Next v1.0.8'
printf '%s
' "$out" | grep 'DO_NOT_READ_SECOND_LINE' >/dev/null && fail "ksud emitted more than the bounded first line"
KSUD_MODE=long out="$(run)"
[ "$(printf '%s
' "$out" | awk -F '	' '$2 == "root" && $3 == "version_evidence" { print length($4) }')" -le 160 ] || fail "ksud evidence was not bounded"
[ "$(wc -l < "$T/ksud.log")" -gt 0 ] || fail "the ksud fixture was never queried"
grep -Ev '^--version$' "$T/ksud.log" && fail "a state-changing ksud command ran"
# fix278: the WebUI's snapshot skips the hook collector and offers it on request; --lsposed
# runs only that collector.
mkdir -p "$T/data/lspd"
out="$(ASB_DEVINFO_LSPOSED=0 run)"
want lsposed_hooks present 1; want lsposed_hooks collection on_demand
printf '%s\n' "$out" | grep '^D	lsposed_hooks	database' >/dev/null && fail 'the quick snapshot still ran the hook collector'
out="$(run --lsposed 2>/dev/null || true)"
printf '%s\n' "$out" | awk -F '\t' '$2 != "meta" && $2 != "lsposed_hooks" { bad = 1 } END { exit bad }' || fail "--lsposed emitted other sections: $out"
want lsposed_hooks present 1
printf '%s\n' "$out" | grep '^D	lsposed_hooks	basis	' >/dev/null || fail "--lsposed did not run the collector: $out"
rmdir "$T/data/lspd"
# dev20: a GKI config is 200-300 KB decompressed. Android's shell has no printf builtin and
# execve refuses one argument over 128 KB, so piping the whole text through printf returned
# nothing on every phone (kernel_config never listed a single CONFIG_ line in any export) while
# a host shell's builtin printf worked. Run the collector with printf forced external.
if command -v bash >/dev/null 2>&1; then
  {
    i=0; while [ "$i" -lt 9000 ]; do printf 'CONFIG_FILLER_OPTION_NUMBER_%05d=y\n' "$i"; i=$((i + 1)); done
    printf 'CONFIG_HZ=250\nCONFIG_LTO_CLANG_THIN=y\nCONFIG_KSU=y\nCONFIG_VPNHIDE=y\n# CONFIG_VPNHIDE_FS_HIDING is not set\n'
    printf 'CONFIG_USB_CONFIGFS_MASS_STORAGE=y\nCONFIG_USB_CONFIGFS_F_HID=y\nCONFIG_USB_CONFIGFS_NCM=y\nCONFIG_IP_NF_TARGET_MASQUERADE=y\n'
    printf 'CONFIG_TCP_CONG_BBR3=y\nCONFIG_WIREGUARD=y\nCONFIG_NET_SCH_CAKE=y\nCONFIG_OVERLAY_FS=y\n'
  } > "$T/config.big"
  [ "$(wc -c < "$T/config.big")" -gt 140000 ] || fail 'big config fixture is not over the 128 KB argument limit'
  gzip -c "$T/config.big" > "$T/proc/config.gz"
  printf 'reno cubic bbr bbr3\n' > "$T/proc/sys/net/ipv4/tcp_available_congestion_control"
  out="$(ASB_DEVINFO_MODDIR="$T/mod" ASB_DEVINFO_SYS="$T/sys" ASB_DEVINFO_PROC="$T/proc" \
    ASB_DEVINFO_DATA="$T/data" ASB_DEVINFO_PROP_FILE="$T/props" ASB_DEVINFO_SUSFS="$T/susfs" \
    ASB_DEVINFO_STATE="$T/state" ASB_DEVINFO_KSUD="$T/ksud" ASB_DEVINFO_DEV="$T/dev" \
    KSUD_LOG="$T/ksud.log" SUSFS_LOG="$T/susfs.log" bash -c 'enable -n printf; . "$1"' devinfo "$D")"
  want kernel_config available yes; want kernel_config entries 9012
  want kernel_config CONFIG_HZ 250; want kernel_config CONFIG_VPNHIDE y; want kernel_config CONFIG_VPNHIDE_FS_HIDING 'not set'
  want kernel_features lto 'ThinLTO (Clang); exposed config only'; want kernel_origin assessment custom-like
  want kernel_features vpn_hide 'built-in config; network option only; runtime not independently confirmed'
  want kernel_features usb_arsenal 'gadget options in exposed config: mass-storage, hid, ncm, nat; runtime not verified'
  want kernel_features bbr_v3 available; want kernel_features wireguard 'built-in config; runtime not independently confirmed'
  want kernel_features net_sch_cake 'built-in config; runtime not independently confirmed'
  want kernel_features overlayfs 'built-in config; runtime not independently confirmed'; want kernel_features cifs 'not exposed in config; runtime not confirmed'
  printf '%s\n' "$out" | grep '^D	kernel_config	CONFIG_FILLER' >/dev/null && fail 'non-whitelisted config lines were emitted'
  printf 'not gzip\n' > "$T/proc/config.gz"
  out="$(run)"; want kernel_config available 'present; not decodable here'; want kernel_features lto unknown
fi
echo "PASS device info: schema 6, ADIOS config/symbol/queue/selection evidence, static/managed/safe-media property readback and BT selection counts; read-only TSV, metamodule/root implementation variants, bounded ksud evidence, built-in/LKM NoMount and version, kernel feature evidence and missing-config semantics, the bounded --kernel probe with sched_stats config/node states, a 140 KB+ config read with an external printf (Android), VPN Hide / USB gadget / WireGuard / BBRv3 / CAKE / OverlayFS evidence"
)

t_webui_tcp_algorithms_runtime() (
# Runtime: every algorithm exposed by this kernel reaches the WebUI, unfiltered and deduplicated.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT HUP INT TERM
fail() { echo "FAIL WebUI TCP algorithms: $*" >&2; exit 1; }
command -v node >/dev/null 2>&1 || { echo 'SKIP WebUI TCP algorithms: node unavailable'; exit 0; }
python3 - "$ROOT/webroot/index.html" "$T/extract.js" <<'PY'
import sys
s=open(sys.argv[1]).read()
a=s.index('async function cfgLoadTcpAlgorithms()')
b=s.index('// Pending-reboot bar.',a)
open(sys.argv[2],'w').write(s[a:b])
PY
cat > "$T/t.js" <<'EOF'
const fs = require('fs');
let ASB_TCP_ALGS = null, _tcpAlgLoadStarted = false, _isReference = false, renders = 0;
function cfgRender(){ renders++; }
globalThis.run = async function(cmd){
  if (!cmd.includes('tcp_available_congestion_control')) throw new Error('unexpected command');
  return { errno:0, stdout:'reno bbr bic cubic westwood htcp bbr invalid-name! \n', stderr:'' };
};
eval(fs.readFileSync(process.argv[2], 'utf8'));
(async function(){
  const it = { key:'net_congestion_wifi', opts:['auto'] };
  const first = cfgOptsFor(it);
  if (JSON.stringify(first) !== JSON.stringify(['auto'])) throw new Error('premature static options');
  await cfgLoadTcpAlgorithms();
  const got = cfgOptsFor(it);
  const want = ['auto','reno','bbr','bic','cubic','westwood','htcp'];
  if (JSON.stringify(got) !== JSON.stringify(want)) throw new Error(JSON.stringify(got));
  if (renders !== 1) throw new Error('dynamic result did not rerender exactly once');
  await cfgLoadTcpAlgorithms();
  if (renders !== 1) throw new Error('algorithm probe repeated');
  console.log('ok');
})().catch(e => { console.error(e); process.exit(1); });
EOF
[ "$(node "$T/t.js" "$T/extract.js")" = ok ] || fail 'runtime algorithm list mismatch'
grep -Fq 'case " $_avail " in' "$ROOT/runtime/asb_net_apply.sh" || fail 'runtime availability revalidation missing'
echo 'PASS WebUI TCP algorithms: reno/bbr/bic/cubic/westwood/htcp come from the live kernel list'
)

t_webui_camera_grade_coverage_runtime() (
# Runtime: marker values and apply-coverage stats produce honest Grain states.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT HUP INT TERM
fail() { echo "FAIL WebUI camera coverage: $*" >&2; exit 1; }
command -v node >/dev/null 2>&1 || { echo 'SKIP WebUI camera coverage: node unavailable'; exit 0; }
python3 - "$ROOT/webroot/index.html" "$T/extract.js" <<'PY'
import sys
s=open(sys.argv[1]).read()
a=s.index('async function cfgLoadGrade()')
b=s.index('const ASB_NEEDS_REBOOT =',a)
open(sys.argv[2],'w').write(s[a:b])
PY
cat > "$T/t.js" <<'EOF'
const fs = require('fs');
let ASB_GRADE = null;
let statsText = 'grain_keys=0\ngrain_pct=1600\n';
globalThis.run = async function(cmd){
  if (cmd.includes('*.mark.stats')) return {errno:0,stdout:statsText,stderr:''};
  if (cmd.includes('*.mark')) return {errno:0,stdout:'ASBGRADE=abc:10:10:3:0:0\n',stderr:''};
  throw new Error('unexpected command: '+cmd);
};
eval(fs.readFileSync(process.argv[2], 'utf8'));
(async function(){
  await cfgLoadGrade();
  if (ASB_GRADE.CAMERA_GRAIN !== '10' || ASB_GRADE.grain_keys !== 0) throw new Error('marker/stats not loaded');
  if (!cfgCameraNotExposed('CAMERA_GRAIN','10')) throw new Error('zero changed keys claimed applied');
  if (cfgCameraNotExposed('CAMERA_GRAIN','3')) throw new Error('stock Grain marked not exposed');
  if (cfgCameraNotExposed('CAMERA_GRAIN','9')) throw new Error('pending change confused with coverage');
  statsText = 'grain_keys=0\ngrain_keys=2\n';
  await cfgLoadGrade();
  if (ASB_GRADE.grain_keys !== 2 || cfgCameraNotExposed('CAMERA_GRAIN','10')) throw new Error('multi-file coverage not summed');
  statsText = '';
  await cfgLoadGrade();
  if (ASB_GRADE.grain_keys !== null || cfgCameraNotExposed('CAMERA_GRAIN','10')) throw new Error('missing evidence became a negative claim');
  console.log('ok');
})().catch(e => { console.error(e); process.exit(1); });
EOF
[ "$(node "$T/t.js" "$T/extract.js")" = ok ] || fail 'camera coverage state mismatch'
echo 'PASS WebUI camera coverage: zero keys = not exposed, multi-file stats summed, missing = unknown'
)

t_device_info_krilikd_field_regression() (
# Field regression from 2026-11-13: a custom KRILIKD kernel with locked/green boot and
# a stock compatibility config was mislabelled stock-like. Built-in features without
# /sys/module directories were also left unknown despite standard runtime evidence.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
D="$ROOT/tools/asb_device_info.sh"
fail() { echo "FAIL KRILIKD field regression: $*" >&2; exit 1; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
mkdir -p "$T/mod" "$T/data" "$T/proc/sys/net/ipv4" "$T/proc/self/ns" \
  "$T/proc/sysvipc" "$T/proc/sys/fs/mqueue" "$T/sys/module/nomount" \
  "$T/sys/kernel/security" "$T/dev"
printf '22\n' > "$T/sys/module/nomount/version"
printf 'Linux version 6.12.69-android16-6-KRILIKD (kleaf@build-host) (Android +pgo, +bolt, +lto, +mlgo clang 19.0.1) #1 SMP PREEMPT\n' > "$T/proc/version"
printf 'console=ttynull androidboot.hardware=qcom\n' > "$T/proc/cmdline"
printf 'bbr bbr3\n' > "$T/proc/sys/net/ipv4/tcp_available_congestion_control"
printf 'lockdown,capability,selinux,baseband_guard\n' > "$T/sys/kernel/security/lsm"
printf 'nodev\n' > "$T/proc/vpnhide_ctl"
for n in ipc pid net uts; do printf '402653\n' > "$T/proc/self/ns/$n"; done
printf 'devtmpfs /dev devtmpfs rw 0 0\n' > "$T/proc/mounts"
ln -s /dev/null "$T/dev/ntsync"
cat > "$T/props" <<'EOF'
[ro.build.type]: [user]
[ro.boot.verifiedbootstate]: [green]
[ro.boot.flash.locked]: [1]
[ro.boot.vbmeta.device_state]: [locked]
EOF
cat > "$T/config" <<'EOF'
# CONFIG_REKERNEL is not set
# CONFIG_REKERNEL_NETWORK is not set
# CONFIG_NTSYNC is not set
# CONFIG_VPNHIDE is not set
# CONFIG_VPNHIDE_FS_HIDING is not set
# CONFIG_BBG is not set
# CONFIG_SECURITY_BASEBAND_GUARD is not set
# CONFIG_BASEBAND_GUARD is not set
# CONFIG_NET_SCH_CAKE is not set
# CONFIG_NAMESPACES is not set
# CONFIG_SYSVIPC is not set
# CONFIG_POSIX_MQUEUE is not set
# CONFIG_IPC_NS is not set
# CONFIG_PID_NS is not set
# CONFIG_NET_NS is not set
# CONFIG_UTS_NS is not set
# CONFIG_DEVTMPFS is not set
CONFIG_LTO_NONE=y
EOF
gzip -c "$T/config" > "$T/proc/config.gz"
cat > "$T/proc/kallsyms" <<'EOF'
0000000000000000 t cake_enqueue
0000000000000000 t rekernel_netlink_start
0000000000000000 t ntsync_init
0000000000000000 t vpnhide_init
0000000000000000 t bbg_init
EOF
cat > "$T/susfs" <<'EOF'
#!/bin/sh
printf '%s\n' "$*" >> "$SUSFS_LOG"
case "$1 $2" in
  'show version') printf 'v2.4.0\n' ;;
  'show variant') printf 'GKI\n' ;;
  'show enabled_features') printf 'CONFIG_KSU_SUSFS_SUS_PATH\n' ;;
esac
EOF
cat > "$T/tc" <<'EOF'
#!/bin/sh
printf '%s\n' "$*" >> "$TC_LOG"
[ "${1:-} ${2:-}" = 'qdisc show' ] || exit 2
printf 'qdisc fq_codel 0: root refcnt 2\n'
EOF
chmod +x "$T/susfs" "$T/tc"
out="$(ASB_DEVINFO_MODDIR="$T/mod" ASB_DEVINFO_SYS="$T/sys" ASB_DEVINFO_PROC="$T/proc" \
  ASB_DEVINFO_DATA="$T/data" ASB_DEVINFO_PROP_FILE="$T/props" ASB_DEVINFO_SUSFS="$T/susfs" \
  ASB_DEVINFO_STATE="$T/state" ASB_DEVINFO_DEV="$T/dev" ASB_DEVINFO_TC="$T/tc" \
  SUSFS_LOG="$T/susfs.log" TC_LOG="$T/tc.log" sh "$D")"
want() {
  _line="$(printf 'D\t%s\t%s\t%s' "$1" "$2" "$3")"
  printf '%s\n' "$out" | grep -Fx "$_line" >/dev/null || fail "missing [$_line] in: $out"
}
want kernel_origin assessment custom-like
want kernel_origin custom_evidence 'build/localversion marker; SuSFS interface; NoMount driver; Re-Kernel kernel symbols; VPN Hide control interface; VPN Hide kernel symbols; Baseband Guard kernel symbols; Baseband Guard in runtime LSM list; BBRv3 runtime algorithm'
want kernel_origin stock_evidence 'verifiedbootstate=green; flash.locked=1; vbmeta=locked; build.type=user'
want kernel_origin basis 'positive build/config/runtime patch indicators; boot lock/build type do not override them; provenance not proven'
want kernel_features net_sch_cake 'available; kernel symbols present'
want kernel_features net_sch_cake_config 'not set'
want kernel_features rekernel 'available; Re-Kernel kernel symbols present; transport/userspace not tested'
want kernel_features ntsync 'available; /dev/ntsync character device exposed'
want kernel_features vpn_hide 'available; /proc/vpnhide_ctl exposed; exposed config disagrees; hiding not tested'
want kernel_features bbg_baseband_guard 'active in runtime LSM list; enforcement policy not tested'
want kernel_features droidspaces 'core runtime interfaces exposed; container operation not tested'
want kernel_features lto 'compiler build marker +lto; exposed config says LTO_NONE; exact mode not independently confirmed'
[ "$(wc -l < "$T/susfs.log")" = 3 ] || fail 'SuSFS read count changed'
grep -Ev '^show (version|variant|enabled_features)$' "$T/susfs.log" && fail 'state-changing SuSFS probe'
grep -Ev '^qdisc show$' "$T/tc.log" && fail 'state-changing tc probe'
echo 'PASS device info KRILIKD field regression: custom runtime evidence outranks locked/green boot, built-in Re-Kernel/NTSync/VPN Hide/BBG evidence, runtime Droidspaces prerequisites, LTO banner and CAKE without writes'
)

t_webui_kernel_control_verdict() (
# Contract: kernel controls render the owner's verdict, never a saved-value success claim.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
python3 - "$H" <<'P'
import sys
h = open(sys.argv[1], encoding='utf-8').read()
keys = ('mglru_mode', 'kernel_timer_migration', 'kernel_sched_nr_migrate', 'kernel_sched_stats', 'kernel_sched_autogroup', 'kernel_sched_child_runs_first')
for key in keys:
    assert "'" + key + "'," in h, 'snapshot key missing: ' + key
    assert key + ': APPLY_LIVE' in h, 'live mode missing: ' + key
branch = "ASB_KERNEL_STATUS_KEYS.indexOf(key) >= 0"
pos = h.rindex(branch)
end = h.index("} else if (BLUR_KEYS.indexOf(key) >= 0)", pos)
body = h[pos:end]
for token in ('await run(', 'asb_kernel_controls.sh', 'kr.errno === 0', "'applied','restored','stock_unowned'", "uiSound('error')", "kp[1]", "kp[3]", 'await kernelPanelLoad(true)'):
    assert token in body, 'verdict branch lost ' + token
assert 'innerHTML' not in body and 'outerHTML' not in body
assert "readback_mismatch" not in body or "kp[1]" in body
P
echo 'PASS WebUI kernel controls: awaited owner verdict, applied/restored only on success, mismatch/error path and text-only values'
)

t_webui_kernel_panel_runtime() (
# dev33: System owns kernel management and wakeup rules. Read-only kernel evidence remains
# on Device Diagnostics instead of being probed and rendered a second time here.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL webui kernel panel: $*" >&2; exit 1; }
python3 - "$ROOT" <<'P' || fail 'static contract'
import json, pathlib, re, sys
root = pathlib.Path(sys.argv[1]); h = (root / 'webroot/index.html').read_text(encoding='utf-8')
groups = h[h.index('const CFG_GROUPS = ['):h.index('const CFG_EXTRA_GROUPS')]
assert re.findall(r"\{ id:'([^']+)'", groups) == ['iface','feel','net','camera','audio','battery','kernel','zygisk','ui']
# dev40: every hub group owns an explicit dark/light hue. In particular Zygisk must not
# silently inherit the primary mint accent through the old, undefined cat-system tile alias.
for token in (
    ":is(.cfg-section,.cfg-tile).cat-feel    { --cat: #b3d65a; }",
    ":is(.cfg-section,.cfg-tile).cat-zygisk  { --cat: #b1b6bc; }",
    ":is(.cfg-section,.cfg-tile).cat-system  { --cat: #a7b7c6; }",
    "const tileCat = g.id === 'ui' ? 'ux' : g.id;",
    "cat-zygisk  { --cat:#5d6167; }",
    "cat-feel    { --cat:#647800; }"
):
    assert token in h, token
sections = h[h.index('  kernel: ['):h.index('  zygisk: [', h.index('  kernel: ['))]
keys = ('mglru_mode','kernel_mglru_min_ttl','kernel_timer_migration','kernel_hrtimer_migration','kernel_lpm_prediction','kernel_sched_nr_migrate','kernel_sched_stats','kernel_sched_autogroup','kernel_sched_child_runs_first','kernel_usb_autosuspend','kernel_rt_boost')
for key in keys:
    assert key in sections and re.search(key + r":'kernel'", h)
assert "card:'wakeup'" in sections and 'capabilities' not in sections
assert "id:'wakeup'" not in sections, 'wakeup must share Kernel management, not a separate subsection'
controls = sections
assert "card:'wakeup'" in controls and all(key in controls for key in keys)
ui_sections = h[h.index('  ui: ['):h.index('  camera: [', h.index('  ui: ['))]
assert not any(key in ui_sections for key in keys) and "id:'zygisk'" not in ui_sections and "id:'feel'" not in ui_sections
assert "else if (section.card === 'wakeup') {" in h and 'sectionItems.forEach' in h[h.index("else if (section.card === 'wakeup') {"):h.index("else if (section.id === 'zygisk')")]
panel = h[h.index('const ASB_KERNEL_STATUS_KEYS'):h.index('function cfgToastText')]
assert 'asb_device_info.sh' not in panel and '_kernelPanel.caps' not in panel
assert 'cfgRenderKernelControlsHelp' in h and 'kernelControlsRefresh' in h and 'kernelOpenDiagnostics' in h
assert 'diagnostics.onclick = kernelOpenDiagnostics' in h
od = h[h.index('function kernelOpenDiagnostics()'):h.index('\n}\n', h.index('function kernelOpenDiagnostics()'))]
assert 'openDevicePage();' in od and "_el('dev-group-kernel')" in od and 'scrollIntoView' in od and '++tries < 40' in od
assert "groupId === 'kernel') kernelPanelEnsure()" in h and "if (_cfgGroup === 'kernel')" in panel
assert 'kernelCapabilityState' not in h and 'cfgRenderKernelCapabilitiesCard' not in h
assert 'kernelPanelLoad(true)' in h and "await kernelPanelLoad(true)" in h
assert '.kernel-unavailable .cfg-seg' in h and '.kernel-unavailable .cfg-sel-pop { display: none; }' in h
set_start = h.index('async function cfgSet(key, val, ctl)')
set_guard = h[set_start:h.index('const _fix = cfgConflictResolve', set_start)]
assert 'kernelControlAvailability(key)' in set_guard and 'not_exposed' in set_guard and 'return;' in set_guard
assert '/sys/kernel/asb_wakeup' not in h and 'ASB_WAKEUP_BLOCKLIST_NODE' not in h
assert "const owner = 'sh ' + shQuote(MD + '/runtime/asb_wakeup_blocker.sh');" in h
assert "+ ' && ' + owner + ' status'" in h
assert 'JSON.stringify(wb.savedAlways) === JSON.stringify(always)' in h
assert 'JSON.stringify(wb.savedSleep) === JSON.stringify(sleep)' in h
assert 'if (applied) _wbDraft = null;' in h
assert "kernelWakeupChipList" in h and "textContent" in h
assert 'setInterval' not in panel
observed_fn = panel[panel.index('function kernelWakeupObservedList'):panel.index('function cfgRenderWakeupBlockerCard')]
assert 'kernelWakeupSourceDialogOpen' in observed_fn and 'kernel-sources-open' in observed_fn
assert 'sources.forEach' not in observed_fn and 'kernel-sources-scroll' not in observed_fn, 'main card must not inline the source list'
for token in ('function kernelWakeupSourceDialogOpen', 'function kernelWakeupSourceDialogClose', 'function kernelWakeupSelectSources', 'function kernelWakeupSourceDialogRender', 'kernel_wb_search', 'kernel_wb_filter_reset', 'kernel_wb_sort_time'):
    assert token in panel, token
assert '.kernel-sources-scroll' in h and 'overflow-y:auto' in h and 'max-height:52vh' in h
en = json.loads((root / 'webroot/i18n/en.json').read_text(encoding='utf-8'))
new = [k for k in en if k.startswith('kernel_') or k.startswith('cfg_kernel_')]
assert len(new) == 139, len(new)
assert 'kernel_wb_saved_toast' in new
assert en.get('grp_kernel') == 'Kernel' and en.get('grp_kernel_desc') and not any(k.startswith('kernel_caps') for k in en)
for p in (root / 'webroot/i18n').glob('*.json'):
    d = json.loads(p.read_text(encoding='utf-8'))
    for k in new:
        assert isinstance(d.get(k), str) and d[k], (p.name, k)
        if p.stem != 'en': assert d[k] != en[k], (p.name, k, 'untranslated')
    for key in keys:
        card = d['cfg'][key]
        min_desc = (45 if p.stem == 'zh' else 100) if key in ('kernel_hrtimer_migration','kernel_lpm_prediction','kernel_usb_autosuspend') else (120 if p.stem == 'zh' else 240)
        # dev57: the trade-offs moved from one paragraph into the per-option lines.
        assert card['name'] and len(card['desc'] + ''.join(card.get('descOpt', {}).values())) >= min_desc, (p.name, key, 'missing mechanism/trade-off explanation')
        assert '/proc/sys/kernel/sched_stats' not in card['desc'], (p.name, key, 'obsolete stats path')
        assert '/proc/sys/kernel/sched_nr_migrate' not in card['desc'], (p.name, key, 'obsolete migration path')
        _opts = re.search(r"\{ key:'%s', type:'seg'[^}]*?opts:\[([^\]]*)\]" % key, h)
        if 'descOpt' in card: assert _opts and set(card['descOpt']) == {o.strip().strip("'") for o in _opts.group(1).split(',')}, (p.name, key)
        if p.stem != 'en': assert card != en['cfg'][key], (p.name, key, 'untranslated')
for _doc in ('docs/README.advanced.md', 'docs/README.advanced.ru.md'):
    _t = (root / _doc).read_text(encoding='utf-8')
    assert '/sys/kernel/debug/sched/nr_migrate' in _t and '/proc/sys/kernel/sched_schedstats' in _t, _doc
P
command -v node >/dev/null 2>&1 || { echo 'SKIP webui kernel panel runtime: no node'; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT HUP INT TERM
cat > "$T/test.js" <<'JS'
