global.T=(k,f)=>f||k;global.Tcfg=(k)=>k;global.uiSound=()=>{};global.haptic=()=>{};global.toast=(m,t)=>toasts.push([m,t]);global.cfgRender=()=>{};global.kernelWakeupSourceDialogRender=()=>{};
