t_webui_card_i18n_coverage_runtime() (
# Runtime (fix240): every Config card has a name and a description in every language.
#
# fix239 shipped DSP Clarity, Sub-bass Filter and Output Headroom with cfg.<key> written as a
# plain string in all 13 locale files and the descriptions parked in a top-level "desc" table
# that nothing reads. Tcfg looks up cfg[key].name / .desc, so every language fell back to the
# English source text (and uk.json carried Russian). Six newer cards kept their English names
# in 11 languages and several option labels were never translated. This test parses CFG_ITEMS
# from index.html and checks each locale: cfg entries are objects with a name and a desc, no
# stray "desc" table, card names are not left in English, descOpt tables are translated, every
# option that English labels has a label of its own, and uk.json holds no Russian-only words.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
fail() { echo "FAIL webui card i18n: $*" >&2; exit 1; }
python3 - "$ROOT" <<'P' || fail "locale coverage"
import json, re, sys, pathlib
root = pathlib.Path(sys.argv[1])
h = (root / 'webroot' / 'index.html').read_text(encoding='utf-8')
body = h[h.index('const CFG_ITEMS = ['):h.index('const CFG_GROUPS = [')]
items = {}
for m in re.finditer(r"\{\s*key:'(\w+)',\s*type:'(\w+)'(.*?)(?=\n\s*\{\s*key:'|\n\];)", body, re.S):
    k, t, rest = m.group(1), m.group(2), m.group(3)
    om = re.search(r"opts:\[([^\]]*)\]", rest)
    nm = re.search(r"name:'((?:[^'\\]|\\.)*)'", rest)
    dm = re.search(r"desc:'((?:[^'\\]|\\.)*)'", rest)
    items[k] = {'type': t, 'opts': re.findall(r"'([^']*)'", om.group(1)) if om else [], 'name': nm.group(1) if nm else '', 'desc': dm.group(0) if dm else ''}
assert len(items) >= 70, 'CFG_ITEMS parse: %d' % len(items)
for k in ('dsp_clarity', 'dsp_rumble', 'dsp_headroom', 'kernel_sched_stats', 'kernel_sched_autogroup', 'kernel_sched_child_runs_first', 'mglru_mode', 'kernel_timer_migration', 'kernel_sched_nr_migrate', 'athena_service', 'net_rps'):
    assert k in items, 'CFG_ITEMS lost ' + k
files = sorted((root / 'webroot' / 'i18n').glob('*.json'))
assert len(files) == 13, len(files)
en = json.loads((root / 'webroot' / 'i18n' / 'en.json').read_text(encoding='utf-8'))
# fix296 semantic copy audit: the English overlay and source fallback must not drift for
# rewritten cards. These strings are rendered with textContent, never as device markup.
audited = set('''bt_link_stability dsp_outputs dsp_loudness dsp_voice audio_remove_volume_limit
audio_resampler media_vol_steps CAMERA_LEVEL CAMERA_CONTRAST CAMERA_GRAIN CAMERA_PORTRAIT
CAMERA_LOWLIGHT CAMERA_PREVIEW_TNR camera_hold_enable UX_MANAGE_TIMEOUTS anim_speed UX_ANIM_FORCE_RESTART
disable_blur ui_effects_level night_modem_idle net_screen_off_lte net_lte_light
net_congestion_mobile net_qdisc net_rps net_txqueue net_route_tune wifi_country
wifi_scan_throttle net_wifi_leave wifi_powersave doze_level doze_trim_whitelist
wakelock_action wakelock_fitness gnss_trim night_quiet_enable sustained_temp_enter
perf_ceiling_pct cool_gaming BG_TRIM_LEVEL gms_trim athena_service ltpo_force ltpo_video
phantom_procs mmfeed_off log_level lsposed_verbose mglru_mode kernel_timer_migration
kernel_sched_nr_migrate kernel_sched_stats kernel_sched_autogroup kernel_sched_child_runs_first'''.split())
def jsq(v):
    return "desc:'" + v.replace('\\', '\\\\').replace("'", "\\'").replace('\n', '\\n') + "'"
for k in audited:
    assert k in items, 'audited card missing: ' + k
    assert items[k]['desc'] == jsq(en['cfg'][k]['desc']), 'English/source description drift: ' + k
all_en = json.dumps(en, ensure_ascii=False)
for rejected in ('no real fps loss', 'free battery with zero impact', 'This is where most of the overnight drain saving comes from', 'the single most expensive thing that can happen to a battery'):
    assert rejected not in all_en, 'unsupported absolute returned: ' + rejected
same = {('de', 'haptic_strength'), ('fr', 'haptic_strength')}
def lab(d, k, o):
    v = d.get('optFor', {}).get(k, {}).get(o)
    return v if v is not None else d.get('opt', {}).get(o)
probs = []
for p in files:
    lg = p.stem
    d = json.loads(p.read_text(encoding='utf-8'))
    if 'desc' in d:
        probs.append('%s: stray top-level "desc" table' % lg)
    for k, v in d.get('cfg', {}).items():
        if not isinstance(v, dict):
            probs.append('%s: cfg.%s is a %s, Tcfg needs {name, desc}' % (lg, k, type(v).__name__))
    for k, it in items.items():
        c = d.get('cfg', {}).get(k)
        if lg != 'en':
            if not isinstance(c, dict) or not str(c.get('name', '')).strip() or not str(c.get('desc', '')).strip():
                probs.append('%s: %s lacks a name or description' % (lg, k))
                continue
            if c['name'].replace('\n', ' ') == it['name'] and (lg, k) not in same and not re.fullmatch(r'[A-Z0-9 /.+-]+', it['name']):
                probs.append('%s: %s name is still English (%s)' % (lg, k, it['name']))
            if c['desc'] == en.get('cfg', {}).get(k, {}).get('desc'):
                probs.append('%s: %s description is still English' % (lg, k))
        ec = en.get('cfg', {}).get(k)
        eo = ec.get('descOpt') if isinstance(ec, dict) else None
        if eo and lg != 'en':
            lo = (c or {}).get('descOpt') or {}
            for o, txt in eo.items():
                if not lo.get(o) or lo.get(o) == txt:
                    probs.append('%s: %s descOpt.%s untranslated' % (lg, k, o))
        if it['type'] == 'seg' and lg != 'en':
            for o in it['opts']:
                if lab(en, k, o) is not None and lab(d, k, o) is None:
                    probs.append('%s: %s option %s has no label' % (lg, k, o))
    if lg == 'uk':
        for w in sorted(set(re.findall(r'\w*[ыэъё]\w*', json.dumps(d, ensure_ascii=False)))):
            probs.append('uk: Russian word ' + w)
for o in items['dsp_headroom']['opts']:
    if lab(en, 'dsp_headroom', o) is None:
        probs.append('en: dsp_headroom %s has no dB label' % o)
assert not probs, '\n'.join(probs)
P
echo "PASS webui card i18n: all 13 languages carry a name, description, translated detail table and option labels for every Config card"
)

t_webui_fix254_visual_states_runtime() (
# Runtime/static (fix254): cap-owner colours survive the neutral metric cascade in all four
# themes, priority actions have no vertical rail, and Liquid Glass distinguishes OFF from ON.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT HUP INT TERM
fail() { echo "FAIL WebUI fix254 visual states: $*" >&2; exit 1; }
python3 - "$H" "$T/metric.js" "$T/owner.js" <<'PY' || fail "CSS or source contract"
import re, sys
s = open(sys.argv[1], encoding='utf-8').read()
def rule(selector):
    m = re.search(re.escape(selector) + r'\s*\{([^}]*)\}', s, re.S)
    assert m, 'missing rule: ' + selector
    return m.group(1)
# The owner colours come after the broad metric-normal rules and use source, not quality,
# identities. Shell has an explicit token so Glass's mint secondary accent cannot recolour it.
normal = s.index(':is(.metric-normal,.metric-info) { color:var(--text) !important; }')
for cls, colour in (('cap-asb', 'var(--accent)'), ('cap-shell', 'var(--owner-shell)')):
    selector = 'html :is(.live-cell-value,.live-info-val).' + cls
    pos = s.index(selector, normal)
    assert pos > normal
    assert colour in s[pos:s.index('}', pos)]
    for theme in ('html[data-asb-glass="1"] ', 'html[data-asb-theme="light"] '):
        assert theme + ':is(.live-cell-value,.live-info-val).' + cls in s, theme + cls
assert '--owner-shell: #7dd3fc;' in s and '--owner-shell:#0b5f86;' in s
assert 'html[data-asb-theme="light"] :is(.live-cell-value,.live-info-val).cap-asb { color:var(--accent) !important; }' in s
assert "vendor_clamp') asbMetricPaint('liveCapSrc', 'metric-bad')" in s
# dev61: a vendor boost above ASB's ceiling is not a limit; it is painted neutral (info).
assert "vendor_raised') asbMetricPaint('liveCapSrc', 'metric-info')" in s
# Stock reuses this element for battery temperature: it must still clear owner classes first.
assert "cls('liveCapSrc', '');" in s and "asbMetricPaint('liveCapSrc', asbThermalMetric(batT, 'battery'));" in s
# No timeline border or indentation rail through the action numbers.
a = rule('.lgr-tip.lgr-action')
assert 'display: grid' in a and 'grid-template-columns: 22px minmax(0, 1fr)' in a
assert 'border' not in a and 'padding-inline-start' not in a
n = rule('.lgr-action-n')
assert 'text-align: end' in n and 'font-variant-numeric: tabular-nums' in n
# Both Glass palettes have neutral OFF cards and tracks. ON alone keeps the accent/category
# treatment. Every new state selector is Glass-scoped, so ordinary dark/light stay untouched.
for sel in (
    'html[data-asb-glass="1"] .cfg-row:not(.is-on)',
    'html[data-asb-glass="1"][data-asb-theme="light"] .cfg-row:not(.is-on)',
    'html[data-asb-glass="1"] .cfg-switch:not(.on)',
    'html[data-asb-glass="1"][data-asb-theme="light"] .cfg-switch:not(.on)'):
    body = rule(sel)
    assert 'background:' in body and 'border-color:' in body, sel
    assert 'var(--accent)' not in body and 'var(--cat' not in body, sel
on = rule('html[data-asb-glass="1"] .cfg-row.is-on')
assert 'var(--cat,var(--accent))' in on
# fix307: the Settings Zygisk summary participates in both Glass palettes as one parent
# material. Its evidence/master children must win over the generic row ON/OFF paints above.
for prefix in ('html[data-asb-glass="1"] ', 'html[data-asb-glass="1"][data-asb-theme="light"] '):
    start = s.index(prefix + '.hdr-cap,\n' + prefix + '.theme-toggle,')
    body = s[start:s.index('}', start)]
    assert '.cfg-zygisk-card' in body and 'backdrop-filter:blur(8px)' in body, prefix
child_sel = 'html[data-asb-glass="1"] .cfg-zygisk-card > .dev-zygisk-link,\nhtml[data-asb-glass="1"] .cfg-zygisk-card > .cfg-row'
child = rule(child_sel)
assert 'background:transparent !important' in child and 'box-shadow:none !important' in child
assert '-webkit-backdrop-filter:none' in child and 'backdrop-filter:none' in child
assert s.index(child_sel) > s.index('html[data-asb-glass="1"] .cfg-row.is-on')
assert s.index(child_sel) > s.index('html[data-asb-glass="1"][data-asb-theme="light"] .cfg-row:not(.is-on)')
light_child = rule('html[data-asb-glass="1"][data-asb-theme="light"] .cfg-zygisk-card > .dev-zygisk-link,\nhtml[data-asb-glass="1"][data-asb-theme="light"] .cfg-zygisk-card > .cfg-row')
assert 'background:transparent !important' in light_child and 'box-shadow:none !important' in light_child
# Text contrast for the actual owner colours on their card-family surfaces.
def rgb(h):
    h = h.lstrip('#'); return tuple(int(h[i:i+2], 16) / 255 for i in (0, 2, 4))
def lum(h):
    c = [v / 12.92 if v <= .04045 else ((v + .055) / 1.055) ** 2.4 for v in rgb(h)]
    return .2126*c[0] + .7152*c[1] + .0722*c[2]
def contrast(a, b):
    x, y = sorted((lum(a), lum(b)), reverse=True); return (x + .05) / (y + .05)
for bg, colours in {
    '#101714': ('#00f0b4', '#7dd3fc', '#ff2d2d', '#ff7a1a'),
    '#f7f9fa': ('#007c63', '#0b5f86', '#b42318', '#b04a00')}.items():
    for fg in colours:
        assert contrast(fg, bg) >= 4.5, (fg, bg, contrast(fg, bg))
# Execute the real painter and real cap-owner branch in Node below.
metric = s[s.index('const METRIC_CLASSES ='):s.index('/* fix253:', s.index('const METRIC_CLASSES ='))]
owner = s[s.index('const CAP_SRC_LABELS ='):s.index('const gpuEl =', s.index('const CAP_SRC_LABELS ='))]
open(sys.argv[2], 'w', encoding='utf-8').write(metric)
open(sys.argv[3], 'w', encoding='utf-8').write(owner)
PY
command -v node >/dev/null 2>&1 || { echo 'SKIP WebUI fix254 owner painter: node unavailable'; }
if command -v node >/dev/null 2>&1; then
cat > "$T/test.js" <<'JS'
const fs = require('fs');
let capSrc, _cs0, _cs1, el;
function _el() { return el; }
function T(_k, fallback) { return fallback; }
eval(fs.readFileSync(process.argv[2], 'utf8'));
// Evaluate the real owner branch in a fresh function scope so its const declarations repeat.
const branch = fs.readFileSync(process.argv[3], 'utf8');
function run(src) {
  el = { className: 'live-cell-value', textContent: '', title: '',
    classList: { add(c) { el.className += ' ' + c; } } };
  capSrc = src; _cs0 = src; _cs1 = '';
  eval(branch);
  return el.className;
}
const cases = {
  asb: ['cap-asb', 'metric-normal'], asb_dynamic: ['cap-asb', 'metric-normal'],
  shell_applied: ['cap-shell', 'metric-normal'], shell_overridden_down: ['cap-shell', 'metric-normal'],
  vendor_clamp: ['metric-bad'], vendor_raised: ['metric-info'],
  thermal_overlay: ['metric-hot'], policy_unknown: ['metric-neutral']
};
for (const [src, wanted] of Object.entries(cases)) {
  const got = run(src);
  for (const cls of wanted) if (!got.split(/\s+/).includes(cls)) throw new Error(src + ': ' + got);
  if ((src === 'vendor_clamp' || src === 'vendor_raised') && /cap-asb|cap-shell/.test(got)) throw new Error(src + ': stale owner class');
}
console.log('ok');
JS
[ "$(node "$T/test.js" "$T/metric.js" "$T/owner.js")" = ok ] || fail "owner painter classes"
fi
echo "PASS WebUI fix254 visual states: ASB green, Shell blue, Vendor clamp red, Vendor ↑ neutral, rail-free actions and neutral OFF glass in both palettes"
)

t_webui_fix256_inactive_profile_glass() (
# Runtime/static (fix256): dark-Glass profile surfaces recede without dimming their content.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL WebUI fix256 inactive profiles: $*" >&2; exit 1; }
python3 - "$H" <<'PY' || fail "CSS or cascade contract"
import re, sys
s = open(sys.argv[1], encoding='utf-8').read()
def rule(selector):
    m = re.search(re.escape(selector) + r'\s*\{([^}]*)\}', s, re.S)
    assert m, 'missing rule: ' + selector
    return m.group(1)
base = 'html[data-asb-glass="1"]:not([data-asb-theme="light"]) .pbtn:not(.on)'
off = rule(base)
# The actual surface is substantially darker than the shared Glass material. No opacity is
# applied to the card itself, so names, icons and neutral %/h chips keep full foreground paint.
assert 'rgba(4,8,6,.96)' in off
assert 'rgba(255,255,255,.022)' in off and 'rgba(255,255,255,.004)' in off
assert 'border-color:rgba(255,255,255,.10) !important' in off
assert 'background:' in off and 'box-shadow:' in off
assert not re.search(r'(?<![-\w])opacity\s*:', off), 'the whole inactive card must not be dimmed'
assert not re.search(r'(?:^|;)\s*color\s*:', off), 'the surface rule must not recolour profile values or labels'
# Smart's normally luminous decorative layer must not leave an inactive card looking selected.
before = rule(base + '::before')
assert 'opacity:0 !important' in before
# These overrides follow both shared Glass materials and the light-Glass active rule. Their
# explicit :not([data-asb-theme="light"]) guard prevents changes to the other three themes.
pos = s.index(base)
assert pos > s.index('html[data-asb-glass="1"] .pbtn,\nhtml[data-asb-glass="1"] .lgr-hero,\nhtml[data-asb-glass="1"] .lgr-sec,\nhtml[data-asb-glass="1"] .live-info-now,\nhtml[data-asb-glass="1"] .live-info-src')
assert pos > s.index('html[data-asb-glass="1"][data-asb-theme="light"] .pbtn,\nhtml[data-asb-glass="1"][data-asb-theme="light"] .lgr-hero,\nhtml[data-asb-glass="1"][data-asb-theme="light"] .lgr-sec,\nhtml[data-asb-glass="1"][data-asb-theme="light"] .live-info-now,\nhtml[data-asb-glass="1"][data-asb-theme="light"] .live-info-src')
assert pos > s.index('html[data-asb-glass="1"][data-asb-theme="light"] .pbtn.on,\nhtml[data-asb-glass="1"][data-asb-theme="light"] .cfg-tile.active,\nhtml[data-asb-glass="1"][data-asb-theme="light"] .cfg-profile-row.selected,\nhtml[data-asb-glass="1"][data-asb-theme="light"] .cfg-row.is-on')
active = rule('html[data-asb-glass="1"] .pbtn.on,\nhtml[data-asb-glass="1"] .cfg-tile.active,\nhtml[data-asb-glass="1"] .cfg-profile-row.selected')
assert 'border-color:var(--accent) !important' in active
# fix259: disabled tweaks use exactly the approved inactive-profile surface, not a lighter
# competing material. Their light-Glass and enabled treatments remain independent.
tweak = rule('html[data-asb-glass="1"] .cfg-row:not(.is-on)')
for token in ('rgba(4,8,6,.96)', 'rgba(255,255,255,.022)', 'rgba(255,255,255,.004)',
              'border-color:rgba(255,255,255,.10) !important',
              'box-shadow:0 8px 22px rgba(0,0,0,.30),inset 0 1px 0 rgba(255,255,255,.065) !important'):
    assert token in tweak and token in off, token
light_tweak = rule('html[data-asb-glass="1"][data-asb-theme="light"] .cfg-row:not(.is-on)')
assert 'rgba(4,8,6,.96)' not in light_tweak
# fix260: only the shared dark-Glass material gets darker. The approved OFF surfaces and
# their neutral icon wells/tracks keep the exact fix259 paint, including highlights.
assert '--surface:rgba(8,13,10,.90)' in s and '--tabbar-bg:rgba(8,13,10,.88)' in s
assert 'rgba(16,23,20,.86)' not in s
well = rule('html[data-asb-glass="1"] .cfg-row:not(.is-on) .cfg-icon')
track = rule('html[data-asb-glass="1"] .cfg-switch:not(.on)')
for body in (well, track):
    assert 'background:rgba(255,255,255,.022)' in body
    assert 'border-color:rgba(255,255,255,.10)' in body
assert 'box-shadow:inset 0 1px 0 rgba(255,255,255,.065)' in track
print('ok')
PY
echo "PASS WebUI fix256 inactive profiles: matching dark-Glass inactive profile/OFF-tweak surfaces, hidden idle sheen, full foreground opacity and unchanged active/light materials"
)

t_webui_fix322_liquid_glass_material() (
# Contract (fix322): Glass is a layered, neutral material system rather than a set of
# nearly opaque green cards. Keep this final cascade focused on paint: header/dock geometry
# and all profile, Smart, evidence and navigation behaviour remain owned by earlier code.
# fix351 retunes the same contract to the ColorOS 17 references: slightly clearer surfaces,
# a stronger blur ladder, a cool-tinted wash and the lower-edge "underlight" inner shadow.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL WebUI fix322 Liquid Glass material: $*" >&2; exit 1; }
python3 - "$H" <<'PY' || fail 'material cascade or accessibility fallback'
import re, sys
s = open(sys.argv[1], encoding='utf-8').read()
marker = '/* ── ColorOS-style Liquid Glass material (fix322)'
assert s.count(marker) == 1
b = s[s.index(marker):s.index('</style>', s.index(marker))]
assert b.count('html:root[data-asb-glass="1"]') >= 20
for token in (
    '--glass-surface:rgba(12,18,15,.52)',
    '--glass-surface-quiet:rgba(8,13,10,.42)',
    '--glass-surface-strong:rgba(10,15,13,.90)',
    '--glass-nav-surface:rgba(6,10,8,.84)',
    '--glass-nav-wash:linear-gradient(135deg,rgba(255,255,255,.045),rgba(255,255,255,.008) 48%,rgba(255,255,255,.018))',
    '--glass-control:rgba(20,27,24,.44)',
    '--glass-edge:rgba(255,255,255,.16)',
    '--glass-underlight:rgba(255,255,255,.055)',
    '--glass-wash:linear-gradient(135deg,rgba(255,255,255,.115),rgba(255,255,255,.024) 46%,rgba(196,214,255,.05))',
    '--glass-blur:blur(22px) saturate(1.28)',
    '--glass-surface:rgba(255,255,255,.42)',
    '--glass-surface-quiet:rgba(255,255,255,.32)',
    '--glass-surface-strong:rgba(250,252,251,.90)',
    '--glass-nav-surface:var(--glass-surface-strong)',
    '--glass-nav-wash:var(--glass-wash)',
    '--glass-control:rgba(255,255,255,.36)',
    '--glass-edge:rgba(70,85,80,.15)',
    '--glass-underlight:rgba(255,255,255,.50)',
    '--glass-wash:linear-gradient(135deg,rgba(255,255,255,.64),rgba(255,255,255,.18) 50%,rgba(244,248,255,.36))',
    '--glass-canvas-image:#000', '--glass-canvas-image:#edf4f1',
    '--glass-scrim:#000', '--glass-scrim:#edf4f1',
):
    assert token in b, token
# fix351: every painted surface family carries the lower inner edge light; the count is
# exact so a silently dropped family fails here instead of on the device.
assert b.count('inset 0 -1px 0 var(--glass-underlight)') == 10
# The same SOLID canvas reaches root/body/drill-in pages and the status scrim. Card materials
# may keep their own washes; the canvas itself must not reintroduce radial/linear paint.
for selector in ('html:root[data-asb-glass="1"] {', 'html:root[data-asb-glass="1"][data-asb-theme="light"] {'):
    block = re.search(re.escape(selector) + r'([^}]*)\}', b)
    assert block, selector
    for prop in ('--glass-canvas-image', '--glass-scrim'):
        value = re.search(re.escape(prop) + r':([^;]+);', block.group(1))
        assert value and 'gradient' not in value.group(1), (selector, prop, value.group(1) if value else None)
assert 'background:var(--glass-canvas-image) !important' in b
assert 'html:root[data-asb-glass="1"] #reportPage,\nhtml:root[data-asb-glass="1"] #devicePage,\nhtml:root[data-asb-glass="1"] #zygiskPage' in b
assert 'background:var(--glass-scrim)' in b
# Every important surface family participates, including previously easy-to-miss controls.
shared = b[b.index('html:root[data-asb-glass="1"] .hdr-cap,\nhtml:root[data-asb-glass="1"] .theme-toggle,'):]
shared = shared[:shared.index('}')]
for cls in ('.cfg-tile', '.cfg-row', '.cfg-zygisk-card', '.live-cell', '.smart-banner',
            '.cfg-profile-sheet', '.cfg-reset-dialog', '.log-menu', '.cfg-fm-box',
            '.pbtn', '.lgr-sec', '.dev-loading', '.live-info-hist'):
    assert cls in shared, cls
# Only floating chrome/dialogs get the denser material. Neutral edges replace the old
# accent outline around ordinary menus and dialogs.
floating = b[b.index('html:root[data-asb-glass="1"] .asb-tabbar,'):]
floating = floating[:floating.index('}')]
assert 'html:root[data-asb-glass="1"] .report-nav,\nhtml:root[data-asb-glass="1"] .zy-page-nav,\nhtml:root[data-asb-glass="1"] .dev-page-nav,\nhtml:root[data-asb-glass="1"] .cfg-page-nav,\nhtml:root[data-asb-glass="1"] .log-menu' in floating
assert 'var(--glass-surface-strong)' in floating and 'blur(28px)' in floating
assert 'border-color:var(--glass-edge) !important' in floating
# fix332: only navigation docks get the darker dark-Glass material; light Glass and
# header capsules keep their approved paints. The rule must follow the dense base rule.
nav_selector = 'html:root[data-asb-glass="1"] .asb-tabbar,\nhtml:root[data-asb-glass="1"] .report-nav,\nhtml:root[data-asb-glass="1"] .zy-page-nav,\nhtml:root[data-asb-glass="1"] .dev-page-nav,\nhtml:root[data-asb-glass="1"] .cfg-page-nav'
assert b.count(nav_selector + ' {') == 1
nav = b[b.index(nav_selector + ' {'):]
nav = nav[:nav.index('}')]
assert 'background:var(--glass-nav-wash),var(--glass-nav-surface) !important' in nav
assert '.log-menu' not in nav and '.hdr-cap' not in nav
assert b.index(nav_selector + ' {') > b.index('html:root[data-asb-glass="1"] .asb-tabbar,')
# The Zygisk note's logical gutter survives the more specific lgr-note reset, including RTL.
assert '#zygiskPage .dev-evidence { padding-inline-start:12px; }' in b
assert '#zygiskPage .zy-controls-card > .dev-evidence' not in b
# Nested report evidence must not double the parent's blur/shadow.
nested = re.search(r'html:root\[data-asb-glass="1"\] :is\(\.lgr-sec,\.cfg-zygisk-card\) \.lgr-hero,\n(?:html:root\[data-asb-glass="1"\] :is\(\.lgr-sec,\.cfg-zygisk-card\) \.(?:lgr-quality|live-info-now),\n){2}html:root\[data-asb-glass="1"\] :is\(\.lgr-sec,\.cfg-zygisk-card\) \.live-info-src \{([^}]*)\}', b)
assert nested and '-webkit-backdrop-filter:none' in nested.group(1)
assert 'box-shadow:inset 0 1px 0' in nested.group(1)
# Selected profiles/categories keep identity through a restrained tint, not a luminous slab.
assert 'color-mix(in srgb,var(--c,var(--accent)) 15%,transparent)' in b
assert 'color-mix(in srgb,var(--cat) 14%,transparent)' in b
assert '.cfg-reboot-tile' in b
assert ':active' in b and 'inset 0 2px 7px' in b
# No-blur, reduced-transparency and forced-colours modes stay readable without depending
# on compositor support. These are real paints, not merely an unsupported media query.
assert '@supports not ((backdrop-filter:blur(1px)) or (-webkit-backdrop-filter:blur(1px)))' in b
assert '@media (prefers-reduced-transparency:reduce)' in b
assert '@media (forced-colors:active)' in b
for token in ('--glass-surface:#151c18', '--glass-surface:#f7f9fa',
              '--glass-nav-surface:#101511', '--glass-nav-surface:#fff',
              'background:Canvas !important', 'color:CanvasText !important'):
    assert token in b, token
# This revision must not reintroduce the old header deformation or ad-hoc navigation sizing.
for pattern in (r'\.header\s*\{', r'\.logo-c\s*\{', r'\.asb-tabbar\s*\{[^}]*(?:width|height|transform)\s*:',
                r'\.status-row\s*\{[^}]*(?:width|height|transform)\s*:'):
    assert not re.search(pattern, b, re.S), pattern
# Fallback text contrast is checked independently in both palettes.
def rgb(h):
    h = h.lstrip('#'); return tuple(int(h[i:i+2], 16) / 255 for i in (0, 2, 4))
def lum(h):
    c = [v / 12.92 if v <= .04045 else ((v + .055) / 1.055) ** 2.4 for v in rgb(h)]
    return .2126*c[0] + .7152*c[1] + .0722*c[2]
def contrast(a, b):
    x, y = sorted((lum(a), lum(b)), reverse=True); return (x + .05) / (y + .05)
for bg, colors in {'#151c18':('#f2fff9','#b8cec4','#91aa9f'),
                   '#f7f9fa':('#15191e','#4a5561','#65717b')}.items():
    for fg in colors:
        assert contrast(fg, bg) >= 4.5, (fg, bg, contrast(fg, bg))
PY
echo "PASS WebUI fix322 Liquid Glass: solid dark/light canvas and scrim, layered card materials, neutral floating chrome, quiet nesting, pressed states and accessibility fallbacks"
)

t_webui_fix324_boot_intro() (
# Contract (fix324): dark Glass is black; the once-per-boot preview performs real bounded
# collector/cache work, never replays within one boot and always returns the ordinary UI.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL WebUI fix324 boot intro: $*" >&2; exit 1; }
python3 - "$ROOT" <<'PY' || fail 'source/visual/localization contract'
import json, re, sys
from pathlib import Path
root=Path(sys.argv[1]); s=(root/'webroot/index.html').read_text(encoding='utf-8')
# Rejected on-device: every full-screen wash/gradient. Dark and light Glass use one
# solid canvas/scrim colour; only the card material retains translucent washes.
dark=re.search(r'html:root\[data-asb-glass="1"\] \{([\s\S]*?)\n\}',s).group(1)
