out="$(node "$T/test.js" "$H" 2>&1)" || { echo "FAIL WebUI fix324 intro runtime: $out" >&2; exit 1; }
[ "$out" = ok ] || { echo "FAIL WebUI fix324 intro runtime: $out" >&2; exit 1; }
echo "PASS WebUI fix324: simplified once-per-boot splash with metric preloading and ordinary progress, no visible LIVE/CONFIG/DEVICE/LOG or duplicate ZYGISK stage labels, bounded fail-safe and no replay"
)

t_webui_fix325_startup_performance() (
# Contract (fix325): one shared startup batch, immediate post-paint cache warming without
# duplicate intro collectors, Home meter reuse, and visibility-aware Live collector sharing.
# dev50 also deduplicates the cold static-device fetch, reuses its valid cache and avoids a
# forced Stock telemetry repeat when a fresh sample already exists.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL WebUI fix325 startup performance: $*" >&2; exit 1; }
python3 - "$H" <<'PY' || fail 'source/scheduling contract'
import re, sys
s=open(sys.argv[1],encoding='utf-8').read()
assert '@import "https://mui.kernelsu.org/internal/insets.css"' not in s
# fix332: the critical canvas is parsed before the optional inset stylesheet, main CSS,
# locale or root bridge. A saved light palette is selected parser-locally; dark never
# depends on the WebView host's initial light-grey default.
critical_start=s.index('<style>')
critical_end=s.index('</style>',critical_start)+len('</style>')
critical=s[critical_start:critical_end]
assert 'html,body{background:#000}' in critical and 'html{color-scheme:dark}' in critical
assert 'html[data-asb-theme="light"],html[data-asb-theme="light"] body{background:#f2f4f6;color-scheme:light}' in critical
assert 'localStorage.getItem(\'asb_theme\')' in s[critical_end:s.index('<style>',critical_end)]
assert s.index("link.rel = 'stylesheet'") > critical_end
head=s[:s.index('<style>\n:root {')]
assert "link.rel = 'stylesheet'" in head and "link.media = 'print'" in head
assert "link.addEventListener('load'" in head and "link.media = 'all'" in head
assert 'https://mui.kernelsu.org/internal/insets.css' in head and 'document.head.appendChild(link)' in head
assert '--window-inset-top: env(safe-area-inset-top, 0px);' in s
def body(sig):
    i=s.index(sig); return s[i:s.index('\n}\n',i)+2]
startup=s[s.index('let _asbStartupSnapshotRun = null;'):s.index('let _asbDebugActionBusy',s.index('let _asbStartupSnapshotRun = null;'))]
assert startup.count('runBatch([')==1
for key,path in (('profile','/current_profile'),('state','/dev/.asb/state'),
                 ('smart_pending','/data/adb/asb/smart_mode_enabled'),('boot','/proc/sys/kernel/random/boot_id')):
    assert "['%s'," % key in startup and path in startup, key
assert 'if (!_asbStartupSnapshotRun)' in startup and 'return _asbStartupSnapshotRun;' in startup
home=s[s.index('(async () => {',s.index('function openTelegram')):s.index('function fmtTempC')]
assert 'await asbStartupSnapshot();' in home and 'refreshSmartSubLine(startup);' in home
assert "await run('cat ' + MD + '/current_profile" not in home
smart=body('async function refreshSmartSubLine(pre) {')
assert 'pre && pre.state' in smart and smart.count('runBatch([')==1
assert 'smart_pending' in smart and "kv._smartPending = 1" in smart
warm=body('function asbStartupWarmCaches() {')
assert 'probe.then(warm' in warm and 'if (introShown || document.hidden) return;' in warm
assert warm.count('asbStartupLater(function () { return cfgLoad(); }, 0, 0);') == 1
assert 'openConfigPage() on demand' not in warm
assert 'asbStartupLater(zygiskHeaderRefresh, 150, 0);' in warm and 'setTimeout(' not in warm
assert 'setTimeout(zygiskHeaderRefresh, 2500)' not in s
load=s[s.index("window.addEventListener('load', function () {",s.index('function asbStartupWarmCaches')):s.index('function asbNavCurrent')]
assert 'homeMeterRefresh(true)' not in load
# fix328: local warm-up starts after the first frame, not after an external stylesheet can
# delay window.load. The warm function/probe and its request counts remain unchanged.
assert 'asbStartupWarmCaches' not in load
schedule='requestAnimationFrame(function () { setTimeout(asbStartupWarmCaches, 0); });'
assert schedule in s and s.index(schedule) < s.index("window.addEventListener('load', function () {",s.index('function asbStartupWarmCaches'))
assert s.count('homeMeterRefresh(true);')==1  # only the intentional post-profile-switch refresh
initial=s[s.index('/* Coordinate the ordinary cold read'):s.index('window._asbBootIntroProbe =',s.index('/* Coordinate the ordinary cold read'))]
assert 'requestAnimationFrame(() => setTimeout(() => {' in initial and '}, 0));' in initial
assert 'if (!shown) asbStartupLater(asbStartupLive, 0, 0);' in initial and ', 250);' not in initial
header=s[s.index("const DEVICE_HEADER_CACHE_KEY = 'asb_device_header_cache'"):s.index('function liveHeaderSync()')]
for token in ('let _deviceHeaderLoad = null;', 'if (cached) { deviceHeaderPaint(cached.model, cached.soc, cached.chip); return; }',
              'if (_deviceHeaderLoad) return _deviceHeaderLoad;', '_deviceHeaderLoad = (async function () {',
              'finally { _deviceHeaderLoad = null; }'):
    assert token in header, token
assert header.index('if (cached)') < header.index("await fetch(")
open_live=body('function openLivePage() {')
assert 'liveMonitorSchedule(liveOpenRefreshDelay());' in open_live
monitor_schedule=body('function liveMonitorSchedule(delay) {')
assert 'pollStockTelemetry(true);' in monitor_schedule and 'pollStockTelemetry(true, true)' not in monitor_schedule
poll=body('async function pollLive(visible, prefetch) {')
for token in ('if (_livePollRun) {','if (!visible || (_livePollVisible && _livePollSeq === _livePageSeq)) return _livePollRun;',
              'if (!_livePollFollow) {','return pollLive(true, prefetch);','} finally {',
              '_livePollRun = null;','if (releasePoll) releasePoll();',
              'else await pollStockTelemetry(false);'):
    assert token in poll, token
assert 'if (visible) lvMeterPaint(_selectedProfile); else if (!_lb.meter) homeMeterPaint();' in poll
assert 'if (!_lb.meter && !visible) homeMeterPaint();' in poll
assert 'if (_lb.meter && !visible) homeMeterPaint();' not in poll
assert poll.count('runBatch(liveBatchParts(visible, prime))')==1
open_dev=body('function openDevicePage() {')
assert 'if (!deviceInfoPresentSnapshot()) asbDeviceInfoLoad();' in open_dev
assert 'asbDeviceInfoLoad(); }, 50)' not in open_dev
assert open_dev.count('asbDeviceInfoLoad();')==1, 'Device navigation must collect only as the no-snapshot fallback'
intro=s[s.index('async function asbBootIntroStart()'):s.index('// ── localized boot:')]
assert 'await asbStartupSnapshot()' in intro and "run('cat /proc/sys/kernel/random/boot_id" not in intro
# No persistent worker was added to make the UI appear faster.
assert intro.count('setInterval(')==0 and warm.count('setInterval(')==0
PY
command -v node >/dev/null 2>&1 || { echo 'SKIP WebUI fix325 runtime: no node'; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
cat > "$T/test.js" <<'JS'
const fs=require('fs'),h=fs.readFileSync(process.argv[2],'utf8');
function grab(sig){const i=h.indexOf(sig);if(i<0)throw Error('missing '+sig);const j=h.indexOf('\n}\n',i);if(j<0)throw Error('unterminated '+sig);return h.slice(i,j+2);}
const chk=(c,m)=>{if(!c)throw Error(m)};
const flush=()=>new Promise(r=>setImmediate(r));
(async()=>{
  let batches=[],snapshot={profile:{errno:0,stdout:'balanced'},state:{errno:0,stdout:'smart_mode=0'},smart_pending:{errno:0,stdout:'1'},boot:{errno:0,stdout:'11111111-1111-4111-8111-111111111111'}};
  global.MD='/mod';global.runBatch=async parts=>{batches.push(parts);return snapshot};
  const a=h.indexOf('let _asbStartupSnapshotRun = null;'),b=h.indexOf('let _asbDebugActionBusy',a);
  eval(h.slice(a,b)+';globalThis.startup=asbStartupSnapshot;');
  const s1=await startup(),s2=await startup();
  chk(s1===s2&&batches.length===1,'startup snapshot was not shared');
  chk(JSON.stringify(batches[0].map(p=>p[0]))===JSON.stringify(['profile','state','smart_pending','boot']),'startup batch parts changed');

  let rendered=null;global.renderSmartSubLine=kv=>{rendered=Object.assign({},kv)};
  eval(grab('async function refreshSmartSubLine(pre) {')+';globalThis.refresh=refreshSmartSubLine;');
  chk(await refresh(s1)===false&&rendered._smartPending===1,'startup Smart pending state was lost');
  chk(batches.length===1,'startup Smart subtitle started another shell');
  snapshot={state:{errno:0,stdout:'smart_mode=1'},smart_pending:{errno:0,stdout:'1'}};
  chk(await refresh()===true&&rendered.smart_mode==='1'&&!('_smartPending' in rendered),'active Smart was marked pending');
  chk(batches.length===2&&batches[1].length===2,'post-switch Smart read was not one batch');

  let cfg=0,zy=0,hidden=false;global._cfgOpen=false;global.cfgLoad=()=>{cfg++};global.zygiskHeaderRefresh=()=>{zy++};global.asbStartupLater=fn=>fn();
  global.document={hidden:false,getElementById:()=>null};global.window={};
  eval(grab('function asbStartupWarmCaches() {')+';globalThis.warm=asbStartupWarmCaches;');
  window._asbBootIntroProbe=Promise.resolve(false);warm();await flush();
  chk(cfg===1&&zy===1,'ordinary opening did not schedule one shared Config transaction and Zygisk');
  window._asbBootIntroProbe=Promise.resolve(true);warm();await flush();
  chk(cfg===1&&zy===1,'boot intro collectors were duplicated');
  document.hidden=true;window._asbBootIntroProbe=Promise.resolve(false);warm();await flush();
  chk(cfg===1&&zy===1,'hidden page performed speculative root work');
  document.hidden=false;window._asbBootIntroProbe=null;warm();
  chk(cfg===2&&zy===2,'missing probe did not retain bounded ordinary warm-up');

  const store={};let fetches=0,releaseFetch;
  global.localStorage={getItem:k=>store[k]||null,setItem:(k,v)=>store[k]=String(v)};
  global.prettyModel=()=> 'OnePlus 15';global.prettySoc=()=> 'Snapdragon';
  global.fetch=()=>{fetches++;return new Promise(r=>releaseFetch=r)};
  const hs=h.indexOf("const DEVICE_HEADER_CACHE_KEY = 'asb_device_header_cache'"),he=h.indexOf('function liveHeaderSync()',hs);
  eval(h.slice(hs,he)+';globalThis.loadHeader=loadDeviceInfo;');
  const hp1=loadHeader(),hp2=loadHeader();await flush();
  chk(fetches===1,'cold concurrent device loads started duplicate fetches');
  releaseFetch({ok:true,json:async()=>({model_code:'PLK110',name_code:'',soc_code:'SM8850'})});
  await Promise.all([hp1,hp2]);await loadHeader();
  chk(fetches===1&&store.asb_device_header_cache,'valid device cache was not reused');

  global._selectedProfile='stock';
  const starts=[],gates=[];
  global.pollStockTelemetry=v=>{starts.push(v);let resolve;const promise=new Promise(r=>resolve=r);gates.push({resolve});return promise;};
  global._liveOpen=true;global._stockTelemetryKv={};
  const decl=h.slice(h.indexOf('let _livePollRun = null,'),h.indexOf('/* Declared up here with the other page flags'));
  eval(decl+'\n'+grab('async function pollLive(visible, prefetch) {')+';globalThis.poll=pollLive;');
  const bg=poll(false),bgJoin=poll(false),vis=poll(true),visJoin=poll(true);
  chk(starts.length===1&&starts[0]===false,'background pass was duplicated');
  gates[0].resolve();await flush();await flush();
  chk(starts.length===2&&starts[1]===true,'visible page did not get its own fresh pass');
  gates[1].resolve();await Promise.all([bg,bgJoin,vis,visJoin]);
  const active=poll(true),activeJoin=poll(true),activeBg=poll(false);
  chk(starts.length===3,'visible/visible or visible/background overlap started a duplicate');
  gates[2].resolve();await Promise.all([active,activeJoin,activeBg]);
  document.hidden=true;await poll(true);chk(starts.length===3,'hidden page polled');
  document.hidden=false;const last=poll(true);chk(starts.length===4,'poll gate did not reset');
  gates[3].resolve();await last;
  console.log('ok');
})().catch(e=>{console.error(e&&e.stack||e);process.exit(1)});
JS
out="$(node "$T/test.js" "$H" 2>&1)" || { echo "FAIL WebUI fix325 runtime: $out" >&2; exit 1; }
[ "$out" = ok ] || { echo "FAIL WebUI fix325 runtime: $out" >&2; exit 1; }
echo "PASS WebUI fix325: shared profile/Smart/boot startup, deduplicated static-device fetch with valid-cache reuse, post-paint warm without intro duplicates, fresh-sample Stock reopen, meter reuse and visibility-safe Live collector sharing"
)

t_webui_snapshot_navigation_release11() (
# Splash snapshots make Device and Infinite Log immediately readable on navigation. Zygisk is
# deliberately different: every opening clears the old snapshot and makes one fresh bounded
# read; its Refresh button is gone and Save remains available only after a successful read.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL WebUI release11 snapshot navigation: $*" >&2; exit 1; }
python3 - "$ROOT" <<'PY' || fail 'source/localization contract'
import json,sys
from pathlib import Path
r=Path(sys.argv[1]); h=(r/'webroot/index.html').read_text(encoding='utf-8')
assert h.count('function deviceInfoSnapshot(')==1
assert 'function deviceInfoSnapshot(d) {' in h and 'function deviceInfoReusableSnapshot() {' in h
assert 'dev-stale' not in h, 'global snapshot dimming returned'
assert 'const ov = deviceInfoOverview(d), snapshot = deviceInfoSnapshot(d);' in h
for token in ('if (!deviceInfoPresentSnapshot()) asbDeviceInfoLoad();',
              'if (!logReportCachedPaint(logReportCacheGet(), false)) asbLogReportLoad();',
              'asbAfterNavAnim(function () { if (_zygiskOpen) zygiskPageLoad(false); }, 30);',
              'id="devRefresh" type="button" onclick="asbDeviceInfoLoad()"',
              'id="rpRefresh" type="button" onclick="asbLogReportLoad()"',
              'id="zySave" type="button" onclick="asbSavePage(\'zygisk\')"'):
 assert token in h,token
assert 'id="zyRefresh"' not in h and 'zygiskPageRender(window._asbZygiskLinkData || null);\n  const save' not in h
need=('dev_snapshot_status','lr_snapshot_status','zy_status_loading','zy_status_failed_empty','dev_sec_adios','dev_guide_adios',
      'dev_sec_asb_properties','dev_guide_asb_properties')
for p in (r/'webroot/i18n').glob('*.json'):
 d=json.loads(p.read_text(encoding='utf-8'))
 for k in need: assert isinstance(d.get(k),str) and d[k],(p.name,k)
 assert d['dev_snapshot_status'].count('%s')==1 and d['lr_snapshot_status'].count('%s')==1
PY
command -v node >/dev/null 2>&1 || { echo 'SKIP WebUI release11 snapshot navigation: no node'; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT HUP INT TERM
cat > "$T/t.js" <<'JS'
const fs=require('fs'),h=fs.readFileSync(process.argv[2],'utf8');
function grab(sig){const i=h.indexOf(sig);if(i<0)throw Error('missing '+sig);const j=h.indexOf('\n}\n',i);if(j<0)throw Error('unterminated '+sig);return h.slice(i,j+2)}
const chk=(c,m)=>{if(!c)throw Error(m)};
const nodes={};
function node(id){if(nodes[id])return nodes[id];const cls=new Set();const n=nodes[id]={id,textContent:'',disabled:false,dataset:{},children:[],scrollTop:0,classList:{add:(...x)=>x.forEach(c=>cls.add(c)),remove:(...x)=>x.forEach(c=>cls.delete(c)),toggle:(c,on)=>{if(on)cls.add(c);else cls.delete(c)},contains:c=>cls.has(c)},setAttribute(){},appendChild(c){this.children.push(c);return c}};return n}
global._el=node;global.window={};global.ASB_LANG='en';global.T=(k,d)=>d;global.uiSound=()=>{};
global.asbNavAnimMark=()=>{};global.asbTabbarVisibility=()=>{};global.asbNavSync=()=>{};global.asbFitPages=()=>{};global.zygiskHeaderRefreshLazy=()=>{};
global.asbUiFrame={request:f=>f()};global.requestAnimationFrame=f=>f();global.setTimeout=f=>{f();return 1};
global.document={body:node('body')};
for(const id of ['devicePage','deviceBody','deviceStatus','devSave','devRefresh','deviceLine','socBadge','verBadge','curProfile',
 'devDeviceLine','devSocBadge','devVerBadge','devCurProfile','reportPage','reportBody','reportStatus','rpDeviceLine','rpSocBadge','rpVerBadge','rpCurProfile',
 'zygiskPage','zygiskStatus','zySave','zyDeviceLine','zySocBadge','zyVerBadge','zyCurProfile'])node(id);
(async()=>{
 let persistent=null,deviceLoads=0,deviceRenders=0;
 global.deviceInfoCacheGet=()=>persistent;
 global.parseDeviceInfo=raw=>({count:String(raw).startsWith('D\t')?1:0,raw});
 global.deviceInfoRender=d=>{deviceRenders++;return d.count};
 global.deviceInfoStamp=()=> 'today';
 global.asbDeviceInfoLoad=async()=>{deviceLoads++};
 global._deviceOpen=false;global._zygiskOpen=false;
 eval(grab('function deviceInfoReusableSnapshot() {')+grab('function deviceInfoPresentSnapshot() {')+grab('function openDevicePage() {'));
 window._asbDeviceInfoData={count:1};window._asbDeviceInfoRaw='D\tsoc\tsoc_model\tSM8850';window._asbDeviceInfoAt=1000;
 openDevicePage();
 chk(deviceLoads===0&&deviceRenders===1,'Device recollected instead of painting its splash snapshot');
 chk(/Snapshot from today/.test(nodes.deviceStatus.textContent)&&!nodes.devSave.disabled,'Device snapshot status/save state wrong');
 global._deviceOpen=false;openDevicePage();chk(deviceLoads===0&&deviceRenders===2,'reopening Device repeated the collector');
 window._asbDeviceInfoData=null;window._asbDeviceInfoRaw='';persistent={t:2000,raw:'D\tsoc\tsoc_model\tSM8850'};global._deviceOpen=false;
 openDevicePage();chk(deviceLoads===0&&deviceRenders===3,'bounded persistent Device snapshot was not reused');
 chk(!nodes.deviceBody.classList.contains('dev-stale'),'persistent snapshot was dimmed instead of staying readable');
 window._asbDeviceInfoData=null;window._asbDeviceInfoRaw='';persistent=null;global._deviceOpen=false;
 openDevicePage();chk(deviceLoads===1,'Device without any snapshot did not run its one collector fallback');

 let reportCache=null,reportLoads=0,reportRenders=0;
 global.logReportCacheGet=()=>reportCache;global.parseLogReport=raw=>({ok:!!raw,raw});
 global.logReportRender=()=>{reportRenders++};global.asbLogReportLoad=async()=>{reportLoads++};global._rpOpen=false;
 eval(grab('function logReportCachedPaint(cache, refreshing) {')+grab('function openReportPage() {'));
 reportCache={t:3000,raw:'meta\telapsed_min=200'};openReportPage();
 chk(reportLoads===0&&reportRenders===1,'Infinite Log recollected instead of using the splash snapshot');
 chk(/Snapshot from today/.test(nodes.reportStatus.textContent)&&!/refreshing/.test(nodes.reportStatus.textContent),'Infinite Log snapshot was presented as a live refresh');
 global._rpOpen=false;openReportPage();chk(reportLoads===0,'Infinite Log duplicated a collector on reopening');
 reportCache=null;global._rpOpen=false;openReportPage();chk(reportLoads===1,'Infinite Log without a snapshot lacked collector fallback');

 let zyLoads=[],zyRenders=0;global._zygiskOpen=false;global._zygiskLoadSeq=0;
 global.zygiskPageRender=()=>{zyRenders++};global.zygiskPageLoad=async user=>{zyLoads.push(user)};global.asbAfterNavAnim=f=>f();
 eval(grab('function openZygiskPage() {'));
 window._asbZygiskLinkData={ok:true};openZygiskPage();
 chk(zyLoads.length===1&&zyLoads[0]===false&&zyRenders===1,'Zygisk opening did not start its mandatory fresh read');
 chk(window._asbZygiskLinkData===null&&nodes.zySave.disabled,'Zygisk opening retained stale data or Save');
