T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
cat > "$T/test.js" <<'JS'
const fs=require('fs'),h=fs.readFileSync(process.argv[2],'utf8');
const chk=(c,m)=>{if(!c)throw Error(m)};
function grab(sig,next){const a=h.indexOf(sig);if(a<0)throw Error('missing '+sig);const b=h.indexOf(next,a);if(b<0)throw Error('missing '+next);return h.slice(a,b);}
function E(tag){this.tag=tag;this.children=[];this.textContent='';this.className='';this.attrs={};this.style={};this.hidden=false;}
E.prototype.appendChild=function(x){this.children.push(x);return x};
E.prototype.setAttribute=function(k,v){this.attrs[k]=String(v)};
Object.defineProperty(E.prototype,'classList',{get(){return {add:(c)=>{this.className+=' '+c}}}});
(async()=>{
  const ids={};for(const id of ['deviceLine','liveDeviceLine','cfgDeviceLine','rpDeviceLine','devDeviceLine','zyDeviceLine','socBadge','liveSocBadge','cfgSocBadge','rpSocBadge','devSocBadge','zySocBadge'])ids[id]=new E('div');
  global.document={getElementById:id=>ids[id]||null};global.T=(k,f)=>f;
  let stored={'asb_device_header_cache':JSON.stringify({t:Date.now(),model:'OnePlus 15',soc:'Snapdragon 8 Elite Gen 5',chip:'SM8850'})};
  global.localStorage={getItem:k=>stored[k]||null,setItem:(k,v)=>{stored[k]=v}};
  let resolveFetch,fetches=0;global.fetch=()=>{fetches++;return new Promise(r=>{resolveFetch=r})};
  eval(grab('const MODEL_MAP','const DEVICE_HEADER_CACHE_KEY'));
  eval(grab('const DEVICE_HEADER_CACHE_KEY','function liveHeaderSync()')+';globalThis.loadHeader=loadDeviceInfo;');
  await loadHeader();
  chk(ids.deviceLine.textContent==='OnePlus 15 / Snapdragon 8 Elite Gen 5'&&ids.socBadge.textContent==='SM8850','valid cached device header did not paint synchronously');
  chk(ids.zyDeviceLine.textContent===ids.deviceLine.textContent&&ids.rpSocBadge.textContent==='SM8850','cached header did not reach every page');
  chk(fetches===0,'a valid static device cache started a redundant fetch');
  stored={};const loading=loadHeader();await new Promise(r=>setImmediate(r));
  chk(fetches===1&&typeof resolveFetch==='function','cold cache did not start the local JSON read');
  resolveFetch({ok:true,json:async()=>({model_code:'ONEPLUS_13',name_code:'',soc_code:'sm8650'})});await loading;
  chk(ids.deviceLine.textContent==='OnePlus 13 / Snapdragon 8 Gen 3'&&ids.socBadge.textContent==='SM8650','fresh local JSON did not replace the cached header: '+ids.deviceLine.textContent+' / '+ids.socBadge.textContent);
  const saved=JSON.parse(stored['asb_device_header_cache']);chk(saved.model==='OnePlus 13'&&saved.chip==='SM8650','fresh header cache was not saved');
  chk(!('raw' in saved)&&!('serial' in saved)&&!('imei' in saved),'header cache stored unrelated device data');

  const created=[];global.document={createElement:t=>{const e=new E(t);created.push(e);return e}};
  global.CFG_GROUPS=['iface','feel','net','camera','audio','battery','kernel','zygisk','ui'].map(id=>({id,icon:id,name:id}));
  global.CFG_ITEMS=CFG_GROUPS.map(g=>({key:g.id,def:'0'}));
  global.cfgGroupOf=k=>k;global._cfgVals={iface:'1'};global.cfgHubActiveCount=(id,items,extras)=>(Number(_cfgVals[id]||0)+extras.filter(Boolean).length);
  global.CFG_GROUP_DESC={audio:'DSP, volume, Bluetooth',camera:'Presets, processing, detail',iface:'Animations, blur',net:'Wi-Fi, LTE, queues',battery:'Smart, Doze, heat, RAM',kernel:'Scheduler, MGLRU, wakeups',feel:'LTPO, vibration, touch',zygisk:'Master switch and status',ui:'Services, processes, diagnostics'};
  global.grpName=g=>g.name;global.T=(k,f)=>f;global.techIcon=k=>'<svg data-kind="'+k+'"></svg>';
  global.uiSound=()=>{};global._cfgGroup='';global.cfgRender=()=>{};global.cfgLoadFresh=()=>{throw Error('hub totals must not wait for Config freshness')};global.requestAnimationFrame=()=>{};global.asbFitPages=()=>{};global.asbUiFrame={request:()=>{}};
  global.setTimeout=()=>0;global.asbStartupLater=()=>{};
  eval(grab('function cfgGroupHiddenKeys(groupId) {','// Settings whose effect lands in a file').replace(/^let /gm,'var ')+';globalThis.renderHub=cfgRenderHub;');
  const list=new E('div');renderHub(list);const hub=list.children[0];
  chk(hub.className==='cfg-hub'&&hub.children.length===9,'nine-category hub was not rendered');
  hub.children.forEach((tile,i)=>{
    chk(tile.tag==='button'&&tile.children.map(x=>x.className).join('|')==='cfg-tile-ico|cfg-tile-name|cfg-tile-desc|cfg-tile-foot','tile structure differs at '+i);
    const wantedCat=CFG_GROUPS[i].id==='ui'?'ux':CFG_GROUPS[i].id;
    chk(tile.className==='cfg-tile cat-'+wantedCat,'category hue alias differs at '+CFG_GROUPS[i].id+': '+tile.className);
    chk(tile.children[0].innerHTML.includes('data-kind="'+CFG_GROUPS[i].id+'"'),'icon is missing at '+i);
    chk(tile.attrs['aria-label'].includes(tile.children[2].textContent),'accessible label lacks the scope at '+i);
    const foot=tile.children[3], meter=foot.children[0];
    chk(foot.children.length===1 && meter.className==='cfg-tile-count','one progress meter required at '+i);
    const expected=1+(CFG_GROUPS[i].id==='camera'?2:['kernel','battery'].includes(CFG_GROUPS[i].id)?1:0);
    const changed=Number(_cfgVals[CFG_GROUPS[i].id]||0)+cfgGroupExtraCards(CFG_GROUPS[i].id).filter(Boolean).length;
    chk(meter.textContent===changed+' / '+expected,'count order or structural total differs at '+i+': '+meter.textContent);
    chk(meter.attrs.style==='--progress:'+Math.min(100,changed/expected*100)+'%','progress fill differs at '+i);
  });
  const totals=hub.children.map(tile=>tile.children[3].children[0].textContent.split(' / ')[1]);
  _cfgVals.iface='0';const staleList=new E('div');renderHub(staleList);
  const afterHub=staleList.children[0];
  chk(afterHub.children.every((tile,i)=>tile.children[3].children[0].textContent.split(' / ')[1]===totals[i]),'Config state changed structural totals');
  chk(hub.children[0].children[3].children[0].textContent !== afterHub.children[0].children[3].children[0].textContent,'changed count did not respond to config');
  console.log('ok');
})().catch(e=>{console.error(e&&e.stack||e);process.exit(1)});
JS
out="$(node "$T/test.js" "$H" 2>&1)" || { echo "FAIL WebUI fix328 runtime: $out" >&2; exit 1; }
[ "$out" = ok ] || { echo "FAIL WebUI fix328 runtime: $out" >&2; exit 1; }
echo "PASS WebUI fix328: neutral first Home frame, bounded header cache, pre-load warm-up and nine centred structural totals that never wait for Config, count active values or create bars"
)

t_webui_fix329_home_monitor_entrance() (
# Contract (fix329): Home enters with Monitor's short fade/scale only after local labels and
# the fixed-width ZYGISK control exist. Final geometry is measured before motion, pending
# values stay honest, and every category shares a centred visual axis.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL WebUI fix329 Home entrance/category axis: $*" >&2; exit 1; }
python3 - "$H" <<'PY' || fail 'source/ordering contract'
import sys
s=open(sys.argv[1],encoding='utf-8').read()
head=s[:s.index('<style>\n:root {')]
assert "document.documentElement.classList.add('asb-home-pending');" in head
assert 'html.asb-home-pending .page:not(.live-page) { opacity:0; pointer-events:none; }' in s
assert '--page-fade-in: 0.18s;' in s and '--page-fade-delay: 0.04s;' in s
home=s[s.index('(async () => {',s.index('function openTelegram')):s.index('function fmtTempC')]
assert home.index('loadDeviceInfo();') < home.index('await asbStartupSnapshot();')
assert home.index('await asbStartupSnapshot();') < home.index('await I18N_READY;')
reveal=s[s.index('let _asbHomeRevealed = false;'):s.index('// ── localized boot:')]
for token in ('function asbHomeReveal() {','asbNavAnimMark();','asbFitPagesNow();',
              "root.classList.remove('asb-home-pending');","transform:'scale(.985)'",
              "transform:'scale(1)'",'duration:180','delay:40',
              "easing:'cubic-bezier(.2,.7,.25,1)'",'window.addEventListener(\'load\', asbHomeReveal',
              'setTimeout(asbHomeReveal, 1600);'):
    assert token in reveal, token
assert reveal.index('asbFitPagesNow();') < reveal.index('home.animate(')
assert 'run(' not in reveal and 'runBatch(' not in reveal
boot=s[s.index('function boot() {',s.index('// ── localized boot:')):s.index('I18N_READY.then(boot);')]
assert boot.index('applyStaticI18n();') < boot.index('zygiskHeaderInit();') < boot.index('asbHomeReveal();')
assert 'asbHomeValueResolve(current);' in s and 'asbHomeValueResolve(smartSub);' in s
assert s.count('asb-value-pending') >= 8
for token in ('html .cfg-tile {\n  align-items:center;','text-align:center;',
              'html .cfg-tile-ico {\n  display:grid;\n  place-items:center;\n  align-self:center;',
              'html .cfg-tile-name {\n  width:100%;','html .cfg-tile-desc {\n  width:100%;',
              'var(--progress,0%)'):
    assert token in s, token
PY
command -v node >/dev/null 2>&1 || { echo 'SKIP WebUI fix329 runtime: no node'; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
cat > "$T/test.js" <<'JS'
const fs=require('fs'),h=fs.readFileSync(process.argv[2],'utf8');
const chk=(c,m)=>{if(!c)throw Error(m)};
function grab(a,b){const i=h.indexOf(a);if(i<0)throw Error('missing '+a);const j=h.indexOf(b,i);if(j<0)throw Error('missing '+b);return h.slice(i,j);}
const pending=new Set(['asb-value-pending']),attrs={};
const el={classList:{contains:c=>pending.has(c),remove:c=>pending.delete(c),add:c=>pending.add(c)},setAttribute:(k,v)=>attrs[k]=v};
eval(grab('function asbHomeValueResolve(el) {','let _selectedProfile'));
asbHomeValueResolve(el);
chk(!pending.has('asb-value-pending')&&pending.has('asb-value-arrived')&&attrs['aria-busy']==='false','resolved value did not leave its pending state');
const events=[];
const rootClasses=new Set(['asb-home-pending']);
const root={classList:{remove:c=>rootClasses.delete(c)}};
const home={style:{transition:''},offsetWidth:412,animate:(frames,options)=>{events.push('animate');chk(options.duration===180&&options.delay===40,'Monitor timing was not reused');chk(frames[0].transform==='scale(.985)'&&frames[1].transform==='scale(1)','fade/scale keyframes differ');return {cancel:()=>events.push('cancel'),set onfinish(fn){this.done=fn}}}};
global.document={documentElement:root,querySelector:s=>s==='.page:not(.live-page)'?home:null};
global.window={matchMedia:()=>({matches:false}),addEventListener:()=>{}};
global.setTimeout=()=>{};global.requestAnimationFrame=fn=>{events.push('raf');fn()};global.asbUiFrame={request:fn=>requestAnimationFrame(fn)};
global.asbNavAnimMark=()=>events.push('mark');global.asbFirstFrameMark=()=>{};
global.asbFitPagesNow=()=>{events.push('fit');chk(!rootClasses.has('asb-home-pending'),'fit ran before final layout state');chk(home.style.transition==='none','CSS transition conflicts with WAAPI fit')};
global.asbFitPages=()=>events.push('fit-queued');
eval(grab('let _asbHomeRevealed = false;','// ── localized boot:'));
asbHomeReveal();
chk(events.join('|')==='mark|fit|animate','unexpected reveal order: '+events.join('|'));
chk(home.style.transition===''&&!rootClasses.has('asb-home-pending'),'Home did not reach its interactive final state');
asbHomeReveal();chk(events.length===3,'reveal was not idempotent');
rootClasses.add('asb-home-pending');events.length=0;
window.matchMedia=()=>({matches:true});home.animate=()=>{throw Error('reduced motion animated')};
eval(grab('let _asbHomeRevealed = false;','// ── localized boot:').replaceAll('asbHomeReveal','asbHomeRevealReduced').replace('let _asbHomeRevealed','let _asbHomeRevealedReduced'));
asbHomeRevealReduced();
chk(events.join('|')==='raf|fit-queued'&&!rootClasses.has('asb-home-pending'),'reduced-motion fallback failed: '+events.join('|')+' pending='+rootClasses.has('asb-home-pending'));
console.log('ok');
JS
out="$(node "$T/test.js" "$H" 2>&1)" || { echo "FAIL WebUI fix329 runtime: $out" >&2; exit 1; }
[ "$out" = ok ] || { echo "FAIL WebUI fix329 runtime: $out" >&2; exit 1; }
echo "PASS WebUI fix329: Monitor-matched Home entrance, pre-motion final fit, honest pending values, reduced motion and centred category axis"
)

t_webui_fix323_glass_navigation_actions() (
# Contract (fix323): the full-height canvas is actually visible, drill-in navigation has
# one parent Glass material, and the three existing guarded restart actions share an
# accessible toolbar menu. No new command path, worker or second navigation router.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL WebUI fix323 Glass/navigation/actions: $*" >&2; exit 1; }
python3 - "$H" <<'PY' || fail 'source/layout/accessibility contract'
import re, sys
s = open(sys.argv[1], encoding='utf-8').read()
marker = '/* ── Device-visual corrections (fix323)'
assert s.count(marker) == 1
b = s[s.index(marker):s.index('/* WebViews without backdrop filtering', s.index(marker))]
# Fixed pages do not contribute to body height: the root, not that short body, owns canvas.
assert 'html:root[data-asb-glass="1"] { background:var(--glass-canvas-image); }' in b
assert 'html:root[data-asb-glass="1"] .page,\nhtml:root[data-asb-glass="1"] .live-page,\nhtml:root[data-asb-glass="1"] .config-page' in b and 'background:transparent !important' in b
# Dark/light Glass now own an explicitly solid canvas; no ambient layer may return.
assert '--glass-canvas-image:#000;' in s and '--glass-canvas-image:#edf4f1;' in s
assert 'radial-gradient(ellipse 120% 48% at 0% 0%,rgba(130,157,143,.28)' not in s
assert 'linear-gradient(180deg,#111713 0%,#050807 48%,#000 100%)' not in s
# Parent dock keeps the shared floating material; child buttons cannot become loose circles.
dock = re.search(r'html:root\[data-asb-glass="1"\] :is\(\.report-nav,\.zy-page-nav,\.dev-page-nav,\.cfg-page-nav\) \.lgr-jump-btn \{([^}]*)\}', b)
assert dock, 'dock rest-state override missing'
for token in ('background:transparent !important', 'border-color:transparent !important',
              'box-shadow:none !important', 'backdrop-filter:none'):
    assert token in dock.group(1), token
# The specific active check follows the generic chip and cannot be painted grey by it.
generic = s.index('html:root[data-asb-glass="1"] .lgr-chip,\nhtml:root[data-asb-glass="1"] .pmeta-chip,\nhtml:root[data-asb-glass="1"] .cfg-icon,\nhtml:root[data-asb-glass="1"] .pchk')
active = s.index('html:root[data-asb-glass="1"] .pbtn.on .pchk {', generic)
assert active > generic
check = re.search(r'html:root\[data-asb-glass="1"\] \.pbtn\.on \.pchk \{([^}]*)\}', b)
assert check and 'background:var(--c) !important' in check.group(1)
assert 'width:22px; height:22px' in check.group(1) and 'transform:none' in check.group(1)
# Exactly three circular tools; exactly three existing actions in the small menu.
tools = re.search(r'<div id="cfgToolsRow">([\s\S]*?)\n    </div>', s)
assert tools, 'tools row missing'
assert tools.group(1).count('class="cfg-lang-btn"') == 3
for token in ('id="cfgRebootMenuBtn"', 'aria-haspopup="menu"', 'aria-expanded="false"',
              'aria-controls="cfgRebootPop"', 'id="cfgRebootPop"', 'role="menu"'):
    assert token in tools.group(1), token
pop = re.search(r'<div class="cfg-lang-pop cfg-reboot-pop" id="cfgRebootPop"[\s\S]*?</div>', s)
assert pop and pop.group(0).count('role="menuitem"') == 3
for key in ('cfg_reboot_tile', 'cfg_soft_tile', 'cfg_sysui_tile'):
    assert key in pop.group(0), key
assert 'id="cfgRebootWrap"' not in s
assert 'class="cfg-reboot-tile' not in s
# Freed height goes to the existing fitter; the symmetric 3 × 3 grid never compacts the shared header.
fit = re.search(r'^function asbFitPagesNow\(\) \{[\s\S]*?^\}', s, re.M)
assert fit and 'cfgRebootWrap' not in fit.group(0) and 'rebH' not in fit.group(0)
assert 'Math.max([100, 88, 76][tier], Math.min(124, Math.floor(h)))' in fit.group(0)
assert 'grid-template-columns: repeat(3, 1fr)' in s
# Menu code delegates to the existing actions and owns no shell command or polling worker.
start = s.index('var _cfgRebootMenuDismissArmed')
end = s.index('/* Close an open dropdown when the next tap lands anywhere else.', start)
js = s[start:end]
assert "await cfgReboot();" in js and "await cfgSoftReboot();" in js and "await cfgRestartSysUI();" in js
assert 'run(' not in js and 'setInterval(' not in js and 'setTimeout(' not in js
# A body-portalled fixed popup sits above Config and uses zoom-corrected viewport geometry.
assert 'document.body.appendChild(initialPop)' in js
assert '.cfg-lang-pop.cfg-reboot-pop { min-width:220px; padding:6px; transform-origin:top right; z-index:1200; }' in s
for token in ("ev.key === 'Escape'", 'cfgRebootMenuClose(true)', "['ArrowDown','ArrowUp','Home','End']",
              "document.addEventListener('click'", "window.addEventListener('resize'",
              "pop.style.position = 'fixed'", "btn.setAttribute('aria-expanded', 'true')",
              'const z = window._asbUiScale || 1;',
              "pop.style.top = ((r.bottom + 8) / z) + 'px'",
              "pop.style.right = (Math.max(8, (window.innerWidth || 360) - r.right) / z) + 'px'",
              "pop.style.maxHeight = (Math.max(152, (window.innerHeight || 640) - r.bottom - 24) / z) + 'px'"):
    assert token in js, token
hard = re.search(r'^async function cfgReboot\(\) \{[\s\S]*?^\}', s, re.M).group(0)
soft = re.search(r'^async function cfgSoftReboot\(\) \{[\s\S]*?^\}', s, re.M).group(0)
assert 'now - _cfgRebootArmed > 4000' in hard and 'now - _cfgSoftArmed > 4000' in soft
assert "svc power reboot 2>/dev/null || reboot" in hard
assert "ASB_QUICK_RESTART) + ' status'" in soft and "ASB_QUICK_RESTART) + ' restart'" in soft
assert 'if (_cfgGroup) cfgRebootMenuClose(false);' in s
assert re.search(r'^function closeConfigPage\(toMain\) \{\n  cfgRebootMenuClose\(false\);', s, re.M)
PY
command -v node >/dev/null 2>&1 || { echo "SKIP WebUI fix323 menu runtime: no node"; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
cat > "$T/test.js" <<'JS'
const fs=require('fs'), h=fs.readFileSync(process.argv[2],'utf8');
function grab(name){const m=h.match(new RegExp('(?:async )?function '+name+'\\([^)]*\\) \\{[\\s\\S]*?\\n\\}'));if(!m)throw Error('missing '+name);return m[0];}
function E(id,cls){this.id=id||'';this.className=cls||'';this.hidden=true;this.attrs={};this.style={};this.children=[];this.textContent='';this.title='';this.label={textContent:id||''};const set=new Set((cls||'').split(/\s+/).filter(Boolean));this.classList={contains:c=>set.has(c),toggle:(c,v)=>{if(v)set.add(c);else set.delete(c)}};}
E.prototype.setAttribute=function(k,v){this.attrs[k]=String(v)};
E.prototype.querySelectorAll=function(){return this.children};
E.prototype.querySelector=function(){return this.label};
E.prototype.contains=function(x){return x===this||this.children.includes(x)};
E.prototype.focus=function(){document.activeElement=this};
E.prototype.getBoundingClientRect=function(){return{right:345,bottom:350}};
const pop=new E('cfgRebootPop','cfg-lang-pop cfg-reboot-pop');
for(const [kind,key] of [['hard','Reboot'],['soft','Soft reboot'],['sysui','Restart SystemUI']]){const b=new E('',kind);b.label.textContent=key;pop.children.push(b)}
const btn=new E('cfgRebootMenuBtn','cfg-lang-btn'),wrap=new E('cfgRebootMenuWrap');wrap.children=[btn,pop];
const lang=new E('cfgLangPop'),outside=new E('outside');
const els={cfgRebootPop:pop,cfgRebootMenuBtn:btn,cfgRebootMenuWrap:wrap,cfgLangPop:lang};
const listeners={keydown:[],click:[]};
global.document={activeElement:null,addEventListener:(k,f)=>listeners[k].push(f)};
global.window={innerWidth:360,innerHeight:800,_asbUiScale:.8,addEventListener:()=>{}};
global._el=id=>els[id]||null; global.T=(k,d)=>d; global.uiSound=()=>{}; global.toast=()=>{};
global.shQuote=s=>"'"+s+"'"; global.ASB_QUICK_RESTART='/mod/runtime/asb_quick_restart.sh';
const commands=[]; global.run=async c=>{commands.push(c);return{errno:0,stdout:'',stderr:''}};
const source=[
 'var _cfgRebootMenuDismissArmed=false; let _cfgRebootArmed=0; let _cfgSoftArmed=0;',
 ...['cfgReboot','cfgSoftReboot','cfgRestartSysUI','cfgRebootMenuItems','cfgRebootMenuPaint','cfgRebootMenuClose','cfgRebootMenuInit','cfgToggleRebootMenu','cfgRebootMenuKey','cfgRebootMenuAction'].map(grab)
].join('\n');
eval(source+`\n(async()=>{
 const ev=()=>({stopped:0,prevented:0,stopPropagation(){this.stopped++},preventDefault(){this.prevented++},key:''});
 cfgToggleRebootMenu(ev());
 if(pop.hidden||btn.attrs['aria-expanded']!=='true'||document.activeElement!==pop.children[0])throw Error('open/focus failed');
 if(pop.style.position!=='fixed'||pop.style.top!=='447.5px'||pop.style.right!=='18.75px'||pop.style.maxHeight!=='532.5px')throw Error('scale-corrected placement failed: '+JSON.stringify(pop.style));
 await cfgRebootMenuAction(ev(),'hard');
 if(commands.some(c=>c.includes('svc power reboot'))||pop.hidden||!pop.children[0].classList.contains('armed'))throw Error('full reboot first tap was not armed');
 await cfgRebootMenuAction(ev(),'hard');
 if(!commands.some(c=>c.includes('svc power reboot'))||!pop.hidden)throw Error('confirmed full reboot failed');
 cfgToggleRebootMenu(ev()); await cfgRebootMenuAction(ev(),'soft');
 if(commands.filter(c=>c.includes('asb_quick_restart.sh')).length!==1||pop.hidden||!pop.children[1].classList.contains('armed'))throw Error('quick restart first tap was not armed');
 await cfgRebootMenuAction(ev(),'soft');
 if(!commands.some(c=>c.includes("asb_quick_restart.sh' restart"))||!pop.hidden)throw Error('confirmed quick restart failed');
 cfgToggleRebootMenu(ev()); await cfgRebootMenuAction(ev(),'sysui');
 if(!commands.some(c=>c.includes('pkill -f com.android.systemui'))||!pop.hidden)throw Error('SystemUI delegation failed');
 cfgToggleRebootMenu(ev()); listeners.click[0]({target:outside});
 if(!pop.hidden)throw Error('outside dismissal failed');
 cfgToggleRebootMenu(ev()); let e=ev();e.key='ArrowDown';listeners.keydown[0](e);
 if(document.activeElement!==pop.children[1]||!e.prevented||!e.stopped)throw Error('ArrowDown failed');
 e=ev();e.key='End';listeners.keydown[0](e);if(document.activeElement!==pop.children[2])throw Error('End failed');
 e=ev();e.key='Escape';listeners.keydown[0](e);
 if(!pop.hidden||document.activeElement!==btn||btn.attrs['aria-expanded']!=='false'||!e.stopped)throw Error('Escape/focus return failed');
 cfgRebootMenuKey(Object.assign(ev(),{key:'ArrowDown'}));if(pop.hidden)throw Error('trigger ArrowDown failed');
 if(listeners.click.length!==1||listeners.keydown.length!==1)throw Error('listeners stacked');
 console.log('ok');
})().catch(e=>{console.error(e&&e.stack||e);process.exit(1)});`);
JS
out="$(node "$T/test.js" "$H" 2>&1)" || { echo "FAIL WebUI fix323 menu runtime: $out" >&2; exit 1; }
[ "$out" = ok ] || { echo "FAIL WebUI fix323 menu runtime: $out" >&2; exit 1; }
echo "PASS WebUI fix323: full-height canvas, unified drill-in Glass docks, accent profile check, larger hub tiles and guarded accessible restart menu"
)

t_webui_fix276_battery_evidence_runtime() (
# Runtime (fix276): navigation and evidence collection are separate; drain tiles name their
# own windows; the explicit wakelock manager renders only parsed user-app rows and risk state.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL WebUI fix276 battery evidence: $*" >&2; exit 1; }
command -v node >/dev/null 2>&1 || { echo "SKIP WebUI fix276 battery evidence: no node"; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
python3 - "$H" "$T" <<'PY' || fail 'source extraction'
import re, sys
from pathlib import Path
h = Path(sys.argv[1]).read_text(encoding='utf-8')
out = Path(sys.argv[2])
def fn(name):
    m = re.search(r'^function ' + re.escape(name) + r'\([^\n]*\) \{.*?^\}', h, re.M | re.S)
    assert m, name
    return m.group(0)
def const(name):
    m = re.search(r'^const ' + re.escape(name) + r' = .*?;$', h, re.M)
    assert m, name
    return m.group(0)
# Opening the page must not await the collector. fix325 invokes the loader immediately so its
# no-snapshot fallback starts the collector immediately; snapshot-first navigation has its own
# release11 runtime test, and the real collector remains behind asbPaintYield (fix287 test).
open_src = '\n'.join([
    "const timers = []; let loads = 0, sound = 0;",
    "function El(id) { this.id=id; this.textContent=id; this.scrollTop=9; this.attrs={}; this.classes=new Set();",
    "  this.classList={add:(...x)=>x.forEach(c=>this.classes.add(c)),remove:(...x)=>x.forEach(c=>this.classes.delete(c))}; }",
    "El.prototype.setAttribute=function(k,v){this.attrs[k]=v};",
    "const els={}; ['devicePage','devDeviceLine','deviceLine','devSocBadge','socBadge','devVerBadge','verBadge','devCurProfile','curProfile'].forEach(x=>els[x]=new El(x));",
    "const document={body:new El('body')}; let _deviceOpen=false; function asbNavAnimMark(){}",
    "function _el(id){return els[id]||null} function uiSound(){sound++} function asbTabbarVisibility(){}",
    "function asbNavSync(){} function asbFitPages(){} function requestAnimationFrame(){} const asbUiFrame={request:f=>f()};",
    "function setTimeout(f){timers.push(f)} function deviceInfoPresentSnapshot(){return false} function asbDeviceInfoLoad(){loads++}",
    fn('openDevicePage'),
    "openDevicePage();",
    "if (!_deviceOpen || !els.devicePage.classes.has('open') || els.devicePage.attrs['aria-hidden'] !== 'false') throw Error('page did not open synchronously');",
    "if (els.devicePage.scrollTop !== 0 || loads !== 1 || timers.length !== 1) throw Error('loading state was not started immediately');",
    "openDevicePage(); if (loads !== 1 || timers.length !== 1) throw Error('repeated open started another collector');",
    "console.log('ok');"
])
(out/'open.js').write_text(open_src)

paint_src = '\n'.join([
    "function T(k,d){return d} function _el(id){return els[id]||null}",
    "const els={}; ['bnDrain','bnDrainOff','bnDrainOnLabel','bnDrainOffLabel'].forEach(x=>els[x]={textContent:'',title:''});",
    const('_lvMeter'), const('_lvGovOff'), "const _lvDrain={}; let _selectedProfile='smart';",
    fn('lvDurDHM'), fn('lvOffFigure'), fn('lvPct'), fn('lvBootBasis'), fn('lvBootOnFigure'), fn('lvNightFresh'), fn('lvNightFigure'), fn('lvProfileNightFigure'), fn('lvProfileOnFigure'), fn('lvBootMature'),fn('lvOnFigure'),fn('lvOnKind'),fn('lvOnTip'), fn('lvPrimaryOffFigure'),
    "function asbMetricPaint(){} function lvEtaPaint(){} function liveDrainIsOpen(){return false}",
    fn('lvMeterPaint'),
    "_lvMeter.cur='smart';_lvMeter.p={battery:{on:330,onMin:88,off:126,offN:3,offS:30000,offLast:138,offLastS:18000,offLastAt:1,onLast:330,onLastS:5280,onLastAt:1}};",
    "lvMeterPaint('battery');",
    "if(els.bnDrain.textContent!=='2.3%/h'||els.bnDrainOff.textContent!=='1.38%/h') throw Error('wrong drain values '+JSON.stringify(els));",
    "if(els.bnDrainOnLabel.textContent!=='Screen on'||els.bnDrainOffLabel.textContent!=='Screen off') throw Error('short labels missing');",
    "if(!/Latest recorded screen-on drain/.test(els.bnDrain.title)||!/88 min/.test(els.bnDrain.title)) throw Error('profile tooltip missing');",
    "_lvMeter.p.battery.offLastS=0; lvMeterPaint('battery');",
    "if(els.bnDrainOff.textContent!=='1.26%/h'||els.bnDrainOffLabel.textContent!=='Screen off') throw Error('aggregate fallback mislabeled');",
    "console.log('ok');"
])
(out/'paint.js').write_text(paint_src)

wl_src = '\n'.join([
    "function T(k,d){return d} function E(){this.children=[];this.textContent='';this.className='';this.disabled=false;this.attrs={};}",
    "E.prototype.appendChild=function(x){this.children.push(x);return x};",
    "E.prototype.setAttribute=function(k,v){this.attrs[k]=String(v)};",
    "const document={createElement:function(){return new E()}};",
    const('_wlManual'), fn('wlManualArmed'), fn('wlManualParse'), fn('wlManualTime'), fn('wlManualState'), fn('wlManualRow'),
    "const d=wlManualParse('version=1\\nscan=ok\\nselected=1\\nrow|com.example.sync|3720|0|1|allow|1\\nrow|bad name|9|0|0|allow|0\\nrow|com.example.chat|25|1|0|ignore|0\\n');",
    "if(d.scan!=='ok'||d.selected!==1||d.rows.length!==2) throw Error('status parser accepted malformed data');",
    "const a=d.rows[0]; if(a.pkg!=='com.example.sync'||a.secs!==3720||!a.selected||!a.protected||a.held) throw Error('row fields wrong');",
    "const r=wlManualRow(a), text=JSON.stringify(r);",
    "if(!/is-selected/.test(r.className)||!/is-lapsed/.test(r.className)||!/Critical class/.test(text)) throw Error('selected critical row not explicit '+text);",
    "if(r.children[1].textContent!=='Restore'||r.children[1].disabled) throw Error('restore action unavailable');",
    "const ext=wlManualRow(d.rows[1]); if(!ext.children[1].disabled||ext.children[1].textContent!=='Block wakelocks') throw Error('external ignore can be adopted');",
    "if(wlManualState({selected:true,eff:'ignore'})!=='Blocked · read-back confirmed') throw Error('read-back state missing');",
    "const free={pkg:'com.example.free',secs:60,held:false,selected:false,eff:'allow',protected:false};",
    "let fr=wlManualRow(free); if(fr.children[1].textContent!=='Block wakelocks'||/is-armed/.test(fr.children[1].className)) throw Error('unarmed row must name package-wide blocking');",
    "_wlManual.armed='com.example.free'; _wlManual.armedAt=Date.now(); fr=wlManualRow(free);",
    "if(fr.children[1].textContent!=='Tap again to block'||!/is-armed/.test(fr.children[1].className)) throw Error('armed row must ask for a second tap');",
    "if(!/may stop or arrive late/.test(JSON.stringify(fr))) throw Error('armed row must show the risk in the page');",
    "if(fr.children[2].textContent!=='Services'||typeof fr.children[2].onclick!=='function') throw Error('individual service entry missing');",
    "if(wlManualArmed('com.example.other')) throw Error('arming leaked to another package');",
    "_wlManual.armedAt=Date.now()-6000; if(wlManualArmed('com.example.free')) throw Error('arming never expires');",
    "console.log('ok');"
])
(out/'wakelock.js').write_text(wl_src)
PY
for t in open paint wakelock; do
  out="$(node "$T/$t.js" 2>&1)" || fail "$t: $out"
  [ "$out" = ok ] || fail "$t: $out"
done
# The only mutation is an explicit package action. Scanning, page opening and loading stay
# read-only; the visible confirmation names both the risk and the original-mode restore.
grep -q "manual-status 2>/dev/null" "$H" || fail 'on-demand read-only scan missing'
grep -q "manual-set ' + shQuote(a.pkg)" "$H" || fail 'explicit package action missing'
grep -q "if (!a.selected && !wlManualArmed(a.pkg)) {" "$H" || fail 'in-page second-tap confirmation missing'
sed -n '/^async function wlManualSet(a) {/,/^}/p' "$H" | grep 'confirm(' >/dev/null && fail 'wakelock freeze still depends on browser confirm()'
grep -q "res === 'external_ignore'" "$H" || fail 'external ignore result is not explained'
grep -q "res === 'uninstalled'" "$H" || fail 'uninstalled entry result is not explained'
grep -q 'Original AppOps modes restored' "$H" || fail 'restore result is not honest'
grep -q "component-list ' + shQuote(pkg)" "$H" || fail 'on-demand Activity/Service list missing'
grep -q "component-set ' + shQuote(pkg)" "$H" || fail 'explicit component action missing'
grep -q 'App wakelock blocking' "$H" || fail 'package AppOps still uses freeze terminology'
grep -q 'not a process freezer' "$H" || fail 'component disabling semantics are not explicit'
echo "PASS WebUI fix276 battery evidence: immediate diagnostics, paint-yielded collection, explicit drain windows and reversible wakelock risk states"
)

t_webui_fix278_perf_runtime() (
# Runtime (fix278): fewer blocking root shells on navigation, and none on the tap itself.
# KernelSU-family bridges run ksu.exec synchronously on the WebView's JS thread and start a
# new root shell per call. The REAL batch helpers run in node against a real POSIX shell
# (exit code and output shape as the bridge returns them); the REAL fit scheduler is driven
# with fake frames and timers; the navigation entry points are checked for calls on the tap.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL webui fix278 perf: $*" >&2; exit 1; }
command -v node >/dev/null 2>&1 || { echo "SKIP webui fix278 perf: no node"; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
{
  cat <<'JS'
const cp = require('child_process');
function shQuote(v) { return "'" + String(v).replace(/'/g, "'\\''") + "'"; }
let calls = [];
async function run(cmd) {
  calls.push(cmd);
  let out = '', code = 0;
  try { out = cp.execFileSync('sh', ['-c', cmd], { encoding: 'utf8' }); } catch (e) { out = e.stdout || ''; code = e.status || 1; }
  return { errno: code, stdout: out.replace(/\n$/, ''), stderr: '' };
}
JS
  sed -n '/^const _ASB_PART = /p; /^function runBatchCmd(/,/^}/p; /^function runBatchSplit(/,/^}/p; /^const _asbBatchCache = /p; /^const _asbBatchPerf = /p; /^async function runBatch(/,/^}/p' "$H"
  cat <<'JS'
let bad = 0; const chk = (c, m) => { if (!c) { console.log('FAIL ' + m); bad++; } };
(async () => {
  const want = {
    nl: 'a\nb', nonl: 'x=1\ny=2', empty: '', blank: '\nlast', fails: 'partial', tricky: '@@asb-part:notours:x\nkept'
  };
  const b = await runBatch([
    ['nl', "printf 'a\\nb\\n'"], ['nonl', "printf 'x=1\\ny=2'"], ['empty', 'true'], ['blank', "printf '\\nlast\\n'"],
    ['tricky', "printf '@@asb-part:notours:x\\nkept\\n'"], ['fails', "printf 'partial\\n'; exit 3"], ['after', "printf 'never'"]]);
  chk(calls.length === 1, 'seven reads took ' + calls.length + ' shells');
  Object.keys(want).forEach(k => {
    if (k === 'fails') return;
    chk(b[k].errno === 0 && b[k].stdout === want[k], k + ': ' + JSON.stringify(b[k]));
  });
  /* `exit` ends the shell: that part and every later one report a failed read, never data. */
  chk(b.fails.errno === 1 && b.after.errno === 1 && b.after.stdout === '', 'a dead shell still produced parts: ' + JSON.stringify(b.fails) + JSON.stringify(b.after));
  calls = [];
  const c = await runBatch([['a', "printf 'one\\n'"], ['b', "printf 'two'"], ['c', 'cat /nonexistent']]);
  chk(c.a.stdout === 'one' && c.b.stdout === 'two' && c.c.stdout === '' && c.c.errno === 0, 'stderr or a missing file leaked: ' + JSON.stringify(c));
  if (bad) process.exit(1);
  console.log('ok');
})();
JS
} > "$T/batch.js"
out="$(node "$T/batch.js" 2>&1)" || fail "batch: $out"
[ "$out" = ok ] || fail "batch: $out"
{
  cat <<'JS'
let now = 0; const performance = { now: () => now };
let frames = [], timers = [], fits = 0;
function requestAnimationFrame(f) { frames.push(f); }
function setTimeout(f, ms) { timers.push({ f, at: now + ms }); }
function _pageAnimMs() { return 160; }
function asbFitPagesNow() { fits++; }
const asbUiFrame = { request(f) { if (!frames.includes(f)) frames.push(f); } };
JS
  sed -n '/^var _asbNavAnimUntil = 0,/p; /^function asbNavAnimMark(/,/^}/p; /^function asbAfterNavAnim(/,/^}/p; /^function asbFitPages(/,/^}/p' "$H"
  cat <<'JS'
let bad = 0; const chk = (c, m) => { if (!c) { console.log('FAIL ' + m); bad++; } };
const flush = () => { const f = frames; frames = []; f.forEach(x => x()); };
const tick = ms => { now += ms; const due = timers.filter(t => t.at <= now); timers = timers.filter(t => t.at > now); due.forEach(t => t.f()); };
asbFitPages(); asbFitPages(); asbFitPages();
chk(fits === 0 && frames.length === 1, 'three requests did not coalesce into one frame');
flush(); chk(fits === 1, 'the coalesced fit did not run');
asbNavAnimMark(); asbFitPages(); asbFitPages();
chk(frames.length === 0 && timers.length === 2, 'a fit during a page slide was not deferred');
tick(100); chk(fits === 1 && frames.length === 0, 'the fit ran inside the slide');
tick(200); flush(); chk(fits === 2, 'the deferred fit never ran after the slide');
let ran = 0; asbNavAnimMark(); asbAfterNavAnim(() => ran++, 30);
tick(200); chk(ran === 0, 'after-slide work ran early'); tick(100); chk(ran === 1, 'after-slide work never ran');
if (bad) process.exit(1); console.log('ok');
JS
} > "$T/fit.js"
out="$(node "$T/fit.js" 2>&1)" || fail "fit: $out"
[ "$out" = ok ] || fail "fit: $out"
python3 - "$H" <<'PY' || fail 'navigation still blocks on root shells'
import re, sys
h = open(sys.argv[1], encoding='utf-8').read()
def body(sig):
    i = h.index(sig); j = h.index('\n}\n', i); return h[i:j]
nav = body('function asbNavGo(target) {')
assert 'zygiskHeaderRefresh' not in nav and 'asbNavSyncSoon();' in nav and 'setTimeout(asbNavSync, 60)' not in nav, 'tab navigation still does unrelated probes or duplicate delayed syncs'
live = body('function openLivePage() {')
assert 'run(' not in live and 'zygiskHeaderRefresh' not in live, 'opening Monitor starts a root shell on the tap'
assert 'liveMonitorSchedule(liveOpenRefreshDelay());' in live, 'Monitor no longer schedules its read after the slide'
monitor_schedule = body('function liveMonitorSchedule(delay) {')
assert 'setTimeout(function () {' in monitor_schedule and 'pollLive(true)' in monitor_schedule, 'Monitor scheduler lost its deferred read'
cfg = body('function openConfigPage() {')
assert 'run(' not in cfg and 'zygiskHeaderRefresh' not in cfg and 'loadDeviceClass' not in cfg, 'opening Settings starts a root shell on the tap'
assert 'asbAfterNavAnim(function () { if (_cfgOpen) cfgLoad(); }, 16);' in cfg, 'Settings no longer refreshes after its shortened slide'
assert '_cfgHubSig === cfgHubSig()' in cfg, 'an unchanged hub is rebuilt before every slide'
load = body('async function cfgLoadNow() {')
assert load.count('runBatch(') == 1 and ' run(' not in load, 'Settings reads are not one batch'
assert 'if (!changed && _rebootBaselineReady)' in load, 'an unchanged refresh still repaints'
parts = body('function cfgLoadParts() {')
for k in ("['conf', 'cat ' + CFG_FILE]", "['ledger', CFG_LEDGER_CMD]", "['trials', CFG_TRIALS_CMD]", "['ltpo', ltpoStatusCmd()]",
          "['mmfeed', mmfeedStatusCmd()]", "['pkg', packageTweakStatusCmd()]", "['devclass',"):
    assert k in parts, 'Settings batch lost ' + k
assert 'const CFG_FRESH_MS = 30000;' in h and 'function cfgLoad(force) {' in h
assert h.count('await cfgLoad(true); cfgRender();') == 2, 'reset/import must force a fresh read'
poll = body('async function pollLive(visible, prefetch) {')
assert poll.count('runBatch(') == 1, 'Monitor poll is not one batch'
for old in ("await run('cat /dev/.asb/learner_state.json", "await run('/data/adb/modules/AutoSystemBoost/bin/asb status", "await run('cat /dev/.asb/recovery.json"):
    assert old not in poll.replace('_lb.learner || ' + old, ''), 'Monitor poll still reads separately: ' + old
pill = body('function zygiskHeaderInit() {')
assert 'btn.onclick = openZygiskPage;' in pill, 'the header pill does not open the Zygisk page'
zp = body('function openZygiskPage() {')
assert 'run(' not in zp and 'asbAfterNavAnim(function () { if (_zygiskOpen) zygiskPageLoad(false); }, 30);' in zp, 'the Zygisk page reads on the tap'
zl = body('async function zygiskPageLoad(user) {')
assert zl.count('runBatch(') == 1 and zl.replace('runBatch(', '').count('run(') == 0 and 'link-status' in zl and 'asb_zygisk_guard.sh' in zl and 'asb_zygisk_aot.sh' in zl and 'asb_device_info' not in zl, 'the Zygisk page runs more than its one read'
mode = body('async function zygiskModeSet(id) {')
assert mode.count('runBatch(') == 0 and ' run(' not in mode and "return zygiskAutoSet('enable', m.profile);" in mode, 'a unified mode does not delegate to the transactional automatic flow'
auto = body('async function zygiskAutoSet(action, profile) {')
assert auto.count('runBatch(') == 1 and ' run(' not in auto and "' auto-' + action" in auto, 'automatic mode change is not one locked batch'
page = h[h.index('id="zygiskPage"'):h.index('<div class="toast" id="toast">')]
for unrelated in ('cfgList', 'cfg-tile', 'ltpo', 'haptic_strength', 'deviceBody'):
    assert unrelated not in page, 'the Zygisk page carries unrelated content: ' + unrelated
assert "if (_zygiskOpen) d++;" in h and "if (_zygiskOpen) { uiSound('nav'); closeZygiskPage(); return; }" in h
assert "'ASB_DEVINFO_LSPOSED=0 sh ' + MD + '/tools/asb_device_info.sh 2>/dev/null'" in h, 'Device page still waits for the hook collector'
PY
echo "PASS webui fix278 perf: one shell per screen read (batch shape checked on a real shell), no root call on the tap, fits coalesced past the slide, an isolated Zygisk page with one delegated transactional mode write"
)

t_logkit_jank_why_runtime() (
# Runtime (fix288): why the late frames were late. LIGHT_IDLE on an OP15 Battery capture read
# 44 % janky; its intervals were one app streaming text untouched and SystemUI's per-second
# redraw, and nothing in the capture could say whether the GPU ceiling (160 MHz there) or the
# app held those frames. The REAL collector runs over graphicsstats dumps with frame and GPU
# histograms: per interval it writes the app with the most janky frames and SystemUI with
# their slow-UI / slow-draw counts and the interval's own frame and GPU percentiles (bucket
# deltas), GPU frames over 8/16 ms, and the GPU ceiling level with its MHz. An app idle for an
# interval keeps no histogram ("?", so the per-poll file stays small) and gets "-" times on its
# next row; a pruned day writes no row; the report and the digest name the cause.
set -u
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
C="$ROOT/tools/logkit/_asb_logkit_common.sh"
DG="$ROOT/tools/logkit/asb_fullday_digest.sh"
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
fail=0; f() { echo "FAIL jank why: $*" >&2; fail=1; }
mkdir -p "$T/out" "$T/cpufreq/policy0" "$T/cpufreq/policy6" "$T/kgsl"
echo 1555200 > "$T/cpufreq/policy0/scaling_max_freq"; echo 1555200 > "$T/cpufreq/policy0/scaling_cur_freq"
echo 1862400 > "$T/cpufreq/policy6/scaling_max_freq"; echo 768000 > "$T/cpufreq/policy6/scaling_cur_freq"
echo 17 > "$T/kgsl/max_pwrlevel"
echo "1200000000 1100000000 1000000000 900000000 850000000 800000000 750000000 700000000 650000000 600000000 550000000 500000000 450000000 400000000 350000000 300000000 222000000 160000000" > "$T/kgsl/gpu_available_frequencies"
g() {   # $1 file, sysui: $2 frames $3 janky $4 slow UI $5 5ms bucket $6 20ms bucket, app: $7 frames $8 janky $9 slow draw ${10} ${11} ${12} buckets
  cat > "$1" <<GFX

Package: com.android.systemui
Version: 36
Stats since: 1000ns
Stats end: 2000ns
Total frames rendered: $2
Janky frames: $3 (1.00%)
Janky frames (legacy): 999 (9.99%)
50th percentile: 5ms
Number Missed Vsync: 0
Number High input latency: 1
Number Slow UI thread: $4
Number Slow bitmap uploads: 0
Number Slow issue draw commands: 0
Number Frame deadline missed: $3
HISTOGRAM: 5ms=$5 6ms=2 20ms=$6
50th gpu percentile: 1ms
GPU HISTOGRAM: 1ms=$5 2ms=$6
Package: com.anthropic.claude
Version: 1
Stats since: 1000ns
Stats end: 2000ns
Total frames rendered: $7
Janky frames: $8 (2.00%)
Number Missed Vsync: 0
Number High input latency: 0
Number Slow UI thread: 3
Number Slow bitmap uploads: 0
Number Slow issue draw commands: $9
Number Frame deadline missed: $8
HISTOGRAM: 5ms=${10} 12ms=${11} 34ms=${12}
GPU HISTOGRAM: 3ms=${10} 5ms=${11} 16ms=${12}
GFX
}
g "$T/g1" 1000 10 5 990 10 5000 50 2 4000 950 50
g "$T/g2" 1060 62 57 1043 17 6600 950 12 4600 1650 350
g "$T/g3" 1110 110 105 1090 20 6600 950 12 4600 1650 350
g "$T/g4" 1160 160 155 1137 23 7000 1000 14 4800 1700 500
g "$T/g5" 1210 210 205 1184 26 100 10 0 90 10 0
printf 'state=LIGHT_IDLE\ntouch_starts=10\n' > "$T/st"
out="$(LK_OUT_DIR="$T/out" ASB_LK_CPUFREQ_ROOT="$T/cpufreq" ASB_LK_KGSL="$T/kgsl" ASB_LK_STATE_FILE="$T/st" sh -c '
  . "$0" >/dev/null 2>&1
  T="$1"
  lk_jank_trace_header
  for n in 1 2 3; do ASB_LK_GFXSTATS_DUMP="$T/g$n" lk_capture_jank_row active 1; done
  echo "--- x3"; cat "$LK_OUT_DIR/.jank_pkgx_prev"
  for n in 4 5; do ASB_LK_GFXSTATS_DUMP="$T/g$n" lk_capture_jank_row active 1; done
  echo "--- detail"; grep -v "^#" "$LK_OUT_DIR/jank_detail.tsv"
  echo "--- why"; lk_emit_jank_why
  ASB_LK_GFXSTATS_DUMP="$T/g5" lk_capture_jank_row idle 0
  [ -e "$LK_OUT_DIR/.jank_pkgx_prev" ] && echo "x kept over screen off"
  echo "--- end"
' "$C" "$T" 2>&1)"
det="$(printf '%s\n' "$out" | sed -n '/^--- detail/,/^--- why/p' | grep '|')"
a2="$(printf '%s\n' "$det" | grep '|com.anthropic.claude|' | head -1)"
[ "$(printf '%s' "$a2" | cut -d'|' -f2-20)" = "LIGHT_IDLE|com.anthropic.claude|1600|900|0|10|0|900|12|34|34|5|16|16|1600|300|300|17|160" ] \
  || f "the streaming app's interval: counters, percentiles, GPU over 8/16 ms, ceiling: $a2"
s2="$(printf '%s\n' "$det" | grep '|com.android.systemui|' | head -1)"
[ "$(printf '%s' "$s2" | cut -d'|' -f4-18)" = "60|52|52|0|0|52|5|20|20|1|2|2|60|0|0" ] || f "SystemUI's interval: $s2"
[ "$(printf '%s\n' "$det" | grep -c '|com.anthropic.claude|')" = 2 ] || f "an idle interval or a pruned day wrote an app row: $det"
[ "$(printf '%s\n' "$det" | grep -c '|com.android.systemui|')" = 3 ] || f "SystemUI rows (none for the pruned day): $det"
a4="$(printf '%s\n' "$det" | grep '|com.anthropic.claude|' | sed -n 2p)"
[ "$(printf '%s' "$a4" | cut -d'|' -f4-20)" = "400|50|0|2|0|50|-|-|-|-|-|-|0|-|-|17|160" ] || f "an app back from an idle interval has counters but no times: $a4"
printf '%s\n' "$out" | sed -n '/^--- x3/,/^--- detail/p' | grep -x 'com.anthropic.claude|6600|950|3|0|12|950|?|?' >/dev/null || f "an idle app kept its histograms in the per-poll file: $out"
printf '%s\n' "$out" | sed -n '/^--- x3/,/^--- detail/p' | grep '^com.android.systemui|1110|110|105|0|0|110|5:1090,6:2,20:20|1:1090,2:20$' >/dev/null || f "SystemUI's histograms are not kept: $out"
why="$(printf '%s\n' "$out" | sed -n '/^--- why/,/^--- end/p')"
printf '%s\n' "$why" | grep '^why frames were late' >/dev/null || f "no summary: $why"
printf '%s\n' "$why" | grep -E '^  com.anthropic.claude +LIGHT_IDLE +2000 +48% \| +0% +1% +32% +32% \| +16 ms +34 ms  17 \(160 MHz\)$' >/dev/null || f "summary row: $why"
printf '%s\n' "$why" | grep 'com.anthropic.claude in LIGHT_IDLE: neither the GPU nor the UI thread' >/dev/null || f "pacing verdict: $why"
printf '%s\n' "$why" | grep 'com.android.systemui in LIGHT_IDLE: its UI thread was slow' >/dev/null || f "SystemUI verdict: $why"
printf '%s\n' "$out" | grep 'x kept over screen off' >/dev/null && f "the per-package histograms survived a screen-off stretch"
# The digest's jwhy rows from the same file; a resumed older capture has no detail file.
touch "$T/out/_full_day_report.txt"
dg="$(sh "$DG" "$T/out" 2>/dev/null | grep '^jwhy')"
printf '%s\n' "$dg" | grep -q "^jwhy	pkg=com.anthropic.claude	state=LIGHT_IDLE	frames=2000	janky=950	ui=0	draw=12	gn=1600	g8=300	g16=300	gp90=16	fp90=34	lvl=17	mhz=160	cause=other$" || f "digest app row: $dg"
printf '%s\n' "$dg" | grep -q "^jwhy	pkg=com.android.systemui	state=LIGHT_IDLE	frames=160	janky=150	ui=150	.*cause=ui$" || f "digest SystemUI row: $dg"
mkdir -p "$T/old"
LK_OUT_DIR="$T/old" ASB_LK_CPUFREQ_ROOT="$T/cpufreq" ASB_LK_STATE_FILE="$T/st" sh -c '
  . "$0" >/dev/null 2>&1
  : > "$LK_OUT_DIR/jank_trace.tsv"
  for n in 1 2; do ASB_LK_GFXSTATS_DUMP="$1/g$n" lk_capture_jank_row active 1; done' "$C" "$T" 2>/dev/null
[ -e "$T/old/jank_detail.tsv" ] && f "a capture started by an older recorder grew a detail file"
grep -q '^    lk_emit_jank_why$' "$ROOT/tools/logkit/asb_log_full_day.sh" || f "the final report does not print the breakdown"
[ "$fail" = 0 ] && echo "PASS logkit jank why: per-interval frame and GPU times of the top janky app and SystemUI, causes in the report and the digest, small per-poll file"
exit "$fail"
)

t_webui_fix289_zygisk_pulse() (
# fix289: the green Zygisk dot breathes. The header pill's dot and the link card's dot pulse
# slowly in the green states only (connected, confirmed, quiet), with opacity and scale (no
# repainted property), and reduced motion stops them.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
python3 - "$ROOT/webroot/index.html" <<'PY'
import re, sys
h = open(sys.argv[1], encoding='utf-8').read()
hc = re.sub(r'/\*.*?\*/', '', h, flags=re.S)
def rule(sel):
    for m in re.finditer(r'([^{}]+)\{([^{}]*)\}', hc):
        sels = [x.strip() for x in m.group(1).split(',')]
        if sel in sels: return m.group(2)
    return None
for st in ('connected', 'confirmed', 'quiet'):
    for dot, wrap in (('zygisk-header-dot', 'zygisk-header-'), ('dev-zygisk-link-dot', 'dev-zygisk-link-')):
        r = rule('.%s%s .%s' % (wrap, st, dot))
        assert r and re.search(r'animation:\s*zyLivePulse\s+3\.6s\s+ease-in-out\s+infinite', r), 'no slow pulse: %s %s' % (dot, st)
        a = rule('.%s%s .%s::after' % (wrap, st, dot))
        assert a and 'zyLiveRing 3.6s' in a, 'no ring: %s %s' % (dot, st)
for st in ('waiting', 'stale', 'safe', 'unknown'):
    assert not re.search(r'\.zygisk-header-%s \.zygisk-header-dot[^{]*\{[^}]*animation' % st, h), 'a non-green state pulses: ' + st
    assert not re.search(r'\.dev-zygisk-link-%s \.dev-zygisk-link-dot[^{]*\{[^}]*animation' % st, h), 'a non-green card pulses: ' + st
for k in ('zyLivePulse', 'zyLiveRing'):
    m = re.search(r'@keyframes %s \{(.*?)\n\}' % k, h, re.S)
    assert m, 'keyframes missing: ' + k
    props = set(re.findall(r'([a-z-]+)\s*:', m.group(1)))
    assert props <= {'opacity', 'transform'}, 'the pulse animates a repainted property: %s %s' % (k, props)
assert re.search(r'@media \(prefers-reduced-motion: reduce\) \{\s*\.zygisk-header-dot, \.zygisk-header-dot::after, \.dev-zygisk-link-dot, \.dev-zygisk-link-dot::after \{ animation: none !important; \}', h), 'reduced motion does not stop the pulse'
PY
echo "PASS webui fix289 zygisk pulse: the green link dots breathe slowly (opacity and scale only), other states stay still, reduced motion stops them"
)

t_webui_smart_brain_header_label_runtime() (
# Smart has one reusable top-down processor-brain at every registry-driven location. The custom
# vector ZYGISK wordmark is created by the same idempotent six-header builder and collapses at c2.
# The dedicated page's section/action icons use the same registry without changing their controls.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
cat > "$T/visual.js" <<'JS'
const fs = require('fs');
const h = fs.readFileSync(process.argv[2], 'utf8');
const icons = h.match(/(const TECH_ICON_PATHS = \{[\s\S]*?\n\};)\n(function techIcon\(kind\) \{[\s\S]*?\n\})/);
if (!icons) throw new Error('the inline SVG registry or renderer is missing');
eval(icons[1] + '\n' + icons[2]);
const brain = techIcon('smart');
if ((brain.match(/<path /g) || []).length !== 6 || (brain.match(/<rect /g) || []).length !== 1 || (brain.match(/<circle /g) || []).length !== 4) throw new Error('the top-down brain lost its hemispheres, processor or four terminals');
for (const token of ['viewBox="0 0 24 24"', 'stroke="currentColor"', '<g stroke-width="1.35">', 'M10.9 8.2V6.2', 'M13.1 8.2V6.2', '<rect x="8.2" y="8.2" width="7.6" height="7.6"', 'cx="22.4" cy="14.5"']) {
  if (!brain.includes(token)) throw new Error('Smart processor-brain geometry/paint missing: ' + token);
}
if (h.includes('M12 8.2l1.05 2.75L15.8 12') || h.includes('M12 5.1C11.4 3.8') || h.includes('M10.4 18.1C9.4 17.6')) throw new Error('an old Smart chip, emblem or side-view brain is still present');
if (!h.includes('data-tech-icon="smart"') || !h.includes("{ id:'smart', icon:'smart'")) throw new Error('a Smart icon consumer left the shared registry');
if (!h.includes('.zygisk-header-wordmark { display: block; width: 42px; height: 8px; overflow: visible; }')) throw new Error('the compact custom vector wordmark styling is missing');
if (!h.includes('html.asb-fit-c2 .zygisk-header-label { display: none; }')) throw new Error('the compact header no longer hides its label');
const wordmarkFn = h.match(/function zygiskHeaderWordmark\(\) \{[\s\S]*?\n\}/);
if (!wordmarkFn) throw new Error('the local ZYGISK vector wordmark is missing');
eval(wordmarkFn[0]);
const wordmark = zygiskHeaderWordmark();
if ((wordmark.match(/<path /g) || []).length !== 6 || !wordmark.includes('viewBox="0 0 68 10"') || !wordmark.includes('>ZYGISK</span>')) throw new Error('the six-letter angular wordmark regressed');
function openZygiskPage() {}
function zygiskHeaderPaint() {}
function zygiskHeaderCacheLoad() { return false; }
function el(tag, cls) {
  const node = { tag, className: cls || '', textContent: '', innerHTML: '', children: [], attrs: {}, firstChild: null,
    setAttribute(k, v) { this.attrs[k] = v; },
    appendChild(c) { this.children.push(c); this.firstChild = this.children[0] || null; return c; },
    insertBefore(c, before) { const at = before ? this.children.indexOf(before) : 0; this.children.splice(at < 0 ? 0 : at, 0, c); this.firstChild = this.children[0] || null; return c; },
    querySelector(sel) { return this.children.find(c => sel === '.zygisk-header-link' && c.className.includes('zygisk-header-link')) || null; }
  };
  const classes = new Set(String(node.className).split(/\s+/).filter(Boolean));
  node.classList = { add(c) { classes.add(c); node.className = Array.from(classes).join(' '); } };
  return node;
}
const hosts = [el('div', 'hdr-info'), el('div', 'hdr-info'), el('div', 'hdr-info')];
global.document = { createElement(tag) { return el(tag); }, querySelectorAll(sel) { return sel === '.hdr-info' ? hosts : []; } };
const init = h.match(/function zygiskHeaderInit\(\) \{[\s\S]*?\n\}/);
if (!init) throw new Error('the shared Zygisk header builder is missing');
eval(init[0]);
zygiskHeaderInit(); zygiskHeaderInit();
for (const host of hosts) {
  if (host.children.length !== 1) throw new Error('the header builder duplicated its button');
  const btn = host.children[0], label = btn.children[1];
  if (btn.onclick !== openZygiskPage || label.innerHTML !== wordmark) throw new Error('the vector wordmark or existing navigation regressed');
}
for (const fn of ['logReportSec', 'zygiskButtonIcon']) {
  const src = h.match(new RegExp('function ' + fn + '\\([^)]*\\) \\{[\\s\\S]*?\\n\\}'));
  if (!src) throw new Error('missing Zygisk icon helper: ' + fn);
  eval(src[0]);
}
const sec = logReportSec('Connection', 'zygisk_observer');
if (sec.attrs['data-zygisk-icon'] !== 'zygisk_observer' || sec.children[0].children.length !== 2 || !sec.children[0].children[0].innerHTML.includes('<svg') || sec.children[0].children[1].textContent !== 'Connection') throw new Error('a Zygisk section icon replaced or duplicated its title');
const action = el('button'); action.textContent = 'Set up automatically'; zygiskButtonIcon(action, 'zygisk_auto');
if (action.children.length !== 1 || !action.children[0].innerHTML.includes('<svg') || action.textContent !== 'Set up automatically' || !action.className.includes('zy-icon-btn')) throw new Error('a Zygisk action icon changed its existing button label');
console.log('ok');
JS
out="$(node "$T/visual.js" "$ROOT/webroot/index.html" 2>&1)" || { echo "FAIL Smart brain/header: $out" >&2; exit 1; }
[ "$out" = ok ] || { echo "FAIL Smart brain/header: $out" >&2; exit 1; }
echo "PASS webui Smart brain/header: one top-down processor-brain at both consumers, six-letter vector ZYGISK wordmark, themed page icons, idempotent navigation and compact hiding"
)


t_fix309_evidence_presentation_contract() (
# fix309: field captures exposed four report/presentation contradictions. Successful direct and
# shell-applied cap readbacks are successes; refused Android settings survive a zero live-FAIL
# verdict; held multicast time is not an energy measurement; temperature and brightness are
# context rather than app attribution. The fixed-page status scrim sits above every page and
# below navigation/modals, and the ART candidate count has an explicit whole-list scope note.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
python3 - "$ROOT" <<'PY'
import json, re, sys
from pathlib import Path
r=Path(sys.argv[1]); h=(r/'webroot/index.html').read_text(); d=(r/'tools/asb_diag.sh').read_text()
assert h.count('class="status-bar-scrim"')==1 and 'aria-hidden="true"' in h
m=re.search(r'\.status-bar-scrim \{([^}]*)\}',h); assert m
css=m.group(1)
for token in ('position: fixed','height: var(--status-scrim-top)','z-index: 150','pointer-events: none','background: var(--bg)'):
    assert token in css, token
assert '--status-scrim-top: max(28px, var(--window-inset-top))' in h
assert '.zygisk-page .lgr-row:not(.lgr-row-long) .lgr-v' in h
assert "T('zy_aot_list_scope'" in h
assert 'REFUSED=$_ux_refused' in d and '_ux_refused=0' in d
assert 'past cost cannot be inferred from held time alone' in d
assert 'held lock costs nothing' not in d
assert '_sb_t_txt="not learned"' in d and '_tw_txt="not learned"' in d
assert 'thresholds in force: warm above ${_tw:-?}' not in d
assert '-> ok( |$)' in (r/'tools/logkit/asb_fullday_digest.sh').read_text()
assert '(DESYNC_)?shell_overridden_(up|down)' in (r/'tools/logkit/asb_fullday_digest.sh').read_text()
old={
'lr_brief_night_hot':'With the screen off the CPU reached {cpu}° at times - something did heavy work in the background.',
'lr_dx_bgheat':'With the screen off the CPU reached {cpu}° at times - something did heavy work in the background (media downloads, a backup, app updates).',
'lr_dx_screen_bright_low':'Average brightness {b}% - the panel is not what costs here.'}
files=sorted((r/'webroot/i18n').glob('*.json')); assert len(files)==13
for p in files:
    x=json.loads(p.read_text())
    assert x.get('zy_aot_list_scope'), p
    for k,v in old.items(): assert x[k]!=v, (p,k)
    assert '{cpu}' in x['lr_brief_night_hot'] and '{cpu}' in x['lr_dx_bgheat'] and '{b}' in x['lr_dx_screen_bright_low']
    for ph in ('{ok}','{total}','{vendor}','{other}'): assert ph in x['lr_impact_cap_readback_fmt'], (p,ph)
en=json.loads((r/'webroot/i18n/en.json').read_text())
assert 'Temperature alone does not identify' in en['lr_brief_night_hot']
assert 'not proof of heavy background work' in en['lr_dx_bgheat']
assert 'Brightness alone does not establish' in en['lr_dx_screen_bright_low']
assert 'external overrides' in en['lr_impact_cap_readback_fmt']
# Every action locale carries the same non-zero-cost semantics; English and Russian are exact.
a=(r/'action.sh').read_text(); ru=(r/'runtime/i18n/action_ru.sh').read_text()
assert 'current radio cost is not shown, and past cost cannot be inferred from held time alone' in a
assert 'текущий расход радиомодуля здесь не показан' in ru and 'прошлый расход нельзя определить' in ru
assert len(list((r/'runtime/i18n').glob('action_*.sh')))==12
PY
# Execute the real extracted thermal presentation snippets, not just their source text.
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
awk '/^case "\$\{_sb_t:-\}"/ { on=1 } on { print } on && /^NOTE "bucket avg temp/ { exit }' "$ROOT/tools/asb_diag.sh" > "$T/bucket.sh"
awk '/^case "\$\{_tw:-\}"/ { on=1 } on { print } on && /^# These two drive/ { exit }' "$ROOT/tools/asb_diag.sh" > "$T/thermal.sh"
cat > "$T/run.sh" <<'SH'
NOTE() { printf '%s\n' "$1"; }
_sb_t="$1"; _sb_d="$2"; _tw="$3"; _tc="$4"
. "$5/bucket.sh"
. "$5/thermal.sh"
SH
zero="$(sh "$T/run.sh" 0 0 0 0 "$T")"
printf '%s\n' "$zero" | grep 'bucket avg temp = not learned.*avg drain = not learned' >/dev/null
printf '%s\n' "$zero" | grep 'thermal thresholds (tenths C): warm above not learned, cool below not learned' >/dev/null
printf '%s\n' "$zero" | grep 'thresholds in force' >/dev/null && { echo 'zero thermal state presented as active thresholds' >&2; exit 1; }
valid="$(sh "$T/run.sh" 503 7 539 381 "$T")"
printf '%s\n' "$valid" | grep 'bucket avg temp = 503.*avg drain = 7' >/dev/null
printf '%s\n' "$valid" | grep 'thresholds in force: warm above 539, cool below 381' >/dev/null
cmp -s "$ROOT/tools/asb_diag.sh" "$ROOT/system/bin/asbdiag"
echo "PASS fix309 evidence/presentation: cap success forms, REFUSED verdict, multicast/thermal honesty, scoped ART list, 13 locales and status-bar layering"
)

t_fix311_drill_in_presentation_contract() (
# fix311: the report and ZYGISK drill-ins expose their information hierarchy without changing
# evidence or controls. Exercise the REAL page renderer for loading/off/populated states and
# every jump target; keep long evidence collapsed while approvals and active restrictions stay
# visible. Bottom docks own their horizontal scrolling, expose the active section and keep 44 px touch targets.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
python3 - "$ROOT" <<'PY'
import json, re, sys
from pathlib import Path
r=Path(sys.argv[1]); h=(r/'webroot/index.html').read_text()
def body(sig):
    i=h.index(sig); return h[i:h.index('\n}\n',i)]
for token in ('.report-nav, .zy-page-nav, .dev-page-nav, .cfg-page-nav { display: none; position: fixed; left: 12px; right: 12px;',
              'bottom: calc(env(safe-area-inset-bottom, 0px) + 10px);', 'overflow-x: auto;',
              'scrollbar-width: none;', 'flex:1 1 0; width:auto; min-width:82px; max-width:none; min-height:60px; padding:4px 6px;',
              "b.setAttribute('aria-current', 'location')", "page.addEventListener('scroll', onScroll, { passive: true })",
              'padding-bottom: calc(102px / var(--asb-ui-scale) + env(safe-area-inset-bottom, 0px));',
              'if (prevScroll > 0) el.scrollTop = prevScroll;',
              'background: var(--cap-wash), var(--tabbar-bg, #000000);',
              'background: var(--pill-wash);', 'box-shadow: var(--pill-edge);',
              'html[data-asb-theme="light"] .cfg-page-nav,\nhtml[data-asb-theme="light"] .asb-tabbar {',
              "head.className = 'lgr-jump-head'", "track.className = 'lgr-jump-track'",
              "b.className = dock ? 'lgr-chip lgr-jump-btn asb-tab'", "icon.className = 'asb-tab-ico'",
              'nav._asbJumpCurrent.textContent = b._asbJumpLabel || b.textContent;',
              'targets.sort((a, b) => a.getBoundingClientRect().top - b.getBoundingClientRect().top);',
              'id="zyLogsBtn"', 'id="zyTgBtn"', 'class="status-row has-back"',
              'font: 700 23px/1.15 var(--sans);',
              "x.open('GET', 'i18n/' + code + '.json?v=27-art4', true)", 'I18N_READY.then(boot);',
              "document.body.classList.contains('zygisk-active')"):
    assert token in h, token
for token in ('#reportPage .logo-c', '#zygiskPage .logo-c', 'zoom: calc(1 / var(--asb-ui-scale))'):
    assert token not in h, 'drill-in header has independent scaling: ' + token
report=body('function logReportAppendAnalysis(body, d, analysis) {')
assert 'body.appendChild(asbPageJump(' not in report
final=body('function logReportFinalizeLayout(body) {')
assert "body.insertBefore(asbPageJump(items" in final
for token in ("['lgr-summary'", "['lgr-actions'", "['lgr-details'", "'lgr-drain'", "'lgr-observations'"):
    assert token in final, token
link=body('function zygiskLinkCard() {')
assert "document.createElement('details')" in link and 'box.open' not in link
guard=body('function zygiskGuardCard() {')
assert "pd.open = true" in guard and 'nb.open' not in guard and 'bb.open' not in guard and 'ev.open' not in guard
assert 'gh.open = !!(g.suggest.length || g.held.length);' in guard
keys=('lr_nav_drain','lr_nav_smooth','lr_nav_thermal','lr_nav_zygisk','zy_nav_mode','zy_nav_auto',
      'zy_nav_controls','zy_nav_activity','zy_nav_guard','zy_link_nav','zy_nav_art','zy_nav_apps')
files=sorted((r/'webroot/i18n').glob('*.json')); assert len(files)==13
for p in files:
    x=json.loads(p.read_text())
    for k in keys: assert isinstance(x.get(k),str) and x[k].strip(), (p,k)
PY
cat > "$T/render.js" <<'JS'
const fs = require('fs');
const h = fs.readFileSync(process.argv[2], 'utf8');
function grab(name) {
  const m = h.match(new RegExp('function ' + name + '\\([^)]*\\) \\{[\\s\\S]*?\\n\\}'));
  if (!m) throw new Error('missing renderer: ' + name);
  return m[0];
}
function el(tag, cls) {
  const n = { tag, children:[], _text:'', className:cls || '', id:'', open:false, scrollHits:0, dataset:{},
    set textContent(v) { this._text=String(v); this.children=[]; }, get textContent() { return this._text; },
    appendChild(c) { this.children.push(c); return c; },
    get firstChild() { return this.children[0] || null; },
    scrollIntoView() { this.scrollHits++; }
  };
  const classes = new Set(String(n.className).split(/\s+/).filter(Boolean));
  n.attrs={}; n.setAttribute=(k,v)=>{n.attrs[k]=String(v);}; n.removeAttribute=k=>{delete n.attrs[k];};
  const sync=()=>String(n.className).split(/\s+/).filter(Boolean).forEach(c=>classes.add(c));
  n.classList = { add(c) { sync(); classes.add(c); n.className=Array.from(classes).join(' '); },
    remove(c) { sync(); classes.delete(c); n.className=Array.from(classes).join(' '); },
    contains(c) { sync(); return classes.has(c); } };
  return n;
}
const body=el('div'), page=el('div'); page.scrollTop=0;
function find(n,id) { if (n.id===id) return n; for (const c of n.children) { const hit=find(c,id); if (hit) return hit; } return null; }
function _el(id) { return id==='zygiskBody' ? body : id==='zygiskPage' ? page : find(body,id); }
global.document={createElement:el,createElementNS:(ns,tag)=>el(tag)}; global.window={};
function T(k,f) { return f; }
function deviceVal(d,s,k) { return String((((d||{}).sections||{})[s]||{})[k] || ''); }
function logReportSec(title) { const c=el('div','lgr-sec'); c.appendChild(el('div','lgr-sec-t')); c.children[0].textContent=title; return c; }
function logReportNote(t) { const n=el('div','lgr-note'); n.textContent=t; return n; }
function deviceZygiskLink() { return el('div','dev-zygisk-link'); }
function zygiskOffCard() { return el('div','zy-off'); }
function techIcon() { return ''; }
for (const name of ['zygiskModeCard','zygiskAutoCard','zygiskControlsCard','zygiskLinkCard','zygiskGuardCard','zygiskAotCard','lspLiteCard','smart7Card'])
  global[name]=function () { return el('div','lgr-sec '+name); };
global.zyCompact=function () {};
for (const name of ['deviceZygiskOverview','zygiskPageRows','deviceZygiskEditor','zygiskEvidenceCard'])
  global[name]=function () { return el(name==='zygiskEvidenceCard'?'details':'div',name); }
eval(grab('asbPageJumpIcon'));
eval(grab('asbPageJumpIsDock'));
eval(grab('asbPageJumpIndicator'));
eval(grab('asbPageJumpClear'));
eval(grab('asbPageJumpActive'));
eval(grab('asbPageJumpWatch'));
eval(grab('asbPageJump'));
eval(grab('asbCosmicLoading'));
eval(grab('zygiskPageRender'));
const chk=(c,m)=>{ if(!c) throw new Error(m); };
const navs=()=>body.children.filter(c=>String(c.className).split(/\s+/).includes('zy-page-nav'));
zygiskPageRender(null);
chk(body.children.length===1 && navs().length===0,'loading state grew populated-page navigation');
const off={sections:{zygisk_observer:{enabled:'0'}}};
zygiskPageRender(off);
chk(body.children.length===4 && body.children[0].id==='zy-status' && body.children[2].id==='zy-lsp' && body.children[3].id==='zy-s7' && navs().length===0,'Off state grew irrelevant navigation or lost the LSPosed/Smart cards');
page.scrollTop=417;
zygiskPageRender({sections:{zygisk_observer:{enabled:'1'}}});
chk(navs().length===1,'populated state must have exactly one section map');
const ids=body.children.filter(c=>c.id).map(c=>c.id);
const expected=['zy-status','zy-guard','zy-engine','zy-s7','zy-aot','zy-apps','zy-evidence'];
chk(JSON.stringify(ids)===JSON.stringify(expected),'section order/IDs regressed: '+JSON.stringify(ids));
/* dev47: Controls live inside the Connection card, so "Connection and controls" is one card. */
const zyStatus=body.children.find(c=>c.id==='zy-status');
chk(zyStatus.children.some(c=>c.id==='zy-controls'),'controls are not inside the Connection card');
chk(zyStatus.children.some(c=>c.id==='zy-auto')&&zyStatus.children.some(c=>c.id==='zy-activity'),'automatic/activity are not merged into the Connection card');
const zyFlow=zyStatus.children.filter(c=>c.id).map(c=>c.id);
chk(JSON.stringify(zyFlow)===JSON.stringify(['zy-controls','zy-mode','zy-auto','zy-activity']),'Mode is not between Controls and Automatic: '+JSON.stringify(zyFlow));
chk(zyStatus.children[0]._text==='Connection and controls','merged card title missing');
chk(page.scrollTop===417,'an unchanged refresh lost the reading position');
const nav=navs()[0], buttons=nav._asbJumpButtons;
chk(buttons.length===6,'the populated section map must use six top-level card links');
chk(nav.attrs.role==='navigation' && buttons.every(b=>b.attrs['aria-controls']),'navigation semantics/controlled section missing');
chk(buttons[0].attrs['aria-current']==='location' && buttons[0].classList.contains('is-active'),'initial active section is not exposed');
chk(nav._asbJumpCurrent.textContent===buttons[0]._asbJumpLabel && nav._asbJumpTrack.children.length===6,'dock header/track did not render');
chk(buttons.every(b=>String(b.className).split(/\s+/).includes('asb-tab') && b.children[0].className==='asb-tab-ico' && b.children[1].className==='asb-tab-label'),'dock does not reuse the main tab structure');
buttons.forEach(b=>{ chk(typeof b.onclick==='function','jump has no handler: '+b._asbJumpLabel); b.onclick(); });
chk(buttons.filter(b=>b.attrs['aria-current']==='location'&&b.classList.contains('is-active')).length===1,'active section is ambiguous after jumps');
chk(nav._asbJumpCurrent.textContent===buttons[buttons.length-1]._asbJumpLabel,'dock header does not follow the active section');
for (const id of ['zy-status','zy-guard','zy-engine','zy-s7','zy-aot','zy-apps'])
  chk(_el(id) && _el(id).scrollHits===1,'jump did not reach its real section: '+id);
/* Nav order may intentionally differ from section order. Execute the real watcher with
 * that arrangement, then verify that the bottom rule also uses rendered section order. */
global.getComputedStyle=()=>({scrollMarginTop:'48px'});
page.clientHeight=600; page.scrollHeight=5000; page.scrollTop=0;
page.getBoundingClientRect=()=>({top:0});
page.addEventListener=(type,fn)=>{ if(type==='scroll') page._asbScroll=fn; };
nav.classList.add('zy-page-nav'); /* keep this lightweight className/classList mock in sync */
nav.closest=()=>page; nav.isConnected=true;
buttons.forEach(b=>{ b._asbJumpTarget && (_el(b._asbJumpTarget).getBoundingClientRect=()=>({top:300})); });
_el(buttons[0]._asbJumpTarget).getBoundingClientRect=()=>({top:-500});
_el(buttons[1]._asbJumpTarget).getBoundingClientRect=()=>({top:-200});
_el(buttons[buttons.length-1]._asbJumpTarget).getBoundingClientRect=()=>({top:-50});
asbPageJumpWatch(nav,buttons.map(b=>[b._asbJumpTarget,b._asbJumpLabel]));
chk(buttons[buttons.length-1].attrs['aria-current']==='location','scroll-spy followed nav order instead of rendered section order');
chk(nav._asbJumpCurrent.textContent===buttons[buttons.length-1]._asbJumpLabel,'current section did not follow reordered scroll-spy');
page.scrollTop=4400;
buttons.forEach(b=>{ _el(b._asbJumpTarget).getBoundingClientRect=()=>({top:-100}); });
