function T(k,d) { const L=I18N[ASB_LANG]; return L && L[k] != null ? L[k] : d; }
let _nightCharge={state:'unknown'};
function ledgerBadge(){return null} function trialHoursLeft(){return 0} function trialExpired(){return false}
