t_webui_slim_package_runtime() (
# Runtime (V66 dev9): the packaging step that makes the module smaller must not change what
# the WebUI is. tools/asb_slim_package.py runs on a copy of webroot here exactly as the
# workflows run it on the staged package:
#  - every translation file parses to the same object it parsed to before;
#  - the page's script blocks still compile, and the ZYGISK note gutter fix is still there;
#  - asbdiag's own reader of the settings registry (_ux_web_rows from tools/asb_diag.sh)
#    prints the same rows from the slim page as from the source page;
#  - the build marker survives, and the result is smaller;
#  - a page that uses a template literal is left as it is (the comment-line rule could cut one).
set -eu
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
fail() { echo "FAIL slim package: $*" >&2; exit 1; }
command -v python3 >/dev/null 2>&1 || { echo "SKIP slim package: no python3"; exit 0; }
mkdir -p "$T/pkg" "$T/src"
cp -r "$ROOT/webroot" "$T/pkg/webroot"; cp -r "$ROOT/webroot" "$T/src/webroot"
out="$(python3 "$ROOT/tools/asb_slim_package.py" "$T/pkg")" || fail "the tool failed: $out"
echo "$out" | grep 'translations -[1-9][0-9]* bytes, page -[1-9][0-9]* bytes (ok;' >/dev/null || fail "nothing was saved: $out"
python3 - "$T/src/webroot/i18n" "$T/pkg/webroot/i18n" <<'PY' || fail "a translation changed"
import json, os, sys
a, b = sys.argv[1], sys.argv[2]
for n in sorted(os.listdir(a)):
    if n.endswith('.json') and json.load(open(os.path.join(a, n))) != json.load(open(os.path.join(b, n))):
        print(n); sys.exit(1)
PY
sed -n '/^_ux_web_rows() {/,/^}/p' "$ROOT/tools/asb_diag.sh" > "$T/rows.sh"
[ -s "$T/rows.sh" ] || fail "asbdiag registry reader not found"
rows() { _ux_web="$1" sh -c '. "$1"; _ux_web_rows' _ "$T/rows.sh"; }
rows "$T/src/webroot/index.html" > "$T/r_src"; rows "$T/pkg/webroot/index.html" > "$T/r_pkg"
[ "$(wc -l < "$T/r_src")" -gt 100 ] || fail "the registry reader read nothing: $(wc -l < "$T/r_src")"
cmp -s "$T/r_src" "$T/r_pkg" || fail "asbdiag reads the settings differently from the slim page: $(diff "$T/r_src" "$T/r_pkg" | head -5)"
grep -q 'ASB_UI_BUILD=light-surface-contract-1' "$T/pkg/webroot/index.html" || fail "the build marker was stripped"
grep -Fq '#zygiskPage .lgr-note.dev-evidence.zy-clamp { padding-inline-start: 12px; }' "$T/pkg/webroot/index.html" || fail "the note gutter rule was lost"
[ "$(wc -c < "$T/pkg/webroot/index.html")" -lt "$(wc -c < "$T/src/webroot/index.html")" ] || fail "the page did not shrink"
if command -v node >/dev/null 2>&1; then
  python3 - "$T/pkg/webroot/index.html" "$T" <<'PY' || fail "a slim script block does not compile"
import re, subprocess, sys
h = open(sys.argv[1], encoding='utf-8').read()
for i, m in enumerate(re.findall(r'<script[^>]*>([\s\S]*?)</script>', h)):
    f = '%s/s%d.js' % (sys.argv[2], i); open(f, 'w', encoding='utf-8').write(m)
    if subprocess.run(['node', '--check', f]).returncode: sys.exit(1)
PY
fi
mkdir -p "$T/tpl/webroot/i18n"
printf '<html><script>\n// a comment\nconst a = `x\n// not a comment\n`;\n</script></html>\n' > "$T/tpl/webroot/index.html"
cp "$T/tpl/webroot/index.html" "$T/tpl/orig.html"
python3 "$ROOT/tools/asb_slim_package.py" "$T/tpl" >/dev/null || fail "the template-literal page made the tool fail"
cmp -s "$T/tpl/webroot/index.html" "$T/tpl/orig.html" || fail "a page with a template literal was changed"
grep -q 'python3 tools/asb_slim_package.py "$PKG_REL"' "$ROOT/.github/workflows/build-release.yml" || fail "the release package is not slimmed"
grep -q 'python3 tools/asb_slim_package.py "$PKG_TEST"' "$ROOT/.github/workflows/build-test.yml" || fail "the test package is not slimmed"
grep -q -- '-ffunction-sections -fdata-sections -Wl,--gc-sections -Wl,--exclude-libs,ALL' "$ROOT/src/build_ndk_release.sh" || fail "the Zygisk libraries keep the whole static C++ runtime"
grep -q "llvm-nm\" -D --defined-only \"\$_zout/\$_zabi.so\" | grep -q ' zygisk_module_entry\$'" "$ROOT/src/build_ndk_release.sh" || fail "the Zygisk entry export check is gone"
echo "PASS slim package: translations re-serialised to the same objects, comment lines out of the page, scripts compile, asbdiag reads the same settings, template literals left alone"
)

t_webui_i18n_untranslated_prose() (
# dev27: 186 strings (Infinite Log digest, device page, wakelock freezer, system load, Zygisk
# observer) were English sentences copied verbatim into eleven locales, plus short labels
# such as Summary/Actions/Details and Safe mode. Any value still identical to English that
# reads as prose (three lowercase words in a row) is a forgotten translation. Technical
# labels (CONFIG_ names, product names) never match the pattern.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." >/dev/null && pwd)"
fail() { echo "FAIL webui untranslated prose: $*" >&2; exit 1; }
python3 - "$ROOT/webroot/i18n" <<'P' || fail "English prose left in a locale"
import json, os, re, sys
d = sys.argv[1]
en = json.load(open(os.path.join(d, 'en.json'), encoding='utf-8'))
prose = re.compile(r'[a-z]{3,}[,;:]? [a-z]{2,} [a-z]{3,}')
short = ('lr_nav_summary', 'lr_nav_actions', 'lr_nav_details', 'dev_zygisk_link_safe',
         'dev_zygisk_observer_safe_mode', 'dev_load_band_light', 'dev_load_band_high', 'wl_manual_restore')
bad = []
for n in sorted(os.listdir(d)):
    if not n.endswith('.json') or n == 'en.json':
        continue
    loc = json.load(open(os.path.join(d, n), encoding='utf-8'))
    for k, v in en.items():
        if isinstance(v, str) and loc.get(k) == v and (prose.search(v) or (k in short and n != 'ru.json')):
            bad.append('%s:%s' % (n, k))
if bad:
    print(len(bad), bad[:12]); sys.exit(1)
P
echo "PASS webui untranslated prose: no locale carries an English sentence or the fixed short labels verbatim"
)

t_webui_kernel_control_verdicts() (
# dev27: the kernel-control toast printed the helper's machine words ("not_exposed",
# "readback_mismatch", "live 0x0001") in English in every locale. Every verdict the helper
# can emit on apply/restore has a localized phrase; the JS fallback equals en.json.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL webui kernel control verdicts: $*" >&2; exit 1; }
{ grep -o 'asb_kc_emit "\$[a-z_]*" [a-z_]*' "$ROOT/runtime/asb_kernel_controls.sh"; grep -o 'asb_kc_emit kernel_hrtimer_migration [a-z_]*' "$ROOT/runtime/asb_kernel_controls.sh"; } | awk '{print $3}' | sort -u | grep -vx writable > "${TMPDIR:-/tmp}/kc_st.$$"
python3 - "$H" "$ROOT/webroot/i18n" "${TMPDIR:-/tmp}/kc_st.$$" <<'P' || { rm -f "${TMPDIR:-/tmp}/kc_st.$$"; fail "verdict map"; }
import json, os, re, sys
h = open(sys.argv[1], encoding='utf-8').read()
m = re.search(r'const ASB_KC_VERDICTS = \{([\s\S]*?)\};', h)
assert m, 'ASB_KC_VERDICTS missing'
js = dict(re.findall(r"([a-z_]+): '([^']*)'", m.group(1)))
st = [l.strip() for l in open(sys.argv[3]) if l.strip()]
assert len(st) >= 10, st
miss = [s for s in st if s not in js]
assert not miss, ('no phrase for', miss)
en = json.load(open(os.path.join(sys.argv[2], 'en.json'), encoding='utf-8'))
for s, v in js.items():
    assert en.get('kc_verdict_' + s) == v, ('fallback differs', s)
assert "T('kc_live', 'kernel: {v}')" in h and en.get('kc_live') == 'kernel: {v}'
for n in sorted(os.listdir(sys.argv[2])):
    if not n.endswith('.json') or n == 'en.json':
        continue
    loc = json.load(open(os.path.join(sys.argv[2], n), encoding='utf-8'))
    for s in js:
        v = loc.get('kc_verdict_' + s)
        assert v and v != js[s], (n, s)
    assert '{v}' in loc.get('kc_live', ''), n
i = h.rindex("ASB_KERNEL_STATUS_KEYS.indexOf(key) >= 0")
seg = h[i:i + 1800]
assert 'asbKernelControlVerdict(kp[1], kp[3], kp[2])' in seg
assert "' · live '" not in seg and "toast(key + ': '" not in seg
P
rm -f "${TMPDIR:-/tmp}/kc_st.$$"
echo "PASS webui kernel control verdicts: every helper verdict has a phrase in 13 locales, the live value is labelled, no raw machine words in the toast"
)

t_debug_support_lock_handoff_runtime() (
# dev27, from the dev27 CI run: "concurrent start count round=2" with one helper answering
# status=starting and the other error=recorder_exited, no status=started at all. Two defects:
#  - full_day_pid_owns_lock read the launcher's command line twice. The first read (in
#    full_day_pid_matches_recorder) could still show the forked helper, the second the exec'd
#    `nohup setsid sh .../asb_log_full_day.sh`, which matched neither pattern of the second
#    check. A live launcher then looked foreign, lock_known_dead said "dead", and the second
#    request renamed the winner's lock away and launched its own recorder. Eight parallel
#    regression jobs on four vCPUs widen that window.
#  - The loser of that race saw its recorder exit (its token no longer matched) and ran
#    rm -rf on the lock directory, which by then belonged to the other request.
# Both are deterministic here: a counting stub serves the two command-line reads in order, and
# a fixture recorder replaces the token before it exits.
set -euo pipefail
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
HELPER="$ROOT/runtime/asb_debug_support.sh"
TMP="$(mktemp -d)"
SLEEPER=""
WINNER=""
trap 'kill $SLEEPER $WINNER 2>/dev/null || true; rm -rf "$TMP"' EXIT
fail() { echo "FAIL debug support lock handoff: $*" >&2; exit 1; }
awk '/^pid_is_live\(\) \{/,/^}/; /^full_day_pid_matches_recorder\(\) \{/,/^}/; /^full_day_pid_owns_lock\(\) \{/,/^}/' "$HELPER" > "$TMP/fn.sh"
[ "$(grep -c '() {' "$TMP/fn.sh")" -eq 3 ] || fail "helper functions not found"
sleep 60 & SLEEPER=$!
mkdir -p "$TMP/proc/$SLEEPER"
printf 'unused\n' > "$TMP/proc/$SLEEPER/cmdline"
rc=0
( MODDIR=/m PROC_ROOT="$TMP/proc"; . "$TMP/fn.sh"
  tr() {
    if [ "${1:-}" = '\000' ]; then
      _c="$(cat "$TMP/reads" 2>/dev/null || echo 0)"; echo $((_c + 1)) > "$TMP/reads"
      cat > /dev/null
      if [ "$_c" -eq 0 ]; then printf 'sh /m/runtime/asb_debug_support.sh full-day'
      else printf 'nohup setsid sh /m/tools/logkit/asb_log_full_day.sh 0'; fi
    else command tr "$@"; fi
  }
  full_day_pid_owns_lock "$SLEEPER" ) || rc=$?
[ "$(cat "$TMP/reads" 2>/dev/null)" = 2 ] || fail "expected two command-line reads, saw $(cat "$TMP/reads" 2>/dev/null)"
[ "$rc" -eq 0 ] || fail "a live launcher that exec'd between the two command-line reads was treated as foreign"
DBG="$TMP/debug"; mkdir -p "$DBG/tools/logkit" "$TMP/state"
printf 'id=AutoSystemBoost\nversion=V66\n' > "$DBG/module.prop"
cat > "$DBG/tools/logkit/asb_log_full_day.sh" <<'EOF_REC'
#!/bin/sh
printf 'other-request\n' > "$ASB_DEBUG_SUPPORT_LOCKDIR/token"
exit 92
EOF_REC
chmod 0755 "$DBG/tools/logkit/asb_log_full_day.sh"
OUT="$(ASB_DEBUG_SUPPORT_MODDIR="$DBG" ASB_DEBUG_SUPPORT_STATE_DIR="$TMP/state" ASB_DEBUG_SUPPORT_RUNLOG="$TMP/run.out" sh "$HELPER" full-day || true)"
grep -Fqx 'error=recorder_exited' <<<"$OUT" || fail "fixture recorder did not exit as planned: $OUT"
[ -d "$TMP/state/full_day_webui.lock" ] || fail "the helper removed a lock that another request had taken over"
grep -Fqx 'other-request' "$TMP/state/full_day_webui.lock/token" || fail "foreign token lost"

# buildfix18: the same exited-launcher branch has a second, distinct outcome. If the token
# changed AND the replacement lock already names a live recorder, the capture is running and
# this request must join it. The old unconditional recorder_exited answer was the CI round=8
# failure even though the concurrent winner had already published status=started and its PID.
mkdir -p "$TMP/winner"
cat > "$TMP/winner/asb_log_full_day.sh" <<'EOF_WINNER'
#!/bin/sh
sleep 60
EOF_WINNER
chmod 0755 "$TMP/winner/asb_log_full_day.sh"
sh "$TMP/winner/asb_log_full_day.sh" & WINNER=$!
cat > "$DBG/tools/logkit/asb_log_full_day.sh" <<'EOF_REC'
#!/bin/sh
printf 'other-request\n' > "$ASB_DEBUG_SUPPORT_LOCKDIR/token"
printf '%s\n' "${ASB_DEBUG_SUPPORT_TEST_WINNER_PID:?}" > "$ASB_DEBUG_SUPPORT_LOCKDIR/pid"
exit 92
EOF_REC
chmod 0755 "$DBG/tools/logkit/asb_log_full_day.sh"
OUT="$(ASB_DEBUG_SUPPORT_TEST_WINNER_PID="$WINNER" ASB_DEBUG_SUPPORT_MODDIR="$DBG" ASB_DEBUG_SUPPORT_STATE_DIR="$TMP/state" ASB_DEBUG_SUPPORT_RUNLOG="$TMP/run.out" sh "$HELPER" full-day || true)"
grep -Fqx 'status=already_running' <<<"$OUT" || fail "live replacement owner not joined: $OUT"
grep -Fqx "pid=$WINNER" <<<"$OUT" || fail "replacement winner PID absent: $OUT"
[ -d "$TMP/state/full_day_webui.lock" ] || fail "joined request removed the replacement lock"
grep -Fqx 'other-request' "$TMP/state/full_day_webui.lock/token" || fail "joined request replaced the winner token"
grep -Fqx "$WINNER" "$TMP/state/full_day_webui.lock/pid" || fail "winner PID file changed"
kill "$WINNER" 2>/dev/null || true; wait "$WINNER" 2>/dev/null || true; WINNER=""
rm -rf "$TMP/state/full_day_webui.lock"
cat > "$DBG/tools/logkit/asb_log_full_day.sh" <<'EOF_REC'
#!/bin/sh
exit 91
EOF_REC
OUT="$(ASB_DEBUG_SUPPORT_MODDIR="$DBG" ASB_DEBUG_SUPPORT_STATE_DIR="$TMP/state" ASB_DEBUG_SUPPORT_RUNLOG="$TMP/run.out" sh "$HELPER" full-day || true)"
grep -Fqx 'error=recorder_exited' <<<"$OUT" || fail "own failed recorder not reported: $OUT"
[ ! -d "$TMP/state/full_day_webui.lock" ] || fail "the helper kept its own lock after its recorder died"
echo "PASS debug support lock handoff: a launcher seen mid-exec still owns its lock, an exited loser joins a verified live replacement, and a failed start removes only its own lock"
)

t_tests_pipefail_grep_q_contract() (
# dev27: under `set -o pipefail`, `echo "$x" | grep pattern` can fail although the pattern is >/dev/null
# there: grep -q exits at the first match and a writer that is still writing gets EPIPE (CI runs
# with SIGPIPE ignored: its log shows "echo: write error: Broken pipe"). Reproduced here as 1 in
# 20000 under load, and as two debug-support failures in 80 parallel runs. Tests that set
# pipefail use here-strings instead.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
fail() { echo "FAIL tests pipefail grep -q: $*" >&2; exit 1; }
python3 - "$ROOT"/tests/asb_*.sh <<'P' || fail "pipe into grep -q under pipefail"
import re, sys
start = re.compile(r"^t_([a-z0-9_]+)\(\) \($")
pipefail = re.compile(r"set -[a-z]*o pipefail")
piped = re.compile(r"(^|[;&(]\s*|\|\|\s*|&&\s*)(echo|printf) [^|]*\| *grep -[A-Za-z]*q")
bad = []
for p in sys.argv[1:]:
    cur = None; pf = False
    for n, l in enumerate(open(p, encoding='utf-8').read().split('\n'), 1):
        m = start.match(l)
        if m:
            cur = m.group(1); pf = False; continue
        if l.lstrip().startswith('#'):
            continue
        if cur and pipefail.search(l):
            pf = True
        if cur and pf and piped.search(l.strip()):
            bad.append('%s:%d %s' % (p.rsplit('/', 1)[-1], n, cur))
if bad:
    print(len(bad), bad[:10]); sys.exit(1)
P
echo "PASS tests pipefail grep -q: no test pipes into grep -q while pipefail is set"
)

t_webui_junk_cleanup_runtime() (
# dev32: a manual, localized Infirmary card around the fixed status/run protocol. No polling,
# arbitrary path or HTML injection; deletion needs a second tap and every failure stays visible.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL webui junk cleanup: $*" >&2; exit 1; }
python3 - "$ROOT" <<'PY' || fail 'static wiring and locales'
from pathlib import Path
import json, re, sys
root=Path(sys.argv[1]); h=(root/'webroot/index.html').read_text(encoding='utf-8')
start=h.index('/* Infirmary → Junk Cleanup')
end=h.index('function cfgRenderGroup(', start)
b=h[start:end]
assert "id:'cleanup'" in h and "card:'junkcleanup'" in h
assert "else if (section.card === 'junkcleanup') cfgRenderJunkCleanupCard(list);" in h
assert "const JUNK_CLEANUP_SCRIPT = MD + '/runtime/asb_junk_cleanup.sh';" in b
assert b.count("run('sh ' + shQuote(JUNK_CLEANUP_SCRIPT) + ' status')") == 1
assert b.count("run('sh ' + shQuote(JUNK_CLEANUP_SCRIPT) + ' run')") == 1
assert 'setInterval(' not in b and 'setTimeout(' not in b
assert b.count('innerHTML =') == 1 and "em.innerHTML = techIcon('cleaner')" in b
assert 'now - _junkArmed > 5000' in b and "state === 'lock_error'" in b
assert "bfxEl('details', 'junk-disclosure asb-disclosure')" in b and 'disclosure.open' not in b
assert b.index('card.appendChild(actions);') < b.index('card.appendChild(disclosure);'), 'categories must follow primary actions'
assert '.asb-disclosure > summary' in h and '.junk-disclosure .junk-cats' in h
assert "junkButtons(false); return true;" in b
for css in ('.junk-total', '.junk-cats', '.junk-cat.is-warn', '.junk-card .bfx-btn'):
    assert css in h, css
keys=set('cfg_inf_section_cleanup cfg_inf_section_cleanup_hint junk_title junk_desc junk_categories junk_scan junk_run junk_refresh junk_confirm junk_running junk_partial_toast junk_cat_dropbox junk_cat_tombstones junk_cat_anr junk_cat_environment junk_cat_installer junk_cat_logs junk_cat_backup junk_cat_trash junk_cat_screenshots junk_cat_coloros junk_unavailable junk_result_meta junk_remaining junk_meta junk_unavailable_short junk_failed junk_found junk_empty junk_ready junk_check junk_clean junk_skipped junk_busy_chip junk_busy junk_done junk_partial junk_partial_chip junk_cleaned'.split())
locales=sorted((root/'webroot/i18n').glob('*.json'))
assert len(locales)==13
base=json.loads((root/'webroot/i18n/en.json').read_text(encoding='utf-8'))
for p in locales:
    d=json.loads(p.read_text(encoding='utf-8'))
    assert not keys-set(d), (p.name, keys-set(d))
    assert 'junk_cat_local' not in d, (p.name, 'removed ASB report category')
    for k in keys:
        assert set(re.findall(r'\{[^}]+\}',base[k])) == set(re.findall(r'\{[^}]+\}',d[k])), (p.name,k)
assert json.loads((root/'webroot/i18n/ru.json').read_text(encoding='utf-8'))['junk_title']=='Чистка от шлаков'
PY
command -v node >/dev/null 2>&1 || { echo "SKIP webui junk cleanup runtime: no node"; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
{
cat <<'EOF'
const fs = require('fs');
const h = fs.readFileSync(process.argv[2], 'utf8');
let MD='/m', ASB_LANG='en', now=10000;
const realNow=Date.now; Date.now=function(){ return now; };
function shQuote(v){ return "'"+String(v)+"'"; }
function T(k,d){ return d; }
function bfxT(k,d,v){ return String(d).replace(/\{([^}]+)\}/g,function(m,n){ return v[n] == null ? m : v[n]; }); }
function techIcon(){ return '<svg></svg>'; }
function cfgInfLater(k,fn){ fn(); }
function uiSound(){}
const toasts=[]; function toast(m,t){ toasts.push({m:m,t:t}); }
const reg={};
function mk(tag){
  const e={tag:tag,children:[],className:'',hidden:false,disabled:false,dataset:{},style:{},innerHTML:'',_text:''};
  Object.defineProperty(e,'id',{get:function(){return e._id;},set:function(v){e._id=v;reg[v]=e;}});
  Object.defineProperty(e,'textContent',{get:function(){return e._text;},set:function(v){e._text=String(v == null ? '' : v);if(v==='')e.children=[];}});
  e.appendChild=function(c){e.children.push(c);c.parent=e;return c;};
  return e;
}
function bfxEl(tag,cls,text){const e=mk(tag);e.className=cls||'';if(text!=null)e.textContent=text;return e;}
function kernelMoreBlock(card,id,nodes){const btn=mk('button');btn.className='kernel-more';card.appendChild(btn);const body=mk('div');body.className='kernel-more-body';body.hidden=true;nodes.forEach(n=>{if(n)body.appendChild(n);});card.appendChild(body);return body;}
function _el(id){return reg[id]||null;}
const cats=['dropbox','tombstones','anr','environment','installer','logs','backup','trash','screenshots','coloros'];
function status(count){
  const rows=cats.map(function(id){
    if(id==='dropbox'&&count)return 'junk_category|dropbox|count=2|bytes=1024|state=ready';
    if(id==='tombstones'&&count)return 'junk_category|tombstones|count=1|bytes=2048|state=ready';
    if(id==='anr')return 'junk_category|anr|count=0|bytes=0|state=not_readable';
    return 'junk_category|'+id+'|count=0|bytes=0|state=ready';
  });
  rows.push('junk_cleanup|status|total_count='+(count?3:0)+'|total_bytes='+(count?3072:0)+'|failed_categories=1');
  return rows.join('\n');
}
const scripted={status:status(true),run:'junk_cleanup|result|state=cleaned|removed_count=3|freed_bytes=3072|failed_categories=0'};
const cmds=[];
async function run(cmd){cmds.push(cmd);return {stdout:/ status$/.test(cmd)?scripted.status:scripted.run};}
const block=h.slice(h.indexOf('const JUNK_CLEANUP_SCRIPT'),h.indexOf('function cfgRenderGroup(',h.indexOf('const JUNK_CLEANUP_SCRIPT')));
eval(block);
let bad=0;function chk(c,m){if(!c){console.log('FAIL '+m);bad++;}}
async function flush(){await Promise.resolve();await Promise.resolve();await Promise.resolve();}
async function confirmRun(){await junkCleanupRun();now+=4000;await junkCleanupRun();}
(async function(){
  const list=mk('div');cfgRenderJunkCleanupCard(list);await flush();
  chk(reg.junkCard&&reg.junkCats.children.length===10,'card or ten categories not rendered');
  chk(reg.junkCats.parent&&reg.junkCats.parent.tag==='details'&&!reg.junkCats.parent.open,'categories are not collapsed by default');
  chk(cmds[0]==="sh '/m/runtime/asb_junk_cleanup.sh' status",'unexpected scan command: '+cmds[0]);
  chk(reg.junkTotal.textContent==='Found: 3 · 3 KB'&&!reg.junkRun.disabled,'ready scan not painted');
  chk(reg.junkNote.textContent==='Unreadable categories are skipped: 1','unreadable category not explained');
  chk(reg.junkCats.children[2].className==='junk-cat is-warn'&&reg.junkCats.children[2].children[1].textContent==='Not readable — skipped','category warning missing');
  chk(reg.junkCats.children.every(function(r){return r.children[0].tag==='div';}),'category value became markup');

  await junkCleanupRun();
  chk(cmds.filter(function(c){return / run$/.test(c);}).length===0&&/Tap again/.test(toasts[toasts.length-1].m),'first tap deleted or did not confirm');
  now+=5001;await junkCleanupRun();
  chk(cmds.filter(function(c){return / run$/.test(c);}).length===0,'expired confirmation was accepted');
  now+=4000;await junkCleanupRun();
  chk(cmds[cmds.length-1]==="sh '/m/runtime/asb_junk_cleanup.sh' run",'unexpected run command');
  chk(reg.junkChip.textContent==='Cleaned'&&reg.junkTotal.textContent==='Removed: 3 · freed 3 KB'&&reg.junkRun.disabled,'cleaned result wrong');
  chk(toasts[toasts.length-1].t==='ok','success not reported');

  scripted.status=status(true);await junkCleanupPaint(true);
  scripted.run=cats.map(function(id){return 'junk_category|'+id+'|removed='+(id==='dropbox'?1:0)+'|freed='+(id==='dropbox'?10:0)+'|remaining='+(id==='dropbox'?1:0)+'|state='+(id==='dropbox'?'partial':'cleaned');}).join('\n')+'\njunk_cleanup|result|state=partial|removed_count=1|freed_bytes=10|failed_categories=1';
  await confirmRun();
  chk(reg.junkChip.textContent==='Partial'&&/failed categories: 1/.test(reg.junkNote.textContent)&&/left: 1/.test(reg.junkCats.children[0].children[1].textContent),'partial result not visible');
  chk(!reg.junkRun.disabled&&toasts[toasts.length-1].t==='error','partial cleanup did not remain retryable');

  scripted.status=status(true);await junkCleanupPaint(true);
  scripted.run='junk_cleanup|result|state=busy';await confirmRun();
  chk(reg.junkChip.textContent==='Busy'&&reg.junkRun.disabled&&!reg.junkRefresh.disabled,'busy state permits deletion or blocks rescan');
  chk(toasts[toasts.length-1].t==='perf','busy not reported distinctly');

  scripted.status=status(true);await junkCleanupPaint(true);
  scripted.run='junk_cleanup|result|state=lock_error';await confirmRun();
  chk(reg.junkChip.textContent==='Unavailable'&&reg.junkRun.disabled&&toasts[toasts.length-1].t==='error','lock error was shown as success');

  scripted.status='not a cleanup status';await junkCleanupPaint(true);
  chk(reg.junkRun.disabled&&reg.junkCats.children.length===0&&reg.junkNote.textContent==='Could not scan the supported locations','invalid status left stale rows or actions');
  scripted.status=status(false);await junkCleanupPaint(true);
  chk(reg.junkChip.textContent==='Check'&&reg.junkRun.disabled&&/No supported/.test(reg.junkTotal.textContent),'empty with unreadable category wrong');
  scripted.status=status(false).replace('failed_categories=1','failed_categories=0').replace('state=not_readable','state=ready');await junkCleanupPaint(true);
  chk(reg.junkChip.textContent==='Clean'&&reg.junkRun.disabled&&reg.junkNote.textContent==='','clean empty state wrong');
  const parsed=junkParse('junk_category|<img src=x onerror=1>|count=9|bytes=9|state=ready\njunk_cleanup|status|total_count=0|total_bytes=x|failed_categories=0');
  chk(Object.keys(parsed.cats).length===0&&parsed.head.total_bytes==='x','unknown category or malformed byte parser wrong');
  chk(junkBytes(parsed.head.total_bytes)==='0 B','non-numeric byte count was accepted');
  if(bad)process.exit(1);console.log('ok');
})().catch(function(e){console.error(e);process.exit(1);}).finally(function(){Date.now=realNow;});
EOF
} > "$T/t.js"
out="$(node "$T/t.js" "$H" 2>&1)" || fail "$out"
[ "$out" = ok ] || fail "$out"
echo "PASS webui junk cleanup: all 13 locales and 38 keys, fixed status/run commands, ten safe textContent rows, no ASB report category, five-second double confirmation, cleaned/partial/busy/lock/unreadable/empty states, no polling or arbitrary path"
)

