)

t_webui_companion_lpm_autogroup_dev58() (
# dev58, from the owner's dev57 phone export:
#  - the build summary and the Device page named the NoMount metamodule version but not the
#    VPN Hide companion module; both kernel companion modules now have one line each (version,
#    enabled/disabled/pending update, kernel side), on the Device page and in asbdiag;
#  - Idle Prediction (LPM): the kernel ships prediction on (qcom-cpu-lpm prediction_disabled=0),
#    so Stock, Auto and On cannot change anything there; the card now says so from the read
#    status, and the text no longer claims that prediction picks deeper sleep (it avoids deep
#    sleeps that would be left at once);
#  - Scheduler Autogroup cannot exist on GKI and would not act on Android apps: the dead card is
#    hidden when the kernel does not expose it, and the help card says why.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
fail() { echo "FAIL companion/lpm/autogroup dev58: $*" >&2; exit 1; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT HUP INT TERM
mkdir -p "$T/data/modules/vpnhide_builtin" "$T/data/modules_update/vpnhide_builtin" "$T/data/modules/nomount" "$T/proc" "$T/sys/module/nomount"
printf 'id=vpnhide_builtin\nname=VPN Hide (Built-in kernel)\nversion=v1.3.1\nversionCode=10301\n' > "$T/data/modules/vpnhide_builtin/module.prop"
printf 'id=vpnhide_builtin\nversion=v1.3.2\nversionCode=10302\n' > "$T/data/modules_update/vpnhide_builtin/module.prop"
printf 'id=nomount\nversion=v2.3.0 (720)\nversionCode=720\n' > "$T/data/modules/nomount/module.prop"
: > "$T/proc/vpnhide_ctl"; echo 23 > "$T/sys/module/nomount/version"
col() {
  ASB_DEVINFO_MODDIR="$T/mod" ASB_DEVINFO_SYS="$T/sys" ASB_DEVINFO_PROC="$T/proc" ASB_DEVINFO_DATA="$T/data" \
  ASB_DEVINFO_PROP_FILE="$T/props" ASB_DEVINFO_SUSFS="$T/none" ASB_DEVINFO_STATE="$T/state" ASB_DEVINFO_KSUD="$T/none" \
  ASB_DEVINFO_DEV="$T/dev" ASB_DEVINFO_TC="$T/none" sh "$ROOT/tools/asb_device_info.sh" 2>/dev/null | grep '^D	companion_modules	'
}
out="$(col)"
printf '%s\n' "$out" | grep -Fx "$(printf 'D\tcompanion_modules\tnomount\tv2.3.0 (720) · enabled · kernel driver version 23')" >/dev/null || fail "nomount: $out"
printf '%s\n' "$out" | grep -Fx "$(printf 'D\tcompanion_modules\tvpnhide\tv1.3.1 (10301) · enabled · update to v1.3.2 (10302) after reboot · kernel interface /proc/vpnhide_ctl present')" >/dev/null || fail "vpnhide: $out"
: > "$T/data/modules/nomount/disable"; rm -rf "$T/data/modules/vpnhide_builtin" "$T/proc/vpnhide_ctl"
out="$(col)"
printf '%s\n' "$out" | grep -F 'nomount	v2.3.0 (720) · disabled' >/dev/null || fail "disabled: $out"
printf '%s\n' "$out" | grep -Fx "$(printf 'D\tcompanion_modules\tvpnhide\tv1.3.2 (10302) · installed, active after reboot · kernel interface /proc/vpnhide_ctl not exposed')" >/dev/null || fail "pending install: $out"
rm -rf "$T/data/modules_update" "$T/data/modules/nomount"
out="$(col)"
[ "$(printf '%s\n' "$out" | grep -c '	not installed · ')" = 2 ] || fail "not installed: $out"
for f in tools/asb_diag.sh system/bin/asbdiag; do
  grep -Fq 'NOTE "kernel companion module $_cmn: $_cmv"' "$ROOT/$f" || fail "$f has no companion module line"
  grep -Fq 'for _cmi in nomount:NoMount vpnhide_builtin:"VPN Hide"; do' "$ROOT/$f" || fail "$f module list"
done
python3 - "$ROOT/webroot" <<'PY' || fail 'webui contract'
import json, re, sys, pathlib
W = pathlib.Path(sys.argv[1]); h = (W / 'index.html').read_text(encoding='utf-8')
assert "  ['metamodule', 'dev_sec_metamodule', 'Metamodule', 'root'],\n  ['companion_modules', 'dev_sec_companion_modules', 'Kernel companion modules', 'root']," in h
en = json.loads((W / 'i18n/en.json').read_text(encoding='utf-8'))
keys = ('dev_sec_companion_modules', 'dev_companion_modules_nomount', 'dev_companion_modules_vpnhide',
        'kc_lpm_default_on', 'kc_lpm_default_off', 'kernel_absent_autogroup')
for p in sorted((W / 'i18n').glob('*.json')):
    d = json.loads(p.read_text(encoding='utf-8'))
    for k in keys:
        assert isinstance(d.get(k), str) and d[k].strip(), (p.name, k)
        if p.stem != 'en' and k not in ('dev_companion_modules_nomount',): assert d[k] != en[k], (p.name, k)
    assert d['cfg']['kernel_sched_autogroup']['name'] in d['kernel_absent_autogroup'], p.name
    lpm = d['cfg']['kernel_lpm_prediction']['desc']
    assert 'prediction_disabled' in lpm, p.name
desc = en['cfg']['kernel_lpm_prediction']['desc']
assert 'deeper sleep state sooner' not in desc and 'lighter sleep state' in desc
assert "'%s'" % en['kc_lpm_default_on'] in h and "'%s'" % en['kc_lpm_default_off'] in h
assert "const KERNEL_HIDE_WHEN_ABSENT = ['kernel_sched_autogroup', 'kernel_hrtimer_migration'];" in h
assert '.cfg-row.kernel-absent-hidden { display:none; }' in h
help_fn = h[h.index('function cfgRenderKernelControlsHelp('):h.index('\n}\n', h.index('function cfgRenderKernelControlsHelp('))]
assert "const hidden = kernelHiddenAbsent();" in help_fn and "hidden.indexOf('kernel_sched_autogroup') >= 0" in help_fn and "T('kernel_absent_autogroup'" in help_fn
PY
node - "$ROOT/webroot/index.html" <<'JS' || fail 'runtime'
const h = require('fs').readFileSync(process.argv[2], 'utf8');
function grab(name) { const i = h.indexOf('function ' + name + '('); if (i < 0) throw Error('missing ' + name); return h.slice(i, h.indexOf('\n}\n', i) + 2); }
const src = h.slice(h.indexOf('const KERNEL_HIDE_WHEN_ABSENT'), h.indexOf('\n};\n', h.indexOf('const KERNEL_HIDE_STATES')) + 3) + '\n' +
  h.slice(h.indexOf('const KERNEL_OPTION_VALUES'), h.indexOf('\n};\n', h.indexOf('const KERNEL_OPTION_VALUES')) + 3) + '\n' +
  grab('kernelHiddenAbsent') + grab('kernelShipped') + grab('kernelDefaultFact') + grab('kernelDecorateControlRow') + grab('kernelControlAvailability') +
  'return { kernelHiddenAbsent, kernelDefaultFact, kernelDecorateControlRow };';
global._kernelPanel = { loading:false, controls:{} };
global.ASB_KERNEL_STATUS_KEYS = ['kernel_lpm_prediction', 'kernel_sched_autogroup'];
const T = (k, fb) => fb;
const kernelStateText = s => s, kernelUnavailableWhy = () => 'why';
const bfxEl = (tag, cls, txt) => ({ tag, className: cls, textContent: txt });
const Topt = o => o, bfxT = (k, fb, v) => fb.replace(/\{(\w+)\}/g, (m, x) => v[x]);
const f = new Function('T', 'kernelStateText', 'kernelUnavailableWhy', 'bfxEl', 'Topt', 'bfxT', src)(T, kernelStateText, kernelUnavailableWhy, bfxEl, Topt, bfxT);
const P = _kernelPanel.controls;
P.kernel_lpm_prediction = { state:'writable', mode:'auto', live:'1', baseline:'none' };
if (!/ships prediction on/.test(f.kernelDefaultFact('kernel_lpm_prediction'))) throw Error('default on');
P.kernel_lpm_prediction = { state:'writable', mode:'on', live:'1', baseline:'0' };
if (!/ships prediction off/.test(f.kernelDefaultFact('kernel_lpm_prediction'))) throw Error('baseline wins over live');
P.kernel_lpm_prediction = { state:'writable', mode:'auto', live:'unknown', baseline:'none' };
if (f.kernelDefaultFact('kernel_lpm_prediction') !== '') throw Error('unknown must say nothing');
if (f.kernelDefaultFact('kernel_timer_migration') !== '') throw Error('other keys');
function row() { const kids = []; const cl = new Set(); return { kids, cl, classList:{ add:c => cl.add(c), contains:c => cl.has(c) },
  appendChild:x => kids.push(x), querySelector:sel => sel === '.cfg-status' ? null : (kids.find(k => sel === '.' + String(k.className).split(' ').pop()) || null),
  querySelectorAll:() => [] }; }
P.kernel_sched_autogroup = { state:'not_exposed', mode:'stock', live:'unknown', baseline:'none' };
const ag = row(); f.kernelDecorateControlRow(ag, 'kernel_sched_autogroup');
if (!ag.cl.has('kernel-absent-hidden') || ag.kids.length) throw Error('autogroup must be hidden, not explained');
if (f.kernelHiddenAbsent().join() !== 'kernel_sched_autogroup') throw Error('hidden list');
P.kernel_sched_autogroup = { state:'writable', mode:'stock', live:'1', baseline:'none' };
const ag2 = row(); f.kernelDecorateControlRow(ag2, 'kernel_sched_autogroup');
if (ag2.cl.has('kernel-absent-hidden') || f.kernelHiddenAbsent().length) throw Error('an exposed autogroup stays visible');
P.kernel_lpm_prediction = { state:'writable', mode:'auto', live:'1', baseline:'none' };
const lp = row(); f.kernelDecorateControlRow(lp, 'kernel_lpm_prediction');
if (lp.kids.length !== 1 || lp.kids[0].className !== 'kernel-why kernel-fact') throw Error('fact line');
f.kernelDecorateControlRow(lp, 'kernel_lpm_prediction');
if (lp.kids.length !== 1) throw Error('fact added twice');
JS
echo 'PASS companion/lpm/autogroup dev58: NoMount and VPN Hide module versions with state and kernel side on the Device page and in asbdiag, LPM card says what the kernel ships and describes prediction correctly, a missing Autogroup is hidden with the reason in the help card, 13 locales'
)

t_webui_dev60_cards_hub_explanations() (
# dev60, from the owner's report on dev59:
#  - the kernel help card and the wakeup-rules card showed every paragraph at once; each now
#    keeps a one-line summary and folds the rest behind a Details toggle that remembers its
#    state across re-renders;
#  - Refresh status felt dead: a press now paints a busy label at once and ends with a toast
#    saying how many controls the kernel lets ASB change; Open Device Diagnostics scrolls to
#    the Kernel group of the Device page;
#  - High-resolution Timer Migration could not be changed because this kernel moves those
#    timers with Timer Migration; the row is hidden like a missing Autogroup, and the hub tile
#    no longer counts it (the tile said 9 / 11);
#  - the Camera tile said 6 / 6 while the screen showed eight cards: cards that are not
#    CFG_ITEMS (Camera Tools, the wakeup rules, the notification fix) count now, and the
#    Camera Tools cards carry the Camera hue instead of the Infirmary green;
#  - battery and performance settings outside Kernel got the kernel cards' layout: a short
#    description, three goal lines and a per-option table (switches included), 13 locales.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL webui dev60 cards/hub/explanations: $*" >&2; exit 1; }
python3 - "$ROOT" <<'P' || fail 'static contract and locales'
import json, pathlib, re, sys
root = pathlib.Path(sys.argv[1]); h = (root / 'webroot/index.html').read_text(encoding='utf-8')
assert "kernel_hrtimer_migration: ['covered_by_timer_migration', 'not_exposed']" in h
help_fn = h[h.index('function cfgRenderKernelControlsHelp('):h.index('\n}\n', h.index('function cfgRenderKernelControlsHelp('))]
assert "kernelMoreBlock(card, 'help', more)" in help_fn and "kernelRefreshButton('kernelControlsRefresh')" in help_fn
assert help_fn.index("T('kernel_controls_summary'") < help_fn.index("kernelMoreBlock(")
wb = h[h.index('function cfgRenderWakeupBlockerCard('):h.index('\n}\n', h.index('function cfgRenderWakeupBlockerCard('))]
assert "kernelMoreBlock(card, 'wb', [" in wb and "T('kernel_wb_summary'" not in wb and "kernelRefreshButton('kernelWakeupRefresh')" not in wb
assert wb.index("kernelMoreBlock(card, 'wb', [") < wb.index("T('kernel_wb_sub'")
assert 'kernel-wakeup-card' in wb and 'kernel-controls-actions' in help_fn
assert '.kernel-more-body[hidden] { display:none; }' in h and '.bfx-btn.is-busy' in h
assert "bfxEl('div', 'cfg-row bfx-card camtools-card cat-camera')" in h
assert '.bfx-card.cfg-row.cat-camera .bfx-emblem { --tech-icon:var(--cat); color:var(--cat);' in h
assert "camera: 'Processing, webcam, fast start'" in h
row = h[h.index('function cfgRenderRow('):h.index('let _cfgSearch')]
assert "const dBool = it.type === 'bool';" in row and "(dBool ? ['1', '0'] : (it.opts ? cfgOptsFor(it) : Object.keys(dOpt)))" in row
assert "T('cfg_sw_on', 'On')" in row and "T('cfg_sw_off', 'Off')" in row
hub = h[h.index('function cfgGroupHiddenKeys('):h.index('// Settings whose effect lands in a file')]
assert 'const total = items.length + extras.length;' in hub and 'cfgHubExtrasEnsure();' in hub
assert "_cfgHubSig !== cfgHubSig()" in hub and 'cfgHubExtraSig()' in h[h.index('function cfgHubSig('):h.index('\n}\n', h.index('function cfgHubSig('))]
assert "else cfgHubRepaintIfShowing();" in h[h.index('async function kernelPanelLoad('):h.index('function kernelStateText(')]
# Search shows the same kernel rows as the category: hidden ones are not found, the rest are
# decorated (state badge, disabled when unavailable) and repainted when the status arrives.
sm = h[h.index('function cfgSearchMatches('):h.index('\n}\n', h.index('function cfgSearchMatches('))]
assert "const hidden = cfgGroupHiddenKeys('kernel');" in sm and 'if (hidden.indexOf(it.key) >= 0) return false;' in sm
rm = h[h.index('function cfgRenderMatches('):h.index('\n}\n', h.index('function cfgRenderMatches('))]
assert 'kernelPanelEnsure();' in rm and 'kernelDecorateControlRow(list.lastChild, it.key);' in rm
assert "if (_cfgGroup === 'kernel' || (_cfgOpen && _cfgSearch)) { try { cfgRender(); } catch (e) {} }" in h
L = {p.stem: json.loads(p.read_text(encoding='utf-8')) for p in sorted((root / 'webroot/i18n').glob('*.json'))}
assert len(L) == 13
en = L['en']
new = ['cfg_sw_on', 'cfg_sw_off', 'kernel_more_show', 'kernel_more_hide', 'kernel_refreshed', 'kernel_refresh_failed', 'kernel_refreshing',
       'kernel_controls_summary', 'kernel_hidden_count', 'kernel_absent_hrtimer', 'kc_default_same',
       'kc_mglru_no_nonleaf', 'ct_wc_summary', 'ct_la_summary']
ph = re.compile(r'\{[a-z_]+\}')
for k in new:
    m = re.search(r"\b(?:T|bfxT)\('%s',\s*'((?:[^'\\]|\\.)*)'" % k, h)
    assert m and m.group(1).replace("\\'", "'") == en[k], ('JS fallback differs from en.json', k)
items = {}
for m in re.finditer(r"\{ key:'([A-Za-z0-9_]+)', type:'([a-z]+)'(.*?)\}(?=,?\s*(?://[^\n]*\n\s*)?(?:\{ key:|\]))", h[h.index('const CFG_ITEMS = ['):h.index('\n];', h.index('const CFG_ITEMS = ['))], re.S):
    o = re.search(r"opts:\[([^\]]*)\]", m.group(3))
    items[m.group(1)] = (m.group(2), [x.strip().strip("'") for x in o.group(1).split(',')] if o else None)
EXPL = ['perf_ceiling_pct', 'BG_TRIM_LEVEL', 'doze_level', 'doze_trim_whitelist', 'gms_freeze', 'gms_trim', 'gnss_trim', 'wakelock_action',
        'wakelock_fitness', 'sustained_temp_mode', 'sustained_temp_enter', 'cool_gaming', 'bat_suppress_gaming', 'auto_battery_enable',
        'charge_aware_enable', 'heavy_prime_escape', 'prime_escape_burst_s', 'prime_escape_rest_s', 'night_quiet_enable', 'profile_class_auto',
        'smart_battery_bias', 'smart_lab', 'smart_lab_mem', 'smart_media_guard', 'smart_records_balanced', 'camera_hold_enable', 'ltpo_force',
        'ltpo_peak_force', 'ltpo_video', 'anim_speed', 'disable_blur', 'ui_effects_level', 'UX_MANAGE_TIMEOUTS', 'wifi_powersave',
        'wifi_scan_throttle', 'net_screen_off_lte', 'net_lte_light', 'night_modem_idle', 'net_rps', 'net_txqueue', 'net_route_tune',
        'net_wifi_leave', 'net_congestion', 'net_congestion_wifi', 'net_congestion_mobile', 'net_qdisc', 'net_qdisc_wifi', 'net_qdisc_mobile',
        'athena_service', 'phantom_procs', 'log_level', 'mmfeed_off', 'bt_a2dp_offload']
assert len(EXPL) == 53 and all(k in items for k in EXPL), [k for k in EXPL if k not in items]
for name, d in L.items():
    for k in new + ['grp_camera_desc']:
        assert isinstance(d.get(k), str) and d[k].strip(), (name, k)
        assert sorted(ph.findall(d[k])) == sorted(ph.findall(en[k])), (name, k, 'placeholders')
    for k in EXPL:
        c = d['cfg'][k]
        desc = c['desc']
        assert desc.count('\n\n') == 1, (name, k, 'one summary paragraph, then the goal lines')
        goals = desc.split('\n\n')[1].split('\n')
        assert len(goals) == 3 and goals[0].startswith('\U0001F50B') and goals[2].startswith('✋'), (name, k, goals)
        if name != 'en': assert desc != en['cfg'][k]['desc'], (name, k, 'untranslated')
        typ, opts = items[k]
        if 'descOpt' in c:
            keys = set(c['descOpt'])
            if typ == 'bool': assert keys == {'1', '0'}, (name, k, keys)
            elif typ == 'range': assert all(re.fullmatch(r'-?[0-9]+', x) for x in keys), (name, k, keys)
            else:
                assert opts, (name, k, 'missing static seed options')
                # TCP algorithms are discovered from the running kernel; descOpt also covers
                # known custom-kernel names that cannot be listed in the static seed opts.
                if not re.fullmatch(r'net_congestion(?:_(?:wifi|mobile))?', k):
                    assert keys <= set(opts), (name, k, keys, opts)
            assert keys == set(en['cfg'][k]['descOpt']), (name, k, 'option set differs from English')
    for k in ('cool_gaming', 'smart_lab', 'ltpo_force', 'gnss_trim', 'wakelock_action', 'net_congestion_wifi', 'gms_freeze'):
        assert 'descOpt' in d['cfg'][k], (name, k)
    assert set(d['cfg']['gms_freeze']['descOpt']) == {'off', 'safe', 'more', 'max'}, name
    assert set(d['cfg']['net_qdisc_mobile']['descOpt']) == {'auto', 'fq', 'fq_codel', 'cake'}, name
assert '0x0004' in en['kc_mglru_no_nonleaf'] and 'x86 feature' not in en['kc_mglru_no_nonleaf']
P
command -v node >/dev/null 2>&1 || { echo 'SKIP webui dev60 runtime: no node'; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT HUP INT TERM
cat > "$T/t.js" <<'JS'
const h = require('fs').readFileSync(process.argv[2], 'utf8');
function grab(name) { const m = h.match(new RegExp('\\n(?:async )?function ' + name + '\\([^)]*\\) \\{[\\s\\S]*?\\n\\}')); if (!m) throw Error('missing ' + name); return m[0]; }
function block(start) { const i = h.indexOf('\n' + start); if (i < 0) throw Error('missing ' + start); return h.slice(i, h.indexOf('\n};\n', i) + 3); }
function el(tag) { return { tag, children: [], className: '', id: '', hidden: false, attrs: {}, _t: '', disabled: false, classList: { s: new Set(), add(c) { this.s.add(c); } },
  set textContent(v) { this._t = String(v); this.children = []; }, get textContent() { return this._t + this.children.map(c => c.textContent).join(' '); },
  set innerHTML(v) { this._html = v; }, get innerHTML() { return this._html || ''; },
  setAttribute(k, v) { this.attrs[k] = String(v); }, getAttribute(k) { return k in this.attrs ? this.attrs[k] : null; },
  appendChild(c) { this.children.push(c); return c; }, querySelector() { return null; }, querySelectorAll() { return []; } }; }
global.document = { createElement: el };
const T = (k, f) => f, Topt = o => o, bfxT = (k, f, v) => f.replace(/\{(\w+)\}/g, (m, x) => v[x]);
function bfxEl(tag, cls, text) { const e = el(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; }
let sounds = [], toasts = [], timers = [], opened = 0, scrolled = 0, loads = 0;
const uiSound = k => sounds.push(k), toast = (m, t) => toasts.push([m, t]);
global.setTimeout = fn => { timers.push(fn); return timers.length; };
let devGroup = null; const _el = id => (id === 'dev-group-kernel' ? devGroup : null);
const openDevicePage = () => { opened++; };
let _wbBusy = false, _cfgGroup = '', _cfgOpen = true, _cfgSearch = '', _cfgHubSig = '', renders = 0;
const cfgRender = () => { renders++; };
const ASB_KERNEL_STATUS_KEYS = ['mglru_mode', 'kernel_timer_migration', 'kernel_hrtimer_migration', 'kernel_usb_autosuspend', 'kernel_sched_autogroup'];
let _kernelPanel = { loaded: false, loading: false, controls: Object.create(null), wakeup: null };
let nextControls = null;
async function kernelPanelLoad() { loads++; _kernelPanel.loading = true; await null; _kernelPanel.controls = nextControls || Object.create(null); _kernelPanel.loading = false; _kernelPanel.loaded = true; }
function kernelPanelEnsure() {}
let _ctFlags = null, _nf = null;
eval([block('const KERNEL_HIDE_WHEN_ABSENT').split('\n').slice(0, 2).join('\n'), block('const KERNEL_HIDE_STATES'), block('const KERNEL_OPTION_VALUES'),
  'let _kernelMore = Object.create(null);',
  grab('kernelHiddenAbsent'), grab('kernelControlAvailability'), grab('kernelShipped'), grab('kernelDefaultFact'), grab('kernelMoreBlock'),
  grab('kernelVisibleKeys'), grab('kernelRefreshClick'), grab('kernelOpenDiagnostics'), grab('kernelRefreshButton'),
  grab('cfgGroupHiddenKeys'), grab('cfgGroupExtraCards')].join('\n').replace(/^const /gm, 'var ').replace(/^let /gm, 'var '));
const chk = (c, m) => { if (!c) throw Error(m); };
(async () => {
  // Details toggle: closed by default, opens and closes, and a re-render keeps the choice.
  let card = el('div'); let body = kernelMoreBlock(card, 'help', [bfxEl('div', 'kernel-note', 'long text'), null]);
  const btn = card.children[0];
  chk(body.hidden === true && btn.textContent === 'Details' && btn.getAttribute('aria-expanded') === 'false' && body.children.length === 1, 'closed by default');
  btn.onclick({ stopPropagation() {} });
  chk(body.hidden === false && btn.textContent === 'Hide details' && btn.getAttribute('aria-expanded') === 'true', 'opens');
  card = el('div'); body = kernelMoreBlock(card, 'help', []);
  chk(body.hidden === false && card.children[0].textContent === 'Hide details', 'state lost on re-render');
  card.children[0].onclick(); chk(body.hidden === true, 'closes');
  // HR timers covered by timer migration: hidden, and not counted in the Kernel tile.
  _kernelPanel.controls = { kernel_hrtimer_migration: { state: 'covered_by_timer_migration', mode: 'auto', live: '0', baseline: 'none' },
    kernel_timer_migration: { state: 'writable', mode: 'auto', live: '1', baseline: '1' },
    kernel_usb_autosuspend: { state: 'writable', mode: 'on', live: '2', baseline: '2' },
    kernel_sched_autogroup: { state: 'writable', mode: 'stock', live: '1', baseline: 'none' },
    mglru_mode: { state: 'writable', mode: 'smart', live: '0x0001', baseline: '0x0003' } };
  chk(kernelHiddenAbsent().join() === 'kernel_hrtimer_migration', 'hrtimer not hidden: ' + kernelHiddenAbsent());
  chk(cfgGroupHiddenKeys('kernel').join() === 'kernel_hrtimer_migration' && cfgGroupHiddenKeys('camera').length === 0, 'hub hidden keys');
  chk(kernelVisibleKeys().length === 4, 'visible keys');
  // What the kernel ships, said once per card.
  chk(/ships 1: stock, on give the same/.test(kernelDefaultFact('kernel_timer_migration')), 'timer fact: ' + kernelDefaultFact('kernel_timer_migration'));
  chk(/ships 2: stock, on give the same/.test(kernelDefaultFact('kernel_usb_autosuspend')), 'usb fact');
  chk(/0x0004 flag/.test(kernelDefaultFact('mglru_mode')) && /light step \(5\) reads 0x0001/.test(kernelDefaultFact('mglru_mode')), 'mglru fact');
  _kernelPanel.controls.mglru_mode.live = '0x0007'; chk(kernelDefaultFact('mglru_mode') === '', 'mglru with all flags kept needs no fact');
  chk(kernelDefaultFact('kernel_sched_autogroup') === '', 'no shipped value, no fact');
  // Extra cards in the hub count.
  chk(cfgGroupExtraCards('camera').join() === 'false,false', 'camera extras before flags');
  _ctFlags = { webcam: '1', launch: '0' }; chk(cfgGroupExtraCards('camera').join() === 'true,false', 'camera extras');
  _kernelPanel.wakeup = { saved: ['a'] }; chk(cfgGroupExtraCards('kernel').join() === 'true', 'legacy wakeup rules count when saved');
  _kernelPanel.wakeup = { saved: [], savedAlways: ['a'], savedSleep: [] }; chk(cfgGroupExtraCards('kernel').join() === 'true', 'Always-only wakeup rule is not counted');
  _kernelPanel.wakeup = { saved: [], savedAlways: [], savedSleep: ['night_lock'] }; chk(cfgGroupExtraCards('kernel').join() === 'true', 'Screen-off-only wakeup rule is not counted');
  _kernelPanel.wakeup = { saved: [], savedAlways: [], savedSleep: [] }; chk(cfgGroupExtraCards('kernel').join() === 'false', 'empty split wakeup rules are counted as active');
  _nf = { count: 0 }; chk(cfgGroupExtraCards('battery').join() === 'false', 'notification fix off');
  chk(cfgGroupExtraCards('audio').length === 0, 'other groups have no extras');
  // Refresh: sound at once, busy label while reading, a toast with the count at the end.
  nextControls = _kernelPanel.controls; sounds = []; toasts = [];
  const p = kernelRefreshClick();
  chk(sounds[0] === 'nav' && _kernelPanel.loading === true, 'no immediate feedback');
  const busy = kernelRefreshButton('x'); chk(busy.disabled && /is-busy/.test(busy.className) && busy.textContent === 'Checking…', 'busy button');
  await p;
  chk(toasts.length === 1 && toasts[0][1] === 'good' && toasts[0][0] === 'Kernel status read: 4 of 4 controls can be changed', 'toast: ' + JSON.stringify(toasts));
  const idle = kernelRefreshButton('x'); chk(!idle.disabled && idle.textContent === 'Refresh status' && idle.onclick === kernelRefreshClick, 'idle button');
  nextControls = Object.create(null); toasts = [];
  await kernelRefreshClick(); chk(toasts[0][1] === 'err' && /Could not read/.test(toasts[0][0]), 'failed read toast');
  // Diagnostics: opens the page, then scrolls to the Kernel group once it exists.
  timers = []; kernelOpenDiagnostics();
  chk(opened === 1 && timers.length === 1, 'device page / wait');
  timers.shift()(); chk(timers.length === 1, 'keeps waiting');
  devGroup = { scrollIntoView() { scrolled++; } }; timers.shift()();
  chk(scrolled === 1 && timers.length === 0, 'scroll to the kernel group');
  devGroup = null; timers = []; kernelOpenDiagnostics(); for (let i = 0; i < 60 && timers.length; i++) timers.shift()();
  chk(timers.length === 0, 'unbounded wait');
  console.log('ok');
})().catch(e => { console.error(e && e.stack || e); process.exit(1); });
JS
out="$(node "$T/t.js" "$H" 2>&1)" || fail "$out"
[ "$out" = ok ] || fail "$out"
echo 'PASS webui dev60: kernel help and wakeup cards fold into Details (state kept), Refresh gives instant feedback and a counted toast, Diagnostics scrolls to Kernel, covered HR timers hidden, not counted and not found by search (found kernel rows decorated), Camera Tools in Camera hue and counted with the other extra cards, kernel facts (shipped value, MGLRU 0x0004), 53 battery/performance cards with goal lines and per-option tables incl. switches, 13 locales'
)

t_webui_dev61_ambient_gpu_pressure() (
# dev61, from the owner's short log and four screenshots (dev60):
#  - with every app closed the Monitor said GPU 60-70 % and the Load sheet said "moderate
#    40/100". The GPU figure was this page drawing its own header at the lowest clock
#    (160 MHz): with the WebUI closed the log's GPU busy median was 4 %. The tile now shows
#    the clock beside the busy share and colours busy x clock / top clock;
#  - dev61 stepped the idle header from a 100 ms timer, which looked like a ten-second
#    slowdown/freeze. Dev66 returned the logo to the native CSS clock but left the wordmark
#    under calm; buildfix3 removes that last header stop and keeps the ticker only for the
#    Smart card glow. Hidden/reduced-motion rules remain intact;
#  - the pressure sheet scored loadavg (it counts tasks asleep on storage) and the share of
#    memory in use (Android keeps apps cached on purpose), which read "moderate" on a phone
#    doing nothing. With /proc/pressure it now scores stall time, and says which basis it used;
#  - "Who set the limit: Vendor" next to "firmware limits 0" read as a contradiction: that
#    owner was a vendor boost above ASB's ceiling, not a clamp. It is "Vendor ↑", neutral.
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
H="$ROOT/webroot/index.html"
fail() { echo "FAIL webui dev61 ambient/gpu/pressure: $*" >&2; exit 1; }
python3 - "$ROOT" <<'P' || fail 'static contract and locales'
import json, pathlib, re, sys
root = pathlib.Path(sys.argv[1]); h = (root / 'webroot/index.html').read_text(encoding='utf-8')
i = h.index('/* dev66/buildfix3: calm never changes any visible header')
blk = h[i:h.index('}', i) + 1]
blk = blk[blk.index('*/') + 2:]
blk = blk.split('/* dev61: the GPU tile')[0]
# buildfix42: the Smart halo no longer calms - paused, it looked like a frozen profile icon.
assert 'html.asb-calm .pico-smart .ai-glow' not in h and 'html.asb-calm .ai-glow' not in h
_a42 = h.index('html[data-asb-effects="reduced"] .zygisk-header-dot:not(asb-spec-pad),')
assert 'ai-glow' not in h[_a42:h.index('{', _a42)], 'ui-jank still freezes the Smart halo'
assert 'animation' not in h[_a42:h.index('}', _a42)], 'ui-jank still freezes the Zygisk header dot'
assert '.pico-smart .ai-glow { animation: none !important; }' in h, 'OS reduced motion no longer owns the halo'
assert 'body.live-active .page:not(.live-page) .ai-glow' in h, 'the halo keeps running behind another page'
assert 'html.asb-calm .app-name' not in h, 'calm still removes the wordmark animation'
for header in ('.app-name', '.logo-sphere-a', '.logo-sphere-b', '.logo-inner', '.dot',
               '.zygisk-header-dot', '.dev-zygisk-link-dot'):
    assert header not in blk, 'header returned to the 100 ms idle ticker: ' + header
assert 'document.getAnimations' not in h and 'ASB_AMBIENT_' not in h and 'asbAmbientTick' not in h
for spinner in ('busy', 'spinner', 'is-running', 'orbit', 'loading', 'stock-restoring', 'is-recording'):
    assert spinner not in blk, 'a progress indicator would stop: ' + spinner
assert '.live-cell-value .lv-sub {' in h and '-webkit-text-fill-color: currentColor;' in h[h.index('.live-cell-value .lv-sub {'):][:300]
assert "'vendor_raised': 'Vendor \\u2191'" in h
assert "else if (capSrc === 'vendor_raised') asbMetricPaint('liveCapSrc', 'metric-info');" in h
assert "if (capSrc === 'vendor_clamp' || capSrc === 'vendor_raised') asbMetricPaint" not in h
chip = h[h.index('if (chip) {', h.index('const _csRank')):h.index('/* Keep collecting for the ROM banner')]
assert "else if (capSrc === 'vendor_clamp' || capSrc === 'thermal_overlay') chip.classList.add('has-issue');" in chip
assert 'vendor_raised' not in chip, 'a vendor boost still marks the status chip as an issue'
assert '.live-info-pressure .lvp-note {' in h
L = 'en ru uk de fr es it pt tr id zh ar hy'.split()
D = {l: json.loads((root / f'webroot/i18n/{l}.json').read_text(encoding='utf-8')) for l in L}
new = ['unit_mhz', 'lv_gpu_work_tip', 'lvp_basis_psi', 'lvp_basis_load', 'lvp_vs_class']
labels = ['gpu_clock_mhz', 'gpu_work_pct', 'basis'] + [f'psi_{r}_{k}' for r in ('cpu', 'memory', 'io') for k in ('some_avg10', 'component', 'weight')]
src = (root / 'runtime/asb_pressure.sh').read_text(encoding='utf-8')
for k in labels:
    assert f'_emit system_load {k} ' in src, k
for l in L:
    for k in new + ['dev_system_load_' + x for x in labels]:
        assert D[l].get(k), (l, k)
    for ph in ('{busy}', '{mhz}', '{max}', '{work}'):
        assert ph in D[l]['lv_gpu_work_tip'], (l, ph)
    assert 'PSI' in D[l]['dev_guide_system_load'] and 'Vendor ↑' in D[l]['lvi_capsrc'], l
    if l != 'en':
        for k in ('lv_gpu_work_tip', 'lvp_basis_psi', 'lvp_basis_load', 'lvp_vs_class', 'cap_tip_raised', 'dev_system_load_gpu_clock_mhz'):
            assert D[l][k] != D['en'][k], (l, k)
for k in new + ['cap_tip_raised', 'lvi_gpu', 'lvi_capsrc']:
    m = re.search(r"T\('" + k + r"', '((?:[^'\\]|\\.)*)'\)", h) or re.search(r"\['" + k + r"', '((?:[^'\\]|\\.)*)'\]", h)
    assert m, 'no fallback for ' + k
    assert m.group(1).replace("\\'", "'") == D['en'][k], 'fallback differs: ' + k
P
command -v node >/dev/null 2>&1 || { echo 'SKIP webui dev61: no node'; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT HUP INT TERM
cat > "$T/t.js" <<'JS'
const fs = require('fs'), h = fs.readFileSync(process.argv[2], 'utf8');
let bad = 0; const chk = (c, m) => { if (!c) { console.log('FAIL ' + m); bad++; } };
const slice = (a, b) => { const i = h.indexOf(a); const j = h.indexOf(b, i); if (i < 0 || j < 0) throw Error('marker ' + a); return h.slice(i, j); };
/* 1. calm uses one bounded timer and CSS owns every animation clock. */
(function () {
  let now = 0; const timers = []; const listeners = {};
  const setTimeout = (fn, ms) => { timers.push({ at: now + (ms || 0), fn, live: true }); return timers.length; };
  const performance = { now: () => now };
  const cls = new Set();
  const document = { documentElement: { classList: { add: c => cls.add(c), remove: c => cls.delete(c) } } };
  const window = { addEventListener: (t, fn) => { listeners[t] = fn; } };
  function advance(ms) {
    const end = now + ms;
    for (;;) {
      const due = timers.filter(t => t.live && t.at <= end).sort((a, b) => a.at - b.at)[0];
      if (!due) break;
      now = due.at; due.live = false; due.fn();
    }
    now = end;
  }
  const live = () => timers.filter(t => t.live).length;
  eval(slice('let _asbInputAt = -1e9;', '\n/* dev4: a job never runs while another page is open or opening.'));
  chk(live() === 1 && !cls.has('asb-calm'), 'one calm timer at startup');
  advance(10100); chk(cls.has('asb-calm') && live() === 0, 'calm left an ambient worker running');
  listeners.touchstart(); chk(!cls.has('asb-calm') && live() === 1, 'wake did not restore the single calm timer');
  advance(10100); chk(cls.has('asb-calm') && live() === 0, 'second calm cycle left a worker');
})();
/* 1b. a clamp or thermal overlay on either cluster outranks a boost on the other */
(function () {
  const pick = (a, b) => { let st = { cap_source_p0: a, cap_source_p6: b };
    return eval(slice('const _cs0 = (st && st.cap_source_p0)', '\n    const advActive') + '\ncapSrc'); };
  chk(pick('vendor_raised', 'vendor_clamp') === 'vendor_clamp', 'a boost hid the clamp on the other cluster');
  chk(pick('vendor_clamp', 'vendor_raised') === 'vendor_clamp', 'clamp on the main cluster');
  chk(pick('asb', 'vendor_raised') === 'vendor_raised' && pick('asb', 'thermal_overlay') === 'thermal_overlay', 'foreign owner on the prime');
  chk(pick('asb', 'asb') === 'asb' && pick('', 'asb') === 'asb' && pick('shell_applied', '') === 'shell_applied', 'ordinary owners');
})();
/* 2. GPU clock reads and work share */
(function () {
  const _lvMeter = { at: Date.now() }; let _selectedProfile = 'smart', _batCapFullMah = 4000;
  const _stockTelemetryLastMs = 0, _stockSettingsAtMs = 0, STOCK_TELEMETRY_MIN_INTERVAL_MS = 1e9, MD = '/m';
  const LV_METER_CMD = 'meter'; const stockTelemetryCmd = () => 'rom';
  const gpu = eval(slice('function liveBatchParts(', 'async function pollLive(') + ';\n({ get clk() { return _lvGpuClkHz; }, get max() { return _lvGpuMaxHz; }, get min() { return _lvGpuMinHz; } })');
  const keys = v => liveBatchParts(v, false).map(p => p[0]);
  chk(keys(true).includes('gpuclk') && keys(true).includes('gpufreqs'), 'visible pass does not read the GPU clock');
  chk(!keys(false).includes('gpuclk') && !keys(false).includes('gpufreqs'), 'background pass reads the GPU clock');
  chk(liveBatchParts(true, false).find(p => p[0] === 'gpuclk')[1] === 'cat /sys/class/kgsl/kgsl-3d0/devfreq/cur_freq', 'clock path');
  chk(lvGpuWork(62) === null, 'work without a clock');
  lvGpuClockRead({ gpuclk: { stdout: '160000000\n' }, gpufreqs: { stdout: '1200000000 900000000 500000000 160000000\n' } });
  chk(gpu.clk === 160000000 && gpu.max === 1200000000 && gpu.min === 160000000, 'clock table');
  chk(!keys(true).includes('gpufreqs') && keys(true).includes('gpuclk'), 'the frequency table is read every pass');
  chk(lvGpuWork(62) === 8 && lvGpuWork(0) === 0, '62 % at 160 of 1200 MHz: ' + lvGpuWork(62));
  lvGpuClockRead({ gpuclk: { stdout: '1200000000' } }); chk(lvGpuWork(62) === 62, 'top clock counts in full');
  lvGpuClockRead({ gpuclk: { stdout: '' } }); chk(lvGpuWork(62) === null && gpu.max === 1200000000, 'an empty clock read left a stale clock');
})();
/* 3. pressure sheet: PSI rows, GPU clock, basis note */
(function () {
  const T = (k, f) => f;
  function mk(tag) { const e = { tag, children: [], className: '', style: {}, hidden: true, _t: '', appendChild(c) { this.children.push(c); return c; },
    get textContent() { return this._t + this.children.map(c => c.textContent).join('|'); }, set textContent(v) { this._t = String(v); this.children = []; } };
    return e; }
  const document = { createElement: mk };
  const deviceVal = (d, s, k) => (d[k] === undefined ? '—' : d[k]);
  const deviceLabel = (s, k) => k;
  const devicePressureScale = () => mk('div');
  eval(slice('const LVI_PRESSURE_KEYS', 'async function lviPressureLoad('));
  const rows = b => b.children.find(c => c.className === 'lvp-parts').children.map(r => r.children[0].textContent + '=' + r.children[2].textContent);
  const note = b => b.children.find(c => c.className === 'lvp-note').textContent;
  const psi = { psi_cpu_some_avg10: '3.00', psi_cpu_component: '6.0', psi_memory_some_avg10: '0.50', psi_memory_component: '2.5',
    psi_io_some_avg10: '1.25', psi_io_component: '5.0', cpu_busy_pct: '12.0', gpu_busy_pct: '62.0', gpu_component: '11.0', gpu_clock_mhz: '160',
    load_per_core: '0.6', load_component: '30.0', memory_used_pct: '61.0' };
  let b = mk('div'); lviPressureRender(b, psi, 'apphint');
  const r = rows(b);
  chk(r[0] === 'psi_cpu_some_avg10=3.00 %' && r[1] === 'psi_memory_some_avg10=0.50 %' && r[2] === 'psi_io_some_avg10=1.25 %', 'PSI rows: ' + r);
  chk(r[4] === 'gpu_busy_pct=62.0 %', 'GPU pressure row must be percent-only: ' + r[4]);
  chk(!r.some(x => /^load_per_core|^memory_used_pct/.test(x)), 'loadavg rows next to PSI');
  const gpuFill = b.children.find(c => c.className === 'lvp-parts').children[4].children[1].children[0];
  chk(gpuFill && gpuFill.style.width === '11%', 'GPU bar is not busy x clock: ' + (gpuFill && gpuFill.style.width));
  chk(/waited for the CPU, memory and storage/.test(note(b)) && /the load class above/.test(note(b)), 'PSI note: ' + note(b));
  const old = Object.assign({}, psi); delete old.psi_cpu_some_avg10; delete old.gpu_clock_mhz;
  b = mk('div'); lviPressureRender(b, old, 'sload');
  const r2 = rows(b);
  chk(r2[0] === 'load_per_core=0.6' && r2[1] === 'memory_used_pct=61.0 %' && r2[3] === 'gpu_busy_pct=62.0 %', 'no-PSI rows: ' + r2);
  chk(/no pressure stall information/.test(note(b)) && !/the load class above/.test(note(b)), 'no-PSI note: ' + note(b));
})();
/* 4. device page values and the Monitor snapshot of the GPU tile */
(function () {
  const T = (k, f) => f; const ASB_LANG = 'en';
  const fns = ['deviceNum', 'deviceFallbackLabel', 'deviceSizeKb', 'deviceDisplayValue'];
  const deviceFill = (k, f, o) => f; const deviceDuration = s => s + 's'; const deviceCpuCount = () => 8; const deviceVal = () => '—';
  eval(fns.map(f => { const i = h.indexOf('\nfunction ' + f + '('); return h.slice(i, h.indexOf('\n}\n', i) + 3); }).join('\n'));
  const nb = s => String(s).replace(/ /g, ' ');
  chk(deviceDisplayValue('system_load', 'psi_memory_some_avg10', '0.50') === '0.50%', 'PSI value');
  chk(nb(deviceDisplayValue('system_load', 'gpu_clock_mhz', '160')) === '160 MHz', 'clock value');
  chk(deviceDisplayValue('system_load', 'gpu_work_pct', '11.0') === '11.0%', 'work value');
  chk(deviceDisplayValue('system_load', 'gpu_clock_mhz', 'not exposed') === 'not exposed', 'missing clock');
})();
(function () {
  const ids = {};
  function mkEl(id) { const e = { id, className: 'live-cell-value', title: '', children: [], _t: '',
    get textContent() { return this._t + this.children.map(c => c.textContent).join(''); }, set textContent(v) { this._t = String(v); this.children = []; },
    appendChild(c) { this.children.push(c); return c; }, querySelector(sel) { return sel === '.lv-sub' ? (this.children.find(c => c.className === 'lv-sub') || null) : null; },
    parentElement: { querySelector: () => ({ textContent: 'GPU' }) } };
    ids[id] = e; return e; }
  const document = { createElement: () => ({ className: '', textContent: '' }) };
  const _el = id => ids[id] || mkEl(id);
  const _lvMonCache = { tiles: null }; let _selectedProfile = 'balanced'; const ASB_LANG = 'en'; const LV_MON_CACHE_MAX_MS = 1800000;
  const lvMonSmartCapture = () => {}; const lvMonCacheSave = () => {};
  eval(slice('const LV_MON_TILE_IDS', '/* The Smart card is part of the same display snapshot.'));
  const g = _el('liveGpu'); g.textContent = '62%'; g.appendChild({ className: 'lv-sub', textContent: '160 MHz' });
  lvMonTilesCapture('balanced');
  chk(_lvMonCache.tiles.values.liveGpu.v === '62%' && _lvMonCache.tiles.values.liveGpu.s === '160 MHz', 'GPU tile snapshot: ' + JSON.stringify(_lvMonCache.tiles.values.liveGpu));
  g.textContent = '—'; lvMonTilesRestore();
  chk(g._t === '62%' && g.children.length === 1 && g.children[0].className === 'lv-sub' && g.children[0].textContent === '160 MHz', 'GPU tile restored glued: ' + g.textContent);
})();
console.log(bad ? 'bad ' + bad : 'ok');
