assert "['stock','auto'].concat(ASB_IO_SCHEDULERS" in h
assert h.index('statusRow.appendChild(badge); main.appendChild(statusRow);') < h.index('const _smartOwner = cfgSmartOwner')
assert "if (_selectedProfile !== 'smart' || !it) return null;" in h
assert "it.key === 'mglru_mode' && v === 'smart'" in h
assert "'io_scheduler','kernel_timer_migration'" in h[h.index('function cfgSmartOwner'):h.index('function cfgVerify',h.index('function cfgSmartOwner'))]
for p in (root/'webroot/i18n').glob('*.json'):
 d=json.loads(p.read_text()); c=d['cfg']['io_scheduler']
 assert c['name'] and c['desc'] and all(k in c['descOpt'] for k in ('stock','auto','adios','mq-deadline','kyber','bfq','none')),p.name
 assert d['optFor']['io_scheduler']['stock'] and d['optFor']['io_scheduler']['auto']
 assert d.get('cfg_smart_profile') and d.get('cfg_smart_owner_profile') and d.get('cfg_smart_limit') and d.get('cfg_smart_owner_limit')
 assert 'cfg_smart_owner_dsp_thermal' not in d
PY
command -v node >/dev/null 2>&1 || { echo 'SKIP WebUI Smart/scheduler runtime: no node'; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT HUP INT TERM
cat > "$T/t.js" <<'JS'
const fs=require('fs'),h=fs.readFileSync(process.argv[2],'utf8');
function grab(name){const m=h.match(new RegExp('function '+name+'\\([^)]*\\) \\{[\\s\\S]*?\\n\\}'));if(!m)throw Error('missing '+name);return m[0]}
for(const n of ['kernelSchedulerOptionsParse','cfgOptsFor','cfgSmartOwner'])eval(grab(n));
let found=kernelSchedulerOptionsParse('io_scheduler_options|bfq kyber mq-deadline none bfq-mq\nio_scheduler_options|kyber bad/name UPPER x\n');
if(found.join(',')!=='bfq,kyber,mq-deadline,none,bfq-mq,x')throw Error('discovery parse '+found);
global.ASB_IO_SCHEDULERS=found;global.ASB_TCP_ALGS=null;global._tcpAlgLoadStarted=true;global._isReference=false;
const opts=cfgOptsFor({key:'io_scheduler',opts:['stock','auto']});
if(opts.join(',')!=='stock,auto,bfq,kyber,mq-deadline,none,bfq-mq,x')throw Error('bounded options '+opts);
ASB_IO_SCHEDULERS=null;if(cfgOptsFor({key:'io_scheduler',opts:['stock','auto']}).join(',')!=='stock,auto')throw Error('unknown discovery offered unverified scheduler');
global._selectedProfile='smart';global._cfgVals={dsp_outputs:'speaker',audio_profile:'stock'};
const own=(key,v)=>cfgSmartOwner({key},v);
if(own('mglru_mode','smart')!=='dynamic')throw Error('Smart MGLRU owner missing');
for(const v of ['on','off','stock'])if(own('mglru_mode',v)!==null)throw Error('manual MGLRU incorrectly owned '+v);
if(own('wifi_powersave','screen_off')!=='dynamic'||own('wifi_powersave','always')!=='dynamic'||own('wifi_powersave','off')!==null)throw Error('Wi-Fi ownership');
for(const k of ['net_screen_off_lte','net_lte_light'])if(own(k,'1')!=='radio'||own(k,'0')!==null)throw Error('radio ownership '+k);
for(const v of ['0','1','30'])if(own('dsp_loudness',v)!==null)throw Error('DSP must stay manual');
if(own('perf_ceiling_pct','85')!=='limit'||own('perf_ceiling_pct','100')!==null)throw Error('ceiling ownership');
if(own('heavy_prime_escape','1')!=='dynamic'||own('heavy_prime_escape','0')!==null)throw Error('prime master ownership');
_cfgVals.heavy_prime_escape='1';if(own('prime_escape_burst_s','20')!=='limit'||own('prime_escape_rest_s','40')!=='limit')throw Error('prime guard ownership');
_cfgVals.heavy_prime_escape='0';if(own('prime_escape_burst_s','20')!==null||own('prime_escape_rest_s','40')!==null)throw Error('disabled prime guards owned');
if(own('io_scheduler','auto')!=='dynamic')throw Error('Smart I/O scenario ownership missing');
for(const k of ['kernel_timer_migration','kernel_hrtimer_migration','kernel_lpm_prediction','kernel_sched_nr_migrate','kernel_sched_stats','kernel_rt_boost','kernel_bore']){
 if(own(k,'auto')!=='dynamic')throw Error('Smart dynamic kernel ownership missing '+k);
 for(const v of ['stock','off','on','0','2','512'])if(own(k,v)!==null)throw Error('manual kernel value incorrectly Smart-owned '+k+'='+v);
}
if(own('io_scheduler','mq-deadline')!==null||own('auto_battery_enable','1')!=='dynamic'||own('auto_battery_enable','0')!==null)throw Error('manual/Auto Battery ownership');
if(own('sustained_temp_mode','smart')!=='thermal'||own('doze_level','night')!==null)throw Error('battery ownership is too broad');
_selectedProfile='balanced';if(own('mglru_mode','smart')!==null||own('wifi_powersave','always')!==null)throw Error('non-Smart profile marked Smart-owned');
console.log('ok');
JS
out="$(node "$T/t.js" "$H" 2>&1)" || fail "$out"
[ "$out" = ok ] || fail "$out"
echo 'PASS WebUI Smart/scheduler options: runtime-only discovery, scenario-owned BORE Auto, live Smart badge, conditional indicators and manual MGLRU ownership in 13 locales'
)


