load=body('function cfgLoad(force) {')
assert load.index('cfgPrimeHub();') < load.index('cfgLoadFresh()')
prime=body('function cfgPrimeHub() {')
assert 'if (_cfgOpen || _cfgGroup || _cfgSearch) return;' in prime and 'cfgRender();' in prime
