command -v node >/dev/null 2>&1 || { echo 'SKIP webui buildfix42: no node'; exit 0; }
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT HUP INT TERM
cat > "$T/t.js" <<'JS'
