printf 'changed\n' > "$T/stage/config/governor.conf.shipped"
if python3 "$ROOT/tools/asb_verify_package.py" "$T/stage" "$T/good.zip" abc >/dev/null 2>&1; then echo 'FAIL staged change accepted' >&2; exit 1; fi
