  let info=nodes.screenshotFixSelected.children[0].children[0].textContent;
  if(!info.includes('Selection published') || !info.includes('Hook status is unknown'))throw Error('selection was confused with runtime activation');
  published='0'; await ctx.screenshotFixLoad();
  info=nodes.screenshotFixSelected.children[0].children[0].textContent;
  if(!info.includes('Selection is not confirmed as published') || !info.includes('Hook status is unknown'))throw Error('unpublished selection was reported active');
  published='1';
  nodes.screenshotFixSearch.value='missing';ctx.screenshotFixFilterApps();
  if(nodes.screenshotFixApps.options.length || !nodes.screenshotFixAdd.disabled)throw Error('search should filter and disable');
  nodes.screenshotFixSearch.value='two';ctx.screenshotFixFilterApps();
  if(nodes.screenshotFixApps.options.length!==1)throw Error('search should match package');
  await ctx.screenshotFixChange('add','org.example.two');
  if(calls.filter(x=>x.startsWith('pm list')).length!==1)throw Error('refresh should reuse recent package list');
  if(!calls.some(x=>x.includes(" add '0' 'org.example.two'")) || !toasts.length)throw Error('validated save');
  let before=calls.length;await ctx.screenshotFixChange('add','org.example.two;bad');if(calls.length!==before)throw Error('unsafe input');
  for (const supportedSdk of ['35','36','37']) { sdk=supportedSdk; await ctx.screenshotFixLoad(); if(nodes.screenshotFixSearch.disabled) throw Error('supported SDK '+sdk); }
  sdk='34';await ctx.screenshotFixLoad();if(!nodes.screenshotFixSearch.disabled || !nodes.screenshotFixAdd.disabled)throw Error('unsupported SDK');
})().catch(e=>{console.error(e);process.exitCode=1});
JS
echo 'PASS screenshot UI: capability gate, per-user selection and validated save'
)

t_webui_infinite_advice_freshness() (
set -eu
ROOT="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
command -v node >/dev/null 2>&1 || { echo 'SKIP advice freshness: node missing'; return 0; }
node - "$ROOT/webroot/index.html" <<'JS'
const fs=require('fs'), h=fs.readFileSync(process.argv[2],'utf8');
const start=h.indexOf('async function infAdviceLoad(manual) {'), end=h.indexOf('\n}',start);
if(start<0||end<0)throw Error('missing loader');
let _infAdviceData=null,_infAdviceAt=0,_infAdviceLoading=false,_infAdviceBusy=false,_infAdviceError='',_infAdviceArmed=0,_infAdviceResults=[];
const INF_ADVICE_MAX_AGE_MS=300000, MD='/m'; let now=1000000, cache=null, reads=0, raw='fresh';
Date.now=()=>now;
function logReportCacheGet(){return cache} function logReportCacheSet(x){cache={raw:x,t:now}}
function parseLogReport(x){return {ok:x!=='bad',raw:x}} function infAdvicePaint(){}
function runText(x){return x.stdout} async function run(){reads++;return {stdout:raw}}
function T(k,d){return d}
eval(h.slice(start,end+2));
const chk=(v,m)=>{if(!v)throw Error(m)};
(async()=>{
 cache={raw:'old',t:now-301000}; await infAdviceLoad(false);
 chk(reads===1&&_infAdviceData.raw==='fresh','stale report cache masked current capture');
 await infAdviceLoad(false); chk(reads===1,'fresh in-memory result should not reread');
 now+=300001; raw='newer'; await infAdviceLoad(false);
 chk(reads===2&&_infAdviceData.raw==='newer','reopening did not refresh stale in-memory data');
 raw='manual'; await infAdviceLoad(true); chk(reads===3&&_infAdviceData.raw==='manual','manual refresh did not bypass cache');
 now+=300001; raw='bad'; await infAdviceLoad(false);
 chk(_infAdviceData===null&&_infAdviceAt===0,'failed refresh presented stale data as current');
 console.log('PASS Infinite Log recommendations: bounded cache, fresh reopen and explicit refresh');
})().catch(e=>{console.error(e);process.exitCode=1});
JS
)

_asb_tests() { declare -F | awk '$3 ~ /^t_/ { print substr($3, 3) }'; }
case "${1:-}" in
  --list) _asb_tests ;;
  --source) "_c_${2:?fixture name}" ;;
  *)
    _asb_failed=0
    for _asb_t in ${*:-$(_asb_tests)}; do
      "t_$_asb_t"
      [ $? -eq 0 ] || { printf 'FAILED: %s\n' "$_asb_t" >&2; _asb_failed=$((_asb_failed + 1)); }
    done
    [ "$_asb_failed" -eq 0 ]
    ;;
esac
